INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86240, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "第三人称复数代词，指人以外的多个事物或动物。", "primary_collocate": null, "pronunciation": "tā men", "ipa": "tʰa˥ mən", "syllable_count": 2, "sentences": [{"text": "动物园里有几只熊猫，它们每天吃竹子。", "target_word": "它们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些照片很旧了，请你好好保管它们。", "target_word": "它们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了几本词典，它们帮了我很大的忙。", "target_word": "它们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的树很高，它们已经长了几十年。", "target_word": "它们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们喜欢小动物，因为它们很可爱。", "target_word": "它们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几张桌子太脏了，我们把它们擦干净吧。", "target_word": "它们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天到了，燕子飞走了，它们要去南方。", "target_word": "它们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的灯都开着，请你把它们关上。", "target_word": "它们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些问题很难，我没办法回答它们。", "target_word": "它们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河里有很多鱼，它们游得很快。", "target_word": "它们", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "它", "label": "单数形式"}, {"form": "它們", "label": "繁体"}], "register": "中性", "sense_fingerprint": "第三人称复数代词，代替人以外的多个事物或动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b149f1bb-a04c-4874-9c02-4b65b2bbfa14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86240, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "它们", "is_correct": true, "explanation": "“它们”指前面提到的几只熊猫，指代正确，句意通顺。"}, {"text": "我们", "is_correct": false, "explanation": "语义：“我们”包括说话人，熊猫不是我们，不能这样指代。"}, {"text": "她们", "is_correct": false, "explanation": "语义：“她们”指女性人群，熊猫不是人，不能这样指代。"}, {"text": "它", "is_correct": false, "explanation": "搭配：“它”是单数，与“几只熊猫”这样的复数名词不搭配。"}], "explanations": {"它们": "“它们”指前面提到的几只熊猫，指代正确，句意通顺。", "我们": "语义：“我们”包括说话人，熊猫不是我们，不能这样指代。", "她们": "语义：“她们”指女性人群，熊猫不是人，不能这样指代。", "它": "搭配：“它”是单数，与“几只熊猫”这样的复数名词不搭配。"}, "sentence_index": 0, "correct_answer": "它们"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "舞蹈队的姑娘们每天都练习，它们很努力。", "explanation": "这里应该用〈她们〉。“它们”不指人，指这些女性要用“她们”。"}, {"text": "工人们在工地上干活，它们很辛苦。", "explanation": "这里应该用〈他们〉。“它们”不指人，指工人们这些人要用“他们”。"}, {"text": "爸爸和妈妈很忙，它们每天都很晚回家。", "explanation": "这里应该用〈他们〉。“它们”不指人，指父母这些人要用“他们”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86240, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "它们", "is_correct": true, "explanation": "“它们”指前面提到的燕子，指代正确，句意通顺。"}, {"text": "他们", "is_correct": false, "explanation": "语义：“他们”指人，燕子不是人，不能这样指代。"}, {"text": "她们", "is_correct": false, "explanation": "语义：“她们”指女性人群，燕子不是人，不能这样指代。"}, {"text": "你们", "is_correct": false, "explanation": "语义：“你们”指说话对象，燕子不是说话对象，不能这样指代。"}], "explanations": {"它们": "“它们”指前面提到的燕子，指代正确，句意通顺。", "他们": "语义：“他们”指人，燕子不是人，不能这样指代。", "她们": "语义：“她们”指女性人群，燕子不是人，不能这样指代。", "你们": "语义：“你们”指说话对象，燕子不是说话对象，不能这样指代。"}, "sentence_index": 6, "correct_answer": "它们"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "阿姨们在广场跳舞，它们跳得很开心。", "explanation": "这里应该用〈她们〉。“它们”不指人，指这些女性要用“她们”。"}, {"text": "我和朋友一起去旅行，它们玩得很开心。", "explanation": "这里应该用〈我们〉。“它们”不指人，指说话人和朋友这些人要用“我们”。"}, {"text": "我的邻居们都很热情，它们经常帮我。", "explanation": "这里应该用〈他们〉。“它们”不指人，指邻居这些人要用“他们”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86240, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些鸡蛋很新鲜，它很好吃。", "corrected_sentence": "这些鸡蛋很新鲜，它们很好吃。", "error_description": "错误：“它”。“这些鸡蛋”是复数，指代时要用“它们”，“它”是单数形式。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86240, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只鸡很饿，我要去喂它们。", "corrected_sentence": "这只鸡很饿，我要去喂它。", "error_description": "错误：“它们”。“这只鸡”是单数，指代时要用“它”，“它们”指多个事物或动物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
