INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86241, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "病是身体不舒服，要去看医生。", "primary_collocate": null, "pronunciation": "bìng", "ipa": "piŋ˥˩", "syllable_count": 1, "sentences": [{"text": "他的病好了，今天去上班。", "target_word": "病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说我的病不重。", "target_word": "病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的病还没好，不能去学校。", "target_word": "病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他得了病，今天不能来上课。", "target_word": "病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个病要多喝水，多休息。", "target_word": "病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥的病昨天又重了。", "target_word": "病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的病怎么样了？", "target_word": "病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了药以后，我的病轻多了。", "target_word": "病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我的病好些了没有。", "target_word": "病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道得了什么病，很不舒服。", "target_word": "病", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "病人", "label": "复合"}, {"form": "病情", "label": "复合"}], "register": "中性", "sense_fingerprint": "身体不舒服、需要看医生吃药的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0344090-a91f-48fd-a918-ec4ab7350984') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86241, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "病", "is_correct": true, "explanation": "正确：病指身体不舒服、需要看医生的状态。"}, {"text": "饼", "is_correct": false, "explanation": "bǐng（第三声）与 bìng（第四声）声调不同，意思是饼。"}, {"text": "冰", "is_correct": false, "explanation": "bīng（第一声）与 bìng（第四声）声调不同，意思是冰。"}, {"text": "命", "is_correct": false, "explanation": "mìng 与 bìng 声母不同（m 与 b），意思是生命。"}], "explanations": {"病": "正确：病指身体不舒服、需要看医生的状态。", "饼": "bǐng（第三声）与 bìng（第四声）声调不同，意思是饼。", "冰": "bīng（第一声）与 bìng（第四声）声调不同，意思是冰。", "命": "mìng 与 bìng 声母不同（m 与 b），意思是生命。"}, "sentence_index": null, "correct_answer": "病"}, "level_3": {"options": [{"text": "病", "is_correct": true, "explanation": "正确：“他的病”指身体不舒服，“好了”指病愈，与“今天去上班”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能“好了”，句意不通。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“好了”不能用于考试，考试只能“结束”或“通过”。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不会“好了”，也不能因此去上班。"}], "explanations": {"病": "正确：“他的病”指身体不舒服，“好了”指病愈，与“今天去上班”相合。", "颜色": "语义：颜色不能“好了”，句意不通。", "考试": "搭配：“好了”不能用于考试，考试只能“结束”或“通过”。", "名字": "语义：名字不会“好了”，也不能因此去上班。"}, "sentence_index": 0, "correct_answer": "病"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个病很合理，大家都同意。", "explanation": "这里应该用〈价格〉。病指身体不舒服，不能用来形容价钱，应说“价格”。"}, {"text": "这个病很饿，中午要吃饭。", "explanation": "这里应该用〈孩子〉。会饿、要吃饭的是人，“病”是身体的状态，不会饿。"}, {"text": "这种病很聪明，每天都学习。", "explanation": "这里应该用〈学生〉。聪明、学习的是人，“病”不会学习。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86241, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "病", "is_correct": true, "explanation": "正确：病指身体不舒服、需要看医生的状态。"}, {"text": "兵", "is_correct": false, "explanation": "bīng（第一声）与 bìng（第四声）声调不同，意思是士兵。"}, {"text": "必", "is_correct": false, "explanation": "bì 与 bìng 韵母不同（少了后鼻音 ng），意思是必须。"}, {"text": "柄", "is_correct": false, "explanation": "bǐng（第三声）与 bìng（第四声）声调不同，意思是把手。"}], "explanations": {"病": "正确：病指身体不舒服、需要看医生的状态。", "兵": "bīng（第一声）与 bìng（第四声）声调不同，意思是士兵。", "必": "bì 与 bìng 韵母不同（少了后鼻音 ng），意思是必须。", "柄": "bǐng（第三声）与 bìng（第四声）声调不同，意思是把手。"}, "sentence_index": null, "correct_answer": "病"}, "level_3": {"options": [{"text": "病", "is_correct": true, "explanation": "正确：“你的病”问对方的病情，与“怎么样了”搭配。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不属于某个人，“你的天气怎么样了”不成立。"}, {"text": "季节", "is_correct": false, "explanation": "语义：季节不是身体或个人的状况，句意不通。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：“你的星期”不能这样说，星期不能问“怎么样了”。"}], "explanations": {"病": "正确：“你的病”问对方的病情，与“怎么样了”搭配。", "天气": "语义：天气不属于某个人，“你的天气怎么样了”不成立。", "季节": "语义：季节不是身体或个人的状况，句意不通。", "星期": "搭配：“你的星期”不能这样说，星期不能问“怎么样了”。"}, "sentence_index": 6, "correct_answer": "病"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画的病很美，大家都夸它。", "explanation": "这里应该用〈颜色〉。病不指颜色，不能用来形容颜色的美，应说“颜色”。"}, {"text": "这个节目的病很好听，大家都爱看。", "explanation": "这里应该用〈声音〉。病不能用来形容声音，应说“声音”。"}, {"text": "这碗汤的病很鲜，大家都喜欢。", "explanation": "这里应该用〈味道〉。病不能用来形容食物的鲜味，应说“味道”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86241, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年得了一张怪病。", "corrected_sentence": "他去年得了一场怪病。", "error_description": "量词错误：“张”用于平面的东西，病的量词用“场”或“种”。错误是“一张怪病”，正确应说“一场怪病”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86241, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妈妈的病终于了好。", "corrected_sentence": "我妈妈的病终于好了。", "error_description": "语序错误：体标“了”要放在谓语“好”的后面。错误是“终于了好”，正确应说“终于好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
