INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86242, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "身体出现不正常的状态；疾病。", "primary_collocate": null, "pronunciation": "bìng", "ipa": "piŋ˥˩", "syllable_count": 1, "sentences": [{"text": "这种病会传染给别人。", "target_word": "病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他得了一种很少见的病。", "target_word": "病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的病需要长期吃药。", "target_word": "病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个病现在可以治好了。", "target_word": "病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生正在研究这种病。", "target_word": "病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人不知道这是什么病。", "target_word": "病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的病越来越重。", "target_word": "病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病是吃得太多引起的。", "target_word": "病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个病在冬天更常见。", "target_word": "病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的病是三年前得的。", "target_word": "病", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "疾病", "label": "复合"}, {"form": "病人", "label": "复合"}], "register": "中性", "sense_fingerprint": "身体出现的不正常状态，即某种疾病", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0344090-a91f-48fd-a918-ec4ab7350984') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86242, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "病", "is_correct": true, "explanation": "正确：病指身体出现的不正常状态，即疾病。"}, {"text": "饼", "is_correct": false, "explanation": "bǐng（第三声）与 bìng（第四声）声调不同，意思是饼。"}, {"text": "冰", "is_correct": false, "explanation": "bīng（第一声）与 bìng（第四声）声调不同，意思是冰。"}, {"text": "命", "is_correct": false, "explanation": "mìng 与 bìng 声母不同（m 与 b），意思是生命。"}], "explanations": {"病": "正确：病指身体出现的不正常状态，即疾病。", "饼": "bǐng（第三声）与 bìng（第四声）声调不同，意思是饼。", "冰": "bīng（第一声）与 bìng（第四声）声调不同，意思是冰。", "命": "mìng 与 bìng 声母不同（m 与 b），意思是生命。"}, "sentence_index": null, "correct_answer": "病"}, "level_3": {"options": [{"text": "病", "is_correct": true, "explanation": "正确：“这种病”指会传染的疾病，与“会传染给别人”搭配。"}, {"text": "形状", "is_correct": false, "explanation": "语义：形状是外观，不会传染给别人。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不会传染，句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“会传染”的主语是疾病或病原，价格不能这样说。"}], "explanations": {"病": "正确：“这种病”指会传染的疾病，与“会传染给别人”搭配。", "形状": "语义：形状是外观，不会传染给别人。", "颜色": "语义：颜色不会传染，句意不通。", "价格": "搭配：“会传染”的主语是疾病或病原，价格不能这样说。"}, "sentence_index": 0, "correct_answer": "病"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的病很好听，大家都喜欢。", "explanation": "这里应该用〈声音〉。病指身体不正常的状态，不能用来形容歌声，应说“声音”。"}, {"text": "这个病很爱跑步，每天早上都去。", "explanation": "这里应该用〈人〉。爱跑步的是人，“病”不会跑步。"}, {"text": "这道菜的病很香，大家都想尝。", "explanation": "这里应该用〈味道〉。病不能用来形容食物的香味，应说“味道”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86242, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "病", "is_correct": true, "explanation": "正确：病指身体出现的不正常状态，即疾病。"}, {"text": "兵", "is_correct": false, "explanation": "bīng（第一声）与 bìng（第四声）声调不同，意思是士兵。"}, {"text": "必", "is_correct": false, "explanation": "bì 与 bìng 韵母不同（少了后鼻音 ng），意思是必须。"}, {"text": "柄", "is_correct": false, "explanation": "bǐng（第三声）与 bìng（第四声）声调不同，意思是把手。"}], "explanations": {"病": "正确：病指身体出现的不正常状态，即疾病。", "兵": "bīng（第一声）与 bìng（第四声）声调不同，意思是士兵。", "必": "bì 与 bìng 韵母不同（少了后鼻音 ng），意思是必须。", "柄": "bǐng（第三声）与 bìng（第四声）声调不同，意思是把手。"}, "sentence_index": null, "correct_answer": "病"}, "level_3": {"options": [{"text": "病", "is_correct": true, "explanation": "正确：“她的病”指疾病，“越来越重”指病情加重，与语境相合。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“越来越重”用于病情或分量，名字不能加重。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间不是身体状态，不会“越来越重”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不属于某个人，“她的天气”不成立。"}], "explanations": {"病": "正确：“她的病”指疾病，“越来越重”指病情加重，与语境相合。", "名字": "搭配：“越来越重”用于病情或分量，名字不能加重。", "房间": "语义：房间不是身体状态，不会“越来越重”。", "天气": "语义：天气不属于某个人，“她的天气”不成立。"}, "sentence_index": 6, "correct_answer": "病"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的病很忙，常常加班。", "explanation": "这里应该用〈工作〉。病不能用来形容事务的忙碌，应说“工作”。"}, {"text": "这个病会唱歌，大家都爱听。", "explanation": "这里应该用〈歌手〉。会唱歌的是人，“病”不会唱歌。"}, {"text": "他的病很干净，每天都打扫。", "explanation": "这里应该用〈房间〉。病不能用来形容空间的干净，应说“房间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86242, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的家人得了一只怪病。", "corrected_sentence": "他的家人得了一种怪病。", "error_description": "量词错误：病的量词是“种”，不是“只”，应说“一种怪病”，不说“一只怪病”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86242, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他得了两病，都很麻烦。", "corrected_sentence": "他得了两种病，都很麻烦。", "error_description": "量词缺失：数词“两”与“病”之间要加量词，应说“两种病”，不说“两病”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
