INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86243, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“期间”是说一段时间里面。", "primary_collocate": null, "pronunciation": "qī jiān", "ipa": "tɕʰi⁵⁵ tɕjɛn⁵⁵", "syllable_count": 2, "sentences": [{"text": "暑假期间，我每天都去游泳。", "target_word": "期间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节期间，很多商店都不开门。", "target_word": "期间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛期间，大家都很紧张。", "target_word": "期间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住院期间，朋友常常来看我。", "target_word": "期间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试期间，学校里特别安静。", "target_word": "期间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在北京学习期间，我认识了很多朋友。", "target_word": "期间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议期间，请大家关掉手机。", "target_word": "期间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他工作期间从来没有迟到过。", "target_word": "期间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行期间，我们住在小旅馆里。", "target_word": "期间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生病期间，妈妈一直照顾我。", "target_word": "期间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "期間", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：某一段时间之内，常接在时间或事件词后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bcfb73b-b30f-4f91-b98a-882ac61a0cd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86243, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "期间", "is_correct": true, "explanation": "正确：“暑假期间”指暑假这段时间之内，与“每天都去游泳”的持续性相符。"}, {"text": "期限", "is_correct": false, "explanation": "语义：期限指规定的截止时间，说的是终点，不是一段时间本身，与“每天都去游泳”不合。"}, {"text": "年代", "is_correct": false, "explanation": "搭配：“年代”指较长的历史阶段，不说“暑假年代”。"}, {"text": "学期", "is_correct": false, "explanation": "语义：学期指上课的一段时间，与暑假放假相冲突。"}], "explanations": {"期间": "正确：“暑假期间”指暑假这段时间之内，与“每天都去游泳”的持续性相符。", "期限": "语义：期限指规定的截止时间，说的是终点，不是一段时间本身，与“每天都去游泳”不合。", "年代": "搭配：“年代”指较长的历史阶段，不说“暑假年代”。", "学期": "语义：学期指上课的一段时间，与暑假放假相冲突。"}, "sentence_index": 0, "correct_answer": "期间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份报告请你在明天期间交上来。", "explanation": "这里应该用〈之前〉。期间指一段时间之内发生的事，表示在某个时间点以前完成要用〈之前〉：“明天之前交上来”。"}, {"text": "我们七点期间吃了晚饭。", "explanation": "这里应该用〈时候〉。期间指一段时间之内，不能指某个时间点；表示某一时刻要说“七点的时候”，不用〈期间〉。"}, {"text": "他写完作业期间出去玩。", "explanation": "这里应该用〈之后〉。期间指一段时间之内，动作完成以后要用〈之后〉：“他写完作业之后出去玩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86243, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "期间", "is_correct": true, "explanation": "正确：“会议期间”指开会这段时间之内，请大家关手机与之相符。"}, {"text": "预算", "is_correct": false, "explanation": "语义：预算指费用计划，与“关掉手机”的时间语境无关，句子读不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”指人的岁数，不说“会议年龄”。"}, {"text": "教材", "is_correct": false, "explanation": "语义：教材是学习用的材料，不能表示会议的一段时间。"}], "explanations": {"期间": "正确：“会议期间”指开会这段时间之内，请大家关手机与之相符。", "预算": "语义：预算指费用计划，与“关掉手机”的时间语境无关，句子读不通。", "年龄": "搭配：“年龄”指人的岁数，不说“会议年龄”。", "教材": "语义：教材是学习用的材料，不能表示会议的一段时间。"}, "sentence_index": 6, "correct_answer": "期间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请在五分钟期间完成这份作业。", "explanation": "这里应该用〈以内〉。期间指一段时间的过程，表示不超过某个限度要用〈以内〉：“五分钟以内完成”。"}, {"text": "他十二点期间吃了午饭。", "explanation": "这里应该用〈的时候〉。期间指一段时间之内，不能指某个时间点；表示某一时刻要说“十二点的时候”。"}, {"text": "他在朋友期间很受欢迎。", "explanation": "这里应该用〈之中〉。期间指一段时间之内，表示在一群人里面要用〈之中〉：“他在朋友之中很受欢迎”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86243, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒假期间着，我每天都在家看书。", "corrected_sentence": "寒假期间，我每天都在家看书。", "error_description": "错误：“期间”后面多加了“着”。“期间”是名词，不能带“着”。正确：“寒假期间，我每天都在家看书。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86243, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他上课期间了从来没有说话。", "corrected_sentence": "他上课期间从来没有说话。", "error_description": "错误：“期间”后面多加了“了”。“期间”是名词，不能带“了”。正确：“上课期间从来没有说话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86245, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
