INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86245, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "疯狂是特别特别激动，好像管不住自己。", "primary_collocate": null, "pronunciation": "fēng kuáng", "ipa": "fɤŋ˥ kʰuaŋ˧˥", "syllable_count": 2, "sentences": [{"text": "球迷们看到进球，疯狂地喊了起来。", "target_word": "疯狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演唱会上，粉丝们兴奋得疯狂尖叫。", "target_word": "疯狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到中奖的消息，他疯狂地跳了起来。", "target_word": "疯狂", "complexity_tier": "T3", "furigana": "tīng dào zhòng jiǎng de xiāo xi, tā fēngkuáng de tiào le qǐ lái.", "sentence_source": "generated"}, {"text": "比赛赢了，大家疯狂地跳了起来。", "target_word": "疯狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看到偶像，激动得几乎疯狂。", "target_word": "疯狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在雪地里疯狂地玩了一下午。", "target_word": "疯狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "歌手一出来，现场的人都变得疯狂了。", "target_word": "疯狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们疯狂地拥抱，因为球队终于夺冠了。", "target_word": "疯狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到好消息，大家兴奋得疯狂地欢呼起来。", "target_word": "疯狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到明星走过来，女孩们疯狂地叫着他的名字。", "target_word": "疯狂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "疯狂地", "label": "状语形式"}, {"form": "瘋狂", "label": "繁体"}], "register": "中性", "sense_fingerprint": "兴奋激动到难以控制自己", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717e23d-bca9-41d2-953d-d55f3fb7f070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86245, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "疯狂", "is_correct": true, "explanation": "正确：「疯狂」修饰「喊」，表示激动到难以自控，与看到进球后的情境相符。"}, {"text": "平静", "is_correct": false, "explanation": "语义：「平静」指心情安稳，与进球后激动喊叫的情境矛盾。"}, {"text": "轻柔", "is_correct": false, "explanation": "搭配：「轻柔」说声音温和，不能修饰「喊」这种高声的动作。"}, {"text": "红润", "is_correct": false, "explanation": "体貌：「红润」形容脸色，不能用来修饰动作「喊」。"}], "explanations": {"疯狂": "正确：「疯狂」修饰「喊」，表示激动到难以自控，与看到进球后的情境相符。", "平静": "语义：「平静」指心情安稳，与进球后激动喊叫的情境矛盾。", "轻柔": "搭配：「轻柔」说声音温和，不能修饰「喊」这种高声的动作。", "红润": "体貌：「红润」形容脸色，不能用来修饰动作「喊」。"}, "sentence_index": 0, "correct_answer": "疯狂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老奶奶疯狂地慢慢喝着茶，显得很悠闲。", "explanation": "这里应该用〈悠闲〉。疯狂指激动到难以自控，慢慢喝茶要用悠闲，不能用疯狂。"}, {"text": "他疯狂地核对账目，一个数字也不差。", "explanation": "这里应该用〈仔细〉。疯狂指激动到难以自控，核对账目要仔细，不能用疯狂。"}, {"text": "老师疯狂地讲解题目，学生听得很认真。", "explanation": "这里应该用〈耐心〉。疯狂形容情绪失控，讲解题目要用耐心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86245, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "疯狂", "is_correct": true, "explanation": "正确：「疯狂」作「变得……了」的补语，表示现场的人情绪激动、失去控制，与歌手出场的情境相符。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：「冷清」多用于场所，说人「变得冷清」不自然，且与现场热闹的情境不合。"}, {"text": "瘦小", "is_correct": false, "explanation": "体貌：「瘦小」形容身材，不能用来描述一群人在歌手出场时的状态。"}, {"text": "乏味", "is_correct": false, "explanation": "语义：「乏味」指无聊、没意思，与歌手出场后现场气氛热烈的情境矛盾。"}], "explanations": {"疯狂": "正确：「疯狂」作「变得……了」的补语，表示现场的人情绪激动、失去控制，与歌手出场的情境相符。", "冷清": "搭配：「冷清」多用于场所，说人「变得冷清」不自然，且与现场热闹的情境不合。", "瘦小": "体貌：「瘦小」形容身材，不能用来描述一群人在歌手出场时的状态。", "乏味": "语义：「乏味」指无聊、没意思，与歌手出场后现场气氛热烈的情境矛盾。"}, "sentence_index": 6, "correct_answer": "疯狂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他疯狂地在纸上慢慢画着线条，一点也不着急。", "explanation": "这里应该用〈从容〉。疯狂指激动到难以自控，慢慢画线要从容，不能用疯狂。"}, {"text": "图书馆里，他疯狂地小声翻着书页，怕吵到别人。", "explanation": "这里应该用〈轻轻〉。疯狂指激动到难以自控，小声翻书、怕吵到别人要轻轻地，不能用疯狂。"}, {"text": "他疯狂地分析了形势，没有慌乱。", "explanation": "这里应该用〈冷静〉。疯狂指激动到失控，分析形势要用冷静，与「没有慌乱」也矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86245, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "比赛结束时，观众疯狂的鼓起掌来。", "corrected_sentence": "比赛结束时，观众疯狂地鼓起掌来。", "error_description": "错误：「疯狂的」；正确：「疯狂地」。「疯狂」在「鼓起掌来」前作状语，要用「地」；用「的」会把它当作定语，不能修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86245, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们在操场上跑很疯狂。", "corrected_sentence": "孩子们在操场上跑得很疯狂。", "error_description": "错误：「跑很疯狂」；正确：「跑得很疯狂」。程度补语要用「动词＋得＋补语」，漏掉「得」，「很疯狂」不能直接接在动词后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86246, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理智", "is_correct": true, "explanation": "反义：「理智」指冷静、有判断力，与「失去理智」的「疯狂」相反。"}, {"text": "干燥", "is_correct": false, "explanation": "无关：「干燥」描述湿度，与「疯狂」没有反义关系。"}, {"text": "潮湿", "is_correct": false, "explanation": "无关：「潮湿」描述空气或物体的水分，与「疯狂」没有反义关系。"}, {"text": "甜蜜", "is_correct": false, "explanation": "无关：「甜蜜」形容感受，与「疯狂」没有反义关系。"}], "correct_answer": "理智", "explanations": {"理智": "反义：「理智」指冷静、有判断力，与「失去理智」的「疯狂」相反。", "干燥": "无关：「干燥」描述湿度，与「疯狂」没有反义关系。", "潮湿": "无关：「潮湿」描述空气或物体的水分，与「疯狂」没有反义关系。", "甜蜜": "无关：「甜蜜」形容感受，与「疯狂」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86246, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理智", "is_correct": true, "explanation": "反义：「理智」指冷静、有判断力，与「失去理智」的「疯狂」相反。"}, {"text": "整齐", "is_correct": false, "explanation": "无关：「整齐」描述排列或外观，与「疯狂」没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "无关：「柔软」描述质地，与「疯狂」没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：「明亮」描述光线或颜色，与「疯狂」没有反义关系。"}], "correct_answer": "理智", "explanations": {"理智": "反义：「理智」指冷静、有判断力，与「失去理智」的「疯狂」相反。", "整齐": "无关：「整齐」描述排列或外观，与「疯狂」没有反义关系。", "柔软": "无关：「柔软」描述质地，与「疯狂」没有反义关系。", "明亮": "无关：「明亮」描述光线或颜色，与「疯狂」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86246, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "失去理智，极度激动；也指程度极强。", "primary_collocate": null, "pronunciation": "fēng kuáng", "ipa": "fɤŋ˥ kʰuaŋ˧˥", "syllable_count": 2, "sentences": [{"text": "那个疯狂的想法让大家都很吃惊。", "target_word": "疯狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他疯狂地爱着她，什么都不顾。", "target_word": "疯狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双十一的时候，大家疯狂地买东西。", "target_word": "疯狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近房价涨得太疯狂了。", "target_word": "疯狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了考上大学，他疯狂地学习了一年。", "target_word": "疯狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司之间的竞争越来越疯狂。", "target_word": "疯狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开车开得太疯狂，真让人担心。", "target_word": "疯狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她疯狂地工作，连饭也忘了吃。", "target_word": "疯狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个疯狂的计划，几乎不可能成功。", "target_word": "疯狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一到夏天，蚊子就疯狂地繁殖。", "target_word": "疯狂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "疯狂地", "label": "状语形式"}, {"form": "瘋狂", "label": "繁体"}], "register": "中性", "sense_fingerprint": "失去理智或程度极强，不顾一切", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717e23d-bca9-41d2-953d-d55f3fb7f070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86246, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "疯狂", "is_correct": true, "explanation": "正确：「疯狂的想法」指荒唐、失去理智的想法，与「让大家都很吃惊」相符。"}, {"text": "忠诚", "is_correct": false, "explanation": "搭配：「忠诚」多用于人的品质，不能用来修饰「想法」。"}, {"text": "苗条", "is_correct": false, "explanation": "体貌：「苗条」形容身材，不能修饰「想法」。"}, {"text": "平凡", "is_correct": false, "explanation": "语义：「平凡」说明没有特别之处，与「让大家都很吃惊」的结果矛盾。"}], "explanations": {"疯狂": "正确：「疯狂的想法」指荒唐、失去理智的想法，与「让大家都很吃惊」相符。", "忠诚": "搭配：「忠诚」多用于人的品质，不能用来修饰「想法」。", "苗条": "体貌：「苗条」形容身材，不能修饰「想法」。", "平凡": "语义：「平凡」说明没有特别之处，与「让大家都很吃惊」的结果矛盾。"}, "sentence_index": 0, "correct_answer": "疯狂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他疯狂地在公园里慢慢散步，神情很放松。", "explanation": "这里应该用〈悠闲〉。疯狂指失去理智或程度极强，慢慢散步要悠闲，与疯狂矛盾。"}, {"text": "服务员疯狂地回答了顾客的问题。", "explanation": "这里应该用〈礼貌〉。疯狂指失去理智或程度极强，回答顾客的问题要用礼貌，不能用疯狂。"}, {"text": "奶奶疯狂地坐在窗边，安安静静地织毛衣。", "explanation": "这里应该用〈安静〉。疯狂指失去理智或程度极强，安安静静织毛衣与疯狂矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86246, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "疯狂", "is_correct": true, "explanation": "正确：「疯狂」在「开得太……」中作程度补语，指开车不顾一切、过分危险，与「真让人担心」相符。"}, {"text": "安全", "is_correct": false, "explanation": "语义：「安全」与「真让人担心」矛盾，安全驾驶不应让人担心。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大」形容身材，不能用来描述开车的程度。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：「矮小」说身材，不能用来形容开车的程度。"}], "explanations": {"疯狂": "正确：「疯狂」在「开得太……」中作程度补语，指开车不顾一切、过分危险，与「真让人担心」相符。", "安全": "语义：「安全」与「真让人担心」矛盾，安全驾驶不应让人担心。", "高大": "体貌：「高大」形容身材，不能用来描述开车的程度。", "矮小": "体貌：「矮小」说身材，不能用来形容开车的程度。"}, "sentence_index": 6, "correct_answer": "疯狂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他疯狂地躺在床上，一动不动地睡着了。", "explanation": "这里应该用〈安稳〉。疯狂指失去理智或程度极强，一动不动地安睡与疯狂矛盾。"}, {"text": "他疯狂地站在台上，等待音乐响起。", "explanation": "这里应该用〈冷静〉。疯狂指失去理智或程度极强，站在台上等待音乐要用冷静，不能用疯狂。"}, {"text": "他疯狂地走进了考场。", "explanation": "这里应该用〈镇定〉。疯狂指失去理智，走进考场要镇定，不能用疯狂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86246, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "股价一涨，大家疯狂的抢购了起来。", "corrected_sentence": "股价一涨，大家疯狂地抢购了起来。", "error_description": "错误：「疯狂的」；正确：「疯狂地」。「疯狂」在「抢购了起来」前作状语，要用「地」；用「的」会把它当作定语，不能修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86246, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车子在山路上开很疯狂。", "corrected_sentence": "车子在山路上开得很疯狂。", "error_description": "错误：「开很疯狂」；正确：「开得很疯狂」。程度补语要用「动词＋得＋补语」，漏掉「得」，「很疯狂」不能直接接在动词后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
