INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86247, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "“调查”是认真去看去问，想弄清楚一件事。", "primary_collocate": null, "pronunciation": "diào chá", "ipa": "tjɑʊ˥˩ tʂʰɑ˧˥", "syllable_count": 2, "sentences": [{"text": "警察正在调查昨晚的事故。", "target_word": "调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师调查了谁打破了窗户。", "target_word": "调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想调查一下这家店的东西为什么便宜。", "target_word": "调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈认真调查了孩子不吃饭的原因。", "target_word": "调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去村子里调查水为什么变黄了。", "target_word": "调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者正在调查这家公司的财务问题。", "target_word": "调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理让小王调查一下客人为什么不来。", "target_word": "调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生先调查了病人最近吃过什么。", "target_word": "调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先调查清楚，再说谁对谁错。", "target_word": "调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人去调查那件奇怪的事。", "target_word": "调查", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "调查了", "label": "体标（了）"}, {"form": "调查过", "label": "体标（过）"}, {"form": "调查调查", "label": "重叠"}, {"form": "调查员", "label": "复合词"}], "register": "中性", "sense_fingerprint": "认真去看去问，弄清楚一件事的原因或真相", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1e2897-790e-4544-bd7b-399254c42829') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86247, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "调查", "is_correct": true, "explanation": "“调查”表示认真去看去问，弄清事故的原因，与“正在……昨晚的事故”相合。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示迎接或接纳，不能用于处理事故。"}, {"text": "参加", "is_correct": false, "explanation": "配价：“参加”的宾语应是活动或会议，不能接“事故”。"}, {"text": "原谅", "is_correct": false, "explanation": "语义：“原谅”的对象是人或过错，不能用于事故本身。"}], "explanations": {"调查": "“调查”表示认真去看去问，弄清事故的原因，与“正在……昨晚的事故”相合。", "欢迎": "语义：“欢迎”表示迎接或接纳，不能用于处理事故。", "参加": "配价：“参加”的宾语应是活动或会议，不能接“事故”。", "原谅": "语义：“原谅”的对象是人或过错，不能用于事故本身。"}, "sentence_index": 0, "correct_answer": "调查"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生调查了病人的眼睛。", "explanation": "这里应该用〈检查〉。调查用于弄清事情的原因或真相，检查身体部位要用检查。"}, {"text": "我们一起坐在湖边调查晚霞。", "explanation": "这里应该用〈欣赏〉。调查是为了弄清情况，看晚霞、享受美景要用欣赏。"}, {"text": "厨师调查了汤的味道。", "explanation": "这里应该用〈品尝〉。调查不用于感受味道，尝味道要用品尝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86247, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "调查", "is_correct": true, "explanation": "“调查”表示去弄清原因，与“为什么不来”相合。"}, {"text": "出席", "is_correct": false, "explanation": "配价：“出席”后接会议或活动，不能接“一下客人为什么不来”。"}, {"text": "参观", "is_correct": false, "explanation": "配价：“参观”的对象是场所或展品，不能接“为什么不来”。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：“照顾”的对象是人，表示关心照料，与弄清原因的意思不符。"}], "explanations": {"调查": "“调查”表示去弄清原因，与“为什么不来”相合。", "出席": "配价：“出席”后接会议或活动，不能接“一下客人为什么不来”。", "参观": "配价：“参观”的对象是场所或展品，不能接“为什么不来”。", "照顾": "语义：“照顾”的对象是人，表示关心照料，与弄清原因的意思不符。"}, "sentence_index": 6, "correct_answer": "调查"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "保洁员调查了地板。", "explanation": "这里应该用〈打扫〉。调查用于了解情况，清扫地面要用打扫。"}, {"text": "他调查了那本小说。", "explanation": "这里应该用〈阅读〉。调查不用于读书看内容，读书要用阅读。"}, {"text": "妹妹调查了那件新衣服。", "explanation": "这里应该用〈试穿〉。调查用于弄清情况，穿衣服试一试要用试穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
