INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86247, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想把调查一下那件事的原因。", "corrected_sentence": "他想调查一下那件事的原因。", "error_description": "“把”字句中，“把”后应先接宾语再接动词，不能直接接“调查”；应说“想调查一下那件事的原因”或“想把那件事的原因调查一下”，错误在于多加了“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
