INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86248, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "动词，指为了了解情况而进行考察、询问。", "primary_collocate": null, "pronunciation": "diào chá", "ipa": "tjɑʊ˥˩ tʂʰɑ˧˥", "syllable_count": 2, "sentences": [{"text": "公司调查了一千个年轻人的看法。", "target_word": "调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校调查过学生每天睡几个小时。", "target_word": "调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们准备调查这个城市的交通情况。", "target_word": "调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者去工厂调查工人的生活。", "target_word": "调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府正在调查市民对新路的意见。", "target_word": "调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们调查了全班同学的上网时间。", "target_word": "调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们调查家乡的变化。", "target_word": "调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店想调查顾客最喜欢哪种饮料。", "target_word": "调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用一个月调查了五个小区的垃圾问题。", "target_word": "调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这里的情况调查清楚。", "target_word": "调查", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "调查了", "label": "体标（了）"}, {"form": "调查过", "label": "体标（过）"}, {"form": "调查报告", "label": "复合词"}], "register": "中性", "sense_fingerprint": "为了了解某方面的情况而考察、询问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1e2897-790e-4544-bd7b-399254c42829') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86248, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "调查", "is_correct": true, "explanation": "“调查”表示为了了解情况而询问、考察，与“看法”相合。"}, {"text": "原谅", "is_correct": false, "explanation": "语义：“原谅”的对象是人或过错，不能用来接“看法”。"}, {"text": "参加", "is_correct": false, "explanation": "配价：“参加”的宾语应是活动或会议，不能接“看法”。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”的对象是场所或物品，不能接“看法”。"}], "explanations": {"调查": "“调查”表示为了了解情况而询问、考察，与“看法”相合。", "原谅": "语义：“原谅”的对象是人或过错，不能用来接“看法”。", "参加": "配价：“参加”的宾语应是活动或会议，不能接“看法”。", "打扫": "语义：“打扫”的对象是场所或物品，不能接“看法”。"}, "sentence_index": 0, "correct_answer": "调查"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈调查了那道菜。", "explanation": "这里应该用〈品尝〉。调查用于弄清情况，尝菜的味道要用品尝。"}, {"text": "观众调查了那场演出。", "explanation": "这里应该用〈欣赏〉。调查是去了解情况，观看演出要用欣赏。"}, {"text": "顾客调查了那件大衣。", "explanation": "这里应该用〈购买〉。调查用于弄清事情，买东西要用购买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86248, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "调查", "is_correct": true, "explanation": "“调查”表示去了解情况、弄清变化，与“家乡的变化”相合。"}, {"text": "出席", "is_correct": false, "explanation": "配价：“出席”后接会议或活动，不能接“家乡的变化”。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：“提高”说水平或质量，不说“家乡的变化”。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”的对象是场所或物品，不能接“变化”。"}], "explanations": {"调查": "“调查”表示去了解情况、弄清变化，与“家乡的变化”相合。", "出席": "配价：“出席”后接会议或活动，不能接“家乡的变化”。", "提高": "搭配：“提高”说水平或质量，不说“家乡的变化”。", "打扫": "语义：“打扫”的对象是场所或物品，不能接“变化”。"}, "sentence_index": 6, "correct_answer": "调查"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "阿姨调查了那件衣服。", "explanation": "这里应该用〈洗〉。调查用于弄清情况，洗衣服要用洗。"}, {"text": "学生们调查了那首曲子。", "explanation": "这里应该用〈演奏〉。调查是去了解情况，演奏乐曲要用演奏。"}, {"text": "孩子调查了一首歌。", "explanation": "这里应该用〈唱〉。调查不用于唱歌，唱歌要用唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
