INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86249, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "追是在后面快快跑，想要赶上前面的人。", "primary_collocate": null, "pronunciation": "zhuī", "ipa": "ʈʂweɪ˥", "syllable_count": 1, "sentences": [{"text": "小狗在后面追着我跑。", "target_word": "追", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察追上了那个小偷。", "target_word": "追", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在公园里追来追去。", "target_word": "追", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑得很快，我追不上他。", "target_word": "追", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫在地上追着一个球。", "target_word": "追", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的人跑了，警察马上追过去。", "target_word": "追", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我追了一路，还是没追到公交车。", "target_word": "追", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟哭着追姐姐。", "target_word": "追", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个男孩一直追着小偷跑了两条街。", "target_word": "追", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别跑，我一定会追上你！", "target_word": "追", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "追了", "label": "体标"}, {"form": "追着", "label": "体标"}, {"form": "追过", "label": "体标"}, {"form": "追上", "label": "复合"}], "register": "中性", "sense_fingerprint": "在后面跑着赶上前面的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b874e5c-1605-4191-991e-5cc99b3cbbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86249, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "追", "is_correct": true, "explanation": "正确答案：追 zhuī，意思是在后面快跑赶上。"}, {"text": "吹", "is_correct": false, "explanation": "吹 chuī 与 zhuī 声母不同（ch 与 zh），意思是吹气。"}, {"text": "坠", "is_correct": false, "explanation": "坠 zhuì 与 zhuī 声调不同（第四声），意思是落下。"}, {"text": "猪", "is_correct": false, "explanation": "猪 zhū 与 zhuī 韵母不同（u 与 ui），意思是猪。"}, {"text": "催", "is_correct": false, "explanation": "催 cuī 与 zhuī 声母不同（c 与 zh），意思是催促。"}], "explanations": {"追": "正确答案：追 zhuī，意思是在后面快跑赶上。", "吹": "吹 chuī 与 zhuī 声母不同（ch 与 zh），意思是吹气。", "坠": "坠 zhuì 与 zhuī 声调不同（第四声），意思是落下。", "猪": "猪 zhū 与 zhuī 韵母不同（u 与 ui），意思是猪。", "催": "催 cuī 与 zhuī 声母不同（c 与 zh），意思是催促。"}, "sentence_index": null, "correct_answer": "追"}, "level_3": {"options": [{"text": "追", "is_correct": true, "explanation": "“追”表示在后面快跑赶上，符合“在后面追着我跑”的语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：狗在后面跑时不会“吃着我跑”，与句意说不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱着我跑”描述不出在后面跟人跑的动作，与句意不符。"}, {"text": "逃", "is_correct": false, "explanation": "语义：“逃”是逃离，与“在后面跟着我跑”的方向相反。"}], "explanations": {"追": "“追”表示在后面快跑赶上，符合“在后面追着我跑”的语境。", "吃": "语义：狗在后面跑时不会“吃着我跑”，与句意说不通。", "唱": "语义：“唱着我跑”描述不出在后面跟人跑的动作，与句意不符。", "逃": "语义：“逃”是逃离，与“在后面跟着我跑”的方向相反。"}, "sentence_index": 0, "correct_answer": "追"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我坐早班车，追上了九点的会议。", "explanation": "这里应该用〈赶〉。赶上表示来得及参加会议，会议不能被“追”；“追上”只用于追赶有形的人或车。"}, {"text": "他早上追了一杯咖啡。", "explanation": "这里应该用〈喝〉。喝是把饮料咽下去；“追”是在后面跑着赶人或车，不能用于喝咖啡。"}, {"text": "我在超市里追了一瓶酱油。", "explanation": "这里应该用〈买〉。买表示付钱获得东西；“追”是赶人或车，不能用来表示买东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9caf49c3-6c80-4ba8-8538-68d293a711e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86249, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "追", "is_correct": true, "explanation": "正确答案：追 zhuī，意思是在后面快跑赶上。"}, {"text": "捉", "is_correct": false, "explanation": "捉 zhuō 与 zhuī 韵母不同（o 与 i），意思是抓住。"}, {"text": "桌", "is_correct": false, "explanation": "桌 zhuō 与 zhuī 韵母不同（o 与 i），意思是桌子。"}, {"text": "之", "is_correct": false, "explanation": "之 zhī 与 zhuī 韵母不同（之没有 u 介音），常见于“之后”“之前”。"}], "explanations": {"追": "正确答案：追 zhuī，意思是在后面快跑赶上。", "捉": "捉 zhuō 与 zhuī 韵母不同（o 与 i），意思是抓住。", "桌": "桌 zhuō 与 zhuī 韵母不同（o 与 i），意思是桌子。", "之": "之 zhī 与 zhuī 韵母不同（之没有 u 介音），常见于“之后”“之前”。"}, "sentence_index": null, "correct_answer": "追"}, "level_3": {"options": [{"text": "追", "is_correct": true, "explanation": "“追了一路”指一路在后面赶，与后半句“还是没追到公交车”前后呼应。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃了一路”说不通，“吃”通常要接食物，不能与“一路”搭配。"}, {"text": "写", "is_correct": false, "explanation": "语义：写与赶车的动作无关，与“还是没追到公交车”说不通。"}, {"text": "画", "is_correct": false, "explanation": "语义：画一路与赶公交车的过程无关，句意不通。"}], "explanations": {"追": "“追了一路”指一路在后面赶，与后半句“还是没追到公交车”前后呼应。", "吃": "搭配：“吃了一路”说不通，“吃”通常要接食物，不能与“一路”搭配。", "写": "语义：写与赶车的动作无关，与“还是没追到公交车”说不通。", "画": "语义：画一路与赶公交车的过程无关，句意不通。"}, "sentence_index": 6, "correct_answer": "追"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我终于追到了钥匙。", "explanation": "这里应该用〈找〉。找到表示寻得失物；追是跑着赶人，不能用于找东西。"}, {"text": "我给她追了一封信。", "explanation": "这里应该用〈写〉。写信是动笔书写；“追”是赶人或车，不能用于写信。"}, {"text": "他在舞台上追了一首歌。", "explanation": "这里应该用〈唱〉。唱是发声演唱；“追”是赶人或车，不能用于唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9caf49c3-6c80-4ba8-8538-68d293a711e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86249, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他骑车追了上那辆汽车。", "corrected_sentence": "他骑车追上了那辆汽车。", "error_description": "错误形式：追了上；正确形式：追上了。“上”是“追”的结果补语，必须紧跟在“追”后面，“了”放在补语之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9caf49c3-6c80-4ba8-8538-68d293a711e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86249, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她追了着那只猫跑了很久。", "corrected_sentence": "她追着那只猫跑了很久。", "error_description": "错误形式：追了着；正确形式：追着。“着”表示动作持续进行，“了”不能和“着”同时用在同一个动词后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9caf49c3-6c80-4ba8-8538-68d293a711e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
