INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86251, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "“并且”表示除了前一件事以外，还有另一件事。", "primary_collocate": null, "pronunciation": "bìng qiě", "ipa": "piŋ˥˩ tɕʰjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他会说英语，并且说得很好。", "target_word": "并且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个手机便宜，并且好用。", "target_word": "并且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她会唱歌，并且会跳舞。", "target_word": "并且", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师来了，并且带来了新书。", "target_word": "并且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店东西好，并且很干净。", "target_word": "并且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我吃了早饭，并且喝了牛奶。", "target_word": "并且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他写完作业，并且检查了一遍。", "target_word": "并且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的菜好吃，并且不贵。", "target_word": "并且", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们参观了学校，并且见到了校长。", "target_word": "并且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈做好饭，并且把桌子擦干净了。", "target_word": "并且", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "连词：连接两个动作或两种情况，表示除前一件事外还有后一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2434161a-3956-4714-972b-e41f185ec812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86251, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，前后意思相反；这里“说得很好”是对“会说英语”的补充，并不相反。"}, {"text": "并且", "is_correct": true, "explanation": "正确：“并且”表示在前一件事之外还有另一件事，这里补充“说得很好”。"}, {"text": "以及", "is_correct": false, "explanation": "搭配：“以及”连接名词性成分，不能连接“会说英语”和“说得很好”这样的小句。"}, {"text": "或者", "is_correct": false, "explanation": "语义：“或者”表示二选一，这里说的是同一个人的两项能力，不是选择。"}], "explanations": {"但是": "语义：“但是”表示转折，前后意思相反；这里“说得很好”是对“会说英语”的补充，并不相反。", "并且": "正确：“并且”表示在前一件事之外还有另一件事，这里补充“说得很好”。", "以及": "搭配：“以及”连接名词性成分，不能连接“会说英语”和“说得很好”这样的小句。", "或者": "语义：“或者”表示二选一，这里说的是同一个人的两项能力，不是选择。"}, "sentence_index": 0, "correct_answer": "并且"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很努力，并且没有成功。", "explanation": "这里应该用〈但是〉。“并且”只表示补充，不表示转折；“很努力”与“没有成功”前后意思相反，要用“但是”。"}, {"text": "我很渴，并且却没有喝水。", "explanation": "这里应该用〈但是〉。“却”表示转折，与只表示补充的“并且”矛盾；“很渴”与“没有喝水”前后形成对比，要用“但是”。"}, {"text": "今天我们去爬山，并且去游泳，你选一个吧。", "explanation": "这里应该用〈或者〉。“并且”表示两件事都要做，这里后面说“你选一个”，是二选一，要用“或者”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86251, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "而是", "is_correct": false, "explanation": "配价：“而是”前面要有“不是……”的否定成分，这里没有，不能单独使用。"}, {"text": "并且", "is_correct": true, "explanation": "正确：“并且”连接动作，表示写完作业之外又检查了一遍。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”说明原因，“检查了一遍”不是“写完作业”的原因。"}, {"text": "以至", "is_correct": false, "explanation": "搭配：“以至”后面要接结果或程度，“检查了一遍”不能用“以至”引出。"}], "explanations": {"而是": "配价：“而是”前面要有“不是……”的否定成分，这里没有，不能单独使用。", "并且": "正确：“并且”连接动作，表示写完作业之外又检查了一遍。", "因为": "语义：“因为”说明原因，“检查了一遍”不是“写完作业”的原因。", "以至": "搭配：“以至”后面要接结果或程度，“检查了一遍”不能用“以至”引出。"}, "sentence_index": 6, "correct_answer": "并且"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这不是他的主意，并且是我的主意。", "explanation": "这里应该用〈而是〉。“不是……而是……”表示更正或对比，“并且”只表示并列补充，不能用来更正前面的说法。"}, {"text": "即使下雨，并且我们也要去。", "explanation": "这里表示让步，应该用“即使……也……”的让步关系；“并且”只表示并列补充，不表示让步。"}, {"text": "虽然他很累，并且还在工作。", "explanation": "这里应该用〈但是〉。“虽然……”要与“但是”配合表示转折，“并且”只表示补充，不能与“虽然”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86251, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我喜欢音乐，并且电影。", "corrected_sentence": "我喜欢音乐，并且喜欢电影。", "error_description": "错误：“并且”后面直接接了名词“电影”，缺少谓语“喜欢”。“并且”连接的应是两个完整的谓语部分，应说“我喜欢音乐，并且喜欢电影”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86251, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她不是很聪明，并且很努力。", "corrected_sentence": "她不是很聪明，但是很努力。", "error_description": "错误：“不是很聪明”与“很努力”前后形成转折，“并且”只表示补充，不表示转折，应该用“但是”：她不是很聪明，但是很努力。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
