INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86252, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示递进或并列关系。", "primary_collocate": null, "pronunciation": "bìng qiě", "ipa": "piŋ˥˩ tɕʰjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这本书很有意思，并且很便宜。", "target_word": "并且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很聪明，并且非常努力。", "target_word": "并且", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我喜欢这个城市，并且想住在这里。", "target_word": "并且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她打开窗户，并且关了灯。", "target_word": "并且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "李明学过法语，并且学得不错。", "target_word": "并且", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要认真听，并且做笔记。", "target_word": "并且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气好，并且不太热，我们去爬山。", "target_word": "并且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生检查了他的腿，并且给了他药。", "target_word": "并且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个办法简单，并且有用。", "target_word": "并且", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他看着我，并且点了点头。", "target_word": "并且", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "连词：连接并列或递进的成分，后面的内容补充或加深前面的内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2434161a-3956-4714-972b-e41f185ec812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86252, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示因果，“很便宜”不是因为“有意思”才有的结果，说不通。"}, {"text": "并且", "is_correct": true, "explanation": "正确：“并且”表示补充，这里在“有意思”之外又补充“很便宜”。"}, {"text": "以及", "is_correct": false, "explanation": "搭配：“以及”连接名词性成分，不能连接“很有意思”和“很便宜”这两个形容词短语。"}, {"text": "或者", "is_correct": false, "explanation": "语义：“或者”表示二选一，这里说的是书的两个优点，不是选择。"}], "explanations": {"因此": "语义：“因此”表示因果，“很便宜”不是因为“有意思”才有的结果，说不通。", "并且": "正确：“并且”表示补充，这里在“有意思”之外又补充“很便宜”。", "以及": "搭配：“以及”连接名词性成分，不能连接“很有意思”和“很便宜”这两个形容词短语。", "或者": "语义：“或者”表示二选一，这里说的是书的两个优点，不是选择。"}, "sentence_index": 0, "correct_answer": "并且"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很聪明，并且成绩很差。", "explanation": "这里应该用〈但是〉。“成绩很差”与“很聪明”形成转折，“并且”只表示补充，要用“但是”。"}, {"text": "周末可以去看电影，并且去逛街，你选一个吧。", "explanation": "这里应该用〈或者〉。后面说“你选一个”，是二选一，“并且”表示两件都要，要用“或者”。"}, {"text": "他很累，并且却还在工作。", "explanation": "这里应该用〈但是〉。“却”表示转折，与只表示补充的“并且”矛盾；“很累”与“还在工作”前后形成对比，要用“但是”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86252, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "而是", "is_correct": false, "explanation": "配价：“而是”前面要有“不是……”的否定成分，这里没有否定成分，不能用。"}, {"text": "于是", "is_correct": false, "explanation": "语义：“于是”表示承接的结果，“不太热”不是因为“天气好”才产生的结果。"}, {"text": "并且", "is_correct": true, "explanation": "正确：“并且”表示补充，这里在“天气好”之外又补充“不太热”。"}, {"text": "从而", "is_correct": false, "explanation": "语义：“从而”表示由此产生的结果，这里前后不构成因果，说不通。"}], "explanations": {"而是": "配价：“而是”前面要有“不是……”的否定成分，这里没有否定成分，不能用。", "于是": "语义：“于是”表示承接的结果，“不太热”不是因为“天气好”才产生的结果。", "并且": "正确：“并且”表示补充，这里在“天气好”之外又补充“不太热”。", "从而": "语义：“从而”表示由此产生的结果，这里前后不构成因果，说不通。"}, "sentence_index": 6, "correct_answer": "并且"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不是来玩的，并且是来工作的。", "explanation": "这里应该用〈而是〉。“不是……而是……”表示更正或对比，“并且”只表示并列补充，不能用来更正前面的说法。"}, {"text": "即使天气很冷，并且我们也要去爬山。", "explanation": "这里表示让步，应该用“即使……也……”的让步关系；“并且”只表示并列补充，不表示让步。"}, {"text": "如果下雨，并且我们就不去爬山。", "explanation": "这里应该用〈就〉。“如果……”后面要用“就”引出结果，“并且”不能放在假设关系中，应去掉〈并且〉，说“如果下雨，我们就不去爬山”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86252, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很有钱，并且却很大方。", "corrected_sentence": "他很有钱，并且也很大方。", "error_description": "错误：“并且”表示补充，后面不能接表示转折的“却”，应说“并且也很大方”，“也”要放在“并且”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86252, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我喜欢喝茶，并且咖啡。", "corrected_sentence": "我喜欢喝茶，并且喜欢喝咖啡。", "error_description": "错误：“并且”后面直接接了名词“咖啡”，缺少谓语“喜欢喝”。“并且”连接的应是完整的谓语部分，应说“并且喜欢喝咖啡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86253, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "异", "is_correct": true, "explanation": "异与“同”（相同）构成反义关系，表示不一样。"}, {"text": "重", "is_correct": false, "explanation": "“重”与“同”（相同）之间没有反义关系，不是相对的概念。"}, {"text": "深", "is_correct": false, "explanation": "“深”与“同”（相同）之间没有反义关系，不是相对的概念。"}, {"text": "慢", "is_correct": false, "explanation": "“慢”与“同”（相同）之间没有反义关系，不是相对的概念。"}], "correct_answer": "异", "explanations": {"异": "异与“同”（相同）构成反义关系，表示不一样。", "重": "“重”与“同”（相同）之间没有反义关系，不是相对的概念。", "深": "“深”与“同”（相同）之间没有反义关系，不是相对的概念。", "慢": "“慢”与“同”（相同）之间没有反义关系，不是相对的概念。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
