INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86253, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "“同”是说两个东西一样，没有不同。", "primary_collocate": null, "pronunciation": "tóng", "ipa": "tʰʊŋ˧˥", "syllable_count": 1, "sentences": [{"text": "我和他同岁。", "target_word": "同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个人同姓。", "target_word": "同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们同一天来到这里。", "target_word": "同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐和我在同一所学校学习。", "target_word": "同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两件衣服同价，都是五十块。", "target_word": "同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两棵树同高。", "target_word": "同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和我同龄。", "target_word": "同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们俩同姓王。", "target_word": "同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和她同班。", "target_word": "同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥和我的生日是同一天。", "target_word": "同", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "同样", "label": "复合"}], "register": "书面语", "sense_fingerprint": "同:相同、一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fd271da-7053-4e94-b9bc-a929e14d7b33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86253, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "同", "is_correct": true, "explanation": "同（tóng）：形容词，相同、一样，没有不同。"}, {"text": "通", "is_correct": false, "explanation": "tōng（第一声）与 tóng（第二声）声调不同，意思是通。"}, {"text": "糖", "is_correct": false, "explanation": "táng 与 tóng 韵母不同（ang 与 ong），意思是糖。"}, {"text": "龙", "is_correct": false, "explanation": "lóng 与 tóng 声母不同（l 与 t），意思是龙。"}, {"text": "停", "is_correct": false, "explanation": "tíng 与 tóng 韵母不同（ing 与 ong），意思是停。"}, {"text": "痛", "is_correct": false, "explanation": "tòng（第四声）与 tóng（第二声）声调不同，意思是痛。"}, {"text": "疼", "is_correct": false, "explanation": "téng 与 tóng 韵母不同（eng 与 ong），意思是疼。"}], "explanations": {"同": "同（tóng）：形容词，相同、一样，没有不同。", "通": "tōng（第一声）与 tóng（第二声）声调不同，意思是通。", "糖": "táng 与 tóng 韵母不同（ang 与 ong），意思是糖。", "龙": "lóng 与 tóng 声母不同（l 与 t），意思是龙。", "停": "tíng 与 tóng 韵母不同（ing 与 ong），意思是停。", "痛": "tòng（第四声）与 tóng（第二声）声调不同，意思是痛。", "疼": "téng 与 tóng 韵母不同（eng 与 ong），意思是疼。"}, "sentence_index": null, "correct_answer": "同"}, "level_3": {"options": [{"text": "同", "is_correct": true, "explanation": "同：形容词，表示相同，此处说两人年龄相同。"}, {"text": "高", "is_correct": false, "explanation": "语义：“高”说身高，与“岁”的年龄语义不合，“高岁”不成立。"}, {"text": "远", "is_correct": false, "explanation": "搭配：“远”不能修饰年龄，“远岁”不搭配。"}, {"text": "快", "is_correct": false, "explanation": "搭配：“快”不能与“岁”搭配，无法表示年龄相同。"}], "explanations": {"同": "同：形容词，表示相同，此处说两人年龄相同。", "高": "语义：“高”说身高，与“岁”的年龄语义不合，“高岁”不成立。", "远": "搭配：“远”不能修饰年龄，“远岁”不搭配。", "快": "搭配：“快”不能与“岁”搭配，无法表示年龄相同。"}, "sentence_index": 0, "correct_answer": "同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我同妈妈一起买衣服。", "explanation": "这里的同是介词，表示跟某人一起，不表示相同。表示两者相同要用〈相同〉或〈一样〉。"}, {"text": "我同你都喜欢画画。", "explanation": "这里的同是连词，表示“和”，把两人并列，不表示相同。表示相同要用〈相同〉或〈一样〉。"}, {"text": "他同规定办事，很认真。", "explanation": "这里应该用〈按照〉。同在这里不表示相同，依据规定办事要用按照。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86253, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "同", "is_correct": true, "explanation": "同（tóng）：形容词，相同、一样，没有不同。"}, {"text": "统", "is_correct": false, "explanation": "tǒng（第三声）与 tóng（第二声）声调不同，意思是统一。"}, {"text": "农", "is_correct": false, "explanation": "nóng 与 tóng 声母不同（n 与 t），意思是农业、农民。"}, {"text": "堂", "is_correct": false, "explanation": "táng 与 tóng 韵母不同（ang 与 ong），意思是厅堂。"}, {"text": "腾", "is_correct": false, "explanation": "téng 与 tóng 韵母不同（eng 与 ong），意思是腾飞、翻腾。"}, {"text": "桶", "is_correct": false, "explanation": "tǒng（第三声）与 tóng（第二声）声调不同，意思是水桶。"}], "explanations": {"同": "同（tóng）：形容词，相同、一样，没有不同。", "统": "tǒng（第三声）与 tóng（第二声）声调不同，意思是统一。", "农": "nóng 与 tóng 声母不同（n 与 t），意思是农业、农民。", "堂": "táng 与 tóng 韵母不同（ang 与 ong），意思是厅堂。", "腾": "téng 与 tóng 韵母不同（eng 与 ong），意思是腾飞、翻腾。", "桶": "tǒng（第三声）与 tóng（第二声）声调不同，意思是水桶。"}, "sentence_index": null, "correct_answer": "同"}, "level_3": {"options": [{"text": "同", "is_correct": true, "explanation": "同：形容词，表示相同；“同龄”即年龄相同。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”是程度副词，不能直接修饰名词“龄”，“很龄”不成立。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”是程度副词，不能直接修饰名词“龄”，“非常龄”不成立。"}, {"text": "更", "is_correct": false, "explanation": "搭配：“更”是程度副词，不能直接修饰名词“龄”，“更龄”不成立。"}], "explanations": {"同": "同：形容词，表示相同；“同龄”即年龄相同。", "很": "搭配：“很”是程度副词，不能直接修饰名词“龄”，“很龄”不成立。", "非常": "搭配：“非常”是程度副词，不能直接修饰名词“龄”，“非常龄”不成立。", "更": "搭配：“更”是程度副词，不能直接修饰名词“龄”，“更龄”不成立。"}, "sentence_index": 6, "correct_answer": "同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师同学生很严格。", "explanation": "这里应该用〈对〉。同在这里不表示相同，对学生严格要用对。"}, {"text": "我同学校出发去超市。", "explanation": "这里应该用〈从〉。同不表示起点，从学校出发要用从。"}, {"text": "他同钥匙开了门。", "explanation": "这里应该用〈用〉。同不表示工具，用钥匙开门要用用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86253, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们两个很同岁。", "corrected_sentence": "他们两个同岁。", "error_description": "“同”作形容词表示相同，前面不能加“很”。应删去“很”，说“他们两个同岁”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86253, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两件衣服一同颜色。", "corrected_sentence": "这两件衣服同一颜色。", "error_description": "“同一”是固定搭配，“一同”是副词，不能修饰“颜色”。应说“同一颜色”，把“一”放在“同”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
