INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86254, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，表示和某人一起做某事，相当于“跟”。", "primary_collocate": null, "pronunciation": "tóng", "ipa": "tʰʊŋ˧˥", "syllable_count": 1, "sentences": [{"text": "我同他一起去学校。", "target_word": "同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她同老师聊了很久。", "target_word": "同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我同姐姐住在一起。", "target_word": "同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王同朋友去看电影。", "target_word": "同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他同我说了一件事。", "target_word": "同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你同大家说一下。", "target_word": "同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我同家人一起过年。", "target_word": "同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他同我商量了这件事。", "target_word": "同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他同我约好明天见面。", "target_word": "同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我同她是在北京认识的。", "target_word": "同", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "同:介词，表示跟、和某人一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fd271da-7053-4e94-b9bc-a929e14d7b33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86254, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "同", "is_correct": true, "explanation": "同（tóng）：介词，表示“跟”，引出一起做事的人。"}, {"text": "通", "is_correct": false, "explanation": "tōng（第一声）与 tóng（第二声）声调不同，意思是通。"}, {"text": "糖", "is_correct": false, "explanation": "táng 与 tóng 韵母不同（ang 与 ong），意思是糖。"}, {"text": "龙", "is_correct": false, "explanation": "lóng 与 tóng 声母不同（l 与 t），意思是龙。"}, {"text": "停", "is_correct": false, "explanation": "tíng 与 tóng 韵母不同（ing 与 ong），意思是停。"}, {"text": "痛", "is_correct": false, "explanation": "tòng（第四声）与 tóng（第二声）声调不同，意思是痛。"}, {"text": "疼", "is_correct": false, "explanation": "téng 与 tóng 韵母不同（eng 与 ong），意思是疼。"}], "explanations": {"同": "同（tóng）：介词，表示“跟”，引出一起做事的人。", "通": "tōng（第一声）与 tóng（第二声）声调不同，意思是通。", "糖": "táng 与 tóng 韵母不同（ang 与 ong），意思是糖。", "龙": "lóng 与 tóng 声母不同（l 与 t），意思是龙。", "停": "tíng 与 tóng 韵母不同（ing 与 ong），意思是停。", "痛": "tòng（第四声）与 tóng（第二声）声调不同，意思是痛。", "疼": "téng 与 tóng 韵母不同（eng 与 ong），意思是疼。"}, "sentence_index": null, "correct_answer": "同"}, "level_3": {"options": [{"text": "同", "is_correct": true, "explanation": "同：介词，表示“跟”，引出一起去学校的人。"}, {"text": "向", "is_correct": false, "explanation": "语义：“向”表示朝向或对象，句中“一起去”是共同行动，不能引出一起去的人。"}, {"text": "对", "is_correct": false, "explanation": "搭配：“对”要带针对的对象或态度，不能与“一起去学校”这种共同行动搭配。"}, {"text": "比", "is_correct": false, "explanation": "语义：“比”表示比较，句中没有比较的内容，句子不成立。"}], "explanations": {"同": "同：介词，表示“跟”，引出一起去学校的人。", "向": "语义：“向”表示朝向或对象，句中“一起去”是共同行动，不能引出一起去的人。", "对": "搭配：“对”要带针对的对象或态度，不能与“一起去学校”这种共同行动搭配。", "比": "语义：“比”表示比较，句中没有比较的内容，句子不成立。"}, "sentence_index": 0, "correct_answer": "同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小王同家出发去看电影。", "explanation": "这里应该用〈从〉。同表示跟某人一起，不引出起点；从某地出发要用从。"}, {"text": "小王同电影院走去看电影。", "explanation": "这里应该用〈向〉。同不表示朝向，走向某处要用向。"}, {"text": "小王同客厅看电影。", "explanation": "这里应该用〈在〉。同不表示处所，在某处做事要用在。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86254, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "同", "is_correct": true, "explanation": "同（tóng）：介词，表示“跟”，引出一起做事的人。"}, {"text": "统", "is_correct": false, "explanation": "tǒng（第三声）与 tóng（第二声）声调不同，意思是统一。"}, {"text": "农", "is_correct": false, "explanation": "nóng 与 tóng 声母不同（n 与 t），意思是农业、农民。"}, {"text": "堂", "is_correct": false, "explanation": "táng 与 tóng 韵母不同（ang 与 ong），意思是厅堂。"}, {"text": "腾", "is_correct": false, "explanation": "téng 与 tóng 韵母不同（eng 与 ong），意思是腾飞、翻腾。"}, {"text": "桶", "is_correct": false, "explanation": "tǒng（第三声）与 tóng（第二声）声调不同，意思是水桶。"}], "explanations": {"同": "同（tóng）：介词，表示“跟”，引出一起做事的人。", "统": "tǒng（第三声）与 tóng（第二声）声调不同，意思是统一。", "农": "nóng 与 tóng 声母不同（n 与 t），意思是农业、农民。", "堂": "táng 与 tóng 韵母不同（ang 与 ong），意思是厅堂。", "腾": "téng 与 tóng 韵母不同（eng 与 ong），意思是腾飞、翻腾。", "桶": "tǒng（第三声）与 tóng（第二声）声调不同，意思是水桶。"}, "sentence_index": null, "correct_answer": "同"}, "level_3": {"options": [{"text": "同", "is_correct": true, "explanation": "同：介词，表示“跟”，引出一起过年的家人。"}, {"text": "从", "is_correct": false, "explanation": "语义：“从”表示起点，与“一起过年”这种共同行为不合。"}, {"text": "把", "is_correct": false, "explanation": "配价：“把”字句需要“把＋宾语＋动词”，“把家人一起过年”结构不成立。"}, {"text": "被", "is_correct": false, "explanation": "配价：“被”需要施事者与动作，“被家人一起过年”的语义不成立。"}], "explanations": {"同": "同：介词，表示“跟”，引出一起过年的家人。", "从": "语义：“从”表示起点，与“一起过年”这种共同行为不合。", "把": "配价：“把”字句需要“把＋宾语＋动词”，“把家人一起过年”结构不成立。", "被": "配价：“被”需要施事者与动作，“被家人一起过年”的语义不成立。"}, "sentence_index": 6, "correct_answer": "同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他同规定办事，很认真。", "explanation": "这里应该用〈按照〉。同不表示依据，按规定办事要用按照。"}, {"text": "他同筷子吃饭，吃得很快。", "explanation": "这里应该用〈用〉。同只引出一起做事的人，不引出工具；用工具做事要用用。"}, {"text": "我同电话通知了他。", "explanation": "这里应该用〈通过〉。同不表示媒介，通过电话通知要用通过。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86254, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我同了朋友一起去超市。", "corrected_sentence": "我同朋友一起去超市。", "error_description": "错误：“同”是介词，后面不能加“了”。应删去“了”，说“我同朋友一起去超市。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86254, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我同和爸爸一起去钓鱼。", "corrected_sentence": "我同爸爸一起去钓鱼。", "error_description": "“同”和“和”都是介词，不能叠用。应删去多余的“和”，说“我同爸爸一起去钓鱼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86255, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "打开", "is_correct": true, "explanation": "反义：“打开”与“关闭”相对，指使电脑重新开启，与本句动作相反。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：“唱歌”与“关闭”没有反义关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "无关：“吃饭”与“关闭”在任何义项上都不构成反义关系。"}, {"text": "写作", "is_correct": false, "explanation": "无关：“写作”与“关闭”没有反义关系。"}], "correct_answer": "打开", "explanations": {"打开": "反义：“打开”与“关闭”相对，指使电脑重新开启，与本句动作相反。", "唱歌": "无关：“唱歌”与“关闭”没有反义关系。", "吃饭": "无关：“吃饭”与“关闭”在任何义项上都不构成反义关系。", "写作": "无关：“写作”与“关闭”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e65b8434-e0fe-4d9e-83e1-4929ab504216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86255, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "开启", "is_correct": true, "explanation": "反义：“开启”与“关闭”相对，指使网页重新打开，与本句动作相反。"}, {"text": "散步", "is_correct": false, "explanation": "无关：“散步”与“关闭”没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "无关：“思考”与“关闭”在任何义项上都不构成反义关系。"}, {"text": "学习", "is_correct": false, "explanation": "无关：“学习”与“关闭”没有反义关系。"}], "correct_answer": "开启", "explanations": {"开启": "反义：“开启”与“关闭”相对，指使网页重新打开，与本句动作相反。", "散步": "无关：“散步”与“关闭”没有反义关系。", "思考": "无关：“思考”与“关闭”在任何义项上都不构成反义关系。", "学习": "无关：“学习”与“关闭”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e65b8434-e0fe-4d9e-83e1-4929ab504216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86255, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "关闭是把开着的东西合上。", "primary_collocate": null, "pronunciation": "guān bì", "ipa": "kwan˥ pi˥˩", "syllable_count": 2, "sentences": [{"text": "睡觉前请关闭电视。", "target_word": "关闭", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他关闭了房间的窗户。", "target_word": "关闭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把门关闭，外面很冷。", "target_word": "关闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她关闭电脑，走出办公室。", "target_word": "关闭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机上要关闭手机。", "target_word": "关闭", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "出门前，我关闭了所有的灯。", "target_word": "关闭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用完水，请关闭水龙头。", "target_word": "关闭", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他关闭了房门，开始看书。", "target_word": "关闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师关闭了教室的门。", "target_word": "关闭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以关闭这个网页吗？", "target_word": "关闭", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "关闭了", "label": "体标"}, {"form": "关闭过", "label": "体标"}, {"form": "關閉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把门、窗、电器等开着的东西合上或关掉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39686117-ff5b-4662-b33e-7c30377afa02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86255, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "关闭", "is_correct": true, "explanation": "“关闭”指使电视停止工作，与“睡觉前”的语境相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，不能说唱电视。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣服、鞋袜，不说穿电视。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”的对象是食物或水，不能用于电视。"}], "explanations": {"关闭": "“关闭”指使电视停止工作，与“睡觉前”的语境相符。", "唱": "语义：“唱”的对象是歌曲，不能说唱电视。", "穿": "搭配：“穿”用于衣服、鞋袜，不说穿电视。", "煮": "语义：“煮”的对象是食物或水，不能用于电视。"}, "sentence_index": 0, "correct_answer": "关闭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他关闭了雨伞，走进屋里。", "explanation": "这里应该用〈收起〉。撑开的雨伞要说收起，关闭用于门窗、电器等可以开合或开关的事物。"}, {"text": "她关闭了眼睛，慢慢地睡着了。", "explanation": "这里应该用〈闭上〉。眼睛要说闭上，关闭用于门窗、电器等可以开合或开关的事物。"}, {"text": "他关闭了课本，开始做作业。", "explanation": "这里应该用〈合上〉。书本要说合上，关闭用于门窗、电器等可以开合或开关的事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e65b8434-e0fe-4d9e-83e1-4929ab504216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86255, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关闭", "is_correct": true, "explanation": "“关闭”指拧紧水龙头、停止出水，与“用完水”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，水龙头不能被“吃”。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”用于帽子、手表等，不说戴水龙头。"}, {"text": "飞", "is_correct": false, "explanation": "语义：“飞”指在空中移动，与水龙头无关，句意不通。"}], "explanations": {"关闭": "“关闭”指拧紧水龙头、停止出水，与“用完水”的语境相符。", "吃": "语义：“吃”的对象是食物，水龙头不能被“吃”。", "戴": "搭配：“戴”用于帽子、手表等，不说戴水龙头。", "飞": "语义：“飞”指在空中移动，与水龙头无关，句意不通。"}, "sentence_index": 6, "correct_answer": "关闭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他关闭了桌上的蜡烛，房间里一片漆黑。", "explanation": "这里应该用〈熄灭〉。蜡烛要说熄灭或吹灭，关闭用于门窗、电器、水龙头等可以开合的物件。"}, {"text": "他关闭了嘴巴，不再说话。", "explanation": "这里应该用〈闭上〉。嘴巴、眼睛要说闭上，关闭用于门窗、电器、水龙头等可以开合或开关的事物。"}, {"text": "他关闭了书包的拉链，背着出了门。", "explanation": "这里应该用〈拉上〉。拉链要说拉上，关闭用于门窗、电器、水龙头等可以开合或开关的事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e65b8434-e0fe-4d9e-83e1-4929ab504216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86255, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她关闭上门，走出了房间。", "corrected_sentence": "她关闭了门，走出了房间。", "error_description": "错误形式：关闭上。正确形式：关闭。原因：“关闭”本身已表示合上，不再接结果补语“上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e65b8434-e0fe-4d9e-83e1-4929ab504216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86255, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把水龙头关闭上了。", "corrected_sentence": "他把水龙头关闭了。", "error_description": "错误形式：关闭上了。正确形式：关闭了。原因：“关闭”本身已表示合上，不能再接结果补语“上”，多加的“上”是多余成分。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e65b8434-e0fe-4d9e-83e1-4929ab504216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
