INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86258, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "了结；解决（心事、债务等）。", "primary_collocate": null, "pronunciation": "liǎo què", "ipa": "ljɑʊ̯˨˩˦ tɕʰɥɛ˥˩", "syllable_count": 2, "sentences": [{"text": "他终于了却了多年的心愿。", "target_word": "了却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈想在退休前了却这桩心事。", "target_word": "了却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人把最后一笔债务了却了，心里很轻松。", "target_word": "了却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想早点了却这件麻烦事，好安心过年。", "target_word": "了却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场多年的恩怨，终于了却了。", "target_word": "了却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一直想了却父亲留下的遗愿。", "target_word": "了却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "了却这桩旧案以后，警察松了一口气。", "target_word": "了却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临走前，他想了却对朋友的亏欠。", "target_word": "了却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬进新家，了却了奶奶多年的牵挂。", "target_word": "了却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他还清了贷款，了却一块心病。", "target_word": "了却", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "了却了", "label": "体标"}], "register": "书面语", "sense_fingerprint": "了结、解决心事、债务、恩怨等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39686117-ff5b-4662-b33e-7c30377afa02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86258, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "了却", "is_correct": true, "explanation": "“了却”指心愿等了结、实现，与“多年的心愿”搭配，句意通顺。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，不能用于心愿，句意不通。"}, {"text": "开", "is_correct": false, "explanation": "搭配：“开”不与“心愿”搭配，不说开心愿。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”的对象是物体或身体，不能用于心愿。"}], "explanations": {"了却": "“了却”指心愿等了结、实现，与“多年的心愿”搭配，句意通顺。", "吃": "语义：“吃”的对象是食物，不能用于心愿，句意不通。", "开": "搭配：“开”不与“心愿”搭配，不说开心愿。", "洗": "语义：“洗”的对象是物体或身体，不能用于心愿。"}, "sentence_index": 0, "correct_answer": "了却"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于了却了自己的能力，大家都很佩服。", "explanation": "这里应该用〈证明〉。了却只指心事、债务等的了结，不能说了却能力。"}, {"text": "牙膏已经了却了，他就去上学了。", "explanation": "这里应该用〈用完〉。了却多指心事、心愿、债务的了结，牙膏要说用完。"}, {"text": "他每天了却锻炼身体，身体越来越好。", "explanation": "这里应该用〈坚持〉。了却只指心事、债务等的了结，锻炼要说坚持。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e65b8434-e0fe-4d9e-83e1-4929ab504216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86258, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "了却", "is_correct": true, "explanation": "“了却”指把旧案了结，与后句“警察松了一口气”相配。"}, {"text": "拍", "is_correct": false, "explanation": "语义：“拍”不能用于案件，“拍这桩旧案”句意不通。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的对象是衣服、鞋袜，不说穿案子。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是饮品，不能用于旧案。"}], "explanations": {"了却": "“了却”指把旧案了结，与后句“警察松了一口气”相配。", "拍": "语义：“拍”不能用于案件，“拍这桩旧案”句意不通。", "穿": "搭配：“穿”的对象是衣服、鞋袜，不说穿案子。", "喝": "语义：“喝”的对象是饮品，不能用于旧案。"}, "sentence_index": 6, "correct_answer": "了却"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把桌上的旧报纸全部了却了。", "explanation": "这里应该用〈清除〉。了却指心事、债务等的了结，旧报纸等实物要说清除。"}, {"text": "他去年了却了一部纪录片。", "explanation": "这里应该用〈拍摄〉。了却不用于制作影视作品，拍纪录片要说拍摄。"}, {"text": "他把卧室了却了一遍。", "explanation": "这里应该用〈打扫〉。了却不指清扫房间，打扫卧室要说打扫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e65b8434-e0fe-4d9e-83e1-4929ab504216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86258, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于了却了了这桩心事。", "corrected_sentence": "他终于了却了这桩心事。", "error_description": "错误形式：了却了了。正确形式：了却了。原因：一个动作只用一个“了”，“了却了”后面不能再加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e65b8434-e0fe-4d9e-83e1-4929ab504216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86258, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他总算了却着这桩心事。", "corrected_sentence": "他总算了却了这桩心事。", "error_description": "错误形式：了却着。正确形式：了却了。原因：“了却”表示心事已经了结，是完成性动作，不能再加表示持续的“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e65b8434-e0fe-4d9e-83e1-4929ab504216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
