INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86259, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做出成果、贡献等具体的东西。", "primary_collocate": null, "pronunciation": "zuò chū", "ipa": "tswo˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "他为公司作出了很大的贡献。", "target_word": "作出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王在工作中作出了好成绩。", "target_word": "作出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师为学生作出了很多努力。", "target_word": "作出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生们为救人作出了很大的牺牲。", "target_word": "作出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位科学家作出了重要的发现。", "target_word": "作出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为国家作出过很多贡献。", "target_word": "作出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在为这件事作出努力。", "target_word": "作出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她作出的成绩让大家很高兴。", "target_word": "作出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些年，他作出了不少成果。", "target_word": "作出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要向作出贡献的人学习。", "target_word": "作出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "作出了", "label": "完成体"}, {"form": "作出过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "作出：做出成果、贡献等具体的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528460c6-b68d-4819-9976-ec879930a8cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86259, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作出", "is_correct": true, "explanation": "正确：“作出贡献”表示做出了有益的事，与句意相符。"}, {"text": "提出", "is_correct": false, "explanation": "搭配：“提出”的宾语是意见、问题、要求，不能说“提出贡献”。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：“吃掉”指把东西咽下去，与“贡献”无关。"}, {"text": "看见", "is_correct": false, "explanation": "语义：“看见”指用眼睛看到，不能作用于“贡献”。"}], "explanations": {"作出": "正确：“作出贡献”表示做出了有益的事，与句意相符。", "提出": "搭配：“提出”的宾语是意见、问题、要求，不能说“提出贡献”。", "吃掉": "语义：“吃掉”指把东西咽下去，与“贡献”无关。", "看见": "语义：“看见”指用眼睛看到，不能作用于“贡献”。"}, "sentence_index": 0, "correct_answer": "作出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "门突然作出了一声巨响。", "explanation": "这里应该用〈发出〉。作出用于做出成果、贡献等，声音要说“发出”。"}, {"text": "他提前作出了任务。", "explanation": "这里应该用〈完成〉。作出的对象是成果，任务要说“完成”。"}, {"text": "他在会上作出了一个哈欠。", "explanation": "这里应该用〈打〉。作出用于成果、贡献等，哈欠要说“打”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86259, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作出", "is_correct": true, "explanation": "正确：“作出努力”表示尽力去做，与句意相符。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃努力”与“大家都在为这件事”的意思相反。"}, {"text": "推迟", "is_correct": false, "explanation": "语义：“推迟”指把时间往后延，与“努力”无关。"}, {"text": "反驳", "is_correct": false, "explanation": "语义：“反驳”指用理由驳斥别人的观点，与“努力”无关。"}], "explanations": {"作出": "正确：“作出努力”表示尽力去做，与句意相符。", "放弃": "语义：“放弃努力”与“大家都在为这件事”的意思相反。", "推迟": "语义：“推迟”指把时间往后延，与“努力”无关。", "反驳": "语义：“反驳”指用理由驳斥别人的观点，与“努力”无关。"}, "sentence_index": 6, "correct_answer": "作出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场火灾作出了很大的损失。", "explanation": "这里应该用〈造成〉。作出用于做出成果、贡献，损失要说“造成”。"}, {"text": "他作出了一个冠军。", "explanation": "这里应该用〈获得〉。作出用于成果、贡献，冠军要说“获得”。"}, {"text": "这项政策作出了很多好处。", "explanation": "这里应该用〈带来〉。作出用于成果、贡献，好处要说“带来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86259, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他为学校没作出了很大的努力。", "corrected_sentence": "他为学校没作出很大的努力。", "error_description": "体标错误：“没”否定的动作不能再加“了”，“作出”后不用“了”，应说“没作出很大的努力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
