INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86260, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做出；制定、提出（决定、反应等）。", "primary_collocate": null, "pronunciation": "zuò chū", "ipa": "tswo˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "经理今天作出了一个重要的决定。", "target_word": "作出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个消息，他马上作出了反应。", "target_word": "作出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请她对这个问题作出回答。", "target_word": "作出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生很快作出了正确的判断。", "target_word": "作出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要先想好，再作出选择。", "target_word": "作出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司已经作出了新的安排。", "target_word": "作出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他作出过很多重要的决定。", "target_word": "作出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校对这件事还没有作出说明。", "target_word": "作出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在等他作出最后的回答。", "target_word": "作出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家对天气作出了新的预测。", "target_word": "作出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "作出了", "label": "完成体"}, {"form": "作出过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "作出：提出或制定决定、反应、回答、判断等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528460c6-b68d-4819-9976-ec879930a8cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86260, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作出", "is_correct": true, "explanation": "正确：“作出决定”表示经过考虑后做出决定，与句意相符。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”的宾语是待遇、生活等，不能说“享受决定”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下，与“决定”无关。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，无法用于“决定”。"}], "explanations": {"作出": "正确：“作出决定”表示经过考虑后做出决定，与句意相符。", "享受": "搭配：“享受”的宾语是待遇、生活等，不能说“享受决定”。", "吃": "语义：“吃”指把食物咽下，与“决定”无关。", "唱": "语义：“唱”指发出歌声，无法用于“决定”。"}, "sentence_index": 0, "correct_answer": "作出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她向大家作出了一个问题。", "explanation": "这里应该用〈提出〉。作出用于决定、反应、回答、判断，问题要说“提出”。"}, {"text": "他昨晚作出了一封信。", "explanation": "这里应该用〈写〉。作出用于决定、反应、判断等，信要说“写”。"}, {"text": "学校作出了一场比赛。", "explanation": "这里应该用〈举行〉。作出用于决定、判断等，比赛要说“举行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86260, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作出", "is_correct": true, "explanation": "正确：“作出过”表示有过做出决定的经历，与句意相符。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”指把液体咽下，与“决定”不搭。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”指用脚击打，与“决定”无关。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车、船、飞机等，不能说“驾驶决定”。"}], "explanations": {"作出": "正确：“作出过”表示有过做出决定的经历，与句意相符。", "喝": "语义：“喝”指把液体咽下，与“决定”不搭。", "踢": "语义：“踢”指用脚击打，与“决定”无关。", "驾驶": "搭配：“驾驶”的对象是车、船、飞机等，不能说“驾驶决定”。"}, "sentence_index": 6, "correct_answer": "作出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他按时作出了作业。", "explanation": "这里应该用〈完成〉。作出用于决定、判断、回答等，作业要说“完成”。"}, {"text": "班长作出了一次活动。", "explanation": "这里应该用〈组织〉。作出用于决定、判断等，活动要说“组织”。"}, {"text": "我们作出了一次决赛。", "explanation": "这里应该用〈举行〉。作出用于决定、判断等，决赛要说“举行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
