INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86261, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "嗯是一个小声的回答，表示好或者知道了。", "primary_collocate": null, "pronunciation": "èn", "ipa": "ən˥˩", "syllable_count": 1, "sentences": [{"text": "她小声说：“嗯，我知道了。”", "target_word": "嗯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“别忘了带伞。”“嗯，我记住了。”", "target_word": "嗯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子低着头，轻轻地“嗯”了一声。", "target_word": "嗯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“早点睡。”“嗯，晚安。”", "target_word": "嗯", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他小声回答：“嗯，好的。”", "target_word": "嗯", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "“明天早上七点起床。”“嗯，知道了。”", "target_word": "嗯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈叫她吃饭，妹妹看着书，只“嗯”了一下。", "target_word": "嗯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话里，奶奶说：“嗯，我听到了。”", "target_word": "嗯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“路上小心。”“嗯，你放心。”", "target_word": "嗯", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师叫他的名字，他小声“嗯”了一下。", "target_word": "嗯", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "叹词，小声回答，表示好或知道了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eb6a069-3cc9-4bff-bb63-1f24166f25c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86261, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "嗯", "is_correct": true, "explanation": "嗯 èn 是叹词，小声应答时表示好或知道了，即本义项。"}, {"text": "恩", "is_correct": false, "explanation": "恩 ēn 为第一声，与 èn（第四声）声调不同，意思是恩惠、恩情。"}, {"text": "按", "is_correct": false, "explanation": "按 àn 与 èn 韵母不同（an 与 en），意思是用手压或依照。"}, {"text": "案", "is_correct": false, "explanation": "案 àn 与 èn 韵母不同（an 与 en），意思是方案或案件。"}, {"text": "暗", "is_correct": false, "explanation": "暗 àn 与 èn 韵母不同（an 与 en），意思是光线不足。"}], "explanations": {"嗯": "嗯 èn 是叹词，小声应答时表示好或知道了，即本义项。", "恩": "恩 ēn 为第一声，与 èn（第四声）声调不同，意思是恩惠、恩情。", "按": "按 àn 与 èn 韵母不同（an 与 en），意思是用手压或依照。", "案": "案 àn 与 èn 韵母不同（an 与 en），意思是方案或案件。", "暗": "暗 àn 与 èn 韵母不同（an 与 en），意思是光线不足。"}, "sentence_index": null, "correct_answer": "嗯"}, "level_3": {"options": [{"text": "嗯", "is_correct": true, "explanation": "“嗯”是小声的应答，与“我知道了”的意思一致，可以填入。"}, {"text": "哇", "is_correct": false, "explanation": "语义：哇表示惊叹，与平静的“我知道了”不符。"}, {"text": "喂", "is_correct": false, "explanation": "语义：喂用来招呼或打电话时引起注意，并不表示知道了。"}, {"text": "唯", "is_correct": false, "explanation": "语域：唯是书面语应答词，与口语的小声回答语域不合。"}], "explanations": {"嗯": "“嗯”是小声的应答，与“我知道了”的意思一致，可以填入。", "哇": "语义：哇表示惊叹，与平静的“我知道了”不符。", "喂": "语义：喂用来招呼或打电话时引起注意，并不表示知道了。", "唯": "语域：唯是书面语应答词，与口语的小声回答语域不合。"}, "sentence_index": 0, "correct_answer": "嗯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我推开门，他抬起头，惊讶地“嗯”了一声。", "explanation": "这里的“嗯”是吃惊时发出的声音，不是小声表示好或知道了。"}, {"text": "他看了一眼账单，皱着眉“嗯”地哼了一声，显然对价格不满。", "explanation": "这里的“嗯”是不满时的哼声，不表示好或知道了。"}, {"text": "他撞到了桌角，一边揉着腿，一边“嗯”地哼了一声。", "explanation": "这里的“嗯”是疼痛时的哼声，不表示好或知道了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f0c2dc0-701e-4d12-98e2-361ee568df0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86261, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嗯", "is_correct": true, "explanation": "妈妈叫她，她小声应答表示知道了，用“嗯”。"}, {"text": "呸", "is_correct": false, "explanation": "语域：呸是粗俗的唾弃声，与描写平静看书的口语叙述不合。"}, {"text": "咦", "is_correct": false, "explanation": "语义：咦表示惊讶，与看书时的平静情景不符。"}, {"text": "嘿", "is_correct": false, "explanation": "语义：嘿用来招呼或引起注意，与“看着书”时的回应不符。"}], "explanations": {"嗯": "妈妈叫她，她小声应答表示知道了，用“嗯”。", "呸": "语域：呸是粗俗的唾弃声，与描写平静看书的口语叙述不合。", "咦": "语义：咦表示惊讶，与看书时的平静情景不符。", "嘿": "语义：嘿用来招呼或引起注意，与“看着书”时的回应不符。"}, "sentence_index": 6, "correct_answer": "嗯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他盯着窗外，心不在焉地“嗯”了一声，不知道在想什么。", "explanation": "这里的“嗯”是走神时漫不经心的哼声，不表示好或知道了。"}, {"text": "他拉着妈妈的袖子，撒娇地“嗯”了几声，不肯松手。", "explanation": "这里的“嗯”是撒娇时拖长的鼻音，不表示好或知道了。"}, {"text": "考试又没考好，他低着头，无奈地“嗯”了一声，半天没说话。", "explanation": "这里的“嗯”是无奈时的叹息声，不表示好或知道了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f0c2dc0-701e-4d12-98e2-361ee568df0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86261, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他小声“嗯”了一个，表示知道了。", "corrected_sentence": "他小声“嗯”了一下，表示知道了。", "error_description": "“嗯”的动量词应为“下”或“声”，不能用“个”。错误形式：嗯了一个；正确形式：嗯了一下。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f0c2dc0-701e-4d12-98e2-361ee568df0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86261, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他小声“嗯”了一个，就低头看书了。", "corrected_sentence": "他小声“嗯”了一下，就低头看书了。", "error_description": "“嗯”的动量词应用“下”或“声”，不能用“个”。错误形式：嗯了一个；正确形式：嗯了一下。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f0c2dc0-701e-4d12-98e2-361ee568df0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
