INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86264, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城市和集镇的合称。", "primary_collocate": null, "pronunciation": "chéng zhèn", "ipa": "ʈʂʰɤŋ˧˥ ʈʂən˥˩", "syllable_count": 2, "sentences": [{"text": "城镇和农村的生活方式不一样。", "target_word": "城镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府正在改善城镇的道路。", "target_word": "城镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城镇人口已经超过了农村人口。", "target_word": "城镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个省的城镇居民收入提高了。", "target_word": "城镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家要让城镇和农村一起发展。", "target_word": "城镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城镇居民每月都要交水费。", "target_word": "城镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全国很多城镇地区都建了新医院。", "target_word": "城镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城镇的住房价格比去年高。", "target_word": "城镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近年来，城镇的空气质量更好了。", "target_word": "城镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府给城镇的老人提供免费检查。", "target_word": "城镇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "城镇化", "label": "复合"}, {"form": "城镇居民", "label": "复合"}, {"form": "城镇人口", "label": "复合"}], "register": "书面", "sense_fingerprint": "与农村相对的城市和集镇的合称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f0846f6-3efb-40f5-acd6-084c548b4338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86264, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "城镇", "is_correct": true, "explanation": "指城市和集镇，与“农村”相对，正好作主语。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不是地方，不能和农村比较生活方式，句子不通。"}, {"text": "数字", "is_correct": false, "explanation": "语义：数字是符号，没有生活方式，句子不通。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不是人口聚居的地区，和农村不能比较生活方式。"}], "explanations": {"城镇": "指城市和集镇，与“农村”相对，正好作主语。", "面包": "语义：面包是食物，不是地方，不能和农村比较生活方式，句子不通。", "数字": "语义：数字是符号，没有生活方式，句子不通。", "海洋": "语义：海洋不是人口聚居的地区，和农村不能比较生活方式。"}, "sentence_index": 0, "correct_answer": "城镇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "北京是一座古老的城镇。", "explanation": "这里应该用〈城市〉。城镇是城市和集镇的合称，指一类地区；北京是具体的城市，应说“城市”。"}, {"text": "重庆是一座直辖城镇，面积很大。", "explanation": "这里应该用〈直辖市〉。“直辖”只与“市”组成固定说法，指由中央直接管辖的城市；城镇是城市和集镇的合称，不能说“直辖城镇”。"}, {"text": "纽约是一座国际化的城镇。", "explanation": "这里应该用〈都市〉。城镇泛指城市和集镇，纽约这样的国际大都市应说“都市”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76e947d0-9fe6-4584-890c-3d3c79f35bff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86264, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "城镇", "is_correct": true, "explanation": "指城市和集镇，是能建医院的地区，符合句意。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是人口聚居的地方，不能“建了新医院”。"}, {"text": "山脉", "is_correct": false, "explanation": "语义：山脉是地形，不是可以建医院的地区。"}, {"text": "森林", "is_correct": false, "explanation": "搭配：“森林”指植物群落，不说“建了新医院”。"}], "explanations": {"城镇": "指城市和集镇，是能建医院的地区，符合句意。", "河流": "语义：河流不是人口聚居的地方，不能“建了新医院”。", "山脉": "语义：山脉是地形，不是可以建医院的地区。", "森林": "搭配：“森林”指植物群落，不说“建了新医院”。"}, "sentence_index": 6, "correct_answer": "城镇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "东京是一座国际城镇。", "explanation": "这里应该用〈大都会〉。城镇泛指城市和集镇，东京是单独的一座大城市，不能用“城镇”指称。"}, {"text": "中国的首都是一座古老的城镇。", "explanation": "这里应该用〈城市〉。城镇是城市和集镇的合称，指一类地区，不能用来指称一座具体的首都。"}, {"text": "广州是一座城镇，人口很多。", "explanation": "这里应该用〈大城市〉。城镇是城市和集镇的合称，不用来指广州这样一个大城市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76e947d0-9fe6-4584-890c-3d3c79f35bff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86264, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "河边有一条小城镇。", "corrected_sentence": "河边有一座小城镇。", "error_description": "量词错误：“城镇”用量词“座”，不用“条”。正确说法：河边有一座小城镇。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76e947d0-9fe6-4584-890c-3d3c79f35bff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86264, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "城镇们的公园越来越多了。", "corrected_sentence": "城镇的公园越来越多了。", "error_description": "“们”只用于指人的名词，“城镇”不能加“们”。正确说法：城镇的公园越来越多了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76e947d0-9fe6-4584-890c-3d3c79f35bff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
