INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86267, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "梦想是你很想做到的事。", "primary_collocate": null, "pronunciation": "mèng xiǎng", "ipa": "mɤŋ˥˩ ɕiaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我的梦想是开一家小饭店。", "target_word": "梦想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的梦想是环游世界。", "target_word": "梦想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟的梦想是当足球运动员。", "target_word": "梦想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的梦想是什么？", "target_word": "梦想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说，她的梦想是有一个大花园。", "target_word": "梦想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都有各自的梦想。", "target_word": "梦想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，我的梦想是当老师。", "target_word": "梦想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的梦想是带全家去海边住一个月。", "target_word": "梦想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个梦想很大，但我一定要做到。", "target_word": "梦想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他终于实现了多年的梦想。", "target_word": "梦想", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "梦想家", "label": "复合"}, {"form": "夢想", "label": "繁体"}], "register": "中性", "sense_fingerprint": "自己很想做到的一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717e23d-bca9-41d2-953d-d55f3fb7f070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86267, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "梦想", "is_correct": true, "explanation": "正确：「梦想」（mèng xiǎng），指自己很想做到的一件事。"}, {"text": "梦乡", "is_correct": false, "explanation": "xiāng（第一声）与 xiǎng（第三声）声调不同，意思是睡梦中的境界。"}, {"text": "闷响", "is_correct": false, "explanation": "mèn 与 mèng 韵母不同（en 与 eng），意思是沉闷的响声。"}, {"text": "冥想", "is_correct": false, "explanation": "míng 与 mèng 韵母、声调不同，意思是安静地深思、打坐。"}], "explanations": {"梦想": "正确：「梦想」（mèng xiǎng），指自己很想做到的一件事。", "梦乡": "xiāng（第一声）与 xiǎng（第三声）声调不同，意思是睡梦中的境界。", "闷响": "mèn 与 mèng 韵母不同（en 与 eng），意思是沉闷的响声。", "冥想": "míng 与 mèng 韵母、声调不同，意思是安静地深思、打坐。"}, "sentence_index": null, "correct_answer": "梦想"}, "level_3": {"options": [{"text": "梦想", "is_correct": true, "explanation": "正确：「我的梦想是开一家小饭店」，「梦想」指自己很想做到的事，与句意相符。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：「体重」指身体的重量，不能说成「是开一家小饭店」。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：「身高」指身体的高度，不能说成要做的事。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」是事物的色彩，与「开一家小饭店」这种行为无关。"}], "explanations": {"梦想": "正确：「我的梦想是开一家小饭店」，「梦想」指自己很想做到的事，与句意相符。", "体重": "体貌：「体重」指身体的重量，不能说成「是开一家小饭店」。", "身高": "体貌：「身高」指身体的高度，不能说成要做的事。", "颜色": "语义：「颜色」是事物的色彩，与「开一家小饭店」这种行为无关。"}, "sentence_index": 0, "correct_answer": "梦想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他给我提了一个很好的梦想。", "explanation": "这里应该用〈建议〉。提的是建议、意见，梦想指对未来的美好愿望，不能用「提」。"}, {"text": "他常常做同一个梦想。", "explanation": "这里应该用〈梦〉。梦想指自己很想做到的事，不指睡觉时的梦境。"}, {"text": "她养成了早起的梦想。", "explanation": "这里应该用〈习惯〉。梦想指想做到的事，不指日常重复的行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86267, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "梦想", "is_correct": true, "explanation": "正确：「小时候，我的梦想是当老师」，「梦想」指想做到的事，与句意相符。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：「年龄」是年数，不能说成「是当老师」。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：「成绩」指考试结果，不能说成「是当老师」。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：「脾气」指性情，不能说成想做到的一件事。"}], "explanations": {"梦想": "正确：「小时候，我的梦想是当老师」，「梦想」指想做到的事，与句意相符。", "年龄": "语义：「年龄」是年数，不能说成「是当老师」。", "成绩": "搭配：「成绩」指考试结果，不能说成「是当老师」。", "脾气": "语义：「脾气」指性情，不能说成想做到的一件事。"}, "sentence_index": 6, "correct_answer": "梦想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的梦想吃了三碗饭，还想再来一碗。", "explanation": "这里应该用〈胃口〉。梦想指自己很想做到的事，不能用来说吃饭的量，要用胃口。"}, {"text": "这盘梦想炒得很香，大家都想尝一口。", "explanation": "这里应该用〈菜〉。梦想指自己很想做到的事，不能用来指炒好的菜。"}, {"text": "他做了一个奇怪的梦想。", "explanation": "这里应该用〈梦〉。梦想指想做到的事，不指睡觉时的梦境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86267, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一只梦想：当一名警察。", "corrected_sentence": "我有一个梦想：当一名警察。", "error_description": "错误：「一只梦想」；正确：「一个梦想」。「只」多用于动物，抽象的「梦想」应搭配量词「个」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86267, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她终于实现了儿时地梦想。", "corrected_sentence": "她终于实现了儿时的梦想。", "error_description": "错误：「儿时地梦想」；正确：「儿时的梦想」。「儿时」作定语修饰「梦想」，要用「的」；「地」用于动词前作状语，不能修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86268, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现实", "is_correct": true, "explanation": "反义：「现实」指客观存在的事实，与「梦想」这种尚未实现的美好愿望相对。"}, {"text": "石头", "is_correct": false, "explanation": "无关：「石头」是矿物，与「梦想」没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "无关：「河流」是地理事物，与「梦想」没有反义关系。"}, {"text": "椅子", "is_correct": false, "explanation": "无关：「椅子」是家具，与「梦想」没有反义关系。"}], "correct_answer": "现实", "explanations": {"现实": "反义：「现实」指客观存在的事实，与「梦想」这种尚未实现的美好愿望相对。", "石头": "无关：「石头」是矿物，与「梦想」没有反义关系。", "河流": "无关：「河流」是地理事物，与「梦想」没有反义关系。", "椅子": "无关：「椅子」是家具，与「梦想」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
