INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86268, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对未来的美好愿望；强烈的理想。", "primary_collocate": null, "pronunciation": "mèng xiǎng", "ipa": "mɤŋ˥˩ ɕiaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我的梦想是当一名医生。", "target_word": "梦想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就有一个当画家的梦想。", "target_word": "梦想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了实现梦想，她每天努力练习。", "target_word": "梦想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人应该有自己的梦想。", "target_word": "梦想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的梦想终于变成了现实。", "target_word": "梦想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要放弃你的梦想，继续努力吧。", "target_word": "梦想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她带着环游世界的梦想来到了这里。", "target_word": "梦想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小女孩的梦想是飞上太空。", "target_word": "梦想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有梦想的人，生活会更有力量。", "target_word": "梦想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师常说，大家要为梦想努力。", "target_word": "梦想", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "梦想家", "label": "复合"}, {"form": "夢想", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对未来的美好理想，值得为之努力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717e23d-bca9-41d2-953d-d55f3fb7f070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86268, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "梦想", "is_correct": true, "explanation": "正确：「梦想」（mèng xiǎng），指对未来的美好愿望。"}, {"text": "梦乡", "is_correct": false, "explanation": "xiāng（第一声）与 xiǎng（第三声）声调不同，意思是睡梦中的境界。"}, {"text": "闷响", "is_correct": false, "explanation": "mèn 与 mèng 韵母不同（en 与 eng），意思是沉闷的响声。"}, {"text": "冥想", "is_correct": false, "explanation": "míng 与 mèng 韵母、声调不同，意思是安静地深思、打坐。"}], "explanations": {"梦想": "正确：「梦想」（mèng xiǎng），指对未来的美好愿望。", "梦乡": "xiāng（第一声）与 xiǎng（第三声）声调不同，意思是睡梦中的境界。", "闷响": "mèn 与 mèng 韵母不同（en 与 eng），意思是沉闷的响声。", "冥想": "míng 与 mèng 韵母、声调不同，意思是安静地深思、打坐。"}, "sentence_index": null, "correct_answer": "梦想"}, "level_3": {"options": [{"text": "梦想", "is_correct": true, "explanation": "正确：「我的梦想是当一名医生」，「梦想」指想实现的美好愿望，与句意相符。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：「年龄」是年数，不能说成「是当一名医生」。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：「身高」指身体的高度，不能说成职业理想。"}, {"text": "味道", "is_correct": false, "explanation": "语义：「味道」指气味或口感，与「当一名医生」无关。"}], "explanations": {"梦想": "正确：「我的梦想是当一名医生」，「梦想」指想实现的美好愿望，与句意相符。", "年龄": "语义：「年龄」是年数，不能说成「是当一名医生」。", "身高": "体貌：「身高」指身体的高度，不能说成职业理想。", "味道": "语义：「味道」指气味或口感，与「当一名医生」无关。"}, "sentence_index": 0, "correct_answer": "梦想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把梦想从冰箱里拿出来，准备下锅炒。", "explanation": "这里应该用〈食材〉。梦想指对未来的美好愿望，不能当作食材下锅。"}, {"text": "我昨晚做了一个很长的梦想。", "explanation": "这里应该用〈梦〉。梦想指对未来的美好愿望，不指睡觉时出现的梦境。"}, {"text": "他把梦想摆在桌上，一件件收进了箱子里。", "explanation": "这里应该用〈物品〉。梦想指对未来的美好愿望，不能当作物品收进箱子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86268, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "梦想", "is_correct": true, "explanation": "正确：「带着环游世界的梦想」，「梦想」指强烈的理想，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」指事物的色彩，不能用来指「环游世界」的愿望。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：「脾气」指性情，不能说成「环游世界的脾气」。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：「体重」指身体的重量，不能修饰「环游世界」。"}], "explanations": {"梦想": "正确：「带着环游世界的梦想」，「梦想」指强烈的理想，与句意相符。", "颜色": "语义：「颜色」指事物的色彩，不能用来指「环游世界」的愿望。", "脾气": "搭配：「脾气」指性情，不能说成「环游世界的脾气」。", "体重": "体貌：「体重」指身体的重量，不能修饰「环游世界」。"}, "sentence_index": 6, "correct_answer": "梦想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他养成了早睡的梦想，每天都很规律。", "explanation": "这里应该用〈习惯〉。梦想指对未来的美好愿望，不指日常重复的行为。"}, {"text": "这个孩子半夜做了一个梦想。", "explanation": "这里应该用〈梦〉。睡觉时出现的梦境说「梦」，梦想不指这种梦。"}, {"text": "他把梦想扫进了簸箕里，倒进了垃圾桶。", "explanation": "这里应该用〈灰尘〉。梦想指对未来的美好愿望，不能被扫进簸箕，要用灰尘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86268, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一只梦想，想成为科学家。", "corrected_sentence": "他有一个梦想，想成为科学家。", "error_description": "错误：「一只梦想」；正确：「一个梦想」。「只」多用于动物，抽象的「梦想」应搭配量词「个」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86268, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她终于实现了小时候地梦想。", "corrected_sentence": "她终于实现了小时候的梦想。", "error_description": "错误：「小时候地梦想」；正确：「小时候的梦想」。「小时候」作定语修饰「梦想」，要用「的」；「地」用于动词前作状语，不能修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
