INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86269, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "姐姐是比你大的女孩，和你有同一个爸爸妈妈。", "primary_collocate": null, "pronunciation": "jiě jie", "ipa": "tɕjɛ˨˩ tɕjɛ", "syllable_count": 2, "sentences": [{"text": "我姐姐在北京工作。", "target_word": "姐姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐比我大三岁。", "target_word": "姐姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有一个姐姐和一个弟弟。", "target_word": "姐姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐每天骑车去学校。", "target_word": "姐姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天姐姐给我买了一本书。", "target_word": "姐姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的姐姐会做很好吃的菜。", "target_word": "姐姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐笑着对我说：“生日快乐！”", "target_word": "姐姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想和姐姐一起去看电影。", "target_word": "姐姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐住在国外，我们很少见面。", "target_word": "姐姐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐把她的衣服送给了我。", "target_word": "姐姐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "大姐", "label": "复合"}, {"form": "表姐", "label": "复合"}], "register": "口语", "sense_fingerprint": "同父母、年纪比自己大的女性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f0846f6-3efb-40f5-acd6-084c548b4338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86269, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "姐姐", "is_correct": true, "explanation": "“我___在北京工作”中，主语是同父母、年长于我的女性亲属，“姐姐”符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能在北京工作。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫是动物，不会工作。"}, {"text": "令堂", "is_correct": false, "explanation": "语域：“令堂”是敬称，指别人的母亲，不能用来称呼自己的亲属。"}], "explanations": {"姐姐": "“我___在北京工作”中，主语是同父母、年长于我的女性亲属，“姐姐”符合句意。", "桌子": "语义：桌子是家具，不能在北京工作。", "小猫": "语义：小猫是动物，不会工作。", "令堂": "语域：“令堂”是敬称，指别人的母亲，不能用来称呼自己的亲属。"}, "sentence_index": 0, "correct_answer": "姐姐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我有一只姐姐和一个弟弟。", "explanation": "这里应该用〈个〉或〈位〉。“只”多用于动物，指人要用“个”或“位”。"}, {"text": "我姐姐比我小两岁。", "explanation": "这里应该用〈妹妹〉。姐姐比自己年长，比我小要说“妹妹”。"}, {"text": "我姐姐是我爸爸的妹妹。", "explanation": "这里应该用〈姑姑〉。“姐姐”指同父母、年纪比我大的女子；爸爸的妹妹是姑姑，不是我的姐姐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76e947d0-9fe6-4584-890c-3d3c79f35bff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86269, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "姐姐", "is_correct": true, "explanation": "“___笑着对我说”需要一个会笑、会说话的人，“姐姐”符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有表情，不会笑着说话。"}, {"text": "汽车", "is_correct": false, "explanation": "配价：“对我说”需要能说话的主语，汽车不能对我说话。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟不会笑，句子不符合常理。"}], "explanations": {"姐姐": "“___笑着对我说”需要一个会笑、会说话的人，“姐姐”符合句意。", "石头": "语义：石头没有表情，不会笑着说话。", "汽车": "配价：“对我说”需要能说话的主语，汽车不能对我说话。", "闹钟": "语义：闹钟不会笑，句子不符合常理。"}, "sentence_index": 6, "correct_answer": "姐姐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的哥哥比我大三岁，是我的姐姐。", "explanation": "这里应该用〈哥哥〉。“姐姐”指女性，比我大的男性要说“哥哥”。"}, {"text": "我家有一条姐姐。", "explanation": "这里应该用〈个〉或〈位〉。“条”用于细长的东西，指人不能用“条”。"}, {"text": "我姐姐生了我和弟弟。", "explanation": "这里应该用〈妈妈〉。生孩子的是母亲，姐姐不能生下我和弟弟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76e947d0-9fe6-4584-890c-3d3c79f35bff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86269, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们家有两个姐姐们。", "corrected_sentence": "我们家有两个姐姐。", "error_description": "“两个”已表示数量，不能再与表示复数的“们”同用，应去掉“们”。正确说法：我们家有两个姐姐。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76e947d0-9fe6-4584-890c-3d3c79f35bff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86269, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一姐姐。", "corrected_sentence": "他有一个姐姐。", "error_description": "“一”后面要用量词“个”，不能直接接“姐姐”。正确说法：他有一个姐姐。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76e947d0-9fe6-4584-890c-3d3c79f35bff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
