INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86273, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“哪”是用来问是几个里的哪一个的。", "primary_collocate": null, "pronunciation": "nǎ", "ipa": "na˨˩˦", "syllable_count": 1, "sentences": [{"text": "你喜欢哪个颜色？", "target_word": "哪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪本书是你的？", "target_word": "哪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想买哪件衣服？", "target_word": "哪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个杯子，哪个是你的？", "target_word": "哪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要坐哪路车去学校？", "target_word": "哪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪位是王老师？", "target_word": "哪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你家的猫是哪只？", "target_word": "哪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们班哪个学生最高？", "target_word": "哪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪种水果你最喜欢？", "target_word": "哪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些菜里，你想吃哪个？", "target_word": "哪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "在几个人或事物中问是哪一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d31e622-4b28-4b23-8714-313fa02ff361') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86273, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "哪", "is_correct": true, "explanation": "哪 nǎ（第三声）是疑问代词，用于在几个人或事物中问是哪一个。"}, {"text": "那", "is_correct": false, "explanation": "nà（第四声）与 nǎ（第三声）声调不同，意思是“那”，是指示代词，不表示疑问。"}, {"text": "拿", "is_correct": false, "explanation": "ná（第二声）与 nǎ（第三声）声调不同，意思是“拿取”。"}, {"text": "奶", "is_correct": false, "explanation": "nǎi 与 nǎ 的韵母不同（多了 i），意思是“奶”。"}, {"text": "脑", "is_correct": false, "explanation": "nǎo 与 nǎ 的韵母不同（多了 o），意思是“大脑”。"}], "explanations": {"哪": "哪 nǎ（第三声）是疑问代词，用于在几个人或事物中问是哪一个。", "那": "nà（第四声）与 nǎ（第三声）声调不同，意思是“那”，是指示代词，不表示疑问。", "拿": "ná（第二声）与 nǎ（第三声）声调不同，意思是“拿取”。", "奶": "nǎi 与 nǎ 的韵母不同（多了 i），意思是“奶”。", "脑": "nǎo 与 nǎ 的韵母不同（多了 o），意思是“大脑”。"}, "sentence_index": null, "correct_answer": "哪"}, "level_3": {"options": [{"text": "哪", "is_correct": true, "explanation": "“哪”用于在几个中问是哪一个，与“你喜欢……颜色？”的选择问句相符。"}, {"text": "每", "is_correct": false, "explanation": "语义：“每”指全部中的每一个，与要求说话人从中选出一个的问句相矛盾。"}, {"text": "某", "is_correct": false, "explanation": "语义：“某”指不确定的一个，不能用来让对方从几种颜色中挑选。"}, {"text": "各", "is_correct": false, "explanation": "搭配：“各”要求分别指向每一个，“你喜欢各个颜色”不能用来提出选择问题。"}], "explanations": {"哪": "“哪”用于在几个中问是哪一个，与“你喜欢……颜色？”的选择问句相符。", "每": "语义：“每”指全部中的每一个，与要求说话人从中选出一个的问句相矛盾。", "某": "语义：“某”指不确定的一个，不能用来让对方从几种颜色中挑选。", "各": "搭配：“各”要求分别指向每一个，“你喜欢各个颜色”不能用来提出选择问题。"}, "sentence_index": 0, "correct_answer": "哪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天买了哪本书，很好看。", "explanation": "这里应该用〈那〉。这是陈述句，说的是已知的那本书，不是在问哪一本。"}, {"text": "哪是我的书，你别拿。", "explanation": "这里应该用〈这〉。句子是在指明自己的书，不是提问，不能用“哪”。"}, {"text": "这两个杯子里，哪是你的。", "explanation": "这里的“哪”单独作主语、没有名词，不能用于陈述句，应用〈哪个〉或〈哪一个〉，并加上疑问语气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86273, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哪", "is_correct": true, "explanation": "“哪”用于在几只猫中问是哪一只，与“你家的猫是……”的疑问相符。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”问的是人，猫是动物，不能用“谁”来问。"}, {"text": "哪位", "is_correct": false, "explanation": "语域：“哪位”是对人的敬称，不能用来问一只猫。"}, {"text": "哪些", "is_correct": false, "explanation": "搭配：“哪些”表示多个，与量词“只”指一只猫的单数语境不合。"}], "explanations": {"哪": "“哪”用于在几只猫中问是哪一只，与“你家的猫是……”的疑问相符。", "谁": "语义：“谁”问的是人，猫是动物，不能用“谁”来问。", "哪位": "语域：“哪位”是对人的敬称，不能用来问一只猫。", "哪些": "搭配：“哪些”表示多个，与量词“只”指一只猫的单数语境不合。"}, "sentence_index": 6, "correct_answer": "哪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我喜欢哪件衣服，就是这件红的。", "explanation": "这里应该用〈那〉。这是陈述句，不是在几件中提问，不能用“哪”。"}, {"text": "你看，哪只猫在睡觉。", "explanation": "这里应该用〈那〉。说话人在指给对方看，不是提问。"}, {"text": "哪位老师昨天给我们上课了，他很好。", "explanation": "这里应该用〈那〉。说的是已知的那位老师，不是在问哪一位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86273, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你想听哪只歌？", "corrected_sentence": "你想听哪首歌？", "error_description": "“歌”的量词应为“首”，不能用“只”。“哪只歌”错误，应说：你想听哪首歌？", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86273, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你想要哪个双鞋？", "corrected_sentence": "你想要哪双鞋？", "error_description": "“鞋”的量词应为“双”，前面不能再加“个”。“哪个双鞋”错误，应说：你想要哪双鞋？", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
