INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86274, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "疑问代词，用来询问在若干人或事物中的某一个。", "primary_collocate": null, "pronunciation": "nǎ", "ipa": "na˨˩˦", "syllable_count": 1, "sentences": [{"text": "你是哪国人？", "target_word": "哪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，哪位是李经理？", "target_word": "哪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你每天坐哪路公共汽车？", "target_word": "哪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几张照片里，哪张是你的？", "target_word": "哪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪个孩子是你弟弟？", "target_word": "哪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想去哪个商店买东西？", "target_word": "哪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你下个星期哪天有空？", "target_word": "哪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两条裤子，你喜欢哪条？", "target_word": "哪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你最喜欢哪门课？", "target_word": "哪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们三个人，哪个是医生？", "target_word": "哪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "疑问代词，询问若干人或事物中的某一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d31e622-4b28-4b23-8714-313fa02ff361') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86274, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "哪", "is_correct": true, "explanation": "哪 nǎ（第三声）是疑问代词，用于在若干人或事物中问是哪一个。"}, {"text": "那", "is_correct": false, "explanation": "nà（第四声）与 nǎ（第三声）声调不同，意思是“那”，是指示代词。"}, {"text": "拿", "is_correct": false, "explanation": "ná（第二声）与 nǎ（第三声）声调不同，意思是“拿取”。"}, {"text": "奶", "is_correct": false, "explanation": "nǎi 与 nǎ 的韵母不同（多了 i），意思是“奶”。"}, {"text": "脑", "is_correct": false, "explanation": "nǎo 与 nǎ 的韵母不同（多了 o），意思是“大脑”。"}], "explanations": {"哪": "哪 nǎ（第三声）是疑问代词，用于在若干人或事物中问是哪一个。", "那": "nà（第四声）与 nǎ（第三声）声调不同，意思是“那”，是指示代词。", "拿": "ná（第二声）与 nǎ（第三声）声调不同，意思是“拿取”。", "奶": "nǎi 与 nǎ 的韵母不同（多了 i），意思是“奶”。", "脑": "nǎo 与 nǎ 的韵母不同（多了 o），意思是“大脑”。"}, "sentence_index": null, "correct_answer": "哪"}, "level_3": {"options": [{"text": "哪", "is_correct": true, "explanation": "“哪”用于询问是哪一个国家，与“你是……国人？”的疑问相符。"}, {"text": "每", "is_correct": false, "explanation": "语义：“每”指全部中的每一个，与询问对方具体是哪国人的语境不符。"}, {"text": "某", "is_correct": false, "explanation": "语义：“某”指不确定的某一个，不能用来确认对方的国籍。"}, {"text": "各", "is_correct": false, "explanation": "搭配：“各国人”指各个国家的人，不能用来问一个人是哪国人。"}], "explanations": {"哪": "“哪”用于询问是哪一个国家，与“你是……国人？”的疑问相符。", "每": "语义：“每”指全部中的每一个，与询问对方具体是哪国人的语境不符。", "某": "语义：“某”指不确定的某一个，不能用来确认对方的国籍。", "各": "搭配：“各国人”指各个国家的人，不能用来问一个人是哪国人。"}, "sentence_index": 0, "correct_answer": "哪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天买了哪张照片，很好看。", "explanation": "这里应该用〈那〉。这是陈述句，说的是已知的那张照片，不是在问哪一张。"}, {"text": "你看，哪个孩子在哭。", "explanation": "这里应该用〈那〉。说话人在指给对方看，不是在若干人中提问。"}, {"text": "这两条裤子里，哪是你的。", "explanation": "这里的“哪”单独作主语、没有名词，不能用于陈述句，应用〈哪条〉并加疑问语气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86274, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哪", "is_correct": true, "explanation": "“哪”用于询问是哪一天，与“你下个星期……天有空”的疑问相符。"}, {"text": "这", "is_correct": false, "explanation": "语义：“这”指说话人已指明的一天，句中没有这样的指代对象，不能用来提问。"}, {"text": "那", "is_correct": false, "explanation": "语义：“那”指前面已提到的某一天，与询问下个星期哪天有空的语境不符。"}, {"text": "任一", "is_correct": false, "explanation": "搭配：“任一天”表示任何一天，不能用于要求对方指定哪一天。"}], "explanations": {"哪": "“哪”用于询问是哪一天，与“你下个星期……天有空”的疑问相符。", "这": "语义：“这”指说话人已指明的一天，句中没有这样的指代对象，不能用来提问。", "那": "语义：“那”指前面已提到的某一天，与询问下个星期哪天有空的语境不符。", "任一": "搭配：“任一天”表示任何一天，不能用于要求对方指定哪一天。"}, "sentence_index": 6, "correct_answer": "哪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "哪条裤子是我昨天买的，很便宜。", "explanation": "这里应该用〈那〉。这是陈述句，不是在几条中提问。"}, {"text": "你看，哪辆车很漂亮。", "explanation": "这里应该用〈那〉。说话人在指给对方看，不是提问。"}, {"text": "我认识哪个医生，他姓王。", "explanation": "这里应该用〈那〉。说的是已知的那个医生，不是在问哪一个。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86274, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你想坐哪本车？", "corrected_sentence": "你想坐哪辆车？", "error_description": "“车”的量词应为“辆”，不能用“本”。“哪本车”错误，应说：你想坐哪辆车？", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86274, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你想住哪只酒店？", "corrected_sentence": "你想住哪家酒店？", "error_description": "“酒店”的量词应为“家”，不能用“只”。“哪只酒店”错误，应说：你想住哪家酒店？", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
