INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86275, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "市长是管一座城市的人。", "primary_collocate": null, "pronunciation": "shì zhǎng", "ipa": "ʂɨ˥˩ ʈʂaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "市长是管我们城市的人。", "target_word": "市长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在电视上见过市长。", "target_word": "市长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长很忙，每天开很多会。", "target_word": "市长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的市长是一位女士。", "target_word": "市长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友给市长送了一朵花。", "target_word": "市长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长住在市中心吗？", "target_word": "市长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长坐地铁去上班。", "target_word": "市长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爸爸是我们市的市长。", "target_word": "市长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长请大家到公园里看花。", "target_word": "市长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我长大以后想当市长。", "target_word": "市长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "副市长", "label": "复合"}, {"form": "市長", "label": "繁体"}], "register": "书面", "sense_fingerprint": "市长：管一座城市的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd9494de-5348-4735-8c04-847b659ff0a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86275, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "市长", "is_correct": true, "explanation": "正确：市长是管理城市的人，可以“是管我们城市的人”。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是人，不能管理城市。"}, {"text": "树", "is_correct": false, "explanation": "配价：“管”要求能动的人作施事，“树”不能充当施事。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不是人，不能管理城市。"}], "explanations": {"市长": "正确：市长是管理城市的人，可以“是管我们城市的人”。", "河流": "语义：河流不是人，不能管理城市。", "树": "配价：“管”要求能动的人作施事，“树”不能充当施事。", "垃圾": "语义：垃圾不是人，不能管理城市。"}, "sentence_index": 0, "correct_answer": "市长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个市长明天要关门。", "explanation": "这里应该用〈商店〉。市长是人，不是店铺，不能“关门”；“关门”属于商店。"}, {"text": "市长里人很多，很热闹。", "explanation": "这里应该用〈市场〉。市长指行政首长，不是地方；“人很多，很热闹”属于市场。"}, {"text": "这个市长有四百万人。", "explanation": "这里应该用〈城市〉。市长指行政首长，不指城市；“有四百万人”属于城市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86275, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "市长", "is_correct": true, "explanation": "正确：市长是人，可以坐地铁去上班。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：“上班”要求能工作的人作施事，鱼不能坐地铁去上班。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是人，不能坐地铁去上班。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不能“坐”地铁去上班。"}], "explanations": {"市长": "正确：市长是人，可以坐地铁去上班。", "鱼": "语义：“上班”要求能工作的人作施事，鱼不能坐地铁去上班。", "空气": "语义：空气不是人，不能坐地铁去上班。", "汽车": "语义：汽车不能“坐”地铁去上班。"}, "sentence_index": 6, "correct_answer": "市长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去市长里买了很多菜。", "explanation": "这里应该用〈市场〉。市长是人，不是地方；“去……里买菜”属于市场。"}, {"text": "我长大以后想在市长里开一家小店。", "explanation": "这里应该用〈市场〉。市长指行政首长，不是地方；“开一家小店”属于市场。"}, {"text": "市长里的东西很便宜。", "explanation": "这里应该用〈超市〉。市长指行政首长，不是卖东西的地方；“东西很便宜”属于超市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86275, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只市长很受欢迎。", "corrected_sentence": "那位市长很受欢迎。", "error_description": "量词错误：指人的“市长”应用“位”（那位市长），“只”不能用于人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86275, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的爸爸当了上我们市的市长。", "corrected_sentence": "他的爸爸当上了我们市的市长。", "error_description": "补语错误：“当上”是动补结构，“了”应放在“上”之后，应说“当上了市长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
