INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86276, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个城市政府的行政首长。", "primary_collocate": null, "pronunciation": "shì zhǎng", "ipa": "ʂɨ˥˩ ʈʂaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "市长今天要去看新开的学校。", "target_word": "市长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的市长很关心老百姓。", "target_word": "市长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长在会上说了明年的计划。", "target_word": "市长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位市长在这个城市工作了十年。", "target_word": "市长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长坐车来到了公园。", "target_word": "市长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当上了这个城市的市长。", "target_word": "市长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新市长明天就要上任了。", "target_word": "市长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长把一份报告交给了记者。", "target_word": "市长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者问市长一个关于交通的问题。", "target_word": "市长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长说，我们这个城市要多种树。", "target_word": "市长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "副市长", "label": "复合"}, {"form": "市長", "label": "繁体"}], "register": "书面", "sense_fingerprint": "市长：城市政府的行政首长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd9494de-5348-4735-8c04-847b659ff0a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86276, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "市长", "is_correct": true, "explanation": "正确：市长是城市政府的行政首长，可以去看新开的学校。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包不是人，不能去看学校。"}, {"text": "树", "is_correct": false, "explanation": "配价：“去看”要求能动的人作施事，“树”不能充当施事。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：铅笔不能去视察学校。"}], "explanations": {"市长": "正确：市长是城市政府的行政首长，可以去看新开的学校。", "面包": "语义：面包不是人，不能去看学校。", "树": "配价：“去看”要求能动的人作施事，“树”不能充当施事。", "铅笔": "语义：铅笔不能去视察学校。"}, "sentence_index": 0, "correct_answer": "市长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市长里有很多人在买菜。", "explanation": "这里应该用〈市场〉。市长指城市的行政首长，不是卖菜的地方。"}, {"text": "这个市长是一座大楼。", "explanation": "这里应该用〈市政府〉。市长是人，不是建筑；“一座大楼”属于市政府。"}, {"text": "这个市长的人口很多。", "explanation": "这里应该用〈城市〉。市长指行政首长，不指城市本身；“人口很多”属于城市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86276, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "市长", "is_correct": true, "explanation": "正确：“新市长”指新任的城市行政首长，明天上任符合语境。"}, {"text": "歌手", "is_correct": false, "explanation": "搭配：“上任”用于担任职务的人，“歌手”不能与之搭配。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不能上任。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不能上任。"}], "explanations": {"市长": "正确：“新市长”指新任的城市行政首长，明天上任符合语境。", "歌手": "搭配：“上任”用于担任职务的人，“歌手”不能与之搭配。", "书": "语义：书不能上任。", "树": "语义：树不能上任。"}, "sentence_index": 6, "correct_answer": "市长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市长里有很多树，很漂亮。", "explanation": "这里应该用〈市区〉。市长指行政首长，不是地方；“里有很多树”属于市区。"}, {"text": "我们坐市长去北京。", "explanation": "这里应该用〈火车〉。市长是人，不是交通工具；“坐……去北京”属于火车。"}, {"text": "这个市长很大，有很多高楼。", "explanation": "这里应该用〈城市〉。市长指行政首长，不指城市本身；“很大、有很多高楼”属于城市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86276, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只市长昨天来了我们学校。", "corrected_sentence": "一位市长昨天来了我们学校。", "error_description": "量词错误：指人的“市长”应用“位”（一位市长）；“只”多用于动物，不能用于人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86276, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于当了上市长。", "corrected_sentence": "他终于当上了市长。", "error_description": "补语错误：“当上”是动补结构，“了”应放在“上”之后，“当了上”不能说，正确是“当上了市长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
