INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86277, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“为人”是说一个人对别人怎么样，品行怎么样。", "primary_collocate": null, "pronunciation": "wéi rén", "ipa": "wei˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "他为人很热情，大家都喜欢他。", "target_word": "为人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "王老师为人认真，对学生也很好。", "target_word": "为人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的邻居为人友好，常常帮助别人。", "target_word": "为人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人的为人不太诚实，我不想和他做朋友。", "target_word": "为人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为人很安静，不爱说别人的坏话。", "target_word": "为人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理为人公平，所以同事都相信他。", "target_word": "为人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为人老实，从来不骗人。", "target_word": "为人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你觉得张明为人怎么样？", "target_word": "为人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶为人善良，村里的人都说她好。", "target_word": "为人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李的为人大方，请朋友吃饭从不小气。", "target_word": "为人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "為人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "为人：一个人的品行和待人的态度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2434161a-3956-4714-972b-e41f185ec812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86277, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指体形高矮胖瘦，不是品性，不能用“很热情”来形容。"}, {"text": "为人", "is_correct": true, "explanation": "正确：“为人”指一个人的品行和待人处世的态度，与“很热情”搭配。"}, {"text": "口音", "is_correct": false, "explanation": "搭配：“热情”形容人的态度，不能与“口音”搭配。"}, {"text": "学历", "is_correct": false, "explanation": "语义：“学历”指受教育的程度，与待人的态度无关，“很热情”说不通。"}], "explanations": {"身材": "体貌：“身材”指体形高矮胖瘦，不是品性，不能用“很热情”来形容。", "为人": "正确：“为人”指一个人的品行和待人处世的态度，与“很热情”搭配。", "口音": "搭配：“热情”形容人的态度，不能与“口音”搭配。", "学历": "语义：“学历”指受教育的程度，与待人的态度无关，“很热情”说不通。"}, "sentence_index": 0, "correct_answer": "为人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的为人很健康，每天坚持跑步。", "explanation": "这里应该用〈身体〉。“为人”指品性和待人处世，不指身体状况；说身体好要用“身体”。"}, {"text": "他的为人很帅，很多女生喜欢他。", "explanation": "这里应该用〈外貌〉。“为人”不指长相，说长相帅要用“外貌”。"}, {"text": "他的为人很强，什么工作都能做。", "explanation": "这里应该用〈能力〉。“为人”说的是品行，不说办事本领，“很强，什么工作都能做”要用“能力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86277, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成绩", "is_correct": false, "explanation": "搭配：“老实”形容人的品性，不能用来形容“成绩”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指岁数，与“老实”不相关，后半句“从来不骗人”说的是品性。"}, {"text": "为人", "is_correct": true, "explanation": "正确：“为人”指品性，与“老实”和“从来不骗人”前后呼应。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，不能用来说人“老实”，前后意思说不通。"}], "explanations": {"成绩": "搭配：“老实”形容人的品性，不能用来形容“成绩”。", "年龄": "语义：“年龄”指岁数，与“老实”不相关，后半句“从来不骗人”说的是品性。", "为人": "正确：“为人”指品性，与“老实”和“从来不骗人”前后呼应。", "天气": "语义：“天气”是自然现象，不能用来说人“老实”，前后意思说不通。"}, "sentence_index": 6, "correct_answer": "为人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的为人读到博士，在大学教书。", "explanation": "这里应该用〈学历〉。“为人”指品性，不指受教育的程度；说读到博士要用“学历”。"}, {"text": "他的为人在班里最高，大家叫他大个子。", "explanation": "这里应该用〈身高〉。“为人”指品性，不指身体的高矮；说高矮要用“身高”。"}, {"text": "他的为人很多，住在大房子里。", "explanation": "这里应该用〈财富〉。“为人”不指钱财，说钱多要用“财富”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86277, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很佩服他为人。", "corrected_sentence": "我很佩服他的为人。", "error_description": "错误：“佩服”后面要接名词性的宾语，“他为人”不能作宾语，应加“的”，说“他的为人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86277, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他地为人很好，大家都信任他。", "corrected_sentence": "他的为人很好，大家都信任他。", "error_description": "错误：修饰名词“为人”时应用“的”，不能用“地”。“地”用于修饰动词或形容词，应说“他的为人很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
