INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86278, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86278, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "名词，指一个人的品性和待人处世的态度。", "primary_collocate": null, "pronunciation": "wéi rén", "ipa": "wei˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "我们常说，一个人的为人比他的成绩更重要。", "target_word": "为人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很喜欢她的为人。", "target_word": "为人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看一个人，不但要看工作，也要看为人。", "target_word": "为人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事让我重新认识了他的为人。", "target_word": "为人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的为人大家都知道，不会做那种事。", "target_word": "为人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的为人很受学生尊敬。", "target_word": "为人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选朋友要看对方的为人，不能只看钱。", "target_word": "为人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不太了解这个人的为人。", "target_word": "为人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的为人让大家都很放心。", "target_word": "为人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面试时，考官最看重的是应聘者的为人。", "target_word": "为人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "為人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "为人：品性与待人处世的态度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: 3 words above tier T1 (max 2): 考官 (Zipf 3.24), 看重 (Zipf 3.84), 应聘 (Zipf 3.68)']::text[], '2434161a-3956-4714-972b-e41f185ec812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86278, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发型", "is_correct": false, "explanation": "语义：“发型”指头发的样式，与品性无关，不能用来和“成绩”比较重要性。"}, {"text": "为人", "is_correct": true, "explanation": "正确：“为人”是品性，符合“一个人的……比……更重要”的说法。"}, {"text": "口音", "is_correct": false, "explanation": "搭配：“比……更重要”的主体要是品性、能力一类的名词，“口音”不能这样比较。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”说的是身体的高矮，属于外表，不能用来比较品性与成绩的重要性。"}], "explanations": {"发型": "语义：“发型”指头发的样式，与品性无关，不能用来和“成绩”比较重要性。", "为人": "正确：“为人”是品性，符合“一个人的……比……更重要”的说法。", "口音": "搭配：“比……更重要”的主体要是品性、能力一类的名词，“口音”不能这样比较。", "身高": "体貌：“身高”说的是身体的高矮，属于外表，不能用来比较品性与成绩的重要性。"}, "sentence_index": 0, "correct_answer": "为人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的为人很英俊，很多女生喜欢他。", "explanation": "这里应该用〈相貌〉。“为人”指品性，不指长相；说长相英俊要用“相貌”。"}, {"text": "他的为人很丰富，见过很多世面。", "explanation": "这里应该用〈经历〉。“为人”指品性，不指见闻；说见过很多世面要用“经历”。"}, {"text": "他的为人很强，做事很快。", "explanation": "这里应该用〈能力〉。“为人”说品性，不说办事本领；“很强，做事很快”要用“能力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86278, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "语义：“体重”与选朋友无关，不能作为选择朋友时要看的内容。"}, {"text": "为人", "is_correct": true, "explanation": "正确：“为人”指品性，与“不能只看钱”形成对照，符合选朋友的标准。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”与选朋友无关，“看天气”不能作为选朋友的标准。"}, {"text": "发色", "is_correct": false, "explanation": "体貌：“发色”指头发的颜色，属于外表，不是选朋友时要看的品性。"}], "explanations": {"体重": "语义：“体重”与选朋友无关，不能作为选择朋友时要看的内容。", "为人": "正确：“为人”指品性，与“不能只看钱”形成对照，符合选朋友的标准。", "天气": "语义：“天气”与选朋友无关，“看天气”不能作为选朋友的标准。", "发色": "体貌：“发色”指头发的颜色，属于外表，不是选朋友时要看的品性。"}, "sentence_index": 6, "correct_answer": "为人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的为人很高，买了一套大房子。", "explanation": "这里应该用〈收入〉。“为人”指品性，不指钱的多少；说收入高要用“收入”。"}, {"text": "他的为人很好听，大家都爱听他唱歌。", "explanation": "这里应该用〈声音〉。“为人”不说好听；“很好听”形容的是声音，要用“声音”。"}, {"text": "他的为人很快，跑步总是第一名。", "explanation": "这里应该用〈速度〉。“为人”说的是品性，不说快慢；“很快”形容速度，要用“速度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86278, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板很看重员工为人。", "corrected_sentence": "老板很看重员工的为人。", "error_description": "错误：“员工为人”前缺少“的”，不能作“看重”的宾语。应说“员工的为人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86278, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他地为人很可靠，我们都愿意和他合作。", "corrected_sentence": "他的为人很可靠，我们都愿意和他合作。", "error_description": "错误：修饰名词“为人”时应用“的”，不能用“地”。“地”用于修饰动词或形容词，应说“他的为人很可靠”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86279, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86279, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86279, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "往往是说常常是这样。", "primary_collocate": null, "pronunciation": "wǎng wǎng", "ipa": "wɑŋ˨˩ wɑŋ˨˩", "syllable_count": 2, "sentences": [{"text": "他往往最后一个到教室。", "target_word": "往往", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好朋友之间，往往不用说太多话。", "target_word": "往往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周日的公园往往人很多。", "target_word": "往往", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做事太快，往往容易出错。", "target_word": "往往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥晚上往往在家看书。", "target_word": "往往", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨后的天空往往特别蓝。", "target_word": "往往", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "带孩子去书店，他往往不想走。", "target_word": "往往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天这里的早上往往有点冷。", "target_word": "往往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一次做的菜，往往不太好吃。", "target_word": "往往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习语言时，我们往往怕说错。", "target_word": "往往", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "常常是这样，说明一般情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '749151d6-7ed4-4f35-af8d-c2dbfaf13d12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86279, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "往往", "is_correct": true, "explanation": "往往：表示经常如此，与“他最后一个到教室”这种习惯性情况相符。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行中，而“到”表示到达这一结果，两者不能搭配。"}, {"text": "马上", "is_correct": false, "explanation": "搭配：“马上”表示立刻发生，与“最后一个到”这种先后顺序说法不搭配。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示紧接着发生，与“最后一个到”所表达的先后顺序相矛盾。"}], "explanations": {"往往": "往往：表示经常如此，与“他最后一个到教室”这种习惯性情况相符。", "正在": "体貌：“正在”表示动作进行中，而“到”表示到达这一结果，两者不能搭配。", "马上": "搭配：“马上”表示立刻发生，与“最后一个到”这种先后顺序说法不搭配。", "立刻": "语义：“立刻”表示紧接着发生，与“最后一个到”所表达的先后顺序相矛盾。"}, "sentence_index": 0, "correct_answer": "往往"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那天下午往往下起了大雨。", "explanation": "这里应该用〈突然〉。往往表示经常出现的情况，不能用来说某一天下午发生的一次性事件。"}, {"text": "我往往在这里住过三年。", "explanation": "这里应该用〈曾经〉。往往表示经常，不能用来描述过去一段时间里发生过一次的经历。"}, {"text": "下个月他往往去上海出差。", "explanation": "这里应该用〈要〉。往往只描述经常出现的情况，不能用来说某个未来的具体安排。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86279, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "往往", "is_correct": true, "explanation": "往往：表示经常如此，与“带孩子去书店，他不想走”这种习惯相符。"}, {"text": "即将", "is_correct": false, "explanation": "体貌：“即将”表示即将发生的动作，而“不想走”是心理状态，不能用“即将”修饰。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行中，不能修饰“不想走”这种心理状态。"}, {"text": "猛地", "is_correct": false, "explanation": "搭配：“猛地”多修饰突然发生的动作，与“不想走”这类心理状态不搭配。"}], "explanations": {"往往": "往往：表示经常如此，与“带孩子去书店，他不想走”这种习惯相符。", "即将": "体貌：“即将”表示即将发生的动作，而“不想走”是心理状态，不能用“即将”修饰。", "正在": "体貌：“正在”表示动作进行中，不能修饰“不想走”这种心理状态。", "猛地": "搭配：“猛地”多修饰突然发生的动作，与“不想走”这类心理状态不搭配。"}, "sentence_index": 6, "correct_answer": "往往"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二加二往往等于四。", "explanation": "这里应该用〈总是〉。往往表示经常但不一定如此，不能用来说明必然的数学结论。"}, {"text": "请往往带上护照！", "explanation": "这里应该用〈务必〉。往往是描述习惯的副词，不能用于提醒或命令别人做某件事。"}, {"text": "这座城市往往是我的家。", "explanation": "这里应该用〈一直〉。往往表示经常出现的情况，不能用来说明地方与人之间长期不变的关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86279, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种人的往往很小心。", "corrected_sentence": "这种人往往很小心。", "error_description": "错误形式：“人的往往”；正确形式：“人往往”。“往往”是副词，直接放在主语后，主语后不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86279, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每年这时候，这里很往往下雨。", "corrected_sentence": "每年这时候，这里往往下雨。", "error_description": "错误形式：“很往往”；正确形式：“往往下雨”。“很”不能修饰副词“往往”，应直接用“往往”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
