INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86283, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "抗议是大声说我不同意，请你不要这样。", "primary_collocate": null, "pronunciation": "kàng yì", "ipa": "kʰɑŋ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "弟弟抗议：“我不想睡觉！”", "target_word": "抗议", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子大声抗议：“这不公平！”", "target_word": "抗议", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我抗议，你不能拿我的书。", "target_word": "抗议", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明抗议说：“你别吵了！”", "target_word": "抗议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她抗议了好几次，可是没有用。", "target_word": "抗议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们都大声抗议：“作业太多了，别再留了！”", "target_word": "抗议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我要抗议，你不能再这样随便拿我的东西了。", "target_word": "抗议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妹妹抗议哥哥玩她的玩具。", "target_word": "抗议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们抗议爸爸关电视。", "target_word": "抗议", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家一起抗议：“不要再吵了！”", "target_word": "抗议", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "抗議", "label": "繁体"}, {"form": "抗议了", "label": "体标"}, {"form": "抗议过", "label": "体标"}, {"form": "抗议书", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词，大声说不同意，要求对方不要这样做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eb6a069-3cc9-4bff-bb63-1f24166f25c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86283, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抗议", "is_correct": true, "explanation": "正确：「抗议」表示大声表示不同意，与弟弟的拒绝语相符。"}, {"text": "同意", "is_correct": false, "explanation": "语义：「同意」表示赞成，与后面的拒绝语“我不想睡觉”矛盾。"}, {"text": "道歉", "is_correct": false, "explanation": "语义：「道歉」表示认错，与“我不想睡觉”的坚持不符。"}, {"text": "禀告", "is_correct": false, "explanation": "语域：「禀告」是书面或敬辞，小孩子大声说话不用这种语体。"}], "explanations": {"抗议": "正确：「抗议」表示大声表示不同意，与弟弟的拒绝语相符。", "同意": "语义：「同意」表示赞成，与后面的拒绝语“我不想睡觉”矛盾。", "道歉": "语义：「道歉」表示认错，与“我不想睡觉”的坚持不符。", "禀告": "语域：「禀告」是书面或敬辞，小孩子大声说话不用这种语体。"}, "sentence_index": 0, "correct_answer": "抗议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小明抗议说：“对不起，我错了。”", "explanation": "这里应该用〈道歉〉。抗议是表示不同意，不能用来认错。"}, {"text": "妈妈抗议说：“你做得很好！”", "explanation": "这里应该用〈称赞〉。抗议是表示不同意，不能用来表扬。"}, {"text": "大家抗议他：“恭喜你！”", "explanation": "这里应该用〈祝贺〉。抗议是大声表示不同意、请对方别这样，不能用来向人道喜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f0c2dc0-701e-4d12-98e2-361ee568df0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86283, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抗议", "is_correct": true, "explanation": "正确：「抗议」表示大声表示不同意，与“你不能再这样随便拿我的东西”的语境相符。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：「微笑」表示笑容，与“你不能再这样随便拿我的东西”的不满语境矛盾。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：「感谢」表示感激，与“你不能再这样随便拿我的东西”的不满语境矛盾。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：「欢迎」表示接纳，与“你不能再这样随便拿我的东西”的不满语境矛盾。"}], "explanations": {"抗议": "正确：「抗议」表示大声表示不同意，与“你不能再这样随便拿我的东西”的语境相符。", "微笑": "语义：「微笑」表示笑容，与“你不能再这样随便拿我的东西”的不满语境矛盾。", "感谢": "语义：「感谢」表示感激，与“你不能再这样随便拿我的东西”的不满语境矛盾。", "欢迎": "语义：「欢迎」表示接纳，与“你不能再这样随便拿我的东西”的不满语境矛盾。"}, "sentence_index": 6, "correct_answer": "抗议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家一起抗议：“加油！”", "explanation": "这里应该用〈鼓励〉。抗议是大声表示不同意、请对方停止，不能用来为对方打气；为对方打气要用〈鼓励〉。"}, {"text": "同学们一起抗议：“来我家玩吧！”", "explanation": "这里应该用〈邀请〉。抗议是大声表示不同意、请对方别这样，不能用来向人发出邀请；发出邀请要用〈邀请〉。"}, {"text": "我抗议他：“请留下来！”", "explanation": "这里应该用〈恳求〉。抗议是表示反对，不能用来恳请对方留下；恳请对方留下要用〈恳求〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f0c2dc0-701e-4d12-98e2-361ee568df0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86283, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹很抗议：“我想再玩一会儿！”", "corrected_sentence": "妹妹大声抗议：“我想再玩一会儿！”", "error_description": "错误：“抗议”是动词，前面不能直接加“很”。表示大声表示不同意时应说“大声抗议”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f0c2dc0-701e-4d12-98e2-361ee568df0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86283, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我抗议了过他拿我的书。", "corrected_sentence": "我抗议过他拿我的书。", "error_description": "错误：“了”和“过”不能同时用在“抗议”后。表示曾经发生过时只用“过”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f0c2dc0-701e-4d12-98e2-361ee568df0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
