INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86284, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对某种言论或行为表示强烈反对。", "primary_collocate": null, "pronunciation": "kàng yì", "ipa": "kʰɑŋ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "工人们抗议公司降低工资。", "target_word": "抗议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市民上街抗议这个决定。", "target_word": "抗议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们抗议学校的新规定。", "target_word": "抗议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他大声抗议裁判的决定。", "target_word": "抗议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人向政府抗议这件事。", "target_word": "抗议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "邻居抗议工厂的噪音。", "target_word": "抗议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家抗议老板的做法。", "target_word": "抗议", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "球迷抗议比赛的结果。", "target_word": "抗议", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "居民们抗议在这里建工厂。", "target_word": "抗议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王抗议过这种不公平的安排。", "target_word": "抗议", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抗議", "label": "繁体"}, {"form": "抗议了", "label": "体标"}, {"form": "抗议过", "label": "体标"}, {"form": "抗议书", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词，公开对言论或行为表示强烈反对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eb6a069-3cc9-4bff-bb63-1f24166f25c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86284, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抗议", "is_correct": true, "explanation": "正确：「抗议」表示强烈反对，与工人反对降薪的语境相符。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：「祝贺」用于喜事，与降低工资这种坏事矛盾。"}, {"text": "赞扬", "is_correct": false, "explanation": "语义：「赞扬」表示肯定，与降低工资这一负面结果不协调。"}, {"text": "完成", "is_correct": false, "explanation": "搭配：「完成」后接任务、工作，不能接“公司降低工资”这样的事件。"}], "explanations": {"抗议": "正确：「抗议」表示强烈反对，与工人反对降薪的语境相符。", "祝贺": "语义：「祝贺」用于喜事，与降低工资这种坏事矛盾。", "赞扬": "语义：「赞扬」表示肯定，与降低工资这一负面结果不协调。", "完成": "搭配：「完成」后接任务、工作，不能接“公司降低工资”这样的事件。"}, "sentence_index": 0, "correct_answer": "抗议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他多次抗议裁判的公正。", "explanation": "这里应该用〈赞美〉。抗议是表示强烈反对，裁判的公正是值得肯定的，应该用〈赞美〉。"}, {"text": "老师抗议他刻苦学习。", "explanation": "这里应该用〈鼓励〉。抗议是表示强烈反对，老师对刻苦学习的学生应该用〈鼓励〉。"}, {"text": "大家抗议他认真负责的工作态度。", "explanation": "这里应该用〈表扬〉。抗议表示反对，而他认真负责的工作态度是值得肯定的，应该用〈表扬〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f0c2dc0-701e-4d12-98e2-361ee568df0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86284, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抗议", "is_correct": true, "explanation": "正确：「抗议」表示反对，与大家对老板做法的不满相符。"}, {"text": "完成", "is_correct": false, "explanation": "搭配：「完成」的对象是任务、工作，不能说“完成做法”。"}, {"text": "回答", "is_correct": false, "explanation": "搭配：「回答」针对问题、疑问，不能接“做法”。"}, {"text": "解决", "is_correct": false, "explanation": "搭配：「解决」针对问题、矛盾，不能说“解决老板的做法”。"}], "explanations": {"抗议": "正确：「抗议」表示反对，与大家对老板做法的不满相符。", "完成": "搭配：「完成」的对象是任务、工作，不能说“完成做法”。", "回答": "搭配：「回答」针对问题、疑问，不能接“做法”。", "解决": "搭配：「解决」针对问题、矛盾，不能说“解决老板的做法”。"}, "sentence_index": 6, "correct_answer": "抗议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板经常抗议我提前完成任务。", "explanation": "这里应该用〈鼓励〉。抗议是公开反对某种言论或行为，不能用于支持对方的积极表现；老板对员工的积极表现应该用〈鼓励〉。"}, {"text": "我抗议老板给我加薪。", "explanation": "这里应该用〈请求〉。抗议是反对别人的行为，不能用于向对方提出要求。"}, {"text": "我抗议老师的耐心指导。", "explanation": "这里应该用〈感激〉。抗议是表示反对，不能用于表达感谢或肯定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f0c2dc0-701e-4d12-98e2-361ee568df0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86284, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们很抗议公司降低工资。", "corrected_sentence": "工人们强烈抗议公司降低工资。", "error_description": "错误：“很”不能直接修饰动词“抗议”。正确：应用“强烈”修饰“抗议”，说“强烈抗议”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f0c2dc0-701e-4d12-98e2-361ee568df0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86284, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他抗议了过很多次。", "corrected_sentence": "他抗议过很多次。", "error_description": "错误：“抗议”后不能同时用“了”和“过”。表示曾经有过这种经历时只用“过”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f0c2dc0-701e-4d12-98e2-361ee568df0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
