INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86285, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "损失是东西坏了、丢了，变少了。", "primary_collocate": null, "pronunciation": "sǔn shī", "ipa": "suən˨˩ ʂɨ˥", "syllable_count": 2, "sentences": [{"text": "这场大雨给农民带来了很大的损失。", "target_word": "损失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次火灾的损失很大。", "target_word": "损失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想办法减少损失。", "target_word": "损失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他丢了钱包，这个损失不小。", "target_word": "损失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保险公司会赔偿你这笔损失。", "target_word": "损失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次地震造成的损失无法计算。", "target_word": "损失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意难免会有一些损失。", "target_word": "损失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里的东西坏了很多，损失很大。", "target_word": "损失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板算了算这个月的损失。", "target_word": "损失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然有损失，但是大家都没有受伤。", "target_word": "损失", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔损失", "label": "量词"}, {"form": "经济损失", "label": "复合"}], "register": "中性", "sense_fingerprint": "损失（名词）：东西坏了、丢了或变少所造成的亏损", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528460c6-b68d-4819-9976-ec879930a8cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86285, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "荣誉", "is_correct": false, "explanation": "语义：荣誉指光荣的称号或名声，大雨不会给农民带来荣誉。"}, {"text": "损失", "is_correct": true, "explanation": "损失指东西坏了、丢了造成的亏损，与“带来很大的”搭配，指这场大雨给农民造成的亏损。"}, {"text": "魅力", "is_correct": false, "explanation": "搭配：“魅力”指人或事物吸引人的力量，“大雨带来很大的魅力”说不通。"}, {"text": "名声", "is_correct": false, "explanation": "语义：名声是社会对人的评价，大雨不能给农民带来名声。"}], "explanations": {"荣誉": "语义：荣誉指光荣的称号或名声，大雨不会给农民带来荣誉。", "损失": "损失指东西坏了、丢了造成的亏损，与“带来很大的”搭配，指这场大雨给农民造成的亏损。", "魅力": "搭配：“魅力”指人或事物吸引人的力量，“大雨带来很大的魅力”说不通。", "名声": "语义：名声是社会对人的评价，大雨不能给农民带来名声。"}, "sentence_index": 0, "correct_answer": "损失"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种药对身体的损失很大。", "explanation": "这里应该用〈损害〉。损害用于身体、健康、权益，损失多指财物或人员的减少，不说“身体的损失”。"}, {"text": "他考试得了第一名，心里有很大的损失。", "explanation": "这里应该用〈快乐〉。考了第一名心里是快乐、高兴，“损失”指财物等的亏损，意思正好不对。"}, {"text": "这件事让我们的友谊受到了很大的损失。", "explanation": "这里应该用〈伤害〉。友谊、感情受到的是伤害，不说“受到损失”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86285, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掌声", "is_correct": false, "explanation": "语义：掌声表示赞扬，“难免”后接的是不利情况，两者矛盾。"}, {"text": "荣光", "is_correct": false, "explanation": "语义：“荣光”指光荣，是正面的，“难免”后接不利情况，不说“难免会有一些荣光”。"}, {"text": "损失", "is_correct": true, "explanation": "损失指做生意时亏掉的钱或财物，与“难免”搭配，表示不利情况。"}, {"text": "信心", "is_correct": false, "explanation": "搭配：“难免”后一般接负面情况，“有信心”是正面的，不说“难免会有一些信心”。"}], "explanations": {"掌声": "语义：掌声表示赞扬，“难免”后接的是不利情况，两者矛盾。", "荣光": "语义：“荣光”指光荣，是正面的，“难免”后接不利情况，不说“难免会有一些荣光”。", "损失": "损失指做生意时亏掉的钱或财物，与“难免”搭配，表示不利情况。", "信心": "搭配：“难免”后一般接负面情况，“有信心”是正面的，不说“难免会有一些信心”。"}, "sentence_index": 6, "correct_answer": "损失"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司在研发上投入了大量损失。", "explanation": "这里应该用〈资金〉。研发上投入的是资金、精力，“损失”指亏掉的财物，不能说“投入损失”。"}, {"text": "这笔生意我们赚了很多损失。", "explanation": "这里应该用〈利润〉。赚钱说“利润”，“损失”是亏掉的部分，不能说“赚了损失”。"}, {"text": "他把这笔损失存进了银行。", "explanation": "这里应该用〈存款〉。存进银行的是钱，“损失”是亏掉的部分，不能存入银行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86285, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次台风给渔民带来了一只不小的损失。", "corrected_sentence": "这次台风给渔民带来了一笔不小的损失。", "error_description": "量词错误：“损失”指款项、财物，量词应用“笔”，不能用“只”（“只”多用于动物）。正确说法是“一笔不小的损失”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86285, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场暴雨过后，农田的损失了很大。", "corrected_sentence": "这场暴雨过后，农田的损失很大。", "error_description": "误加“了”：“损失”作名词，表示损失的程度，后面不能加“了”。正确说法是“损失很大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86286, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "散步", "is_correct": false, "explanation": "散步是动作，与“损失”没有反义关系。"}, {"text": "获得", "is_correct": true, "explanation": "获得指得到，与“损失”意义相反，是反义动词。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉是动作，与“损失”没有反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳是动作，与“损失”没有反义关系。"}], "correct_answer": "获得", "explanations": {"散步": "散步是动作，与“损失”没有反义关系。", "获得": "获得指得到，与“损失”意义相反，是反义动词。", "睡觉": "睡觉是动作，与“损失”没有反义关系。", "游泳": "游泳是动作，与“损失”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86286, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "画画", "is_correct": false, "explanation": "画画是动作，与“损失”没有反义关系。"}, {"text": "得到", "is_correct": true, "explanation": "得到指获得，与“损失”意义相反，是反义动词。"}, {"text": "吃饭", "is_correct": false, "explanation": "吃饭是动作，与“损失”没有反义关系。"}, {"text": "读书", "is_correct": false, "explanation": "读书是动作，与“损失”没有反义关系。"}], "correct_answer": "得到", "explanations": {"画画": "画画是动作，与“损失”没有反义关系。", "得到": "得到指获得，与“损失”意义相反，是反义动词。", "吃饭": "吃饭是动作，与“损失”没有反义关系。", "读书": "读书是动作，与“损失”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86286, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "受到损害而失去钱、物或人员。", "primary_collocate": null, "pronunciation": "sǔn shī", "ipa": "suən˨˩ ʂɨ˥", "syllable_count": 2, "sentences": [{"text": "这家公司去年损失了很多钱。", "target_word": "损失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大火让他损失了一间房子。", "target_word": "损失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货船遇到风浪，损失了不少货物。", "target_word": "损失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做，我们不会损失什么。", "target_word": "损失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生意失败，损失了所有的存款。", "target_word": "损失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，我们队损失了两名主力。", "target_word": "损失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民们担心天气不好会损失粮食。", "target_word": "损失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他丢了手机，也损失了很多照片。", "target_word": "损失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不用担心，我们没有损失一分钱。", "target_word": "损失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水过后，村里损失了不少牛羊。", "target_word": "损失", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "损失了", "label": "完成体"}, {"form": "损失过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "损失（动词）：受到损害而失去钱、物或人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528460c6-b68d-4819-9976-ec879930a8cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86286, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”的对象是美好的事物，不能用来说失去钱。"}, {"text": "损失", "is_correct": true, "explanation": "损失指失去钱、物，与“很多钱”搭配，说明公司去年失去了不少钱。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：“照顾”指关心、照料，不能说“照顾了很多钱”。"}, {"text": "认识", "is_correct": false, "explanation": "语义：“认识”指了解人或事物，不能用于钱。"}], "explanations": {"欣赏": "语义：“欣赏”的对象是美好的事物，不能用来说失去钱。", "损失": "损失指失去钱、物，与“很多钱”搭配，说明公司去年失去了不少钱。", "照顾": "语义：“照顾”指关心、照料，不能说“照顾了很多钱”。", "认识": "语义：“认识”指了解人或事物，不能用于钱。"}, "sentence_index": 0, "correct_answer": "损失"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把很多时间损失在游戏上。", "explanation": "这里应该用〈浪费〉。浪费指无益地花用，时间用在游戏上是浪费；“损失”指失去已有的东西。"}, {"text": "他对这份工作损失了信心。", "explanation": "这里应该用〈失去〉。固定搭配是“失去信心”，“损失”不能和“信心”搭配。"}, {"text": "他做实验时粗心，损失了一个关键步骤。", "explanation": "这里应该用〈遗漏〉。遗漏指漏掉，“损失”指失去已有的东西，不说“损失步骤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86286, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "祈祷", "is_correct": false, "explanation": "语义：“祈祷”的对象不是粮食，与“会……粮食”不合。"}, {"text": "聊天", "is_correct": false, "explanation": "配价：“聊天”是不及物动词，不能带“粮食”作宾语。"}, {"text": "损失", "is_correct": true, "explanation": "损失指失去粮食，与“会……粮食”搭配，表示担心的后果。"}, {"text": "跳", "is_correct": false, "explanation": "语义：“跳”不能用来表示对粮食的处置，句子不通。"}], "explanations": {"祈祷": "语义：“祈祷”的对象不是粮食，与“会……粮食”不合。", "聊天": "配价：“聊天”是不及物动词，不能带“粮食”作宾语。", "损失": "损失指失去粮食，与“会……粮食”搭配，表示担心的后果。", "跳": "语义：“跳”不能用来表示对粮食的处置，句子不通。"}, "sentence_index": 6, "correct_answer": "损失"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛我们队损失了所有的对手。", "explanation": "这里应该用〈打败〉。打败指战胜对方，对手不能被“损失”。"}, {"text": "他终于损失了这个困境。", "explanation": "这里应该用〈摆脱〉。摆脱困境是脱离困境，“损失”指失去已有的东西，不说“损失困境”。"}, {"text": "他想了很久，终于损失了这道难题。", "explanation": "这里应该用〈解决〉。解决的是难题、问题，“损失”指失去钱、物或人员，不说“损失难题”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86286, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次台风，渔民损失着很多渔船。", "corrected_sentence": "这次台风，渔民损失了很多渔船。", "error_description": "体标错误：“损失”表示已经发生的损失，要用“了”，不能用“着”。正确说法是“损失了很多渔船”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86286, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "台风过后，村民损失的很惨。", "corrected_sentence": "台风过后，村民损失得很惨。", "error_description": "补语标记错误：表示程度的补语要用“得”，“的”不能用在“损失”之后，应说“损失得很惨”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
