INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86288, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "艺术家、作者创作出来的文艺成果，如画、书、乐曲。", "primary_collocate": null, "pronunciation": "zuò pǐn", "ipa": "tswo˥˩ pʰin˨˩˦", "syllable_count": 2, "sentences": [{"text": "这位画家的作品很有名。", "target_word": "作品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "博物馆里有很多古代作品。", "target_word": "作品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的新作品下个月会出版。", "target_word": "作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件作品是学生做的，真漂亮。", "target_word": "作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把大家的作品挂在教室里。", "target_word": "作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢这位作家的作品。", "target_word": "作品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的音乐作品让很多人感动。", "target_word": "作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的作品在比赛中得了第一名。", "target_word": "作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展览上有三十件作品，我都看过。", "target_word": "作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者写完了作品，想先给朋友看看。", "target_word": "作品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "部", "label": "量词"}, {"form": "文学作品", "label": "复合"}, {"form": "艺术作品", "label": "复合"}], "register": "中性", "sense_fingerprint": "作品：艺术家或作者创作的文艺成果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2434161a-3956-4714-972b-e41f185ec812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86288, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作品", "is_correct": true, "explanation": "“画家的作品”指画家创作的成果，与“很有名”搭配自然。"}, {"text": "作家", "is_correct": false, "explanation": "语义：“作家”指写作的人，句中要说的是成果，画家的作家说不通。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”不能用“很有名”来形容。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“性格”不能用“很有名”来形容，“有名”一般用于作品或人。"}], "explanations": {"作品": "“画家的作品”指画家创作的成果，与“很有名”搭配自然。", "作家": "语义：“作家”指写作的人，句中要说的是成果，画家的作家说不通。", "工资": "搭配：“工资”不能用“很有名”来形容。", "性格": "搭配：“性格”不能用“很有名”来形容，“有名”一般用于作品或人。"}, "sentence_index": 0, "correct_answer": "作品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家菜市场的作品很新鲜，一斤只要两块钱。", "explanation": "这里应该用〈蔬菜〉。“作品”指文艺成果，不能指菜，卖菜的要用“蔬菜”。"}, {"text": "这次考试的作品很难，我没考好。", "explanation": "这里应该用〈试题〉。“作品”指艺术家、作者创作的成果，考试的题目要用“试题”。"}, {"text": "这些作品用来洗衣服，效果很好。", "explanation": "这里应该用〈洗涤剂〉。“作品”指文艺成果，洗衣服用的东西要用“洗涤剂”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86288, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作品", "is_correct": true, "explanation": "“她的音乐作品”指她创作的音乐成果，主语能让人感动。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”是身体的数值，不是能让人感动的对象，句中语义不合。"}, {"text": "座位", "is_correct": false, "explanation": "语义：“座位”指座椅的位置，不能作主语使人感动。"}, {"text": "账单", "is_correct": false, "explanation": "语义：“账单”是消费的记录，不是创作的成果，不能使人感动，句中语义不合。"}], "explanations": {"作品": "“她的音乐作品”指她创作的音乐成果，主语能让人感动。", "体温": "语义：“体温”是身体的数值，不是能让人感动的对象，句中语义不合。", "座位": "语义：“座位”指座椅的位置，不能作主语使人感动。", "账单": "语义：“账单”是消费的记录，不是创作的成果，不能使人感动，句中语义不合。"}, "sentence_index": 6, "correct_answer": "作品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种作品对感冒很有效。", "explanation": "这里应该用〈药品〉。“作品”指创作成果，治病的东西要用“药品”。"}, {"text": "这位作品每天写作，很努力。", "explanation": "这里应该用〈作家〉。“作品”指成果，不能指写作的人，写作、努力的主体要用“作家”。"}, {"text": "这家超市的作品很新鲜。", "explanation": "这里应该用〈食品〉。“作品”指文艺成果，超市里新鲜的东西要用“食品”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86288, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次展览一共有五只作品。", "corrected_sentence": "这次展览一共有五件作品。", "error_description": "量词“只”多用于动物或成对的东西，作品应该用“件”或“部”，应说“五件作品”，不能说“五只作品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86288, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他作品很有名，很多人都读过。", "corrected_sentence": "他的作品很有名，很多人都读过。", "error_description": "错误：“他”修饰名词“作品”表示所属时要加“的”，应说“他的作品”，不能说“他作品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
