INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86290, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e65b8434-e0fe-4d9e-83e1-4929ab504216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86290, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某个时间点；也指一段时间。", "primary_collocate": null, "pronunciation": "shí kè", "ipa": "ʂɻ̩˧˥ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "飞机起飞的时刻是下午三点。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我你到达的具体时刻。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在最困难的时刻，家人一直陪着我。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些艰难的时刻，我永远不会忘记。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试期间是学生最紧张的时刻。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车的出发时刻写在车票上。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孤独的时刻，他喜欢听音乐。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在不是休息的时刻，大家继续工作。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都有想家的时刻。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个时刻，整个城市都安静下来了。", "target_word": "时刻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "時刻", "label": "繁体"}], "register": "中性", "sense_fingerprint": "具体的时间点，或指某一段特定的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39686117-ff5b-4662-b33e-7c30377afa02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86290, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时刻", "is_correct": true, "explanation": "“时刻”指一个具体的时间点，与“下午三点”对应，句意通顺。"}, {"text": "地点", "is_correct": false, "explanation": "语义：“地点”指空间位置，不能是“下午三点”这样的时间。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱数，不能与“下午三点”对应。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是外观特征，不是时间，不能与“下午三点”对应。"}], "explanations": {"时刻": "“时刻”指一个具体的时间点，与“下午三点”对应，句意通顺。", "地点": "语义：“地点”指空间位置，不能是“下午三点”这样的时间。", "价格": "语义：“价格”指钱数，不能与“下午三点”对应。", "颜色": "语义：“颜色”是外观特征，不是时间，不能与“下午三点”对应。"}, "sentence_index": 0, "correct_answer": "时刻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我永远记得那一块时刻。", "explanation": "这里应该用〈个〉。“块”用于成块的东西，不能用来计量“时刻”。"}, {"text": "我在售票处买了一张时刻。", "explanation": "这里应该用〈时刻表〉。“时刻”不能指写着列车或车次时间的表格，应说“时刻表”。"}, {"text": "在春秋时刻，各国常常打仗。", "explanation": "这里应该用〈时代〉。“时代”指较长的历史阶段，“春秋”是历史时代的名称，不能说“春秋时刻”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e65b8434-e0fe-4d9e-83e1-4929ab504216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86290, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时刻", "is_correct": true, "explanation": "“时刻”指一个时间点，可以与“孤独的”修饰的时段相配，句意通顺。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”是身体的数值，不能用“孤独的”来修饰。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“孤独”不能修饰“速度”，搭配不当。"}, {"text": "号码", "is_correct": false, "explanation": "语义：“号码”与“孤独”无关，句意不通。"}], "explanations": {"时刻": "“时刻”指一个时间点，可以与“孤独的”修饰的时段相配，句意通顺。", "体温": "语义：“体温”是身体的数值，不能用“孤独的”来修饰。", "速度": "搭配：“孤独”不能修饰“速度”，搭配不当。", "号码": "语义：“号码”与“孤独”无关，句意不通。"}, "sentence_index": 6, "correct_answer": "时刻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "从家到学校需要二十分钟的时刻。", "explanation": "这里应该用〈时间〉。“需要二十分钟”说的是花费的时长，应该用“时间”；“时刻”多指某个时间点或某个特定的时候，不用来说花费多长时间。"}, {"text": "他等了一时刻钟才上车。", "explanation": "这里应该用〈一刻钟〉。“时刻”不能与“钟”直接组合表示时长，应说“一刻钟”。"}, {"text": "我们约好的时刻是学校门口。", "explanation": "这里应该用〈地点〉。“学校门口”是一个地方，要用“地点”；“时刻”指时间，不能指地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e65b8434-e0fe-4d9e-83e1-4929ab504216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86290, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "火车的到站时刻了是晚上八点。", "corrected_sentence": "火车的到站时刻是晚上八点。", "error_description": "错误：“时刻”后多加了“了”。“时刻”是名词，后面不能直接加“了”。正确：“火车的到站时刻是晚上八点。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e65b8434-e0fe-4d9e-83e1-4929ab504216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是他人生中了重要时刻。", "corrected_sentence": "这是他人生中的重要时刻。", "error_description": "错误：修饰语“重要”与“时刻”之间的“的”误写为“了”。“了”是体标，不能放在修饰语和名词之间。正确：“这是他人生中的重要时刻。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e65b8434-e0fe-4d9e-83e1-4929ab504216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86291, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b268d74d-6786-4d74-8f85-b1d48d0279b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86291, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b268d74d-6786-4d74-8f85-b1d48d0279b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86291, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "“台”是比地面高一点、可以站在上面的地方。", "primary_collocate": null, "pronunciation": "tái", "ipa": "tʰaɪ̯˧˥", "syllable_count": 1, "sentences": [{"text": "他站在台上，看见了整个村子。", "target_word": "台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "台下堆着几只旧木箱。", "target_word": "台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友走上台，伸手去够树上的果子。", "target_word": "台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个台很高，小孩自己上不去。", "target_word": "台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从台上跳了下来。", "target_word": "台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "台上的雪还没化，踩上去很滑。", "target_word": "台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走到台边，往下看了看。", "target_word": "台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在台边坐下，看着远处的山。", "target_word": "台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们爬上台，高兴地跳起来。", "target_word": "台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "台上有风，站久了有点冷。", "target_word": "台", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "臺", "label": "繁体"}, {"form": "台阶", "label": "复合"}], "register": "中性", "sense_fingerprint": "比地面高的平地，人可以站或坐在上面，常与台上、台边连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: 3 words above tier T1 (max 2): 伸手 (Zipf 3.8), 树上 (Zipf 3.82), 果子 (Zipf 3.45)']::text[], '9c7e51ce-19b3-4ce8-8dfa-fa8a07b5b200') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86291, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "台", "is_correct": true, "explanation": "台（tái）指比地面高、可以站上去的平台，是正确答案。"}, {"text": "太", "is_correct": false, "explanation": "tài（第四声）与 tái（第二声）声调不同，意思是“太”。"}, {"text": "胎", "is_correct": false, "explanation": "tāi（第一声）与 tái（第二声）声调不同，意思是“胎”。"}, {"text": "谈", "is_correct": false, "explanation": "tán 与 tái 韵母不同（an 与 ai），意思是“谈”。"}, {"text": "糖", "is_correct": false, "explanation": "táng 与 tái 韵母不同（ang 与 ai），意思是“糖”。"}], "explanations": {"台": "台（tái）指比地面高、可以站上去的平台，是正确答案。", "太": "tài（第四声）与 tái（第二声）声调不同，意思是“太”。", "胎": "tāi（第一声）与 tái（第二声）声调不同，意思是“胎”。", "谈": "tán 与 tái 韵母不同（an 与 ai），意思是“谈”。", "糖": "táng 与 tái 韵母不同（ang 与 ai），意思是“糖”。"}, "sentence_index": null, "correct_answer": "台"}, "level_3": {"options": [{"text": "台", "is_correct": true, "explanation": "“台”指高出地面、可以站立的平面，站在台上能看得更远，符合语境。"}, {"text": "烟", "is_correct": false, "explanation": "语义：烟无法承托人站立，句意不通。"}, {"text": "雾", "is_correct": false, "explanation": "语义：雾无法承托人站立，“站在雾上”句意不通。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子只是光线投下的暗区，承托不了人站立，句意不通。"}], "explanations": {"台": "“台”指高出地面、可以站立的平面，站在台上能看得更远，符合语境。", "烟": "语义：烟无法承托人站立，句意不通。", "雾": "语义：雾无法承托人站立，“站在雾上”句意不通。", "影子": "语义：影子只是光线投下的暗区，承托不了人站立，句意不通。"}, "sentence_index": 0, "correct_answer": "台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我和朋友去俱乐部打台。", "explanation": "这里应该用〈台球〉。台指比地面高、可以站上去的平面，不能单独指打的台球。"}, {"text": "天黑了，他打开桌上的台看书。", "explanation": "这里应该用〈台灯〉。台指比地面高、可以站上去的平面，不能单独指台灯。"}, {"text": "昨晚台掠过海面，渔船都回了港。", "explanation": "这里应该用〈台风〉。台指比地面高、可以站上去的平面，不能单独指台风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b268d74d-6786-4d74-8f85-b1d48d0279b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86291, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "台", "is_correct": true, "explanation": "台（tái）指比地面高、可以站上去的平台，是正确答案。"}, {"text": "态", "is_correct": false, "explanation": "tài（第四声）与 tái（第二声）声调不同，意思是“态”。"}, {"text": "坛", "is_correct": false, "explanation": "tán 与 tái 韵母不同（an 与 ai），意思是“坛”。"}, {"text": "堂", "is_correct": false, "explanation": "táng 与 tái 韵母不同（ang 与 ai），意思是“堂”。"}], "explanations": {"台": "台（tái）指比地面高、可以站上去的平台，是正确答案。", "态": "tài（第四声）与 tái（第二声）声调不同，意思是“态”。", "坛": "tán 与 tái 韵母不同（an 与 ai），意思是“坛”。", "堂": "táng 与 tái 韵母不同（ang 与 ai），意思是“堂”。"}, "sentence_index": null, "correct_answer": "台"}, "level_3": {"options": [{"text": "台", "is_correct": true, "explanation": "“台”指比地面高、可以站上去的地方，走到台边往下看，符合语境。"}, {"text": "风", "is_correct": false, "explanation": "语义：风看不见也摸不着，没有边可以走到，句意不通。"}, {"text": "光", "is_correct": false, "explanation": "语义：光不是能走到边上再往下看的高处，句意不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不是一个地方，不能“走到声音边”，句意不通。"}], "explanations": {"台": "“台”指比地面高、可以站上去的地方，走到台边往下看，符合语境。", "风": "语义：风看不见也摸不着，没有边可以走到，句意不通。", "光": "语义：光不是能走到边上再往下看的高处，句意不通。", "声音": "语义：声音不是一个地方，不能“走到声音边”，句意不通。"}, "sentence_index": 6, "correct_answer": "台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "台过境后，街上到处是落叶。", "explanation": "这里应该用〈台风〉。台指比地面高、可以站上去的平面，不能单独指台风。"}, {"text": "他把台背得很熟。", "explanation": "这里应该用〈台词〉。台指可以站上去的平面，演员要背的台词不能说台。"}, {"text": "孩子们一步一个台地往上走。", "explanation": "这里应该用〈台阶〉。台指比地面高的平台，一级一级的踏步要说台阶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b268d74d-6786-4d74-8f85-b1d48d0279b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86291, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "广场中间有一只台，很高。", "corrected_sentence": "广场中间有一个台，很高。", "error_description": "错误形式：“一只台”；正确形式：“一个台”。“只”是动物的量词，台应该用“个”来计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b268d74d-6786-4d74-8f85-b1d48d0279b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86291, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他走到台里，大家都停下来看他。", "corrected_sentence": "他走到台上，大家都停下来看他。", "error_description": "错误形式：“台里”；正确形式：“台上”。平台是可以站上去的平面，表示位置要用“上”，“里”表示容器的内部。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b268d74d-6786-4d74-8f85-b1d48d0279b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
