INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86293, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "本人是自己，不是别人。", "primary_collocate": null, "pronunciation": "běn rén", "ipa": "pən˨˩˦ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "办这个手续，必须本人去。", "target_word": "本人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请带好身份证，由本人签字。", "target_word": "本人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片和本人不太一样。", "target_word": "本人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理本人也来参加了晚会。", "target_word": "本人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信是总统本人写的。", "target_word": "本人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行说，取钱要本人来办。", "target_word": "本人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师本人没有来，只来了他的学生。", "target_word": "本人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电话不是助手打的，是他本人打的。", "target_word": "本人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想见的不是他的助手，而是他本人。", "target_word": "本人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车票要本人使用，别人不能用。", "target_word": "本人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "指某人自己，强调不是别人代替", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717e23d-bca9-41d2-953d-d55f3fb7f070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86293, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本人", "is_correct": true, "explanation": "“本人”指当事人自己，与“办手续必须亲自去”的要求相符。"}, {"text": "本来", "is_correct": false, "explanation": "语法：“本来”是副词，表示原先，不能作“去”的主语。"}, {"text": "本领", "is_correct": false, "explanation": "语义：“本领”指能力，不是人，不能去办手续。"}, {"text": "原来", "is_correct": false, "explanation": "语法：“原来”是副词或形容词，不能作“去”的主语。"}], "explanations": {"本人": "“本人”指当事人自己，与“办手续必须亲自去”的要求相符。", "本来": "语法：“本来”是副词，表示原先，不能作“去”的主语。", "本领": "语义：“本领”指能力，不是人，不能去办手续。", "原来": "语法：“原来”是副词或形容词，不能作“去”的主语。"}, "sentence_index": 0, "correct_answer": "本人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个城市的本人很热情。", "explanation": "这里应该用〈本地人〉。“本人”指人自己，不指当地人。"}, {"text": "这个问题本人很简单。", "explanation": "这里应该用〈本身〉。“本人”只用于人，说事情自身要用“本身”。"}, {"text": "我雇了一个本人来帮忙。", "explanation": "这里应该用〈工人〉。“本人”指说话人或当事人自己，不能当作可以雇用、泛指的人来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86293, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本人", "is_correct": true, "explanation": "“本人”指老师自己，与“没有来”搭配自然，并与后文“只来了他的学生”相呼应。"}, {"text": "大家", "is_correct": false, "explanation": "搭配：“大家”指所有人，与“老师”同指矛盾，也与“只来了他的学生”的语境不符。"}, {"text": "某人", "is_correct": false, "explanation": "语义：“某人”指不确定的人，与说明老师具体没来的语境不符。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问词，放在陈述句中语义不通，也无法与“只来了学生”的叙述衔接。"}], "explanations": {"本人": "“本人”指老师自己，与“没有来”搭配自然，并与后文“只来了他的学生”相呼应。", "大家": "搭配：“大家”指所有人，与“老师”同指矛盾，也与“只来了他的学生”的语境不符。", "某人": "语义：“某人”指不确定的人，与说明老师具体没来的语境不符。", "谁": "语义：“谁”是疑问词，放在陈述句中语义不通，也无法与“只来了学生”的叙述衔接。"}, "sentence_index": 6, "correct_answer": "本人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的本人都在国外。", "explanation": "这里应该用〈亲人〉。“本人”指某个人自己，不指家里的人，也不能用“都”统括一群亲人。"}, {"text": "他的本人很大。", "explanation": "这里应该用〈本领〉。“本人”指人自己，不指能力，说能力强要用“本领”。"}, {"text": "这些本人都很努力。", "explanation": "这里应该用〈同学〉。“本人”指某一个人自己，不能与“这些”搭配指一群人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
