INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86294, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "说话人自己；也指当事人自身。", "primary_collocate": null, "pronunciation": "běn rén", "ipa": "pən˨˩˦ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "大家好，本人今年二十岁，喜欢画画。", "target_word": "本人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本人对这件事不太了解。", "target_word": "本人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以上内容，本人都同意。", "target_word": "本人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本人明天不在公司，请改天再来。", "target_word": "本人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事和本人没有关系。", "target_word": "本人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本人很高兴能认识大家。", "target_word": "本人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题我来处理，本人会负责到底。", "target_word": "本人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢大家，本人一定努力工作。", "target_word": "本人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对于这个决定，本人没有意见。", "target_word": "本人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本人愿意把这些书送给学校。", "target_word": "本人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "说话人用来称呼自己，相当于“我”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717e23d-bca9-41d2-953d-d55f3fb7f070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86294, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本人", "is_correct": true, "explanation": "“本人”是说话人自称，相当于“我”，与自我介绍的语境相符。"}, {"text": "你", "is_correct": false, "explanation": "语义：“你”指听话人，自我介绍中不能用它指说话人自己。"}, {"text": "别人", "is_correct": false, "explanation": "语义：“别人”指说话人以外的人，不能作说话人的自称。"}, {"text": "人家", "is_correct": false, "explanation": "语域：“人家”口语色彩浓，用于正式自我介绍不合适，而且指他人，与语境矛盾。"}], "explanations": {"本人": "“本人”是说话人自称，相当于“我”，与自我介绍的语境相符。", "你": "语义：“你”指听话人，自我介绍中不能用它指说话人自己。", "别人": "语义：“别人”指说话人以外的人，不能作说话人的自称。", "人家": "语域：“人家”口语色彩浓，用于正式自我介绍不合适，而且指他人，与语境矛盾。"}, "sentence_index": 0, "correct_answer": "本人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些本人都很高兴。", "explanation": "这里应该用〈同学们〉。“本人”只指说话人或当事人自己一个人，不能指一群人。"}, {"text": "本人一起去看展览吧。", "explanation": "这里应该用〈我们〉。“本人”只指说话人自己一个人，不能指包括别人在内的“我们”。"}, {"text": "本人明天有空吗？", "explanation": "这里应该用〈你〉。“本人”指说话人自己，不能用来问对方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86294, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本人", "is_correct": true, "explanation": "“本人”是说话人自称，与“会负责到底”的承诺语境相符。"}, {"text": "某人", "is_correct": false, "explanation": "语义：“某人”指不确定的人，与说话人表态承担责任的语境不符。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问词，放在陈述句中语义不通，无法表示承担责任的表态。"}, {"text": "本领", "is_correct": false, "explanation": "语义：“本领”指能力，不是人，不能作“负责”的主语。"}], "explanations": {"本人": "“本人”是说话人自称，与“会负责到底”的承诺语境相符。", "某人": "语义：“某人”指不确定的人，与说话人表态承担责任的语境不符。", "谁": "语义：“谁”是疑问词，放在陈述句中语义不通，无法表示承担责任的表态。", "本领": "语义：“本领”指能力，不是人，不能作“负责”的主语。"}, "sentence_index": 6, "correct_answer": "本人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的本人都很健康。", "explanation": "这里应该用〈家人〉。“本人”只指一个人自己，不能指整个家庭。"}, {"text": "一家本人都很高兴。", "explanation": "这里应该用〈一家人〉。“本人”只指一个人自己，不能指整个家庭。"}, {"text": "本人一起去吃饭吧。", "explanation": "这里应该用〈咱们〉。“本人”只指说话人自己，不能指包括对方在内的集体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
