INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86295, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "“杀”是让人或动物不能再活着。", "primary_collocate": null, "pronunciation": "shā", "ipa": "ʂa˥", "syllable_count": 1, "sentences": [{"text": "农民杀了一头猪。", "target_word": "杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这头猪太大了，不好杀。", "target_word": "杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，他们杀牛祭天。", "target_word": "杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在法律上，杀人要受到惩罚。", "target_word": "杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来没有杀过一只动物。", "target_word": "杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让我把那条鱼杀了。", "target_word": "杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能随便杀野生动物。", "target_word": "杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小时候，我看见爷爷杀羊。", "target_word": "杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的人过节才杀鸡。", "target_word": "杀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位厨师一天杀二十条鱼。", "target_word": "杀", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "杀了", "label": "完成体"}, {"form": "杀过", "label": "经验体"}, {"form": "杀死", "label": "复合词"}, {"form": "杀手", "label": "复合词"}, {"form": "殺", "label": "繁体"}], "register": "中性", "sense_fingerprint": "让人或动物不能再活着，如杀猪、杀牛、杀羊", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c0ab6f7-c290-4f0d-b235-03751b345931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86295, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "杀", "is_correct": true, "explanation": "杀 shā（第一声）：让人或动物不能再活着，正确答案。"}, {"text": "撒", "is_correct": false, "explanation": "sā 与 shā 声母不同（s 与 sh），意思是撒落。"}, {"text": "伤", "is_correct": false, "explanation": "shāng 与 shā 韵尾不同（-ng 与 -a），意思是受伤。"}, {"text": "刷", "is_correct": false, "explanation": "shuā 比 shā 多了介音 u，意思是刷子、刷洗。"}], "explanations": {"杀": "杀 shā（第一声）：让人或动物不能再活着，正确答案。", "撒": "sā 与 shā 声母不同（s 与 sh），意思是撒落。", "伤": "shāng 与 shā 韵尾不同（-ng 与 -a），意思是受伤。", "刷": "shuā 比 shā 多了介音 u，意思是刷子、刷洗。"}, "sentence_index": null, "correct_answer": "杀"}, "level_3": {"options": [{"text": "杀", "is_correct": true, "explanation": "杀：让动物不能再活着，与“一头猪”搭配，符合语境。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”用于歌曲、戏曲，不能与“猪”搭配。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“穿”表示把衣服穿在身上，与“一头猪”的意思不符。"}, {"text": "读", "is_correct": false, "explanation": "搭配：“读”的对象是文字，不能说“读一头猪”。"}], "explanations": {"杀": "杀：让动物不能再活着，与“一头猪”搭配，符合语境。", "唱": "搭配：“唱”用于歌曲、戏曲，不能与“猪”搭配。", "穿": "语义：“穿”表示把衣服穿在身上，与“一头猪”的意思不符。", "读": "搭配：“读”的对象是文字，不能说“读一头猪”。"}, "sentence_index": 0, "correct_answer": "杀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把那张纸杀成了两半。", "explanation": "这里应该用〈撕〉。“杀”指使人或动物失去生命，不能用于把纸弄成两半，撕纸要说“撕”。"}, {"text": "他用斧子杀木头。", "explanation": "这里应该用〈砍〉。“杀”只用于人或动物，不能用于木头。"}, {"text": "她在院子里杀花。", "explanation": "这里应该用〈摘〉。“杀”不用于花，采花要说“摘”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86295, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "杀", "is_correct": true, "explanation": "杀 shā（第一声）：让人或动物不能再活着，正确答案。"}, {"text": "傻", "is_correct": false, "explanation": "shǎ（第三声）与 shā（第一声）声调不同，意思是傻。"}, {"text": "煞", "is_correct": false, "explanation": "shà（第四声）与 shā（第一声）声调不同，意思是煞住。"}, {"text": "删", "is_correct": false, "explanation": "shān 与 shā 韵尾不同（多一个 n），意思是删除。"}], "explanations": {"杀": "杀 shā（第一声）：让人或动物不能再活着，正确答案。", "傻": "shǎ（第三声）与 shā（第一声）声调不同，意思是傻。", "煞": "shà（第四声）与 shā（第一声）声调不同，意思是煞住。", "删": "shān 与 shā 韵尾不同（多一个 n），意思是删除。"}, "sentence_index": null, "correct_answer": "杀"}, "level_3": {"options": [{"text": "杀", "is_correct": true, "explanation": "杀：让动物不能再活着，与“随便”的语境相符，表示随意伤害动物。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字，不能说“写野生动物”。"}, {"text": "听", "is_correct": false, "explanation": "搭配：“听”的对象是声音，不能说“听野生动物”。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，不能说“喝野生动物”。"}], "explanations": {"杀": "杀：让动物不能再活着，与“随便”的语境相符，表示随意伤害动物。", "写": "搭配：“写”的对象是文字，不能说“写野生动物”。", "听": "搭配：“听”的对象是声音，不能说“听野生动物”。", "喝": "搭配：“喝”的对象是饮品，不能说“喝野生动物”。"}, "sentence_index": 6, "correct_answer": "杀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在锅里杀鸡蛋。", "explanation": "这里应该用〈煎〉。“杀”指使人或动物失去生命，不能用于煎鸡蛋。"}, {"text": "他杀干净了桌子。", "explanation": "这里应该用〈擦〉。“杀”不用于擦拭，擦桌子要说“擦”。"}, {"text": "她用剪刀杀纸。", "explanation": "这里应该用〈剪〉。“杀”不用于纸，剪纸要说“剪”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id