INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86296, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "杀", "is_correct": true, "explanation": "杀 shā（第一声）：使人或动物失去生命，正确答案。"}, {"text": "煞", "is_correct": false, "explanation": "shà（第四声）与 shā（第一声）声调不同，意思是煞住、停止。"}, {"text": "啥", "is_correct": false, "explanation": "shá（第二声）与 shā（第一声）声调不同，意思是什么。"}, {"text": "删", "is_correct": false, "explanation": "shān 与 shā 韵尾不同（多一个 n），意思是删除。"}, {"text": "伤", "is_correct": false, "explanation": "shāng 与 shā 韵尾不同（-ng 与 -a），意思是受伤。"}], "explanations": {"杀": "杀 shā（第一声）：使人或动物失去生命，正确答案。", "煞": "shà（第四声）与 shā（第一声）声调不同，意思是煞住、停止。", "啥": "shá（第二声）与 shā（第一声）声调不同，意思是什么。", "删": "shān 与 shā 韵尾不同（多一个 n），意思是删除。", "伤": "shāng 与 shā 韵尾不同（-ng 与 -a），意思是受伤。"}, "sentence_index": null, "correct_answer": "杀"}, "level_3": {"options": [{"text": "杀", "is_correct": true, "explanation": "杀：使人失去生命，与“人”和“犯法”的语境相符。"}, {"text": "救", "is_correct": false, "explanation": "语义：“救”表示使人脱离危险，救人不会犯法，与“犯法”矛盾。"}, {"text": "帮", "is_correct": false, "explanation": "语义：“帮”是帮助别人，不属于违法行为，与“犯法”矛盾。"}, {"text": "扶", "is_correct": false, "explanation": "搭配：“扶”指扶持、搀扶，不能与“犯法”搭配构成这样的判断。"}], "explanations": {"杀": "杀：使人失去生命，与“人”和“犯法”的语境相符。", "救": "语义：“救”表示使人脱离危险，救人不会犯法，与“犯法”矛盾。", "帮": "语义：“帮”是帮助别人，不属于违法行为，与“犯法”矛盾。", "扶": "搭配：“扶”指扶持、搀扶，不能与“犯法”搭配构成这样的判断。"}, "sentence_index": 6, "correct_answer": "杀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在案板上杀肉馅。", "explanation": "这里应该用〈剁〉。“杀”指使人或动物失去生命，不用于把肉剁碎。"}, {"text": "农民在地里杀麦子。", "explanation": "这里应该用〈割〉。“杀”不用于庄稼，收割麦子要说“割”。"}, {"text": "他在树下杀了一个苹果。", "explanation": "这里应该用〈摘〉。“杀”指使人或动物失去生命，不用于摘果子，摘苹果要说“摘”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86296, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我从来没杀了鸭子。", "corrected_sentence": "我从来没杀过鸭子。", "error_description": "错误在于“了”与“过”用错。否定经历要用“没……过”，“了”不能用于经历的否定，应说“没杀过鸭子”，不说“没杀了鸭子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86296, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在河边了杀一条鱼。", "corrected_sentence": "他在河边杀了一条鱼。", "error_description": "错误在于“了”的位置。完成体“了”应放在动词之后，应说“杀了一条鱼”，不说“了杀一条鱼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
