INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86300, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "“第一”指最重要、最优先的。", "primary_collocate": null, "pronunciation": "dì yī", "ipa": "ti⁵¹ i⁵⁵", "syllable_count": 2, "sentences": [{"text": "安全第一，大家要小心。", "target_word": "第一", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "对我来说，健康第一。", "target_word": "第一", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在这个家里，孩子的学习是第一位的。", "target_word": "第一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做生意，质量第一，客人第二。", "target_word": "第一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对他来说，朋友的感受是第一位的。", "target_word": "第一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司把客人放在第一位。", "target_word": "第一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车的时候，安全比什么都重要，安全永远是第一。", "target_word": "第一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈觉得，孩子的身体第一，成绩第二。", "target_word": "第一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在他心里，家人永远排第一。", "target_word": "第一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛再重要，也要身体第一。", "target_word": "第一", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "第一流", "label": "复合"}], "register": "中性", "sense_fingerprint": "表示最重要、最优先，如安全第一、健康第一、放在第一位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a6dfb6-2ee6-453e-a7c2-961fd8e3fc9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86300, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "第一", "is_correct": true, "explanation": "正确答案。第一表示最重要、最优先，读作 dì yī。"}, {"text": "地域", "is_correct": false, "explanation": "dì yù 与 dì yī 第一个字同音同调，第二个字韵母和声调不同，意思是地区范围。"}, {"text": "敌意", "is_correct": false, "explanation": "dí（第二声）与 dì（第四声）声调不同，yì（第四声）与 yī（第一声）声调也不同，意思是敌对的心理。"}, {"text": "立意", "is_correct": false, "explanation": "lì（第四声）与 dì 声母不同（l 与 d），yì 与 yī 声调不同，意思是构思的意图。"}], "explanations": {"第一": "正确答案。第一表示最重要、最优先，读作 dì yī。", "地域": "dì yù 与 dì yī 第一个字同音同调，第二个字韵母和声调不同，意思是地区范围。", "敌意": "dí（第二声）与 dì（第四声）声调不同，yì（第四声）与 yī（第一声）声调也不同，意思是敌对的心理。", "立意": "lì（第四声）与 dì 声母不同（l 与 d），yì 与 yī 声调不同，意思是构思的意图。"}, "sentence_index": null, "correct_answer": "第一"}, "level_3": {"options": [{"text": "第一", "is_correct": true, "explanation": "正确答案。“安全第一”表示安全最重要，符合句意。"}, {"text": "最后", "is_correct": false, "explanation": "语义：最后指末位，“安全最后”与后句“大家要小心”的提醒相矛盾。"}, {"text": "次要", "is_correct": false, "explanation": "语义：次要表示不重要，与后句“大家要小心”的提醒相矛盾。"}, {"text": "无足轻重", "is_correct": false, "explanation": "语义：无足轻重表示不重要，与“安全”的优先地位及后句的提醒相矛盾。"}], "explanations": {"第一": "正确答案。“安全第一”表示安全最重要，符合句意。", "最后": "语义：最后指末位，“安全最后”与后句“大家要小心”的提醒相矛盾。", "次要": "语义：次要表示不重要，与后句“大家要小心”的提醒相矛盾。", "无足轻重": "语义：无足轻重表示不重要，与“安全”的优先地位及后句的提醒相矛盾。"}, "sentence_index": 0, "correct_answer": "第一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "做生意，质量非常第一。", "explanation": "〈第一〉表示“最重要”时已是最高程度，不能再受〈非常〉修饰；应说〈质量第一〉。"}, {"text": "做生意，质量比价格第一。", "explanation": "〈第一〉不能用在“比”字句中作比较结果；应说〈质量比价格重要〉或〈质量第一〉。"}, {"text": "做生意，质量第一得很。", "explanation": "〈第一〉不能带程度补语〈得很〉；应说〈质量第一〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86300, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "第一", "is_correct": true, "explanation": "正确答案。“安全永远是第一”表示安全始终最重要，符合句意。"}, {"text": "末位", "is_correct": false, "explanation": "语义：末位指排在最后，与前文“安全比什么都重要”相反。"}, {"text": "多余", "is_correct": false, "explanation": "语义：多余表示不必要，与前文“安全比什么都重要”相反。"}, {"text": "普通", "is_correct": false, "explanation": "语义：普通表示平常，与前文对安全的强调不符。"}], "explanations": {"第一": "正确答案。“安全永远是第一”表示安全始终最重要，符合句意。", "末位": "语义：末位指排在最后，与前文“安全比什么都重要”相反。", "多余": "语义：多余表示不必要，与前文“安全比什么都重要”相反。", "普通": "语义：普通表示平常，与前文对安全的强调不符。"}, "sentence_index": 6, "correct_answer": "第一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛再重要，也要身体第一个。", "explanation": "〈第一〉表示“最重要”时作谓语，后面不接量词〈个〉；这里应说〈身体第一〉或〈身体最重要〉。"}, {"text": "我觉得身体很第一，比赛其次。", "explanation": "〈第一〉表示“最重要”时作谓语，不能受程度副词〈很〉修饰；应说〈身体最重要〉。"}, {"text": "比赛再重要，也要身体第一地。", "explanation": "〈第一〉后面不能接〈地〉作状语；表示“最重要”应说〈身体最重要〉或〈身体第一〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86300, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在我心里，健康第一位的。", "corrected_sentence": "在我心里，健康是第一位的。", "error_description": "“第一位”作谓语时要用“是……的”结构，漏掉“是”不对。正确说法是“健康是第一位的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86300, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈觉得，孩子的身体最第一。", "corrected_sentence": "妈妈觉得，孩子的身体第一。", "error_description": "“第一”本身就表示最重要，不能再加“最”。正确说法是“孩子的身体第一”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
