INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86301, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "班是一起上课的一群学生。", "primary_collocate": null, "pronunciation": "bān", "ipa": "pan˥", "syllable_count": 1, "sentences": [{"text": "我们班的老师姓王。", "target_word": "班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班一共有四十个学生。", "target_word": "班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们班学习最好的。", "target_word": "班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天我们班要去参观博物馆。", "target_word": "班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想转到别的班上课。", "target_word": "班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班来了一位新同学。", "target_word": "班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她进了这个班，认识了很多朋友。", "target_word": "班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们班的同学都喜欢打篮球。", "target_word": "班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请我们班的同学安静一下。", "target_word": "班", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班的学生来自五个国家。", "target_word": "班", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "班级", "label": "复合"}, {"form": "班长", "label": "复合"}, {"form": "班主任", "label": "复合"}], "register": "中性", "sense_fingerprint": "班：一起上课的一群学生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd9494de-5348-4735-8c04-847b659ff0a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86301, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "班", "is_correct": true, "explanation": "班 bān（第一声）：一起上课的一群学生。"}, {"text": "办", "is_correct": false, "explanation": "办 bàn（第四声）与 bān（第一声）声调不同，意思是办理、处理。"}, {"text": "帮", "is_correct": false, "explanation": "帮 bāng 与 bān 韵尾不同（ang 与 an），意思是帮助。"}, {"text": "板", "is_correct": false, "explanation": "板 bǎn（第三声）与 bān（第一声）声调不同，意思是木板。"}], "explanations": {"班": "班 bān（第一声）：一起上课的一群学生。", "办": "办 bàn（第四声）与 bān（第一声）声调不同，意思是办理、处理。", "帮": "帮 bāng 与 bān 韵尾不同（ang 与 an），意思是帮助。", "板": "板 bǎn（第三声）与 bān（第一声）声调不同，意思是木板。"}, "sentence_index": null, "correct_answer": "班"}, "level_3": {"options": [{"text": "班", "is_correct": true, "explanation": "正确：“我们班”指一起上课的一群学生，可以有老师。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书，不是一群学生，不能有“老师姓王”的说法。"}, {"text": "样子", "is_correct": false, "explanation": "体貌：“样子”指外表形状，不指学生集体，与“的老师”不搭。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不能与老师构成“的老师”的关系。"}], "explanations": {"班": "正确：“我们班”指一起上课的一群学生，可以有老师。", "课本": "语义：课本是书，不是一群学生，不能有“老师姓王”的说法。", "样子": "体貌：“样子”指外表形状，不指学生集体，与“的老师”不搭。", "窗户": "语义：窗户是建筑部件，不能与老师构成“的老师”的关系。"}, "sentence_index": 0, "correct_answer": "班"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的河很长，很清。", "explanation": "这里应该用〈河流〉。班是一群学生，不是河流；“很长，很清”属于河流。"}, {"text": "我们班的汽油快用完了。", "explanation": "这里应该用〈汽车〉。班是一群学生，不用汽油；“汽油快用完了”属于汽车。"}, {"text": "这个班的东西很便宜。", "explanation": "这里应该用〈超市〉。班指学生组织，不卖东西；“东西很便宜”属于超市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86301, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "班", "is_correct": true, "explanation": "班 bān（第一声）：一起上课的一群学生。"}, {"text": "半", "is_correct": false, "explanation": "半 bàn（第四声）与 bān（第一声）声调不同，意思是一半。"}, {"text": "版", "is_correct": false, "explanation": "版 bǎn（第三声）与 bān（第一声）声调不同，意思是版面、版本。"}, {"text": "八", "is_correct": false, "explanation": "八 bā 比 bān 少了韵尾 n，意思是数字八。"}, {"text": "奔", "is_correct": false, "explanation": "奔 bēn 与 bān 韵母不同（en 与 an），意思是奔跑。"}], "explanations": {"班": "班 bān（第一声）：一起上课的一群学生。", "半": "半 bàn（第四声）与 bān（第一声）声调不同，意思是一半。", "版": "版 bǎn（第三声）与 bān（第一声）声调不同，意思是版面、版本。", "八": "八 bā 比 bān 少了韵尾 n，意思是数字八。", "奔": "奔 bēn 与 bān 韵母不同（en 与 an），意思是奔跑。"}, "sentence_index": null, "correct_answer": "班"}, "level_3": {"options": [{"text": "班", "is_correct": true, "explanation": "正确：“这个班”指一起上课的学生群体，可以“进”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是电子设备，不是可以进入的学习群体。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，“进了冰箱”与“认识朋友”不成立。"}, {"text": "河", "is_correct": false, "explanation": "搭配：“进”后接河流不是常见搭配，且“认识朋友”与河不相关。"}], "explanations": {"班": "正确：“这个班”指一起上课的学生群体，可以“进”。", "手机": "语义：手机是电子设备，不是可以进入的学习群体。", "冰箱": "语义：冰箱是家电，“进了冰箱”与“认识朋友”不成立。", "河": "搭配：“进”后接河流不是常见搭配，且“认识朋友”与河不相关。"}, "sentence_index": 6, "correct_answer": "班"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个班有四个轮子，跑得很快。", "explanation": "这里应该用〈汽车〉。班是一群学生，没有轮子；“四个轮子，跑得很快”属于汽车。"}, {"text": "我们班的井很深。", "explanation": "这里应该用〈水井〉。班不是地方，没有井；“很深”属于水井。"}, {"text": "秋天到了，这个班的叶子都黄了。", "explanation": "这里应该用〈树〉。班是一群学生，没有叶子；“叶子都黄了”属于树。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt