INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86303, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "“不对”是说不是这样，说错了。", "primary_collocate": null, "pronunciation": "bú duì", "ipa": "pu˧˥ tuei˥˩", "syllable_count": 2, "sentences": [{"text": "你说得不对，今天不是星期五。", "target_word": "不对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个答案不对，请再想一想。", "target_word": "不对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说：“不对，应该是三。”", "target_word": "不对", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他算的钱不对，少了十块。", "target_word": "不对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我记的电话号码不对。", "target_word": "不对", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "“他是你哥哥吗？”“不对，他是我弟弟。”", "target_word": "不对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个字你写得不对，少了一点。", "target_word": "不对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的想法不对，事情不是这样的。", "target_word": "不对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你抄的这个数字不对，原题是七。", "target_word": "不对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这句话不对，太阳不从西边出来。", "target_word": "不对", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "答案、说法或数目错了，不正确", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d31e622-4b28-4b23-8714-313fa02ff361') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86303, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不对", "is_correct": true, "explanation": "不对（bú duì）：指不正确、说错了，即本词。"}, {"text": "部队", "is_correct": false, "explanation": "bù（第四声）与 bú（第二声）声调不同，意思是军队。"}, {"text": "不会", "is_correct": false, "explanation": "huì 与 duì 声母不同（h 与 d），意思是“不会”。"}, {"text": "不贵", "is_correct": false, "explanation": "guì 与 duì 声母不同（g 与 d），意思是“不贵”。"}, {"text": "不睡", "is_correct": false, "explanation": "shuì 与 duì 声母不同（sh 与 d），意思是“不睡”。"}], "explanations": {"不对": "不对（bú duì）：指不正确、说错了，即本词。", "部队": "bù（第四声）与 bú（第二声）声调不同，意思是军队。", "不会": "huì 与 duì 声母不同（h 与 d），意思是“不会”。", "不贵": "guì 与 duì 声母不同（g 与 d），意思是“不贵”。", "不睡": "shuì 与 duì 声母不同（sh 与 d），意思是“不睡”。"}, "sentence_index": null, "correct_answer": "不对"}, "level_3": {"options": [{"text": "不对", "is_correct": true, "explanation": "“说得不对”指说的内容有错，与后句“今天不是星期五”形成纠正。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”说味道，不能形容说话的内容。"}, {"text": "暖", "is_correct": false, "explanation": "搭配：“暖”说温度或感情，不能用来评价说话的对错。"}, {"text": "方", "is_correct": false, "explanation": "语义：“方”说形状，不能用来评价说话的对错。"}], "explanations": {"不对": "“说得不对”指说的内容有错，与后句“今天不是星期五”形成纠正。", "咸": "语义：“咸”说味道，不能形容说话的内容。", "暖": "搭配：“暖”说温度或感情，不能用来评价说话的对错。", "方": "语义：“方”说形状，不能用来评价说话的对错。"}, "sentence_index": 0, "correct_answer": "不对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天天气很不对，阳光特别好。", "explanation": "这里应该用〈好〉。不对指答案或说法错了，夸天气好要用好。"}, {"text": "这家饭馆的菜很不对，大家都很喜欢。", "explanation": "这里应该用〈不错〉。不对指答案或数目错了，夸菜好要用不错。"}, {"text": "这本书很不对，我看了三遍。", "explanation": "这里应该用〈好看〉。不对指答案或说法错了，夸书好要用好看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86303, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不对", "is_correct": true, "explanation": "“写得不对”指字写错了，与后句“少了一点”一致。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说味道，不能形容写字的对错。"}, {"text": "凉", "is_correct": false, "explanation": "搭配：“凉”说温度，不能说“写得凉”。"}, {"text": "苦", "is_correct": false, "explanation": "语义：“苦”说味道，不能形容写字的对错。"}], "explanations": {"不对": "“写得不对”指字写错了，与后句“少了一点”一致。", "甜": "语义：“甜”说味道，不能形容写字的对错。", "凉": "搭配：“凉”说温度，不能说“写得凉”。", "苦": "语义：“苦”说味道，不能形容写字的对错。"}, "sentence_index": 6, "correct_answer": "不对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的新同学很不对，大家都喜欢他。", "explanation": "这里应该用〈好〉。不对指答案或说法错了，不能用来夸人。"}, {"text": "这次考试他很不对，一道题都没答。", "explanation": "这里应该用〈糟糕〉。不对表示答案或做法错了，形容考试表现差要用糟糕。"}, {"text": "他听到这个好消息很不对，一直在笑。", "explanation": "这里应该用〈高兴〉。不对指答案或说法错了，不能用来形容心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86303, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个数字不不对，应该是八。", "corrected_sentence": "这个数字不对，应该是八。", "error_description": "错误：“不不对”，多写了一个“不”；正确：“不对”。“不对”只用一个否定词，重复“不”不成词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
