INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86304, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容词，指不正确、不合适。", "primary_collocate": null, "pronunciation": "bú duì", "ipa": "pu˧˥ tuei˥˩", "syllable_count": 2, "sentences": [{"text": "在会议上大声说话是不对的。", "target_word": "不对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样对老人说话不对。", "target_word": "不对", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "打人是不对的，要说对不起。", "target_word": "不对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你这样做不对，别人会不高兴。", "target_word": "不对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这双鞋的颜色不对，和这件衣服不配。", "target_word": "不对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天穿这件衣服去面试不对。", "target_word": "不对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在去朋友家不对，他们在睡觉。", "target_word": "不对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在电影院里打电话不对。", "target_word": "不对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说话的时间不对，大家都在忙。", "target_word": "不对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "拿走别人的东西是不对的。", "target_word": "不对", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "做法或场合不合适，不应该", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d31e622-4b28-4b23-8714-313fa02ff361') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86304, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不对", "is_correct": true, "explanation": "不对（bú duì）：指做法或场合不合适、不应该，即本词。"}, {"text": "部队", "is_correct": false, "explanation": "bù（第四声）与 bú（第二声）声调不同，意思是军队。"}, {"text": "不会", "is_correct": false, "explanation": "huì 与 duì 声母不同（h 与 d），意思是“不会”。"}, {"text": "不贵", "is_correct": false, "explanation": "guì 与 duì 声母不同（g 与 d），意思是“不贵”。"}, {"text": "不睡", "is_correct": false, "explanation": "shuì 与 duì 声母不同（sh 与 d），意思是“不睡”。"}], "explanations": {"不对": "不对（bú duì）：指做法或场合不合适、不应该，即本词。", "部队": "bù（第四声）与 bú（第二声）声调不同，意思是军队。", "不会": "huì 与 duì 声母不同（h 与 d），意思是“不会”。", "不贵": "guì 与 duì 声母不同（g 与 d），意思是“不贵”。", "不睡": "shuì 与 duì 声母不同（sh 与 d），意思是“不睡”。"}, "sentence_index": null, "correct_answer": "不对"}, "level_3": {"options": [{"text": "不对", "is_correct": true, "explanation": "“是不对的”评价做法不合适，与前句“在会议上大声说话”搭配。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说味道，不能用来评价行为。"}, {"text": "冷", "is_correct": false, "explanation": "搭配：“冷”说温度或态度，不能用来评价“大声说话”。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”说形状，不能用来评价行为。"}], "explanations": {"不对": "“是不对的”评价做法不合适，与前句“在会议上大声说话”搭配。", "甜": "语义：“甜”说味道，不能用来评价行为。", "冷": "搭配：“冷”说温度或态度，不能用来评价“大声说话”。", "圆": "语义：“圆”说形状，不能用来评价行为。"}, "sentence_index": 0, "correct_answer": "不对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜的味道很不对，大家都夸它好吃。", "explanation": "这里应该用〈好吃〉。不对表示不正确、不合适，夸菜味道好要用好吃。"}, {"text": "这个西瓜很不对，我一口气吃了很多。", "explanation": "这里应该用〈甜〉。不对表示不正确、不合适，说西瓜好吃要用甜。"}, {"text": "他的心情很不对，每天都在笑。", "explanation": "这里应该用〈高兴〉。不对表示不正确、不合适，形容心情好要用高兴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86304, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不对", "is_correct": true, "explanation": "“去朋友家不对”指时机不合适，与后句“他们在睡觉”呼应。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”说味道，不能评价拜访的时机。"}, {"text": "硬", "is_correct": false, "explanation": "语义：“硬”说质地，不能评价拜访的时机。"}, {"text": "苦", "is_correct": false, "explanation": "语义：“苦”说味道，不能评价拜访的时机。"}], "explanations": {"不对": "“去朋友家不对”指时机不合适，与后句“他们在睡觉”呼应。", "咸": "语义：“咸”说味道，不能评价拜访的时机。", "硬": "语义：“硬”说质地，不能评价拜访的时机。", "苦": "语义：“苦”说味道，不能评价拜访的时机。"}, "sentence_index": 6, "correct_answer": "不对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去年买的房子很不对，住得很开心。", "explanation": "这里应该用〈好〉。不对表示不正确、不合适，说房子住得满意要用好。"}, {"text": "这份合同的签字很不对，大家都很放心。", "explanation": "这里应该用〈正确〉。不对表示不合适，说签字无误要用正确。"}, {"text": "这次旅行的天气很不对，阳光很好。", "explanation": "这里应该用〈好〉。不对表示不正确、不合适，说天气晴好要用好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86304, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在医院里大声喧哗不不对。", "corrected_sentence": "在医院里大声喧哗不对。", "error_description": "错误：“不不对”，多写了一个“不”；正确：“不对”。“不对”只用一个否定词，重复“不”不成词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86304, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在图书馆大声说话不对的。", "corrected_sentence": "在图书馆大声说话不对。", "error_description": "错误：句末多了“的”；正确：“在图书馆大声说话不对”。“不对”作谓语时句末不加“的”，“不对的”只用于“是……的”等句式。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
