INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86305, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "“到了”是说走到了想去的地方。", "primary_collocate": null, "pronunciation": "dào le", "ipa": "taʊ̯˥˩ lɤ", "syllable_count": 2, "sentences": [{"text": "我们到了，这就是我家。", "target_word": "到了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们到了公园门口。", "target_word": "到了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走了一个小时，终于到了山顶。", "target_word": "到了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了车站，我给妈妈打电话。", "target_word": "到了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸到了机场，朋友在那里等他。", "target_word": "到了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你到了学校，请给我发消息。", "target_word": "到了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们走了很久，到了河边。", "target_word": "到了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人到了门口，我去开门。", "target_word": "到了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说：“大家到了，我们进去吧。”", "target_word": "到了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗跑得很快，先到了房子前面。", "target_word": "到了", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "到", "label": "单字形式"}, {"form": "到过", "label": "经验体"}, {"form": "没到", "label": "否定形式"}], "register": "中性", "sense_fingerprint": "走到了想去的地方，如到了学校、到了山顶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c0ab6f7-c290-4f0d-b235-03751b345931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86305, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "到了", "is_correct": true, "explanation": "到了 dào le：表示走到了想去的地方，正确答案。"}, {"text": "闹了", "is_correct": false, "explanation": "nào le 与 dào le 声母不同（n 与 d），意思是吵闹。"}, {"text": "套了", "is_correct": false, "explanation": "tào le 与 dào le 声母不同（t 与 d），意思是套住。"}, {"text": "掉了", "is_correct": false, "explanation": "diào le 比 dào le 多了介音 i，意思是掉落。"}], "explanations": {"到了": "到了 dào le：表示走到了想去的地方，正确答案。", "闹了": "nào le 与 dào le 声母不同（n 与 d），意思是吵闹。", "套了": "tào le 与 dào le 声母不同（t 与 d），意思是套住。", "掉了": "diào le 比 dào le 多了介音 i，意思是掉落。"}, "sentence_index": null, "correct_answer": "到了"}, "level_3": {"options": [{"text": "到了", "is_correct": true, "explanation": "到了：表示已经走到了家，与“这就是我家”的语境相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”表示唱歌，与“这就是我家”的语境不符。"}, {"text": "跳", "is_correct": false, "explanation": "语义：“跳”表示跳跃，与“这就是我家”的语境不符。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”表示用水清洁东西，与“这就是我家”表示抵达的语境不符。"}], "explanations": {"到了": "到了：表示已经走到了家，与“这就是我家”的语境相符。", "唱": "语义：“唱”表示唱歌，与“这就是我家”的语境不符。", "跳": "语义：“跳”表示跳跃，与“这就是我家”的语境不符。", "洗": "语义：“洗”表示用水清洁东西，与“这就是我家”表示抵达的语境不符。"}, "sentence_index": 0, "correct_answer": "到了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天到了钱包，急死了。", "explanation": "这里应该用〈丢〉。“到了”表示抵达，不表示丢失东西，丢了钱包要说“丢了”。"}, {"text": "他到了一个包裹。", "explanation": "这里应该用〈拿到〉。“到了”表示抵达，不表示拿到东西。"}, {"text": "妈妈终于到了眼镜。", "explanation": "这里应该用〈找到〉。“到了”表示抵达，不能用于找到东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86305, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "到了", "is_correct": true, "explanation": "到了 dào le：表示走到了想去的地方，正确答案。"}, {"text": "倒了", "is_correct": false, "explanation": "dǎo le（第三声）与 dào le（第四声）第一音节声调不同，意思是倒下。"}, {"text": "待了", "is_correct": false, "explanation": "dài le 与 dào le 韵母不同（ai 与 ao），意思是停留。"}, {"text": "吊了", "is_correct": false, "explanation": "diào le 比 dào le 多了介音 i，意思是悬挂。"}], "explanations": {"到了": "到了 dào le：表示走到了想去的地方，正确答案。", "倒了": "dǎo le（第三声）与 dào le（第四声）第一音节声调不同，意思是倒下。", "待了": "dài le 与 dào le 韵母不同（ai 与 ao），意思是停留。", "吊了": "diào le 比 dào le 多了介音 i，意思是悬挂。"}, "sentence_index": null, "correct_answer": "到了"}, "level_3": {"options": [{"text": "到了", "is_correct": true, "explanation": "到了：表示走了很久后已经抵达河边，与语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”表示进食，“吃了河边”与语境不符。"}, {"text": "讲", "is_correct": false, "explanation": "搭配：“讲”后接话题或内容，不能接处所“河边”。"}, {"text": "缝", "is_correct": false, "explanation": "语义：“缝”表示用针线连接，与走路到河边的语境不符。"}], "explanations": {"到了": "到了：表示走了很久后已经抵达河边，与语境相符。", "吃": "语义：“吃”表示进食，“吃了河边”与语境不符。", "讲": "搭配：“讲”后接话题或内容，不能接处所“河边”。", "缝": "语义：“缝”表示用针线连接，与走路到河边的语境不符。"}, "sentence_index": 6, "correct_answer": "到了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把书到了桌子上。", "explanation": "这里应该用〈放〉。“到了”表示抵达，不表示把东西放置在某处。"}, {"text": "妈妈到了我一份礼物。", "explanation": "这里应该用〈送〉。“到了”表示抵达，不表示送给别人东西。"}, {"text": "他把画到了墙上。", "explanation": "这里应该用〈挂〉。“到了”表示抵达，不表示把画挂在墙上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.