INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86306, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "动词，表示已经抵达某个地点或达到某个时间。", "primary_collocate": null, "pronunciation": "dào le", "ipa": "taʊ̯˥˩ lɤ", "syllable_count": 2, "sentences": [{"text": "火车到了北京。", "target_word": "到了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到了冬天，这里很冷。", "target_word": "到了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们到了，快下车吧。", "target_word": "到了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到了八点，商店就关门。", "target_word": "到了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他到了家，先喝了一杯水。", "target_word": "到了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了春天，山上开满了花。", "target_word": "到了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶到了医院，医生已经在等她。", "target_word": "到了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间到了，请大家交作业。", "target_word": "到了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机晚上十点到了上海。", "target_word": "到了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到了周末，我们常去公园玩。", "target_word": "到了", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "到", "label": "单字形式"}, {"form": "到过", "label": "经验体"}, {"form": "没到", "label": "否定形式"}], "register": "中性", "sense_fingerprint": "已经抵达某地或到了某个时间点，如到了北京、到了冬天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c0ab6f7-c290-4f0d-b235-03751b345931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86306, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "到了", "is_correct": true, "explanation": "到了 dào le：表示已经抵达某地或某时间，正确答案。"}, {"text": "倒了", "is_correct": false, "explanation": "dǎo le（第三声）与 dào le（第四声）第一音节声调不同，意思是倒下。"}, {"text": "掉了", "is_correct": false, "explanation": "diào le 比 dào le 多了介音 i，意思是掉落。"}, {"text": "套了", "is_correct": false, "explanation": "tào le 与 dào le 声母不同（t 与 d），意思是套住。"}], "explanations": {"到了": "到了 dào le：表示已经抵达某地或某时间，正确答案。", "倒了": "dǎo le（第三声）与 dào le（第四声）第一音节声调不同，意思是倒下。", "掉了": "diào le 比 dào le 多了介音 i，意思是掉落。", "套了": "tào le 与 dào le 声母不同（t 与 d），意思是套住。"}, "sentence_index": null, "correct_answer": "到了"}, "level_3": {"options": [{"text": "到了", "is_correct": true, "explanation": "到了：表示火车已经抵达北京，符合语境。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”表示唱歌，火车不能唱北京，语义不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”表示进食，与“火车”和“北京”的语境不符。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”后接具体的物体，不能接城市名。"}], "explanations": {"到了": "到了：表示火车已经抵达北京，符合语境。", "唱": "语义：“唱”表示唱歌，火车不能唱北京，语义不通。", "吃": "语义：“吃”表示进食，与“火车”和“北京”的语境不符。", "咬": "搭配：“咬”后接具体的物体，不能接城市名。"}, "sentence_index": 0, "correct_answer": "到了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天到了感冒。", "explanation": "这里应该用〈得〉。“到了”表示抵达，不表示患病，患感冒要说“得了感冒”。"}, {"text": "他到了一封信。", "explanation": "这里应该用〈收到〉。“到了”表示抵达，不表示收到东西。"}, {"text": "我终于到了钥匙。", "explanation": "这里应该用〈找到〉。“到了”表示抵达，不能用于找到东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86306, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "到了", "is_correct": true, "explanation": "到了 dào le：表示已经抵达某地或某时间，正确答案。"}, {"text": "闹了", "is_correct": false, "explanation": "nào le 与 dào le 声母不同（n 与 d），意思是吵闹。"}, {"text": "待了", "is_correct": false, "explanation": "dài le 与 dào le 韵母不同（ai 与 ao），意思是停留。"}, {"text": "吊了", "is_correct": false, "explanation": "diào le 比 dào le 多了介音 i，意思是悬挂。"}], "explanations": {"到了": "到了 dào le：表示已经抵达某地或某时间，正确答案。", "闹了": "nào le 与 dào le 声母不同（n 与 d），意思是吵闹。", "待了": "dài le 与 dào le 韵母不同（ai 与 ao），意思是停留。", "吊了": "diào le 比 dào le 多了介音 i，意思是悬挂。"}, "sentence_index": null, "correct_answer": "到了"}, "level_3": {"options": [{"text": "到了", "is_correct": true, "explanation": "到了：表示奶奶已经抵达医院，与后文“医生在等她”相符。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”表示拆除，“奶奶拆医院”不合语境，与后文矛盾。"}, {"text": "讲", "is_correct": false, "explanation": "搭配：“讲”后接话题或内容，不能接处所“医院”。"}, {"text": "缝", "is_correct": false, "explanation": "语义：“缝”表示用针线连接，与“医院”和后文的语境不符。"}], "explanations": {"到了": "到了：表示奶奶已经抵达医院，与后文“医生在等她”相符。", "拆": "语义：“拆”表示拆除，“奶奶拆医院”不合语境，与后文矛盾。", "讲": "搭配：“讲”后接话题或内容，不能接处所“医院”。", "缝": "语义：“缝”表示用针线连接，与“医院”和后文的语境不符。"}, "sentence_index": 6, "correct_answer": "到了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我到了她一份生日礼物。", "explanation": "这里应该用〈送〉。“到了”表示抵达，不表示把礼物送给别人，送礼物要说“送”。"}, {"text": "我今天到了一个老朋友。", "explanation": "这里应该用〈遇到〉。“到了”表示抵达，不表示遇见某人。"}, {"text": "我在门口到了一个下午。", "explanation": "这里应该用〈等〉。“到了”表示抵达，不表示等候，等一个下午要说“等了一个下午”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86306, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "火车还没到了北京。", "corrected_sentence": "火车还没到北京。", "error_description": "错误在于“没”与“了”同用。否定“到”应说“还没到北京”，“没到”后不能再加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86306, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们到跑了车站。", "corrected_sentence": "他们跑到了车站。", "error_description": "错误在于结果补语“到”的位置。应说“跑到了车站”，“到”要放在动词之后，不能说“到跑了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86307, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "快乐", "is_correct": true, "explanation": "“快乐”与“痛苦”意思相反，词典中列为反义词。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”形容清晰，与“痛苦”不构成反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "无关：“安静”的反义词是“吵闹”，与“痛苦”没有对应关系。"}, {"text": "严肃", "is_correct": false, "explanation": "无关：“严肃”形容态度庄重，与描述疼或难过的“痛苦”不构成反义。"}], "correct_answer": "快乐", "explanations": {"快乐": "“快乐”与“痛苦”意思相反，词典中列为反义词。", "清楚": "无关：“清楚”形容清晰，与“痛苦”不构成反义关系。", "安静": "无关：“安静”的反义词是“吵闹”，与“痛苦”没有对应关系。", "严肃": "无关：“严肃”形容态度庄重，与描述疼或难过的“痛苦”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
