INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86307, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "痛苦是身体很疼，或心里很难过。", "primary_collocate": null, "pronunciation": "tòng kǔ", "ipa": "tʰʊŋ˥˩ kʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "牙疼的时候，他痛苦得吃不下饭。", "target_word": "痛苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友离开以后，她心里非常痛苦。", "target_word": "痛苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "腿受伤了，他走路时表情很痛苦。", "target_word": "痛苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到坏消息，妈妈的表情很痛苦。", "target_word": "痛苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人想着过去的事，越想越痛苦。", "target_word": "痛苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肚子疼得厉害，她痛苦地躺在床上。", "target_word": "痛苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失去工作让他觉得很痛苦。", "target_word": "痛苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种痛苦的日子，我再也不想过了。", "target_word": "痛苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子生病了，父母看着也很痛苦。", "target_word": "痛苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的心很痛苦，可是什么也没说。", "target_word": "痛苦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "身体疼痛或心里难过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717e23d-bca9-41d2-953d-d55f3fb7f070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86307, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "痛苦", "is_correct": true, "explanation": "“痛苦”指牙疼带来的难受，与“吃不下饭”的结果相符。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”表示愉快，与“牙疼”的语境矛盾。"}, {"text": "欢喜", "is_correct": false, "explanation": "语义：“欢喜”表示高兴，与“牙疼吃不下饭”的语境矛盾。"}, {"text": "兴奋", "is_correct": false, "explanation": "语义：“兴奋”表示情绪高涨，与“牙疼吃不下饭”的情况不符。"}], "explanations": {"痛苦": "“痛苦”指牙疼带来的难受，与“吃不下饭”的结果相符。", "高兴": "语义：“高兴”表示愉快，与“牙疼”的语境矛盾。", "欢喜": "语义：“欢喜”表示高兴，与“牙疼吃不下饭”的语境矛盾。", "兴奋": "语义：“兴奋”表示情绪高涨，与“牙疼吃不下饭”的情况不符。"}, "sentence_index": 0, "correct_answer": "痛苦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们在公园里玩得很痛苦。", "explanation": "这里应该用〈快乐〉。玩得开心要用“快乐”，“痛苦”指身体疼或心里难过。"}, {"text": "听到录取的消息，他觉得很痛苦。", "explanation": "这里应该用〈高兴〉。听到录取的好消息要用“高兴”，“痛苦”指身体疼或心里难过，不能形容这种喜悦。"}, {"text": "他洗了个热水澡，觉得很痛苦。", "explanation": "这里应该用〈舒服〉。洗完热水澡身体舒适，应该用“舒服”，“痛苦”表示疼或难受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86307, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "痛苦", "is_correct": true, "explanation": "“痛苦”表示心里难过，与“失去工作”的语境相符。"}, {"text": "舒服", "is_correct": false, "explanation": "语义：“舒服”表示舒适，与“失去工作”的打击不符。"}, {"text": "得意", "is_correct": false, "explanation": "语义：“得意”表示满意自豪，与失去工作的处境矛盾。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，不能用来形容心里的感受。"}], "explanations": {"痛苦": "“痛苦”表示心里难过，与“失去工作”的语境相符。", "舒服": "语义：“舒服”表示舒适，与“失去工作”的打击不符。", "得意": "语义：“得意”表示满意自豪，与失去工作的处境矛盾。", "漂亮": "体貌：“漂亮”形容外貌，不能用来形容心里的感受。"}, "sentence_index": 6, "correct_answer": "痛苦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他坐在沙发上，觉得很痛苦。", "explanation": "这里应该用〈舒适〉。坐着休息的舒适感要用“舒适”，“痛苦”指身体疼或心里难过。"}, {"text": "大家吃到美食后都很痛苦。", "explanation": "这里应该用〈满足〉。吃到美食后的心情要用“满足”，“痛苦”指身体疼或心里难过。"}, {"text": "他在树下乘凉，很痛苦。", "explanation": "这里应该用〈凉快〉。乘凉时的感觉要用“凉快”，“痛苦”不能形容这种舒适的感受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86307, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "牙疼的时候，他痛苦着得睡不着觉。", "corrected_sentence": "牙疼的时候，他痛苦得睡不着觉。", "error_description": "错误形式：痛苦着得睡不着觉；正确形式：痛苦得睡不着觉。“痛苦”后多了“着”，补语“睡不着觉”要直接用“得”连接在“痛苦”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86307, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种痛苦地经历让他难忘。", "corrected_sentence": "这种痛苦的经历让他难忘。", "error_description": "错误形式：痛苦地经历；正确形式：痛苦的经历。“痛苦”修饰名词“经历”时，要用“的”，不能用表示修饰动词的“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86308, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "舒适", "is_correct": true, "explanation": "“舒适”与“痛苦”相对，表示身体不难受，词典中列为反义词。"}, {"text": "慷慨", "is_correct": false, "explanation": "无关：“慷慨”形容待人大方，与身体难受的“痛苦”没有反义关系。"}, {"text": "严谨", "is_correct": false, "explanation": "无关：“严谨”形容做事认真细致，与“痛苦”不构成反义。"}, {"text": "陌生", "is_correct": false, "explanation": "无关：“陌生”指不熟悉，与身体或精神的难受没有反义关系。"}], "correct_answer": "舒适", "explanations": {"舒适": "“舒适”与“痛苦”相对，表示身体不难受，词典中列为反义词。", "慷慨": "无关：“慷慨”形容待人大方，与身体难受的“痛苦”没有反义关系。", "严谨": "无关：“严谨”形容做事认真细致，与“痛苦”不构成反义。", "陌生": "无关：“陌生”指不熟悉，与身体或精神的难受没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
