INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86308, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "身体或精神感到非常难受。", "primary_collocate": null, "pronunciation": "tòng kǔ", "ipa": "tʰʊŋ˥˩ kʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "发高烧的那几天，我真的很痛苦。", "target_word": "痛苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天加班到半夜，他过得很痛苦。", "target_word": "痛苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不能和家人见面，她精神上非常痛苦。", "target_word": "痛苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的腰疼了好几年，每天都很痛苦。", "target_word": "痛苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试没过，同学们都很痛苦。", "target_word": "痛苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次手术以后，病人一直很痛苦。", "target_word": "痛苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢这份工作，每天上班都很痛苦。", "target_word": "痛苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她痛苦地捂着头，说不出话来。", "target_word": "痛苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一直睡不着觉，真让人痛苦。", "target_word": "痛苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和不喜欢的人住在一起，我觉得非常痛苦。", "target_word": "痛苦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "身体或精神非常难受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717e23d-bca9-41d2-953d-d55f3fb7f070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86308, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "痛苦", "is_correct": true, "explanation": "“痛苦”表示身体或精神非常难受，与“发高烧”的语境相符。"}, {"text": "舒服", "is_correct": false, "explanation": "语义：“舒服”表示舒适，与“发高烧”的状况矛盾。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，不能用来形容身体或精神的感受。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”表示愉快，与发高烧时的感受不符。"}], "explanations": {"痛苦": "“痛苦”表示身体或精神非常难受，与“发高烧”的语境相符。", "舒服": "语义：“舒服”表示舒适，与“发高烧”的状况矛盾。", "漂亮": "体貌：“漂亮”形容外貌，不能用来形容身体或精神的感受。", "高兴": "语义：“高兴”表示愉快，与发高烧时的感受不符。"}, "sentence_index": 0, "correct_answer": "痛苦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "能受邀参加，他觉得很痛苦。", "explanation": "这里应该用〈荣幸〉。受邀参加要用“荣幸”，“痛苦”指非常难受，不能形容这种光荣的感受。"}, {"text": "他躺在草地上晒太阳，很痛苦。", "explanation": "这里应该用〈惬意〉。躺在草地上晒太阳的舒适心情要用“惬意”，“痛苦”指非常难受。"}, {"text": "听到好消息，他很痛苦。", "explanation": "这里应该用〈高兴〉。听到好消息要用“高兴”，“痛苦”不能形容这种心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86308, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "痛苦", "is_correct": true, "explanation": "“痛苦”表示非常难受，与“不喜欢这份工作，每天上班”的语境相符。"}, {"text": "愉快", "is_correct": false, "explanation": "语义：“愉快”表示开心，与“不喜欢这份工作”的语境矛盾。"}, {"text": "兴奋", "is_correct": false, "explanation": "语义：“兴奋”表示情绪高涨，与每天上班的厌烦感受矛盾。"}, {"text": "欢喜", "is_correct": false, "explanation": "语义：“欢喜”表示高兴，与“不喜欢这份工作”的语境矛盾。"}], "explanations": {"痛苦": "“痛苦”表示非常难受，与“不喜欢这份工作，每天上班”的语境相符。", "愉快": "语义：“愉快”表示开心，与“不喜欢这份工作”的语境矛盾。", "兴奋": "语义：“兴奋”表示情绪高涨，与每天上班的厌烦感受矛盾。", "欢喜": "语义：“欢喜”表示高兴，与“不喜欢这份工作”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "痛苦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他吃到一块甜蛋糕，很痛苦。", "explanation": "这里应该用〈满足〉。吃到甜点的心情要用“满足”，“痛苦”指身体或精神非常难受。"}, {"text": "比赛赢了，他很痛苦。", "explanation": "这里应该用〈得意〉。赢了比赛的心情要用“得意”，“痛苦”不能这样形容。"}, {"text": "老人们在公园里跳舞，很痛苦。", "explanation": "这里应该用〈欢乐〉。跳舞时的快乐心情要用“欢乐”，“痛苦”指非常难受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86308, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几天他很痛苦着。", "corrected_sentence": "这几天他很痛苦。", "error_description": "错误形式：很痛苦着；正确形式：很痛苦。“痛苦”是形容词，受“很”修饰表示状态时，后面不能加“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86308, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她痛苦了站不起来。", "corrected_sentence": "她痛苦得站不起来。", "error_description": "错误形式：痛苦了站不起来；正确形式：痛苦得站不起来。“痛苦”后不能加“了”，补语“站不起来”要用“得”连接在“痛苦”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
