INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86310, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "疑问代词，询问方式或状况。", "primary_collocate": null, "pronunciation": "zěn yàng", "ipa": "ʈʂən˨˩ jɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个手机怎样用？", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你家的小狗最近怎样？", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，去火车站怎样走？", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的身体现在怎样？", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道怎样跟朋友说这件事。", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说，这件事怎样解决才好？", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的菜怎样？", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎样读这个词。", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管你怎样说，我都相信他。", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在新学校过得怎样？", "target_word": "怎样", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "怎样：疑问代词，问方式或状况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad9311d-2259-4b31-9471-d7d48a98239a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86310, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "怎样", "is_correct": true, "explanation": "正确：“怎样”放在动词“用”前作状语，询问使用方法。"}, {"text": "为什么", "is_correct": false, "explanation": "语义：“为什么”问原因，“这个手机为什么用”不能用来问使用方法。"}, {"text": "多少", "is_correct": false, "explanation": "语义：“多少”问数量，不能放在动词前问使用方法，“这个手机多少用”不成句。"}, {"text": "什么", "is_correct": false, "explanation": "语法：“什么”指代事物，不能直接修饰动词“用”，“这个手机什么用”不成句。"}], "explanations": {"怎样": "正确：“怎样”放在动词“用”前作状语，询问使用方法。", "为什么": "语义：“为什么”问原因，“这个手机为什么用”不能用来问使用方法。", "多少": "语义：“多少”问数量，不能放在动词前问使用方法，“这个手机多少用”不成句。", "什么": "语法：“什么”指代事物，不能直接修饰动词“用”，“这个手机什么用”不成句。"}, "sentence_index": 0, "correct_answer": "怎样"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在这里住了怎样久？", "explanation": "这里应该用〈多久〉。问时间长短要用“多久”，“怎样”只问方式或状况，不能用来问居住的时长。"}, {"text": "这件衣服怎样贵？", "explanation": "这里应该用〈多〉。问价格的高低要用“多”或“多么”，“怎样”只问方式或状况，不能用来问贵的程度。"}, {"text": "他怎样一直不说话？", "explanation": "这里应该用〈为何〉。“为何”用于问原因，此处表达的是沉默的原因，“怎样”不能用于这种问法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86310, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怎样", "is_correct": true, "explanation": "正确：“怎样”问饭店菜的状况，可以作谓语。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”指人，不能用来问菜的状况。"}, {"text": "哪儿", "is_correct": false, "explanation": "语义：“哪儿”问地点，与问菜的状况不相符。"}, {"text": "为何", "is_correct": false, "explanation": "语义：“为何”问原因，不能用来问菜的状况。"}], "explanations": {"怎样": "正确：“怎样”问饭店菜的状况，可以作谓语。", "谁": "语义：“谁”指人，不能用来问菜的状况。", "哪儿": "语义：“哪儿”问地点，与问菜的状况不相符。", "为何": "语义：“为何”问原因，不能用来问菜的状况。"}, "sentence_index": 6, "correct_answer": "怎样"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这点小事就怎样算了吧。", "explanation": "这里应该用〈这样〉。“就这样算了”指照这个样子结束，要用指示词“这样”；“怎样”是疑问词，不能用来指代。"}, {"text": "你别再怎样了，我已经知道错了。", "explanation": "这里应该用〈那样〉。指代对方刚才的做法要用“那样”，“怎样”是疑问词，不能这样指代。"}, {"text": "他把钥匙丢在怎样了？", "explanation": "这里应该用〈哪儿〉。问地点要用“哪儿”，“怎样”只问方式或状况，不能用来问钥匙丢在哪里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请告诉我你怎样胖了。", "corrected_sentence": "请告诉我你为什么胖了。", "error_description": "用法错误：“怎样”只问方式或状况，不能用来问原因。问原因应说“为什么”，“你怎样胖了”不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次旅行的情况怎样的？", "corrected_sentence": "这次旅行的情况怎样了？", "error_description": "语法错误：句末单说「情况怎样的？」不成立，要说「情况是怎样的」或「情况怎样了」。这里问状况的变化，用「了」，正确说法是「情况怎样了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
