INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86312, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，确实，表示肯定。", "primary_collocate": null, "pronunciation": "dí què", "ipa": "ti˧˥ tɕʰɥe˥˩", "syllable_count": 2, "sentences": [{"text": "他的确很聪明。", "target_word": "的确", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭馆的菜的确很好吃。", "target_word": "的确", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天的确比昨天冷。", "target_word": "的确", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的汉语的确进步了不少。", "target_word": "的确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的确是我的错。", "target_word": "的确", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书的确很有意思。", "target_word": "的确", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你说得对，他的确来过。", "target_word": "的确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法的确很好。", "target_word": "的确", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的确不知道他在哪儿。", "target_word": "的确", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那家商店的东西的确很便宜。", "target_word": "的确", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "的的确确", "label": "重叠"}], "register": "通用", "sense_fingerprint": "副词，确实，表示肯定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfe20271-9b49-478a-a8e6-68fb9be44438') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86312, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "的确", "is_correct": true, "explanation": "正确：“的确”表示确实如此，修饰形容词“聪明”，与句意相符。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”表示事情忽然发生，与“聪明”这种稳定的特点不合。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”多与否定词连用，与肯定的“很聪明”搭配不当。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”指时间刚过去，不能修饰表示状态的“很聪明”。"}], "explanations": {"的确": "正确：“的确”表示确实如此，修饰形容词“聪明”，与句意相符。", "突然": "语义：“突然”表示事情忽然发生，与“聪明”这种稳定的特点不合。", "根本": "搭配：“根本”多与否定词连用，与肯定的“很聪明”搭配不当。", "刚刚": "语义：“刚刚”指时间刚过去，不能修饰表示状态的“很聪明”。"}, "sentence_index": 0, "correct_answer": "的确"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你的确是谁？", "explanation": "这里应该用〈到底〉。“的确”表示肯定某个事实，不用于询问“究竟是谁”的疑问句。"}, {"text": "他的确也许明天来。", "explanation": "这里应该用〈估计〉。“的确”表示肯定，与推测的语境矛盾，推测时应去掉“的确”。"}, {"text": "你的确去吧。", "explanation": "这里应该用〈一定〉。“的确”表示确认事实，不用于劝说或祈使；劝人去要用“一定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba4155ca-be3b-4518-8830-7044e11b5664') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86312, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "的确", "is_correct": true, "explanation": "正确：“的确”确认事实，与“你说得对”的语境相符，“来过”前可以用。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然，与“来过”所表示的既往经历不合。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示动作进行中，不能与表示经历的“来过”连用。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”指即刻发生的动作，与表示既往经历的“来过”不合。"}], "explanations": {"的确": "正确：“的确”确认事实，与“你说得对”的语境相符，“来过”前可以用。", "忽然": "语义：“忽然”表示突然，与“来过”所表示的既往经历不合。", "正在": "搭配：“正在”表示动作进行中，不能与表示经历的“来过”连用。", "马上": "语义：“马上”指即刻发生的动作，与表示既往经历的“来过”不合。"}, "sentence_index": 6, "correct_answer": "的确"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的确去了哪里？", "explanation": "这里应该用〈究竟〉。“的确”表示肯定事实，不用于询问“去了哪里”的疑问句。"}, {"text": "这件事的确也许是真的。", "explanation": "这里应该用〈估计〉。“的确”表示肯定，与推测的语境矛盾，推测时应去掉“的确”。"}, {"text": "他看起来很糟，的确情况比想象中好。", "explanation": "这里应该用〈其实〉。“的确”表示肯定事实，不用于表示与外表相反的转折，转折要用“其实”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba4155ca-be3b-4518-8830-7044e11b5664') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86312, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的确地没有来。", "corrected_sentence": "他的确没有来。", "error_description": "多加“地”：“的确”是副词，后面不能再加“地”，“他的确地没有来”不通，应为“他的确没有来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba4155ca-be3b-4518-8830-7044e11b5664') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86312, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的确的忘了这件事。", "corrected_sentence": "我的确忘了这件事。", "error_description": "多加“的”：“的确”是副词，后面不能再加“的”，“的确的忘了”不成立，应为“的确忘了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba4155ca-be3b-4518-8830-7044e11b5664') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
