INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86313, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "“据”是说话时告诉别人，这个消息是从哪里听到的。", "primary_collocate": null, "pronunciation": "jù", "ipa": "tɕy˥˩", "syllable_count": 1, "sentences": [{"text": "据新闻说，明天会下大雨。", "target_word": "据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据天气预报，明天会很冷。", "target_word": "据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据他说，这家店很好吃。", "target_word": "据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据老师说，下周要考试。", "target_word": "据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据妈妈说，我小时候很爱哭。", "target_word": "据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据朋友说，那个地方很漂亮。", "target_word": "据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据网上说，这本书很有名。", "target_word": "据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据我哥哥说，他明年去北京。", "target_word": "据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据电视上说，今天有雪。", "target_word": "据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据同学说，这家书店在学校旁边。", "target_word": "据", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "据说", "label": "复合"}], "register": "书面语", "sense_fingerprint": "据:引出消息来源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fd271da-7053-4e94-b9bc-a929e14d7b33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86313, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "据", "is_correct": true, "explanation": "据（jù）：介词，引出消息的来源。"}, {"text": "举", "is_correct": false, "explanation": "jǔ（第三声）与 jù（第四声）声调不同，意思是举起。"}, {"text": "居", "is_correct": false, "explanation": "jū（第一声）与 jù（第四声）声调不同，意思是居住。"}, {"text": "去", "is_correct": false, "explanation": "qù 与 jù 声母不同（q 与 j），意思是去。"}, {"text": "记", "is_correct": false, "explanation": "jì 与 jù 韵母不同（i 与 ü），意思是记住。"}, {"text": "续", "is_correct": false, "explanation": "xù 与 jù 声母不同（x 与 j），意思是继续。"}], "explanations": {"据": "据（jù）：介词，引出消息的来源。", "举": "jǔ（第三声）与 jù（第四声）声调不同，意思是举起。", "居": "jū（第一声）与 jù（第四声）声调不同，意思是居住。", "去": "qù 与 jù 声母不同（q 与 j），意思是去。", "记": "jì 与 jù 韵母不同（i 与 ü），意思是记住。", "续": "xù 与 jù 声母不同（x 与 j），意思是继续。"}, "sentence_index": null, "correct_answer": "据"}, "level_3": {"options": [{"text": "据", "is_correct": true, "explanation": "据：介词，引出消息来源，此处表示“根据新闻说”。"}, {"text": "对", "is_correct": false, "explanation": "语义：“对”引出对象，“对新闻说”表示对新闻说话，不表示消息来源。"}, {"text": "向", "is_correct": false, "explanation": "语义：“向”引出对象，“向新闻说”的对象不成立，不能表示消息来源。"}, {"text": "给", "is_correct": false, "explanation": "配价：“给”需要接受者，“给新闻说”的接受者不成立。"}], "explanations": {"据": "据：介词，引出消息来源，此处表示“根据新闻说”。", "对": "语义：“对”引出对象，“对新闻说”表示对新闻说话，不表示消息来源。", "向": "语义：“向”引出对象，“向新闻说”的对象不成立，不能表示消息来源。", "给": "配价：“给”需要接受者，“给新闻说”的接受者不成立。"}, "sentence_index": 0, "correct_answer": "据"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "据我昨天去了一趟超市，买了很多水果。", "explanation": "这里不该用〈据〉。据引出的是从别人或资料得来的消息，说自己的经历不用据。"}, {"text": "他据老师那里借了一本书。", "explanation": "这里应该用〈从〉。据表示消息来源，不能引出借东西的来处；从某人那里借要用从。"}, {"text": "据大家的努力，比赛赢了。", "explanation": "这里应该用〈由于〉。据不表示原因，说明原因要用由于。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86313, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "据", "is_correct": true, "explanation": "据（jù）：介词，引出消息的来源。"}, {"text": "局", "is_correct": false, "explanation": "jú（第二声）与 jù（第四声）声调不同，意思是局面、局部。"}, {"text": "寄", "is_correct": false, "explanation": "jì 与 jù 韵母不同（i 与 ü），意思是寄信。"}, {"text": "季", "is_correct": false, "explanation": "jì 与 jù 韵母不同（i 与 ü），意思是季节。"}, {"text": "趣", "is_correct": false, "explanation": "qù 与 jù 声母不同（q 与 j），意思是兴趣、趣味。"}], "explanations": {"据": "据（jù）：介词，引出消息的来源。", "局": "jú（第二声）与 jù（第四声）声调不同，意思是局面、局部。", "寄": "jì 与 jù 韵母不同（i 与 ü），意思是寄信。", "季": "jì 与 jù 韵母不同（i 与 ü），意思是季节。", "趣": "qù 与 jù 声母不同（q 与 j），意思是兴趣、趣味。"}, "sentence_index": null, "correct_answer": "据"}, "level_3": {"options": [{"text": "据", "is_correct": true, "explanation": "据：介词，引出消息来源，此处表示“根据网上说”。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替或为某人，“替网上说”不能表示消息来源。"}, {"text": "把", "is_correct": false, "explanation": "配价：“把”字句需要“把＋宾语＋动词”，“把网上说”结构不成立。"}, {"text": "被", "is_correct": false, "explanation": "配价：“被”需要施事者与动作，“被网上说”的语义不成立。"}], "explanations": {"据": "据：介词，引出消息来源，此处表示“根据网上说”。", "替": "语义：“替”表示代替或为某人，“替网上说”不能表示消息来源。", "把": "配价：“把”字句需要“把＋宾语＋动词”，“把网上说”结构不成立。", "被": "配价：“被”需要施事者与动作，“被网上说”的语义不成立。"}, "sentence_index": 6, "correct_answer": "据"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他据图书馆看书，一看就是一天。", "explanation": "这里应该用〈在〉。据不表示处所，在某地做事要用在。"}, {"text": "我据老师请假，明天不去学校。", "explanation": "这里应该用〈向〉。据不表示对象，向某人请假要用向。"}, {"text": "老师据学生很严格。", "explanation": "这里应该用〈对〉。据不表示对象或态度，对某人严格要用对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_v