INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86314, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "据", "is_correct": true, "explanation": "据（jù）：介词，表示按照、依据，引出消息来源。"}, {"text": "居", "is_correct": false, "explanation": "jū（第一声）与 jù（第四声）声调不同，意思是居住。"}, {"text": "记", "is_correct": false, "explanation": "jì 与 jù 韵母不同（i 与 ü），意思是记住。"}, {"text": "去", "is_correct": false, "explanation": "qù 与 jù 声母不同（q 与 j），意思是去。"}, {"text": "续", "is_correct": false, "explanation": "xù 与 jù 声母不同（x 与 j），意思是继续。"}], "explanations": {"据": "据（jù）：介词，表示按照、依据，引出消息来源。", "居": "jū（第一声）与 jù（第四声）声调不同，意思是居住。", "记": "jì 与 jù 韵母不同（i 与 ü），意思是记住。", "去": "qù 与 jù 声母不同（q 与 j），意思是去。", "续": "xù 与 jù 声母不同（x 与 j），意思是继续。"}, "sentence_index": null, "correct_answer": "据"}, "level_3": {"options": [{"text": "据", "is_correct": true, "explanation": "据：介词，表示依据，引出消息来源，此处指根据电视新闻。"}, {"text": "对", "is_correct": false, "explanation": "语义：“对”引出对象，“对电视新闻”不能表示消息来源。"}, {"text": "给", "is_correct": false, "explanation": "配价：“给”需要接受者与动作，“给电视新闻”不成立。"}, {"text": "被", "is_correct": false, "explanation": "配价：“被”需要施事者与动作，“被电视新闻”不成立。"}], "explanations": {"据": "据：介词，表示依据，引出消息来源，此处指根据电视新闻。", "对": "语义：“对”引出对象，“对电视新闻”不能表示消息来源。", "给": "配价：“给”需要接受者与动作，“给电视新闻”不成立。", "被": "配价：“被”需要施事者与动作，“被电视新闻”不成立。"}, "sentence_index": 6, "correct_answer": "据"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他据北京来，今天刚到。", "explanation": "这里应该用〈从〉。据不表示起点，从某地来要用从。"}, {"text": "据我昨天买了一台新电脑。", "explanation": "这里不该用〈据〉。据只引出从别人或资料得来的消息，自己买东西的事不用据。"}, {"text": "妈妈据孩子很耐心。", "explanation": "这里应该用〈对〉。据不表示对象，对孩子耐心要用对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86314, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "据医生，他的病好了。", "corrected_sentence": "据医生说，他的病好了。", "error_description": "“据”后面是人（如医生）时，要加“说”才能表示消息来源。只说“据医生”不完整，应说“据医生说，他的病好了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86314, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "据据公安局通报，那条路暂时封闭。", "corrected_sentence": "据公安局通报，那条路暂时封闭。", "error_description": "“据”是介词，前面不能叠用“据”。应删去多余的“据”，说“据公安局通报”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
