INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86316, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "成年的男性。", "primary_collocate": null, "pronunciation": "nán rén", "ipa": "nan˧˥ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "那个男人在门口等他的朋友。", "target_word": "男人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里有一个男人在跑步。", "target_word": "男人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家商店卖男人穿的衣服。", "target_word": "男人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个男人把车停在了路边。", "target_word": "男人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室里只有三个男人。", "target_word": "男人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个男人手里拿着一把伞。", "target_word": "男人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天在地铁上见过那个男人。", "target_word": "男人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一个很爱家的男人，每天都早早回家吃饭。", "target_word": "男人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公交车上，一个男人主动给老人让座。", "target_word": "男人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个男人每天开车送孩子上学。", "target_word": "男人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个男人", "label": "量词"}, {"form": "男人们", "label": "复合"}], "register": "中性", "sense_fingerprint": "成年男性，泛指成年男子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d31e622-4b28-4b23-8714-313fa02ff361') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86316, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "男人", "is_correct": true, "explanation": "“男人”指成年男子，能够在门口等人，与句意相符。"}, {"text": "商店", "is_correct": false, "explanation": "语义：“商店”是场所，不能“等人”。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”是物体，句中“等朋友”需要有生命的主语。"}, {"text": "电脑", "is_correct": false, "explanation": "配价：“等”要求有生命的施事，“电脑”不能充当这个成分。"}], "explanations": {"男人": "“男人”指成年男子，能够在门口等人，与句意相符。", "商店": "语义：“商店”是场所，不能“等人”。", "椅子": "语义：“椅子”是物体，句中“等朋友”需要有生命的主语。", "电脑": "配价：“等”要求有生命的施事，“电脑”不能充当这个成分。"}, "sentence_index": 0, "correct_answer": "男人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我弟弟还在上小学，已经是个男人了。", "explanation": "这里应该用〈男孩〉。上小学的男童是男孩，“男人”指成年男子，不能这样说。"}, {"text": "一个男人把车停在了路边，他是个小孩。", "explanation": "这里的“男人”指成年男子，句中的人是小孩，应用〈男孩〉。"}, {"text": "这只小狗是男人。", "explanation": "这里应该用〈雄性〉。“男人”专指成年男子，不能指动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86316, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "男人", "is_correct": true, "explanation": "“男人”指男性，能被看见，与“在地铁上见过那个……”的语境相符。"}, {"text": "公园", "is_correct": false, "explanation": "语义：地铁车厢里不会见到“公园”这样的地方，句意不通。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”是自然景物，不会在地铁上被“见过”。"}, {"text": "超市", "is_correct": false, "explanation": "搭配：“见过”后接的是可见之物，“超市”是地方，在地铁上说不通。"}], "explanations": {"男人": "“男人”指男性，能被看见，与“在地铁上见过那个……”的语境相符。", "公园": "语义：地铁车厢里不会见到“公园”这样的地方，句意不通。", "河流": "语义：“河流”是自然景物，不会在地铁上被“见过”。", "超市": "搭配：“见过”后接的是可见之物，“超市”是地方，在地铁上说不通。"}, "sentence_index": 6, "correct_answer": "男人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的弟弟是个男人，每天去学校上课。", "explanation": "这里应该用〈男孩〉。弟弟还在上学，是小孩，不能说男人。"}, {"text": "我妹妹今年五岁，是个可爱的男人。", "explanation": "这里应该用〈女孩〉。妹妹是女性、是小孩，“男人”指成年男子。"}, {"text": "这只小猫是男人。", "explanation": "这里应该用〈雄性〉。“男人”专指成年男子，不能指动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86316, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只男人是我的老师。", "corrected_sentence": "那个男人是我的老师。", "error_description": "“只”用于动物或成对的东西，不能用于人。“那只男人”错误，应说：那个男人是我的老师。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86316, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一个非常勇敢地男人。", "corrected_sentence": "他是一个非常勇敢的男人。", "error_description": "错误：“勇敢”修饰名词时要用“的”，不能用“地”（“地”用于动词、形容词前）。“勇敢地男人”错误，应说：他是一个非常勇敢的男人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
