INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86317, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "“别”是叫别人不要做某件事。", "primary_collocate": null, "pronunciation": "bié", "ipa": "pje˧˥", "syllable_count": 1, "sentences": [{"text": "别吃太多糖，对牙不好。", "target_word": "别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别开玩笑了，这件事很重要。", "target_word": "别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说：“别玩手机了，快去睡觉。”", "target_word": "别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路滑，你别骑太快。", "target_word": "别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别笑我，我刚开始学中文。", "target_word": "别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别站在门口，进来坐吧。", "target_word": "别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里不能拍照，请别用手机。", "target_word": "别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别担心，我会帮你。", "target_word": "别", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你别告诉他这件事，好吗？", "target_word": "别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别等我了，我今天要加班。", "target_word": "别", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "別", "label": "繁体"}], "register": "口语", "sense_fingerprint": "别：叫别人不要做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2434161a-3956-4714-972b-e41f185ec812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86317, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "别", "is_correct": true, "explanation": "别（bié）是副词，叫别人不要做某事。"}, {"text": "憋", "is_correct": false, "explanation": "bié（第二声）与 biē（第一声）声调不同，意思是“憋”（如憋气），不是“别”。"}, {"text": "瘪", "is_correct": false, "explanation": "biě（第三声）与 bié（第二声）声调不同，意思是“瘪”（凹陷），不是“别”。"}, {"text": "叠", "is_correct": false, "explanation": "dié 与 bié 声母不同（d 与 b），意思是“叠”（一层层地放），不是“别”。"}, {"text": "碟", "is_correct": false, "explanation": "dié（第二声）与 bié 声母不同（d 与 b），意思是“碟子”，不是“别”。"}], "explanations": {"别": "别（bié）是副词，叫别人不要做某事。", "憋": "bié（第二声）与 biē（第一声）声调不同，意思是“憋”（如憋气），不是“别”。", "瘪": "biě（第三声）与 bié（第二声）声调不同，意思是“瘪”（凹陷），不是“别”。", "叠": "dié 与 bié 声母不同（d 与 b），意思是“叠”（一层层地放），不是“别”。", "碟": "dié（第二声）与 bié 声母不同（d 与 b），意思是“碟子”，不是“别”。"}, "sentence_index": null, "correct_answer": "别"}, "level_3": {"options": [{"text": "别", "is_correct": true, "explanation": "“别吃太多糖”表示劝阻，与“对牙不好”的语境相符。"}, {"text": "赶快", "is_correct": false, "explanation": "语义：“赶快”表示催促快做，与“对牙不好”的劝阻语境相反。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行中，不能表示劝阻。"}, {"text": "终于", "is_correct": false, "explanation": "语义：“终于”表示经过等待后实现，不能表示劝阻，与“对牙不好”的语境不符。"}], "explanations": {"别": "“别吃太多糖”表示劝阻，与“对牙不好”的语境相符。", "赶快": "语义：“赶快”表示催促快做，与“对牙不好”的劝阻语境相反。", "正在": "体貌：“正在”表示动作进行中，不能表示劝阻。", "终于": "语义：“终于”表示经过等待后实现，不能表示劝阻，与“对牙不好”的语境不符。"}, "sentence_index": 0, "correct_answer": "别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天生病了，别去上班。", "explanation": "这里应该用〈没〉。“没去上班”叙述过去没做某事，“别”只用于劝阻，不能这样用。"}, {"text": "我别喜欢这个城市，所以常来。", "explanation": "这里应该用〈很〉。“很喜欢”表示程度，“别”只用于劝阻，不能这样用。"}, {"text": "他别会唱歌，声音很好听。", "explanation": "这里应该用〈很〉。“很会唱歌”表示擅长，“别”只用于劝阻，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86317, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "别", "is_correct": true, "explanation": "别（bié）是副词，叫别人不要做某事。"}, {"text": "瘪", "is_correct": false, "explanation": "biě（第三声）与 bié（第二声）声调不同，意思是“瘪”（凹陷），不是“别”。"}, {"text": "鳖", "is_correct": false, "explanation": "biē（第一声）与 bié 声调不同，意思是“鳖”（甲鱼），不是“别”。"}, {"text": "憋", "is_correct": false, "explanation": "biē（第一声）与 bié（第二声）声调不同，意思是“憋”（如憋气），不是“别”。"}, {"text": "蝶", "is_correct": false, "explanation": "dié 与 bié 声母不同（d 与 b），意思是“蝴蝶”，不是“别”。"}], "explanations": {"别": "别（bié）是副词，叫别人不要做某事。", "瘪": "biě（第三声）与 bié（第二声）声调不同，意思是“瘪”（凹陷），不是“别”。", "鳖": "biē（第一声）与 bié 声调不同，意思是“鳖”（甲鱼），不是“别”。", "憋": "biē（第一声）与 bié（第二声）声调不同，意思是“憋”（如憋气），不是“别”。", "蝶": "dié 与 bié 声母不同（d 与 b），意思是“蝴蝶”，不是“别”。"}, "sentence_index": null, "correct_answer": "别"}, "level_3": {"options": [{"text": "别", "is_correct": true, "explanation": "“请别用手机”表示禁止，与“这里不能拍照”的语境相符。"}, {"text": "还", "is_correct": false, "explanation": "语义：“还”表示持续，与“不能拍照”的禁止语境不符。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示故意或反而，与“不能拍照”的禁止语境不符。"}, {"text": "也", "is_correct": false, "explanation": "搭配：“请也用手机”不是常用说法，且与“不能拍照”的语境矛盾。"}], "explanations": {"别": "“请别用手机”表示禁止，与“这里不能拍照”的语境相符。", "还": "语义：“还”表示持续，与“不能拍照”的禁止语境不符。", "偏偏": "语义：“偏偏”表示故意或反而，与“不能拍照”的禁止语境不符。", "也": "搭配：“请也用手机”不是常用说法，且与“不能拍照”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他别守时，所以老是迟到。", "explanation": "这里应该用〈不〉。“不”表示否定，“别”只用于劝阻，不能这样用。"}, {"text": "这家公司的待遇别好，很受欢迎。", "explanation": "这里应该用〈很〉。“很好”表示程度，“别”不能修饰形容词。"}, {"text": "他明天别会来，我们不用准备他的饭。", "explanation": "这里应该用〈不会〉。“不会”表示推测将来不发生，“别”只用于禁止或劝阻，不能表示推测。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86317, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "不别喝太多冷饮，对胃不好。", "corrected_sentence": "别喝太多冷饮，对胃不好。", "error_description": "“别”本身已含否定意思，前面不能再加“不”，应说“别喝太多冷饮”，不能说“不别喝”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86317, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "别等了我，你先吃饭吧。", "corrected_sentence": "别等我了，你先吃饭吧。", "error_description": "句末的“了”应紧跟在“我”之后，应说“别等我了”，不能说“别等了我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
