INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86318, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示禁止或劝阻，相当于“不要”。", "primary_collocate": null, "pronunciation": "bié", "ipa": "pje˧˥", "syllable_count": 1, "sentences": [{"text": "别说话，孩子睡着了。", "target_word": "别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别忘了带伞，外面在下雨。", "target_word": "别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气很冷，别穿这么少。", "target_word": "别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别跑，路上有很多车。", "target_word": "别", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "太晚了，别再看手机了。", "target_word": "别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别生气，我不是故意的。", "target_word": "别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别哭，我们一起想办法。", "target_word": "别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图书馆里请别大声说话。", "target_word": "别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别把杯子放在桌边，会掉下去的。", "target_word": "别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别着急，时间还很多。", "target_word": "别", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "別", "label": "繁体"}], "register": "口语", "sense_fingerprint": "别：禁止或劝阻，相当于不要", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: 3 words above tier T1 (max 2): 杯子 (Zipf 3.82), 桌 (Zipf 3.79), 掉下去 (Zipf 3.25)']::text[], '2434161a-3956-4714-972b-e41f185ec812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86318, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "别", "is_correct": true, "explanation": "别（bié）是副词，表示禁止或劝阻，相当于“不要”。"}, {"text": "憋", "is_correct": false, "explanation": "bié（第二声）与 biē（第一声）声调不同，意思是“憋”（如憋气），不是“别”。"}, {"text": "瘪", "is_correct": false, "explanation": "biě（第三声）与 bié（第二声）声调不同，意思是“瘪”（凹陷），不是“别”。"}, {"text": "碟", "is_correct": false, "explanation": "dié 与 bié 声母不同（d 与 b），意思是“碟子”，不是“别”。"}, {"text": "叠", "is_correct": false, "explanation": "dié 与 bié 声母不同（d 与 b），意思是“叠”（一层层地放），不是“别”。"}], "explanations": {"别": "别（bié）是副词，表示禁止或劝阻，相当于“不要”。", "憋": "bié（第二声）与 biē（第一声）声调不同，意思是“憋”（如憋气），不是“别”。", "瘪": "biě（第三声）与 bié（第二声）声调不同，意思是“瘪”（凹陷），不是“别”。", "碟": "dié 与 bié 声母不同（d 与 b），意思是“碟子”，不是“别”。", "叠": "dié 与 bié 声母不同（d 与 b），意思是“叠”（一层层地放），不是“别”。"}, "sentence_index": null, "correct_answer": "别"}, "level_3": {"options": [{"text": "别", "is_correct": true, "explanation": "“别说话”表示禁止，与“孩子睡着了”的安静语境相符。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示催促尽快行动，与孩子睡着、需要安静的语境相反。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作已经完成，不能表示禁止或劝阻。"}, {"text": "又", "is_correct": false, "explanation": "语义：“又”表示动作重复，不能表示禁止或劝阻。"}], "explanations": {"别": "“别说话”表示禁止，与“孩子睡着了”的安静语境相符。", "赶紧": "语义：“赶紧”表示催促尽快行动，与孩子睡着、需要安静的语境相反。", "已经": "体貌：“已经”表示动作已经完成，不能表示禁止或劝阻。", "又": "语义：“又”表示动作重复，不能表示禁止或劝阻。"}, "sentence_index": 0, "correct_answer": "别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我别这个蛋糕，太甜了。", "explanation": "这里应该用〈不要〉。表示不想要某样东西时用“不要”，“别”只用于禁止或劝阻，不能这样表达。"}, {"text": "他别忙，所以没有来。", "explanation": "这里应该用〈很〉。“很忙”表示程度，“别”只用于劝阻，不能修饰形容词。"}, {"text": "这件事我别清楚，所以不能帮你。", "explanation": "这里应该用〈不〉。“不清楚”表示否定，“别”只用于禁止或劝阻，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86318, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "别", "is_correct": true, "explanation": "别（bié）是副词，表示禁止或劝阻，相当于“不要”。"}, {"text": "鳖", "is_correct": false, "explanation": "biē（第一声）与 bié（第二声）声调不同，意思是“鳖”（甲鱼）。"}, {"text": "瘪", "is_correct": false, "explanation": "biě（第三声）与 bié（第二声）声调不同，意思是“瘪”（凹陷），不是“别”。"}, {"text": "蝶", "is_correct": false, "explanation": "dié 与 bié 声母不同（d 与 b），意思是“蝴蝶”，不是“别”。"}, {"text": "碟", "is_correct": false, "explanation": "dié（第二声）与 bié 声母不同（d 与 b），意思是“碟子”，不是“别”。"}], "explanations": {"别": "别（bié）是副词，表示禁止或劝阻，相当于“不要”。", "鳖": "biē（第一声）与 bié（第二声）声调不同，意思是“鳖”（甲鱼）。", "瘪": "biě（第三声）与 bié（第二声）声调不同，意思是“瘪”（凹陷），不是“别”。", "蝶": "dié 与 bié 声母不同（d 与 b），意思是“蝴蝶”，不是“别”。", "碟": "dié（第二声）与 bié 声母不同（d 与 b），意思是“碟子”，不是“别”。"}, "sentence_index": null, "correct_answer": "别"}, "level_3": {"options": [{"text": "别", "is_correct": true, "explanation": "“别哭”表示劝阻，与“我们一起想办法”的安慰语境相符。"}, {"text": "终于", "is_correct": false, "explanation": "语义：“终于”表示经过等待后实现，不能表示劝阻，与安慰语境不合。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行中，不能表示劝阻。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示故意、反而，与“我们一起想办法”的安慰语境不合。"}], "explanations": {"别": "“别哭”表示劝阻，与“我们一起想办法”的安慰语境相符。", "终于": "语义：“终于”表示经过等待后实现，不能表示劝阻，与安慰语境不合。", "正在": "体貌：“正在”表示动作进行中，不能表示劝阻。", "偏偏": "语义：“偏偏”表示故意、反而，与“我们一起想办法”的安慰语境不合。"}, "sentence_index": 6, "correct_answer": "别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他别来过中国，所以不太了解那里。", "explanation": "这里应该用〈没〉。“没来过”表示过去没有某种经历，“别”只用于劝阻，不能这样用。"}, {"text": "我别会游泳，所以不去海边。", "explanation": "这里应该用〈不会〉。“不会”表示不具备某种能力，“别”只能用于禁止或劝阻。"}, {"text": "这家店的衣服别便宜，很多人都买。", "explanation": "这里应该用〈很〉。“很便宜”表示程度，“别”不能修饰形容词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86318, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "别你说话，奶奶在休息。", "corrected_sentence": "你别说话，奶奶在休息。", "error_description": "“别”应放在主语“你”之后，应说“你别说话”，不能说“别你说话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86318, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "不别担心，他很快就回来。", "corrected_sentence": "别担心，他很快就回来。", "error_description": "“别”本身已含否定意思，前面不能再加“不”，应说“别担心”，不能说“不别担心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
