INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86319, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "立场是你站在哪一边看事情。", "primary_collocate": null, "pronunciation": "lì chǎng", "ipa": "li˥˩ ʈʂʰaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们要站在孩子的立场想问题。", "target_word": "立场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的立场和我不一样。", "target_word": "立场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人的立场不同，看法也不同。", "target_word": "立场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你站在我的立场想一想。", "target_word": "立场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师站在学生的立场说了几句话。", "target_word": "立场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这件事上，我们的立场是一样的。", "target_word": "立场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是站在朋友的立场说话。", "target_word": "立场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的立场是什么？你同意还是不同意？", "target_word": "立场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从公司的立场看，这个办法不错。", "target_word": "立场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换了立场，不再支持这个计划。", "target_word": "立场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "立場", "label": "繁体"}], "register": "中性", "sense_fingerprint": "立场：站在哪一边看事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd9494de-5348-4735-8c04-847b659ff0a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86319, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "立场", "is_correct": true, "explanation": "正确：“站在孩子的立场”指从孩子的角度看问题，“立场”正好作“站在……”的宾语。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”是人的岁数，不能作为“站在”的立足点，与“想问题”无关。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是具体物品，不能表示看问题的角度，“站在孩子的书包想问题”说不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”描述外形，不能表示看问题的立足点。"}], "explanations": {"立场": "正确：“站在孩子的立场”指从孩子的角度看问题，“立场”正好作“站在……”的宾语。", "年龄": "语义：“年龄”是人的岁数，不能作为“站在”的立足点，与“想问题”无关。", "书包": "语义：“书包”是具体物品，不能表示看问题的角度，“站在孩子的书包想问题”说不通。", "身材": "体貌：“身材”描述外形，不能表示看问题的立足点。"}, "sentence_index": 0, "correct_answer": "立场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子应该放在窗户旁边的立场。", "explanation": "这里应该用〈位置〉。“立场”指对问题的立足点和态度，桌子所在的地方要用“位置”。"}, {"text": "他在公司的立场很高，大家都很尊敬他。", "explanation": "这里应该用〈地位〉。“立场”指对问题的立足点，人在组织里的高低要用“地位”。"}, {"text": "他的立场是老师，我们都很尊敬他。", "explanation": "这里应该用〈身份〉。“立场”指看问题的角度，说一个人的职业或社会角色要用“身份”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86319, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "立场", "is_correct": true, "explanation": "正确：“站在朋友的立场说话”指从朋友的角度说话，“立场”作“站在……”的宾语最自然。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”是性情特点，不能作为“站在……”的立足点，句子说不通。"}, {"text": "口音", "is_correct": false, "explanation": "语义：“口音”是说话的腔调，不能表示说话时的角度，“站在朋友的口音说话”意思不通。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“站在……”后接的是角度或立场，“脾气”不能作为说话的立足点，搭配不当。"}], "explanations": {"立场": "正确：“站在朋友的立场说话”指从朋友的角度说话，“立场”作“站在……”的宾语最自然。", "性格": "语义：“性格”是性情特点，不能作为“站在……”的立足点，句子说不通。", "口音": "语义：“口音”是说话的腔调，不能表示说话时的角度，“站在朋友的口音说话”意思不通。", "脾气": "搭配：“站在……”后接的是角度或立场，“脾气”不能作为说话的立足点，搭配不当。"}, "sentence_index": 6, "correct_answer": "立场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对工作的立场很认真，从不偷懒。", "explanation": "这里应该用〈态度〉。“立场”指对问题的立足点，对工作认真与否要用“态度”。"}, {"text": "这件衣服的立场很便宜，他一下子就买了。", "explanation": "这里应该用〈价格〉。“立场”指站在哪一边看事情，衣服的价钱要用“价格”。"}, {"text": "他在剧里的立场是医生，演得很像。", "explanation": "这里应该用〈角色〉。“立场”指看问题的角度，演员扮演的人物要用“角色”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86319, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事让他改变了一只立场。", "corrected_sentence": "这件事让他改变了立场。", "error_description": "“一只立场”错误：“只”用于动物或成对的小东西，不能修饰抽象的“立场”。应直接说“改变了立场”，或说“一种立场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86319, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她总是站在老师立场替我说话。", "corrected_sentence": "她总是站在老师的立场替我说话。", "error_description": "漏了“的”：“老师”与“立场”之间是所属关系，应加“的”，说“老师的立场”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
