INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86320, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "认识和处理问题时所处的位置和态度。", "primary_collocate": null, "pronunciation": "lì chǎng", "ipa": "li˥˩ ʈʂʰaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "在这个问题上，他的立场很清楚。", "target_word": "立场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家对这件事的立场没有变。", "target_word": "立场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她坚持自己的立场，不听别人的。", "target_word": "立场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人立场不同，说了很久也没有结果。", "target_word": "立场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸要说清楚自己的立场。", "target_word": "立场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在会上说明了公司的立场。", "target_word": "立场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了朋友，他改变了原来的立场。", "target_word": "立场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在两个学生之间保持中立的立场。", "target_word": "立场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想知道市长对这件事的立场。", "target_word": "立场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他表明立场以后，大家就不再问了。", "target_word": "立场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "立場", "label": "繁体"}], "register": "书面", "sense_fingerprint": "立场：认识和处理问题时所处的位置和态度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd9494de-5348-4735-8c04-847b659ff0a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86320, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "立场", "is_correct": true, "explanation": "正确：“在这个问题上”说的是对问题的态度和位置，“他的立场很清楚”最自然。"}, {"text": "字迹", "is_correct": false, "explanation": "语义：“字迹”指书写留下的痕迹，与“在这个问题上”的态度无关。"}, {"text": "发音", "is_correct": false, "explanation": "语义：“发音”指读音清不清楚，不能用来说明对问题的看法。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是外形特征，不能用来描述对问题的态度。"}], "explanations": {"立场": "正确：“在这个问题上”说的是对问题的态度和位置，“他的立场很清楚”最自然。", "字迹": "语义：“字迹”指书写留下的痕迹，与“在这个问题上”的态度无关。", "发音": "语义：“发音”指读音清不清楚，不能用来说明对问题的看法。", "身高": "体貌：“身高”是外形特征，不能用来描述对问题的态度。"}, "sentence_index": 0, "correct_answer": "立场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次考试的立场很好，老师都很高兴。", "explanation": "这里应该用〈成绩〉。“立场”指认识问题时的位置和态度，考试的结果要用“成绩”。"}, {"text": "公司的立场很充足，足够发工资。", "explanation": "这里应该用〈资金〉。“立场”指认识问题时的位置和态度，钱款的多少要用“资金”。"}, {"text": "他的立场是老师，所以很关心学生。", "explanation": "这里应该用〈身份〉。“立场”指看问题的角度，说一个人的职业或社会角色要用“身份”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86320, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "立场", "is_correct": true, "explanation": "正确：“为了朋友，他改变了原来的立场”说的是他对事情的态度转变，“立场”最合适。"}, {"text": "年纪", "is_correct": false, "explanation": "语义：“年纪”是岁数，不能被“改变了原来的”修饰来表示为朋友做的转变，句子说不通。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”是日期，不能因为朋友而“改变”，与句子的意思矛盾。"}, {"text": "笑声", "is_correct": false, "explanation": "语义：“笑声”是笑的声音，不是对事情的态度，不能“为了朋友”而改变。"}], "explanations": {"立场": "正确：“为了朋友，他改变了原来的立场”说的是他对事情的态度转变，“立场”最合适。", "年纪": "语义：“年纪”是岁数，不能被“改变了原来的”修饰来表示为朋友做的转变，句子说不通。", "生日": "语义：“生日”是日期，不能因为朋友而“改变”，与句子的意思矛盾。", "笑声": "语义：“笑声”是笑的声音，不是对事情的态度，不能“为了朋友”而改变。"}, "sentence_index": 6, "correct_answer": "立场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电视应该放在客厅中间的立场。", "explanation": "这里应该用〈位置〉。“立场”指对问题的立足点，电视所在的地方要用“位置”。"}, {"text": "这个房子的立场很贵，他没有买。", "explanation": "这里应该用〈价格〉。“立场”指认识问题时的位置和态度，房子的价钱要用“价格”。"}, {"text": "这次比赛，他的立场是裁判。", "explanation": "这里应该用〈角色〉。“立场”指看问题的角度，说一个人在比赛中担任的职务要用“角色”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86320, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在会上明确表明了一只立场。", "corrected_sentence": "他在会上明确表明了一种立场。", "error_description": "“一只立场”错误：“只”不能用来数抽象的“立场”，应说“一种立场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86320, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的立场很高，大家都支持他。", "corrected_sentence": "他的立场很坚定，大家都支持他。", "error_description": "“立场很高”搭配错误：“立场”不说“高”，常说“立场坚定”或“立场鲜明”，应说“他的立场很坚定”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86322, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86322, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86322, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示充分条件，常与“就”配合使用。", "primary_collocate": null, "pronunciation": "zhǐ yào", "ipa": "ʈʂɨ²¹⁴ jɑʊ̯⁵¹", "syllable_count": 2, "sentences": [{"text": "只要你来，我就高兴。", "target_word": "只要", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "只要天气好，我们就去玩。", "target_word": "只要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只要努力学习，你就会进步。", "target_word": "只要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只要看过一遍，她就能记住。", "target_word": "只要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要不下雨，比赛就照常进行。", "target_word": "只要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只要每天听一小时，你的汉语就会好起来。", "target_word": "只要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只要明天不下雨，我们就去公园。", "target_word": "只要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只要坐地铁，二十分钟就能到公司。", "target_word": "只要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只要你说一声，我马上就来。", "target_word": "只要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只要他想学，老师就愿意教他。", "target_word": "只要", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "连词，引出充分条件，后面常用“就”接结果，如只要……就……", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a6dfb6-2ee6-453e-a7c2-961fd8e3fc9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86322, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "只要", "is_correct": true, "explanation": "正确答案。“只要你来，我就高兴”表示充分条件，符合句意。"}, {"text": "不但", "is_correct": false, "explanation": "搭配：“不但”要与“而且”或“也”配合，与后句的“就”不能搭配。"}, {"text": "无论", "is_correct": false, "explanation": "搭配：“无论”后要与“都”配合，此处用“就”不通。"}, {"text": "虽然", "is_correct": false, "explanation": "语义：“虽然”表示让步，与“我就高兴”的条件结果不符。"}], "explanations": {"只要": "正确答案。“只要你来，我就高兴”表示充分条件，符合句意。", "不但": "搭配：“不但”要与“而且”或“也”配合，与后句的“就”不能搭配。", "无论": "搭配：“无论”后要与“都”配合，此处用“就”不通。", "虽然": "语义：“虽然”表示让步，与“我就高兴”的条件结果不符。"}, "sentence_index": 0, "correct_answer": "只要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "只要努力学习，但是你并没有进步。", "explanation": "这里应该用〈虽然〉，表示让步，与“但是”配合。〈只要〉引出充分条件，与表示转折的“但是”搭配不当。"}, {"text": "只要你肯努力，这次却没考好。", "explanation": "这里应该用〈虽然〉，表示让步，与“却”配合。〈只要〉引出充分条件，与“却”表示的转折不相容。"}, {"text": "只要他很努力，所以成绩好。", "explanation": "这里应该用〈因为〉，表示原因。〈只要〉引出充分条件，后面应接“就”，不能接“所以”表示因果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86322, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "只要", "is_correct": true, "explanation": "正确答案。“只要明天不下雨，我们就去公园”表示充分条件，符合句意。"}, {"text": "只好", "is_correct": false, "explanation": "搭配：“只好”是副词，不能用来引出条件分句。"}, {"text": "不管", "is_correct": false, "explanation": "搭配：“不管”要与“都”配合，与后句的“就”不能搭配。"}, {"text": "尽管", "is_correct": false, "explanation": "语义：“尽管”表示让步，与“我们就去公园”的条件结果不符。"}], "explanations": {"只要": "正确答案。“只要明天不下雨，我们就去公园”表示充分条件，符合句意。", "只好": "搭配：“只好”是副词，不能用来引出条件分句。", "不管": "搭配：“不管”要与“都”配合，与后句的“就”不能搭配。", "尽管": "语义：“尽管”表示让步，与“我们就去公园”的条件结果不符。"}, "sentence_index": 6, "correct_answer": "只要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "只要天气怎样，我们都去公园。", "explanation": "这里应该用〈不管〉，表示无论哪种情况，后接“都”。〈只要〉引出充分条件，不能表示无条件的意思。"}, {"text": "只要下雨，我们还是去了。", "explanation": "这里应该用〈虽然〉，表示让步。〈只要〉引出充分条件，不能用来表示转折的“还是”。"}, {"text": "只要他生病了，所以今天没来上课。", "explanation": "这里应该用〈因为〉，与“所以”配合表示原因。〈只要〉引出充分条件，后面应接“就”，不能接“所以”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86322, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "只要你肯努力，却能学好汉语。", "corrected_sentence": "只要你肯努力，就能学好汉语。", "error_description": "“只要”引出充分条件，后分句应接“就”。此处把“就”换成“却”，“却”表示转折，与“只要”引出的充分条件不相容。正确说法是“只要你肯努力，就能学好汉语”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86322, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "只要多练习，你的口语却会好起来。", "corrected_sentence": "只要多练习，你的口语就会好起来。", "error_description": "“只要”引出充分条件，后分句应接“就”。此处把“就”换成“却”，“却”表示转折，与“只要”不相容。正确说法是“只要多练习，你的口语就会好起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86323, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86323, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86323, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "网页是上网时，屏幕上看到的一页。", "primary_collocate": null, "pronunciation": "wǎng yè", "ipa": "waŋ˨˩˦ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "屏幕上的网页突然变白了。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网页太长，我往下看了很久。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上网时，我常常同时开着几个网页。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他关掉了所有的网页。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网页的颜色很舒服。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网页上出现了一个红色的字。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把网页往上拉一点儿。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈看着网页，不知道怎么点。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刷新一下网页，就能看到新的内容。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的电脑里有太多没关的网页。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "张", "label": "量词"}, {"form": "网页设计", "label": "复合"}], "register": "通用", "sense_fingerprint": "网页：上网时屏幕上看到的一页", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7cea0ef-f5d6-475e-98b1-4539dcad4711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86323, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "网页", "is_correct": true, "explanation": "网页指上网时屏幕上看到的一页，屏幕上出现的正是它，符合语境。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是一种疾病，不是能显示在屏幕上、会变白的东西，与语境不符。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是人内在的感受，不是屏幕上可见的东西，与“突然变白了”不相符。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：友谊是人与人之间的情感，不是能显示在屏幕上的东西，与语境不符。"}], "explanations": {"网页": "网页指上网时屏幕上看到的一页，屏幕上出现的正是它，符合语境。", "感冒": "语义：感冒是一种疾病，不是能显示在屏幕上、会变白的东西，与语境不符。", "心情": "语义：心情是人内在的感受，不是屏幕上可见的东西，与“突然变白了”不相符。", "友谊": "语义：友谊是人与人之间的情感，不是能显示在屏幕上的东西，与语境不符。"}, "sentence_index": 0, "correct_answer": "网页"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个网页是用木头刻出来的。", "explanation": "这里的“网页”被当成了实物。网页是屏幕上显示的页面，没有实体，不能用木头刻，这个意思不对。"}, {"text": "我家的网页很快，看视频不卡。", "explanation": "这里应该用〈网络〉。网页指单个页面，说连接的速度快要用“网络”。"}, {"text": "渔夫把网页撒进了河里。", "explanation": "这里应该用〈渔网〉。这里的“网”是渔网，网页是屏幕上的页面，不能撒进河里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86323, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "网页", "is_correct": true, "explanation": "网页可以在窗口中上下滚动，“往上拉”指拖动页面，符合语境。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是一种疾病，不是可以拖动调整位置的东西，“把感冒往上拉”不通。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：白菜是蔬菜，不是可以拖动调整的页面，“把白菜往上拉”与语境不符。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭是一顿饭，不是可以拖动调整位置的东西，与语境不符。"}], "explanations": {"网页": "网页可以在窗口中上下滚动，“往上拉”指拖动页面，符合语境。", "感冒": "语义：感冒是一种疾病，不是可以拖动调整位置的东西，“把感冒往上拉”不通。", "白菜": "语义：白菜是蔬菜，不是可以拖动调整的页面，“把白菜往上拉”与语境不符。", "早饭": "语义：早饭是一顿饭，不是可以拖动调整位置的东西，与语境不符。"}, "sentence_index": 6, "correct_answer": "网页"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天收到很多网页。", "explanation": "这里应该用〈邮件〉。收到的是邮件，网页是在浏览器里打开浏览的，不说“收到网页”。"}, {"text": "我的网页碎了，换了一块新的。", "explanation": "这里应该用〈屏幕〉。屏幕是会碎的硬件，网页只是屏幕上显示的内容，不会碎。"}, {"text": "这本书有三百个网页。", "explanation": "这里应该用〈页〉。书的页是纸上的页，网页只指屏幕上的页面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86323, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我打开了一只网页。", "corrected_sentence": "我打开了一个网页。", "error_description": "量词错误：“网页”应配“个”（或“张”），“只”用于动物。正确说法是“一个网页”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86323, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把网页们关掉了。", "corrected_sentence": "妈妈把网页关掉了。", "error_description": "错误：“网页”指屏幕上的页面，不是人或动物，不能加“们”表示复数；去掉“们”即为“妈妈把网页关掉了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
