INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86324, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86324, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "互联网上的页面，可显示文字、图片等。", "primary_collocate": null, "pronunciation": "wǎng yè", "ipa": "waŋ˨˩˦ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "我打开了一个新网页。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网页上有很多漂亮的图片。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在学做网页。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这个网页发给我。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网页的字太小，我看不清楚。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网页打不开，可能是网速太慢。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用手机看了一个新闻网页。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网页是用中文写的。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们找一个介绍中国的网页。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把有用的网页都存起来了。", "target_word": "网页", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "张", "label": "量词"}, {"form": "网页设计", "label": "复合"}], "register": "通用", "sense_fingerprint": "网页：互联网上可显示文字、图片的页面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7cea0ef-f5d6-475e-98b1-4539dcad4711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86324, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "网页", "is_correct": true, "explanation": "正确：网页是互联网上可以打开的页面，与“打开”搭配。"}, {"text": "网速", "is_correct": false, "explanation": "语义：网速指网络传输的速度，不是可以打开的东西。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是一种疾病，不是可以打开的东西，与语境不符。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭是一顿饭，不是可以打开的东西，与语境不符。"}], "explanations": {"网页": "正确：网页是互联网上可以打开的页面，与“打开”搭配。", "网速": "语义：网速指网络传输的速度，不是可以打开的东西。", "感冒": "语义：感冒是一种疾病，不是可以打开的东西，与语境不符。", "早饭": "语义：早饭是一顿饭，不是可以打开的东西，与语境不符。"}, "sentence_index": 0, "correct_answer": "网页"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我打开了一本网页。", "explanation": "这里应该用〈个〉。“本”是书籍的量词，网页应用“个”或“张”计量。"}, {"text": "我买了一台新网页。", "explanation": "这里应该用〈电脑〉。“台”用于机器，网页不是机器，不能用“台”计量。"}, {"text": "我们家的网页很快。", "explanation": "这里应该用〈网络〉。“很快”形容网络的速度，网页是页面，不能用来形容速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86324, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "网页", "is_correct": true, "explanation": "正确：网页是在手机上可以看到的页面，符合“看了一个新闻”的语境。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视是一台设备，不能说用手机看了一个电视。"}, {"text": "水龙头", "is_correct": false, "explanation": "语义：水龙头是用来出水的设备，与“看新闻”的语境完全不符。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：看不与“音乐”搭配，听音乐才这样说。"}], "explanations": {"网页": "正确：网页是在手机上可以看到的页面，符合“看了一个新闻”的语境。", "电视": "语义：电视是一台设备，不能说用手机看了一个电视。", "水龙头": "语义：水龙头是用来出水的设备，与“看新闻”的语境完全不符。", "音乐": "搭配：看不与“音乐”搭配，听音乐才这样说。"}, "sentence_index": 6, "correct_answer": "网页"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的网页没电了，要充电。", "explanation": "这里应该用〈手机〉。没电要充电的是手机等设备，网页是页面，不能说没电。"}, {"text": "我把网页的电源关掉了。", "explanation": "这里应该用〈电脑〉。电源是电脑等设备才有的，网页是页面，不能说关掉它的电源。"}, {"text": "我在厨房里煮了一锅网页。", "explanation": "这里应该用〈饭〉。“煮”的对象是食物，网页是屏幕上的页面，不能下锅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86324, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我刚打开了一只新网页，里面有很多图片。", "corrected_sentence": "我刚打开了一个新网页，里面有很多图片。", "error_description": "错误：网页的量词应为“个”或“张”，“一只”是动物的量词，用在网页上错了。正确说法是“一个新网页”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86324, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她用手机看了一个天气网页们。", "corrected_sentence": "她用手机看了一个天气网页。", "error_description": "错误：“网页”指屏幕上的页面，不是人或动物，不能加“们”表示复数；去掉“们”即为“她用手机看了一个天气网页。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
