INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86325, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86325, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“如此”是说像这样，就是这个样子。", "primary_collocate": null, "pronunciation": "rú cǐ", "ipa": "ʐu˧˥ tsʰɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "事情就是如此。", "target_word": "如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生活就是如此。", "target_word": "如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原来如此，我明白了。", "target_word": "如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直如此，从来不迟到。", "target_word": "如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不只是他，别人也是如此。", "target_word": "如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上写的就是如此。", "target_word": "如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说得对，事实如此。", "target_word": "如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你既然如此说，我就相信你。", "target_word": "如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天如此，从不休息。", "target_word": "如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小如此，大家都习惯了。", "target_word": "如此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "如此:像这样、就是这个样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fd271da-7053-4e94-b9bc-a929e14d7b33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86325, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哪个", "is_correct": false, "explanation": "语义：「哪个」是疑问代词，要问具体的人或事物，放在陈述句末「事情就是哪个。」不成话，也不能表示事情的状态。"}, {"text": "如此", "is_correct": true, "explanation": "如此：指示状态，意思是就是这个样子，接在「就是」后面，说明事情本来就是这样。"}, {"text": "某些", "is_correct": false, "explanation": "语义：「某些」指部分事物，不能概括事情的整体状态。"}, {"text": "其他", "is_correct": false, "explanation": "搭配：「就是」后面要接状态或方式，「其他」指别的事物，不能接在这里。"}], "explanations": {"哪个": "语义：「哪个」是疑问代词，要问具体的人或事物，放在陈述句末「事情就是哪个。」不成话，也不能表示事情的状态。", "如此": "如此：指示状态，意思是就是这个样子，接在「就是」后面，说明事情本来就是这样。", "某些": "语义：「某些」指部分事物，不能概括事情的整体状态。", "其他": "搭配：「就是」后面要接状态或方式，「其他」指别的事物，不能接在这里。"}, "sentence_index": 0, "correct_answer": "如此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脾气如此他父亲，很急。", "explanation": "这里不该用〈如此〉。〈如此〉是代词，指示状态，不能直接带名词宾语；表示“像”要用〈如〉或〈像〉。"}, {"text": "我只带了如此两块钱。", "explanation": "这里不该用〈如此〉。〈如此〉只指状态或程度，不能与数词连用表示数量，直接说“两块钱”即可。"}, {"text": "如此你不来，我就生气。", "explanation": "这里不该用〈如此〉。〈如此〉表示状态，不表示假设；假设要用〈如果〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86325, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "什么", "is_correct": false, "explanation": "语义：「什么」是疑问代词，「事实什么」不能表示事实的状态。"}, {"text": "如此", "is_correct": true, "explanation": "如此：指示状态，意思是事实就是这样，正好承接前面「老师说得对」的判断。"}, {"text": "哪些", "is_correct": false, "explanation": "语义：「哪些」问的是具体的几个，不能用来概括事实的状态。"}, {"text": "别的", "is_correct": false, "explanation": "搭配：「事实」后面要接状态的描述，「别的」指另外的事物，与「事实」不搭配。"}], "explanations": {"什么": "语义：「什么」是疑问代词，「事实什么」不能表示事实的状态。", "如此": "如此：指示状态，意思是事实就是这样，正好承接前面「老师说得对」的判断。", "哪些": "语义：「哪些」问的是具体的几个，不能用来概括事实的状态。", "别的": "搭配：「事实」后面要接状态的描述，「别的」指另外的事物，与「事实」不搭配。"}, "sentence_index": 6, "correct_answer": "如此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的书如此在桌子上。", "explanation": "这里不该用〈如此〉。〈如此〉指状态或方式，不表示处所，应说“他的书在桌子上”。"}, {"text": "如此你们不同意，我们就算了。", "explanation": "这里不该用〈如此〉。〈如此〉表示状态，不表示假设；假设要用〈如果〉。"}, {"text": "他的个子如此我一样高。", "explanation": "这里不该用〈如此〉。〈如此〉表示状态或程度，不用于比较；比较要用〈像〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86325, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个办法向来的如此，大家早就习惯了。", "corrected_sentence": "这个办法向来如此，大家早就习惯了。", "error_description": "错误：“如此”前面多加了“的”。“如此”是代词，前面不能加“的”，应去掉“的”，说“这个办法向来如此，大家早就习惯了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86325, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我觉得这件事就是很如此。", "corrected_sentence": "我觉得这件事就是如此。", "error_description": "错误：“如此”前面加了“很”。“如此”是代词，本身指示状态，不能再受程度副词修饰，应去掉“很”，说“我觉得这件事就是如此。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
