INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86326, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "代词，指示状态、方式或程度，相当于“这样”。", "primary_collocate": null, "pronunciation": "rú cǐ", "ipa": "ʐu˧˥ tsʰɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "天气如此冷，我不想出门。", "target_word": "如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为什么如此生气？", "target_word": "如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "如此好的机会，不要错过。", "target_word": "如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她如此爱笑，大家都喜欢她。", "target_word": "如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里如此安静，我很喜欢。", "target_word": "如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说得如此清楚，我听懂了。", "target_word": "如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事如此简单，你自己做吧。", "target_word": "如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试的题目如此难，连老师也没有把握。", "target_word": "如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师如此年轻，学生都很吃惊。", "target_word": "如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他如此努力，一定会成功。", "target_word": "如此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "如此:指示状态、方式、程度,相当于这样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fd271da-7053-4e94-b9bc-a929e14d7b33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86326, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "某些", "is_correct": false, "explanation": "语义：「某些」指部分事物，不能用来表示天气冷的程度。"}, {"text": "如此", "is_correct": true, "explanation": "如此：表示程度，修饰形容词「冷」，说明天气冷到这种地步。"}, {"text": "其他", "is_correct": false, "explanation": "语义：「其他」指别的事物，与天气的冷热程度无关。"}, {"text": "怎样", "is_correct": false, "explanation": "搭配：「怎样」用来问方式，不能直接修饰形容词「冷」表示程度。"}], "explanations": {"某些": "语义：「某些」指部分事物，不能用来表示天气冷的程度。", "如此": "如此：表示程度，修饰形容词「冷」，说明天气冷到这种地步。", "其他": "语义：「其他」指别的事物，与天气的冷热程度无关。", "怎样": "搭配：「怎样」用来问方式，不能直接修饰形容词「冷」表示程度。"}, "sentence_index": 0, "correct_answer": "如此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "如此你不来，我就生气。", "explanation": "这里不该用〈如此〉。〈如此〉表示状态或程度，不表示假设；假设要用〈如果〉。"}, {"text": "她很如此爱笑，大家都喜欢她。", "explanation": "这里不该用〈如此〉。〈如此〉本身表示程度，不能与〈很〉并用，“很如此”是重复。"}, {"text": "班里如此十个学生。", "explanation": "这里不该用〈如此〉。〈如此〉只指状态或程度，不能与数词连用表示人数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86326, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "什么", "is_correct": false, "explanation": "语义：「什么」问具体事物，「这件事什么简单」不能表示程度。"}, {"text": "如此", "is_correct": true, "explanation": "如此：表示程度，修饰形容词「简单」，说明这件事简单到这种地步。"}, {"text": "哪些", "is_correct": false, "explanation": "语义：「哪些」问的是几个不同的事物，不能修饰形容词「简单」。"}, {"text": "别的", "is_correct": false, "explanation": "搭配：「别的」修饰名词，不能直接修饰形容词「简单」表示程度。"}], "explanations": {"什么": "语义：「什么」问具体事物，「这件事什么简单」不能表示程度。", "如此": "如此：表示程度，修饰形容词「简单」，说明这件事简单到这种地步。", "哪些": "语义：「哪些」问的是几个不同的事物，不能修饰形容词「简单」。", "别的": "搭配：「别的」修饰名词，不能直接修饰形容词「简单」表示程度。"}, "sentence_index": 6, "correct_answer": "如此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的书如此在桌子上。", "explanation": "这里不该用〈如此〉。〈如此〉指状态或方式，不表示处所，应说“他的书在桌子上”。"}, {"text": "如此你们不去，我们就算了。", "explanation": "这里不该用〈如此〉。〈如此〉表示状态，不表示假设；假设要用〈如果〉。"}, {"text": "他的个子如此我一样高。", "explanation": "这里不该用〈如此〉。〈如此〉表示状态或程度，不用于比较；比较要用〈像〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86326, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天天气如此很好，我们去公园吧。", "corrected_sentence": "今天天气如此好，我们去公园吧。", "error_description": "错误：“如此”和“很”同时用了。“如此”已经表示程度，不能再与“很”并用，应去掉“很”，说“今天天气如此好，我们去公园吧。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86326, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这道题的如此难，我们一起想想吧。", "corrected_sentence": "这道题如此难，我们一起想想吧。", "error_description": "错误：“的”放在了“如此”前面。“如此”前面不能加“的”，应去掉“的”，说“这道题如此难，我们一起想想吧。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
