INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86327, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "脚是人和动物身体最下面，用来走路的部分。", "primary_collocate": null, "pronunciation": "jiǎo", "ipa": "tɕjɑʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "我的脚很疼，不想走路。", "target_word": "脚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把脚放进热水里。", "target_word": "脚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗的脚上有泥。", "target_word": "脚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子光着脚在地上跑。", "target_word": "脚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋太小，我的脚放不进去。", "target_word": "脚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的左脚昨天受伤了。", "target_word": "脚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天冷了，我的脚总是很冷。", "target_word": "脚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把脚抬起来，我要扫地。", "target_word": "脚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大象的脚又大又重。", "target_word": "脚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走了一天路，我的脚都肿了。", "target_word": "脚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "双", "label": "量词"}, {"form": "腳", "label": "繁体"}, {"form": "脚步", "label": "复合"}, {"form": "脚印", "label": "复合"}], "register": "中性", "sense_fingerprint": "人和动物身体最下面、用来走路的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd86389b0-f4c1-4e9d-ad63-6659a36e1d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86327, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "脚", "is_correct": true, "explanation": "脚（第三声）：人或动物身体最下面、用来走路的部分。"}, {"text": "交", "is_correct": false, "explanation": "jiāo（第一声）与 jiǎo（第三声）声调不同，意思是交给、交流。"}, {"text": "巧", "is_correct": false, "explanation": "qiǎo 与 jiǎo 声母不同（q 与 j），意思是灵巧、巧妙。"}, {"text": "剪", "is_correct": false, "explanation": "jiǎn 与 jiǎo 韵母不同（-ǎn 与 -ǎo），意思是剪断、剪刀。"}, {"text": "小", "is_correct": false, "explanation": "xiǎo 与 jiǎo 声母不同（x 与 j），意思是小、少。"}], "explanations": {"脚": "脚（第三声）：人或动物身体最下面、用来走路的部分。", "交": "jiāo（第一声）与 jiǎo（第三声）声调不同，意思是交给、交流。", "巧": "qiǎo 与 jiǎo 声母不同（q 与 j），意思是灵巧、巧妙。", "剪": "jiǎn 与 jiǎo 韵母不同（-ǎn 与 -ǎo），意思是剪断、剪刀。", "小": "xiǎo 与 jiǎo 声母不同（x 与 j），意思是小、少。"}, "sentence_index": null, "correct_answer": "脚"}, "level_3": {"options": [{"text": "脚", "is_correct": true, "explanation": "脚：身体下部用来走路的部分，“很疼”“不想走路”都与脚相关，填入句中正确。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不会疼，“我的书包很疼”没有意义。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指体形，不能说身材疼，与“不想走路”也无关。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会感到疼，“我的桌子很疼”不合常理。"}], "explanations": {"脚": "脚：身体下部用来走路的部分，“很疼”“不想走路”都与脚相关，填入句中正确。", "书包": "语义：书包不会疼，“我的书包很疼”没有意义。", "身材": "体貌：“身材”指体形，不能说身材疼，与“不想走路”也无关。", "桌子": "语义：桌子不会感到疼，“我的桌子很疼”不合常理。"}, "sentence_index": 0, "correct_answer": "脚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的一支脚受伤了，走路很慢。", "explanation": "这里应该用〈只〉。脚是成对的身体部位，一只脚用量词“只”，“支”用于笔、歌等。"}, {"text": "她用脚端着一碗汤，走得很稳。", "explanation": "这里应该用〈手〉。端东西要用手，脚是用来走路的部位，不能用来端东西。"}, {"text": "他用脚吃着苹果，说说笑笑。", "explanation": "这里应该用〈嘴〉。吃东西要用嘴，脚不能用来吃东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86327, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "脚", "is_correct": true, "explanation": "脚（第三声）：人或动物身体最下面、用来走路的部分。"}, {"text": "教", "is_correct": false, "explanation": "jiào（第四声）与 jiǎo（第三声）声调不同，意思是教导。"}, {"text": "叫", "is_correct": false, "explanation": "jiào（第四声）与 jiǎo（第三声）声调不同，意思是叫喊、称为。"}, {"text": "讲", "is_correct": false, "explanation": "jiǎng 与 jiǎo 韵母不同（-ǎng 与 -ǎo），意思是讲话、讲解。"}, {"text": "奖", "is_correct": false, "explanation": "jiǎng 与 jiǎo 韵母不同（-ǎng 与 -ǎo），意思是奖励、奖品。"}], "explanations": {"脚": "脚（第三声）：人或动物身体最下面、用来走路的部分。", "教": "jiào（第四声）与 jiǎo（第三声）声调不同，意思是教导。", "叫": "jiào（第四声）与 jiǎo（第三声）声调不同，意思是叫喊、称为。", "讲": "jiǎng 与 jiǎo 韵母不同（-ǎng 与 -ǎo），意思是讲话、讲解。", "奖": "jiǎng 与 jiǎo 韵母不同（-ǎng 与 -ǎo），意思是奖励、奖品。"}, "sentence_index": null, "correct_answer": "脚"}, "level_3": {"options": [{"text": "脚", "is_correct": true, "explanation": "脚：身体下部，“总是很冷”描述的是身体部位，填入句中正确。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指身体的高矮，不会感到冷，“我的身高总是很冷”不合常理。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不会感到冷，“我的时间总是很冷”没有意义。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：成绩不会感到冷，“我的成绩总是很冷”不合常理。"}], "explanations": {"脚": "脚：身体下部，“总是很冷”描述的是身体部位，填入句中正确。", "身高": "体貌：“身高”指身体的高矮，不会感到冷，“我的身高总是很冷”不合常理。", "时间": "语义：时间不会感到冷，“我的时间总是很冷”没有意义。", "成绩": "语义：成绩不会感到冷，“我的成绩总是很冷”不合常理。"}, "sentence_index": 6, "correct_answer": "脚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的一把脚肿了，不能穿鞋。", "explanation": "这里应该用〈只〉。“把”用于有柄的器物，脚不能用“把”计数。"}, {"text": "她用脚看清了远处的山。", "explanation": "这里应该用〈眼睛〉。看东西要用眼睛，脚不能用来看东西。"}, {"text": "他跟我见面时握了握脚。", "explanation": "这里应该用〈手〉。握手要用手，脚不能用来握手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used 