INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86328, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人或动物腿的最下端，接触地面的部分。", "primary_collocate": null, "pronunciation": "jiǎo", "ipa": "tɕjɑʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "他跳下床，脚一落地就觉得很凉。", "target_word": "脚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把脚放在地上，别晃来晃去。", "target_word": "脚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她脚上穿着一双红鞋。", "target_word": "脚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸡的脚踩在泥地上。", "target_word": "脚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在沙滩上脱了鞋，用脚踩沙子。", "target_word": "脚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩的脚还很小。", "target_word": "脚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生检查了我的右脚。", "target_word": "脚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "脚踩在地上，感觉很凉。", "target_word": "脚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫的脚很软，走路没有声音。", "target_word": "脚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打球时他的脚扭了一下。", "target_word": "脚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "双", "label": "量词"}, {"form": "腳", "label": "繁体"}, {"form": "脚步", "label": "复合"}, {"form": "脚印", "label": "复合"}], "register": "中性", "sense_fingerprint": "腿的最下端、接触地面的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd86389b0-f4c1-4e9d-ad63-6659a36e1d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86328, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "脚", "is_correct": true, "explanation": "脚（第三声）：腿的最下端，接触地面的部分。"}, {"text": "交", "is_correct": false, "explanation": "jiāo（第一声）与 jiǎo（第三声）声调不同，意思是交给、交流。"}, {"text": "巧", "is_correct": false, "explanation": "qiǎo 与 jiǎo 声母不同（q 与 j），意思是灵巧、巧妙。"}, {"text": "剪", "is_correct": false, "explanation": "jiǎn 与 jiǎo 韵母不同（-ǎn 与 -ǎo），意思是剪断、剪刀。"}], "explanations": {"脚": "脚（第三声）：腿的最下端，接触地面的部分。", "交": "jiāo（第一声）与 jiǎo（第三声）声调不同，意思是交给、交流。", "巧": "qiǎo 与 jiǎo 声母不同（q 与 j），意思是灵巧、巧妙。", "剪": "jiǎn 与 jiǎo 韵母不同（-ǎn 与 -ǎo），意思是剪断、剪刀。"}, "sentence_index": null, "correct_answer": "脚"}, "level_3": {"options": [{"text": "脚", "is_correct": true, "explanation": "脚：腿的最下端，“一落地”指脚接触地面，与“落地”搭配，填入句中正确。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不会“落地”后感到凉，“书一落地就觉得很凉”不合语境。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李不会自己感觉凉，句子的主语应是人的身体部位。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指体形，不能说身材一落地，与“觉得很凉”也不合。"}], "explanations": {"脚": "脚：腿的最下端，“一落地”指脚接触地面，与“落地”搭配，填入句中正确。", "书": "语义：书不会“落地”后感到凉，“书一落地就觉得很凉”不合语境。", "行李": "语义：行李不会自己感觉凉，句子的主语应是人的身体部位。", "身材": "体貌：“身材”指体形，不能说身材一落地，与“觉得很凉”也不合。"}, "sentence_index": 0, "correct_answer": "脚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老朋友见面，先握了握脚。", "explanation": "这里应该用〈手〉。握手要用手，脚不能用来握手。"}, {"text": "她用脚吹凉了汤，慢慢喝了下去。", "explanation": "这里应该用〈嘴〉。吹凉东西要用嘴，脚不能用来吹东西。"}, {"text": "他的一支脚踩进了水坑。", "explanation": "这里应该用〈只〉。脚用量词“只”，“支”用于笔、歌等，不能用于脚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86328, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "脚", "is_correct": true, "explanation": "脚（第三声）：腿的最下端，接触地面的部分。"}, {"text": "教", "is_correct": false, "explanation": "jiào（第四声）与 jiǎo（第三声）声调不同，意思是教导。"}, {"text": "叫", "is_correct": false, "explanation": "jiào（第四声）与 jiǎo（第三声）声调不同，意思是叫喊、称为。"}, {"text": "讲", "is_correct": false, "explanation": "jiǎng 与 jiǎo 韵母不同（-ǎng 与 -ǎo），意思是讲话、讲解。"}], "explanations": {"脚": "脚（第三声）：腿的最下端，接触地面的部分。", "教": "jiào（第四声）与 jiǎo（第三声）声调不同，意思是教导。", "叫": "jiào（第四声）与 jiǎo（第三声）声调不同，意思是叫喊、称为。", "讲": "jiǎng 与 jiǎo 韵母不同（-ǎng 与 -ǎo），意思是讲话、讲解。"}, "sentence_index": null, "correct_answer": "脚"}, "level_3": {"options": [{"text": "脚", "is_correct": true, "explanation": "脚：人身体的下肢末端，“我的右脚”指右边的脚，与“检查”搭配，填入句中正确。"}, {"text": "笔", "is_correct": false, "explanation": "语义：笔不是身体部位，“右笔”没有意义，医生不会检查笔。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不能被医生检查，“我的右时间”不合常理。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是身体部位，不能说“我的右颜色”，医生也不会检查它。"}], "explanations": {"脚": "脚：人身体的下肢末端，“我的右脚”指右边的脚，与“检查”搭配，填入句中正确。", "笔": "语义：笔不是身体部位，“右笔”没有意义，医生不会检查笔。", "时间": "语义：时间不能被医生检查，“我的右时间”不合常理。", "颜色": "语义：颜色不是身体部位，不能说“我的右颜色”，医生也不会检查它。"}, "sentence_index": 6, "correct_answer": "脚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用脚闻了闻花香，很开心。", "explanation": "这里应该用〈鼻子〉。闻东西要用鼻子，脚不能用来闻。"}, {"text": "他扭伤了一根脚。", "explanation": "这里应该用〈只〉。“根”用于细长的东西，脚不能用“根”计数。"}, {"text": "她用脚听了听门后的动静。", "explanation": "这里应该用〈耳朵〉。听声音要用耳朵，脚不能用来听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86328, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请脚把抬高一点，好好休息。", "corrected_sentence": "请把脚抬高一点，好好休息。", "error_description": "语序错误：“把”字句应为“把+受事+动词”，应说“请把脚抬高”，不能说“请脚把抬高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86328, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的两条脚都湿透了。", "corrected_sentence": "他的两只脚都湿透了。", "error_description": "量词错误：“脚”成对，应用量词“只”；“条”用于腿、蛇等细长的东西，不能说“两条脚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86329, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "局部", "is_correct": true, "explanation": "正确：“整个”指全部，“局部”指一部分，两者是反义关系。"}, {"text": "特别", "is_correct": false, "explanation": "“特别”表示不一般，与“整个”指全部的范围无反义关系。"}, {"text": "微小", "is_correct": false, "explanation": "“微小”形容很小，不是“整个”在范围上的反义词。"}, {"text": "普通", "is_correct": false, "explanation": "“普通”表示平常，与“整个”的范围含义无关。"}], "correct_answer": "局部", "explanations": {"局部": "正确：“整个”指全部，“局部”指一部分，两者是反义关系。", "特别": "“特别”表示不一般，与“整个”指全部的范围无反义关系。", "微小": "“微小”形容很小，不是“整个”在范围上的反义词。", "普通": "“普通”表示平常，与“整个”的范围含义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98b5a4cf-7669-4ed4-b455-fc83b20db20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86329, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "局部", "is_correct": true, "explanation": "正确：“整个”指全部，“局部”指一部分，两者是反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白、不模糊，与“整个”的范围含义无反义关系。"}, {"text": "精细", "is_correct": false, "explanation": "“精细”形容细致，与“整个”的范围含义无反义关系。"}, {"text": "迅速", "is_correct": false, "explanation": "“迅速”形容速度快，与“整个”的范围含义无关。"}], "correct_answer": "局部", "explanations": {"局部": "正确：“整个”指全部，“局部”指一部分，两者是反义关系。", "清楚": "“清楚”形容明白、不模糊，与“整个”的范围含义无反义关系。", "精细": "“精细”形容细致，与“整个”的范围含义无反义关系。", "迅速": "“迅速”形容速度快，与“整个”的范围含义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98b5a4cf-7669-4ed4-b455-fc83b20db20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86329, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "“整个”是说全部，一点不少。", "primary_collocate": null, "pronunciation": "zhěng gè", "ipa": "ʈʂɤŋ˨˩˦ kɤ˥˩", "syllable_count": 2, "sentences": [{"text": "整个下午我都在图书馆看书。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "整个城市都下着大雨。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他病了，整个星期没去上班。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "整个晚上孩子都在哭。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师走进来，整个教室都安静了。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "整个夏天我们都住在海边。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "整个班的同学都参加了比赛。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事，整个公司的人都知道。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "整个房间里都是花的香味。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "整个冬天，这里一直没有下雪。", "target_word": "整个", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "整个：用于时间、范围，指全部，一点不少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0962041-b86f-4f5b-b465-232c20626925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86329, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "整个", "is_correct": true, "explanation": "正确：“整个下午”表示全部时间，与后面“我都在”的全程含义相符。"}, {"text": "部分", "is_correct": false, "explanation": "搭配：“部分”表示不全，与后面的“都”要求全部的语义矛盾。"}, {"text": "零星", "is_correct": false, "explanation": "语义：“零星”指断断续续、很少，与“我都在图书馆看书”的整段时间冲突。"}, {"text": "短暂", "is_correct": false, "explanation": "语义：“短暂”说时间很短，与这里整段下午的时长相反。"}], "explanations": {"整个": "正确：“整个下午”表示全部时间，与后面“我都在”的全程含义相符。", "部分": "搭配：“部分”表示不全，与后面的“都”要求全部的语义矛盾。", "零星": "语义：“零星”指断断续续、很少，与“我都在图书馆看书”的整段时间冲突。", "短暂": "语义：“短暂”说时间很短，与这里整段下午的时长相反。"}, "sentence_index": 0, "correct_answer": "整个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把假期的整个都用来看书，很少出门。", "explanation": "这里应该用〈全部〉。“整个”是形容词，只能修饰名词，不能单独作名词；应说“假期的全部”或“整个假期”。"}, {"text": "他忘了这件事的整个，直到第二天才想起来。", "explanation": "这里应该用〈全部〉。“整个”是形容词，不能单独作名词；应说“这件事的全部”。"}, {"text": "这些钱的整个交给了他。", "explanation": "这里应该用〈全部〉。“整个”是形容词，不能单独作名词；应说“这些钱的全部”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98b5a4cf-7669-4ed4-b455-fc83b20db20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86329, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "整个", "is_correct": true, "explanation": "正确：“整个班”指全班，与“都参加了比赛”相符。"}, {"text": "偏僻", "is_correct": false, "explanation": "语义：“偏僻”形容地方冷僻，不能修饰一个班级的全体同学。"}, {"text": "残缺", "is_correct": false, "explanation": "搭配：“残缺”多用于物品或身体，不用来修饰班级及其成员全部到齐的情况。"}, {"text": "空荡", "is_correct": false, "explanation": "语义：“空荡”形容空间空旷，与“同学都参加了比赛”的人员状态冲突。"}], "explanations": {"整个": "正确：“整个班”指全班，与“都参加了比赛”相符。", "偏僻": "语义：“偏僻”形容地方冷僻，不能修饰一个班级的全体同学。", "残缺": "搭配：“残缺”多用于物品或身体，不用来修饰班级及其成员全部到齐的情况。", "空荡": "语义：“空荡”形容空间空旷，与“同学都参加了比赛”的人员状态冲突。"}, "sentence_index": 6, "correct_answer": "整个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们的整个在操场上玩，玩到天黑。", "explanation": "这里应该用〈全体〉。“整个”是形容词，不能单独作主语；指全体孩子应说“全体孩子”。"}, {"text": "这些菜我们的整个吃完了，一点也没剩。", "explanation": "这里应该用〈全部〉。“整个”是形容词，不能单独作名词；应说“这些菜我们全部吃完了”。"}, {"text": "这些书的整个卖完了。", "explanation": "这里应该用〈全部〉。“整个”是形容词，不能单独作名词；应说“这些书全部卖完了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98b5a4cf-7669-4ed4-b455-fc83b20db20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
