INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86332, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电视或广播中，传送某套节目的信号通路。", "primary_collocate": null, "pronunciation": "pín dào", "ipa": "pʰin˧˥ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "请把电视换到新闻频道。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个频道的信号不太好。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收音机里有很多音乐频道。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个频道二十四小时播放新闻。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视的频道太多了。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天晚上看体育频道。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的电视只能收到十个频道。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个广播频道晚上播放音乐。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信号太弱，这个频道看不清楚。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把收音机调到交通频道。", "target_word": "频道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "頻道", "label": "繁体"}, {"form": "新闻频道", "label": "复合"}], "register": "中性", "sense_fingerprint": "电视或广播传送某套节目的信号通路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da3fe4f3-6505-4386-9195-0de57bfd5131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86332, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：电视不能换到“作业”上，作业不是可以切换的播出内容。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“新闻”修饰的是频道、节目，不能修饰手机。"}, {"text": "频道", "is_correct": true, "explanation": "正确答案：“新闻频道”指播放新闻的电视频道，电视可以换到这里。"}, {"text": "面包", "is_correct": false, "explanation": "语义：“面包”是食物，电视不能换到它上面。"}], "explanations": {"作业": "语义：电视不能换到“作业”上，作业不是可以切换的播出内容。", "手机": "搭配：“新闻”修饰的是频道、节目，不能修饰手机。", "频道": "正确答案：“新闻频道”指播放新闻的电视频道，电视可以换到这里。", "面包": "语义：“面包”是食物，电视不能换到它上面。"}, "sentence_index": 0, "correct_answer": "频道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个频道表演了一首歌。", "explanation": "这里应该用〈节目〉。频道是信号通路，不能表演；能表演的是节目。"}, {"text": "我们从这个频道走出了地铁站。", "explanation": "这里应该用〈通道〉。频道指电视或广播的节目信号通路，不能指供人通行的通道。"}, {"text": "我家电视上有一条频道在播新闻。", "explanation": "这里应该用〈个〉。频道的量词是“个”，“条”多用于河流、道路、消息等，不用于频道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86332, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信件", "is_correct": false, "explanation": "语义：电视不能收到“信件”，信件不是可以接收的节目或信号。"}, {"text": "频道", "is_correct": true, "explanation": "正确答案：电视能收到的是频道，“十个频道”是数量。"}, {"text": "包裹", "is_correct": false, "explanation": "语义：“包裹”是寄送的物品，电视不能收到它。"}, {"text": "孩子", "is_correct": false, "explanation": "搭配：“收到”接的是信号、节目、频道这类内容，不能搭配“孩子”。"}], "explanations": {"信件": "语义：电视不能收到“信件”，信件不是可以接收的节目或信号。", "频道": "正确答案：电视能收到的是频道，“十个频道”是数量。", "包裹": "语义：“包裹”是寄送的物品，电视不能收到它。", "孩子": "搭配：“收到”接的是信号、节目、频道这类内容，不能搭配“孩子”。"}, "sentence_index": 6, "correct_answer": "频道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们通过正规频道买到了票。", "explanation": "这里应该用〈渠道〉。频道只指电视或广播的节目信号通路，“通过……买到”的途径要用渠道。"}, {"text": "这个频道的水流很急。", "explanation": "这里应该用〈管道〉。频道指电视或广播的节目信号通路，不能指输水的管道。"}, {"text": "我家电视只有一根频道。", "explanation": "这里应该用〈个〉。频道的量词是“个”，“根”用于细长的东西，不用于频道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86332, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家有三只频道。", "corrected_sentence": "我家有三个频道。", "error_description": "量词错误：“频道”应搭配量词“个”。“只”多用于动物或成对器物中的单个，不能用于频道。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86332, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把电视调到一条体育频道。", "corrected_sentence": "请把电视调到一个体育频道。", "error_description": "量词错误：“频道”应搭配量词“个”，“条”不用于频道，应为“调到一个体育频道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86335, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "被动", "is_correct": true, "explanation": "反义：“主动”指不待推动而自觉行动，“被动”指不自觉、要靠外力推动，二者构成反义。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”指没有声音或动静小，与“主动”的意思不构成反义。"}, {"text": "认真", "is_correct": false, "explanation": "“认真”指做事专心、严肃，与“主动”不构成反义关系。"}, {"text": "快乐", "is_correct": false, "explanation": "“快乐”指心情愉快，与“主动”不构成反义关系。"}], "correct_answer": "被动", "explanations": {"被动": "反义：“主动”指不待推动而自觉行动，“被动”指不自觉、要靠外力推动，二者构成反义。", "安静": "“安静”指没有声音或动静小，与“主动”的意思不构成反义。", "认真": "“认真”指做事专心、严肃，与“主动”不构成反义关系。", "快乐": "“快乐”指心情愉快，与“主动”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86335, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "被动", "is_correct": true, "explanation": "反义：“主动”指不用别人说就自己去做，“被动”指不自觉、要靠外力推动，二者构成反义。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”指场面喧闹、有人气，与“主动”不构成反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”指质地不硬，与“主动”不构成反义关系。"}, {"text": "勇敢", "is_correct": false, "explanation": "“勇敢”指不怕困难和危险，与“主动”不构成反义关系。"}], "correct_answer": "被动", "explanations": {"被动": "反义：“主动”指不用别人说就自己去做，“被动”指不自觉、要靠外力推动，二者构成反义。", "热闹": "“热闹”指场面喧闹、有人气，与“主动”不构成反义关系。", "柔软": "“柔软”指质地不硬，与“主动”不构成反义关系。", "勇敢": "“勇敢”指不怕困难和危险，与“主动”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86335, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "主动是不用别人说，自己就去做。", "primary_collocate": null, "pronunciation": "zhǔ dòng", "ipa": "ʈʂu˨˩˦ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈做饭时，女儿主动洗碗。", "target_word": "主动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他主动问老师不懂的问题。", "target_word": "主动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完饭，儿子主动把桌子擦干净了。", "target_word": "主动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很主动，看见朋友有困难就去帮忙。", "target_word": "主动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事是我主动做的，没人叫我。", "target_word": "主动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们主动打扫教室，老师很高兴。", "target_word": "主动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他主动说出了自己的错误。", "target_word": "主动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做错事要主动认错。", "target_word": "主动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子主动写作业，爸爸不用说。", "target_word": "主动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李主动留下来加班。", "target_word": "主动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "主动性", "label": "复合"}], "register": "中性", "sense_fingerprint": "不用别人说自己就去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717e23d-bca9-41d2-953d-d55f3fb7f070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86335, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主动", "is_correct": true, "explanation": "正确：主动（zhǔ dòng）。"}, {"text": "出动", "is_correct": false, "explanation": "chū（第一声）与 zhǔ（第三声）声母与声调都不同，意思是出动（派出人员或车辆）。"}, {"text": "触动", "is_correct": false, "explanation": "chù（第四声）与 zhǔ（第三声）声母（ch/zh）和声调都不同，意思是触动（打动、碰到）。"}, {"text": "蛀洞", "is_correct": false, "explanation": "zhù（第四声）与 zhǔ（第三声）声调不同，意思是蛀洞（虫子蛀出的洞）。"}, {"text": "出洞", "is_correct": false, "explanation": "chū（第一声）与 zhǔ（第三声）声母与声调都不同，意思是出洞（从洞里出来）。"}], "explanations": {"主动": "正确：主动（zhǔ dòng）。", "出动": "chū（第一声）与 zhǔ（第三声）声母与声调都不同，意思是出动（派出人员或车辆）。", "触动": "chù（第四声）与 zhǔ（第三声）声母（ch/zh）和声调都不同，意思是触动（打动、碰到）。", "蛀洞": "zhù（第四声）与 zhǔ（第三声）声调不同，意思是蛀洞（虫子蛀出的洞）。", "出洞": "chū（第一声）与 zhǔ（第三声）声母与声调都不同，意思是出洞（从洞里出来）。"}, "sentence_index": null, "correct_answer": "主动"}, "level_3": {"options": [{"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”形容外貌或事物好看，不能修饰“洗碗”这一动作。"}, {"text": "主动", "is_correct": true, "explanation": "正确：“主动”指不用别人说就自己去做，与“女儿……洗碗”相符。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容身材，不能修饰“洗碗”这一动作。"}, {"text": "饥饿", "is_correct": false, "explanation": "搭配：“饥饿”形容身体状态，不能修饰“洗碗”这一动作。"}], "explanations": {"漂亮": "搭配：“漂亮”形容外貌或事物好看，不能修饰“洗碗”这一动作。", "主动": "正确：“主动”指不用别人说就自己去做，与“女儿……洗碗”相符。", "矮小": "体貌：“矮小”形容身材，不能修饰“洗碗”这一动作。", "饥饿": "搭配：“饥饿”形容身体状态，不能修饰“洗碗”这一动作。"}, "sentence_index": 0, "correct_answer": "主动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对这部电影的评价很主动。", "explanation": "这里应该用〈主观〉。主观指凭个人想法看问题，用于评价、判断；主动指自觉行动，不用来形容评价。"}, {"text": "这次比赛失败的主动原因是天气。", "explanation": "这里应该用〈主要〉。主要指最重要的，用于原因；主动指自觉行动，不说“主动原因”。"}, {"text": "这场比赛，我们一直占据着主动。", "explanation": "这里的“主动”是“占有优势、掌握主导”的意思，与“不用别人说、自己就去做”的本义不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86335, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雪白", "is_correct": false, "explanation": "搭配：“雪白”形容颜色，不能修饰“说出错误”这一行为。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，不能修饰“说出错误”这一行为。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”指不说话，与“说出了自己的错误”直接矛盾。"}, {"text": "主动", "is_correct": true, "explanation": "正确：“主动”指不用别人催促就自己去做，与“说出了自己的错误”相符。"}], "explanations": {"雪白": "搭配：“雪白”形容颜色，不能修饰“说出错误”这一行为。", "高大": "体貌：“高大”形容身材，不能修饰“说出错误”这一行为。", "沉默": "语义：“沉默”指不说话，与“说出了自己的错误”直接矛盾。", "主动": "正确：“主动”指不用别人催促就自己去做，与“说出了自己的错误”相符。"}, "sentence_index": 6, "correct_answer": "主动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影的主动风格很明显，节奏很快。", "explanation": "这里应该用〈主导〉。主导指起支配作用的，常说“主导风格”；主动指自觉行动，不能用来修饰风格。"}, {"text": "这是今年最主动的潮流。", "explanation": "这里应该用〈主流〉。主流指占主要地位的趋势，用于潮流、观点；主动指自觉行动，不用来修饰潮流。"}, {"text": "这个句子采用的是主动形式。", "explanation": "这里的“主动”是语法术语，指主动形式（主动语态），与“不用别人说、自己就去做”的本义无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86335, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他主动的向老师请教了问题。", "corrected_sentence": "他主动地向老师请教了问题。", "error_description": "应把“的”改为“地”。“主动”修饰动词“请教”，作状语，要用“地”；用“的”会把它当作定语，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86335, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他工作很主动性，常常提出新想法。", "corrected_sentence": "他工作很主动，常常提出新想法。", "error_description": "“很”后应接形容词“主动”，不能接名词“主动性”；应删去“性”，改为“他工作很主动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
