INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86336, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不待外力推动，自觉地行动。", "primary_collocate": null, "pronunciation": "zhǔ dòng", "ipa": "ʈʂu˨˩˦ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他学习很主动，不用老师提醒。", "target_word": "主动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王主动帮邻居搬家。", "target_word": "主动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作中要主动一点，别等别人来问。", "target_word": "主动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子很主动，总是自己整理房间。", "target_word": "主动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看到老人上车，主动让了座。", "target_word": "主动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她主动给我打电话，说了对不起。", "target_word": "主动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想学好汉语，就要主动开口说。", "target_word": "主动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王经理很主动，每次都先做好准备。", "target_word": "主动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要是主动一些，大家会更喜欢你。", "target_word": "主动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他主动站起来，把水递给客人。", "target_word": "主动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "主动性", "label": "复合"}], "register": "中性", "sense_fingerprint": "不待外力推动而自觉行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717e23d-bca9-41d2-953d-d55f3fb7f070') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86336, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主动", "is_correct": true, "explanation": "正确：主动（zhǔ dòng）。"}, {"text": "出动", "is_correct": false, "explanation": "chū（第一声）与 zhǔ（第三声）声母与声调都不同，意思是出动（派出人员或车辆）。"}, {"text": "触动", "is_correct": false, "explanation": "chù（第四声）与 zhǔ（第三声）声母（ch/zh）和声调都不同，意思是触动（打动、碰到）。"}, {"text": "蛀洞", "is_correct": false, "explanation": "zhù（第四声）与 zhǔ（第三声）声调不同，意思是蛀洞（虫子蛀出的洞）。"}, {"text": "出洞", "is_correct": false, "explanation": "chū（第一声）与 zhǔ（第三声）声母与声调都不同，意思是出洞（从洞里出来）。"}], "explanations": {"主动": "正确：主动（zhǔ dòng）。", "出动": "chū（第一声）与 zhǔ（第三声）声母与声调都不同，意思是出动（派出人员或车辆）。", "触动": "chù（第四声）与 zhǔ（第三声）声母（ch/zh）和声调都不同，意思是触动（打动、碰到）。", "蛀洞": "zhù（第四声）与 zhǔ（第三声）声调不同，意思是蛀洞（虫子蛀出的洞）。", "出洞": "chū（第一声）与 zhǔ（第三声）声母与声调都不同，意思是出洞（从洞里出来）。"}, "sentence_index": null, "correct_answer": "主动"}, "level_3": {"options": [{"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”指不愿做事，与后半句“不用老师提醒”所表现的自觉相反。"}, {"text": "主动", "is_correct": true, "explanation": "正确：“主动”指不待别人提醒就自觉去做，与“不用老师提醒”相符。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”形容外貌或事物好看，不能用来形容学习。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材或体型，不能用来形容学习。"}], "explanations": {"懒惰": "语义：“懒惰”指不愿做事，与后半句“不用老师提醒”所表现的自觉相反。", "主动": "正确：“主动”指不待别人提醒就自觉去做，与“不用老师提醒”相符。", "漂亮": "搭配：“漂亮”形容外貌或事物好看，不能用来形容学习。", "高大": "体貌：“高大”形容身材或体型，不能用来形容学习。"}, "sentence_index": 0, "correct_answer": "主动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对这件事的看法很主动。", "explanation": "这里应该用〈主观〉。主观指凭个人想法看问题，用于看法、判断；主动指不待推动而自觉行动，不用来形容看法。"}, {"text": "他凭主动的直觉做决定，没有可靠依据。", "explanation": "这里应该用〈主观〉。主观指凭个人感受、想法做判断，常说“凭主观直觉”；主动指不待推动而自觉行动，不能用来修饰直觉。"}, {"text": "这场比赛，我们一直掌握着主动。", "explanation": "这里的“主动”是“占据优势、掌握主导权”的意思，与“不待外力推动、自觉行动”的本义不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86336, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”指不说话，与“开口说”直接矛盾。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容身材，不能修饰“开口说”这一行为。"}, {"text": "雪白", "is_correct": false, "explanation": "搭配：“雪白”形容颜色，不能修饰说话。"}, {"text": "主动", "is_correct": true, "explanation": "正确：“主动”指不待别人催促就自觉去做，与“想学好汉语，就要……开口说”相符。"}], "explanations": {"沉默": "语义：“沉默”指不说话，与“开口说”直接矛盾。", "矮小": "体貌：“矮小”形容身材，不能修饰“开口说”这一行为。", "雪白": "搭配：“雪白”形容颜色，不能修饰说话。", "主动": "正确：“主动”指不待别人催促就自觉去做，与“想学好汉语，就要……开口说”相符。"}, "sentence_index": 6, "correct_answer": "主动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次失败最主动的原因是天气。", "explanation": "这里应该用〈主要〉。主要指最重要的，用于原因、部分；主动指自觉行动，不能说“最主动的原因”。"}, {"text": "这是今年最主动的潮流。", "explanation": "这里应该用〈主流〉。主流指占主要地位的趋势，用于潮流、观点；主动指自觉行动，不用来修饰潮流。"}, {"text": "这句话用的是主动形式。", "explanation": "这里的“主动”是语法术语，指主动形式（主动语态），与“自觉行动”的本义无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86336, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他主动的站起来，把座位让给了老人。", "corrected_sentence": "他主动地站起来，把座位让给了老人。", "error_description": "应把“的”改为“地”。“主动”修饰动词“站起来”，作状语，状语后要用“地”；用“的”会把它当作定语，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86336, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师主动了给我们讲了这道题。", "corrected_sentence": "老师主动给我们讲了这道题。", "error_description": "“主动”在这里作状语修饰“讲”，“了”不能插在状语和动词之间；应删去“主动”后的“了”，改为“老师主动给我们讲了这道题。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe12537d-4a8c-4e07-86c4-7210e31beb49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
