INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86337, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86337, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "群众是很多普通的人。", "primary_collocate": null, "pronunciation": "qún zhòng", "ipa": "tɕʰyn˧˥ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "广场上站满了群众。", "target_word": "群众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到消防车来了，群众都让开了路。", "target_word": "群众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台下的群众一起鼓掌。", "target_word": "群众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大门外围着很多群众。", "target_word": "群众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，群众慢慢离开了。", "target_word": "群众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "群众听了他的话，都笑了。", "target_word": "群众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向群众挥手。", "target_word": "群众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看热闹的群众越来越多。", "target_word": "群众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请群众不要靠近这里。", "target_word": "群众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "群众都排着队等着进门。", "target_word": "群众", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "群眾", "label": "繁体"}], "register": "中性", "sense_fingerprint": "聚在一起的很多普通人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c0ab6f7-c290-4f0d-b235-03751b345931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86337, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "群众", "is_correct": true, "explanation": "群众：指聚在一起的很多普通人，符合“站满了”的语境。"}, {"text": "书本", "is_correct": false, "explanation": "语义：书本不能站立，与“站满了”不相容。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能“站”，句意不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“站满了”一般搭配人或有形体的东西，“空气”不能与之搭配。"}], "explanations": {"群众": "群众：指聚在一起的很多普通人，符合“站满了”的语境。", "书本": "语义：书本不能站立，与“站满了”不相容。", "窗户": "语义：窗户不能“站”，句意不通。", "空气": "搭配：“站满了”一般搭配人或有形体的东西，“空气”不能与之搭配。"}, "sentence_index": 0, "correct_answer": "群众"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这个人很群众，从来不骗人。", "explanation": "这里应该用〈诚实〉。“群众”是名词，指很多普通人，不能当形容词受“很”修饰。"}, {"text": "他是我们班的群众，成绩很好。", "explanation": "这里应该用〈同学〉。“群众”指广大普通人，不用来指同班的人。"}, {"text": "他的群众很多，大家都很喜欢他。", "explanation": "这里应该用〈粉丝〉。“群众”指广大普通人，不指某人的追随者，不能说“他的群众”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86337, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "群众", "is_correct": true, "explanation": "群众：指一大群普通人，可以作为“向……挥手”的对象。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟不能作为“挥手”的对象，句意不通。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“向……挥手”的对象一般是人，“石头”不能与之搭配。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能作为“挥手”的对象。"}], "explanations": {"群众": "群众：指一大群普通人，可以作为“向……挥手”的对象。", "闹钟": "语义：闹钟不能作为“挥手”的对象，句意不通。", "石头": "搭配：“向……挥手”的对象一般是人，“石头”不能与之搭配。", "桌子": "语义：桌子不能作为“挥手”的对象。"}, "sentence_index": 6, "correct_answer": "群众"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他下个月要和群众结婚。", "explanation": "这里应该用〈对象〉。“群众”是集合名词，指一大群人，不能指某个具体的人作结婚对象。"}, {"text": "我们学校的群众都很努力。", "explanation": "这里应该用〈学生〉。“群众”指聚在一起的普通人，不用来指某个学校的成员。"}, {"text": "我家养了一只可爱的群众。", "explanation": "这里应该用〈小狗〉。“群众”指很多普通人，不能指动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86337, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门口聚集着一只群众。", "corrected_sentence": "门口聚集着一些群众。", "error_description": "“只”是用于动物的量词，不能用来计量“群众”。应说“一些群众”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86337, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他向群众很热情。", "corrected_sentence": "他对群众很热情。", "error_description": "“对群众很热情”中应用“对”，“向”表示动作的方向，不能用来修饰“很热情”这样的态度。应说“对群众很热情”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86338, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86338, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86338, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指广大的普通人民。", "primary_collocate": null, "pronunciation": "qún zhòng", "ipa": "tɕʰyn˧˥ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "政府要听群众的意见。", "target_word": "群众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察是为群众服务的。", "target_word": "群众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "群众对新政策很满意。", "target_word": "群众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生深受群众喜爱。", "target_word": "群众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长走到群众中间，听大家说话。", "target_word": "群众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "群众的生活越来越好。", "target_word": "群众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要多为群众做好事。", "target_word": "群众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干部要多和群众谈话。", "target_word": "群众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "群众提出了很多好办法。", "target_word": "群众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路修好了，群众都很高兴。", "target_word": "群众", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "群眾", "label": "繁体"}], "register": "中性", "sense_fingerprint": "广大的普通人民，常与政府、干部相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c0ab6f7-c290-4f0d-b235-03751b345931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86338, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "群众", "is_correct": true, "explanation": "群众：指广大普通人民，与政府相对，符合“政府要听……的意见”的语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能提出意见，与“听……的意见”不相容。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会发表意见，不能作为“听”的对象。"}, {"text": "政策", "is_correct": false, "explanation": "搭配：“政策”不能提出“意见”，“听……的意见”需要有人提出意见。"}], "explanations": {"群众": "群众：指广大普通人民，与政府相对，符合“政府要听……的意见”的语境。", "石头": "语义：石头不能提出意见，与“听……的意见”不相容。", "窗户": "语义：窗户不会发表意见，不能作为“听”的对象。", "政策": "搭配：“政策”不能提出“意见”，“听……的意见”需要有人提出意见。"}, "sentence_index": 0, "correct_answer": "群众"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这款手机是一种群众消费品。", "explanation": "这里应该用〈大众〉。“大众消费品”是固定说法，“群众”指人，不用来修饰商品。"}, {"text": "他这个人很群众，从来不骗人。", "explanation": "这里应该用〈诚实〉。“群众”是名词，指广大普通人民，不能当形容词受“很”修饰。"}, {"text": "这个软件的群众很大，是它最大的优势。", "explanation": "这里应该用〈用户群〉。“群众”指广大普通人，不指软件的使用者，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86338, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "群众", "is_correct": true, "explanation": "群众：指广大普通人，是“为……做好事”的受益对象，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“做好事”的对象应是人，桌子不能作受益者。"}, {"text": "钟表", "is_correct": false, "explanation": "语义：钟表不能作为“为……做好事”的受益者，句意不通。"}, {"text": "雨水", "is_correct": false, "explanation": "搭配：“为……做好事”的对象一般是人，“雨水”不能与之搭配。"}], "explanations": {"群众": "群众：指广大普通人，是“为……做好事”的受益对象，符合句意。", "桌子": "语义：“做好事”的对象应是人，桌子不能作受益者。", "钟表": "语义：钟表不能作为“为……做好事”的受益者，句意不通。", "雨水": "搭配：“为……做好事”的对象一般是人，“雨水”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "群众"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路修好了，我的群众都很高兴。", "explanation": "这里应该用〈朋友〉。“群众”指广大普通人，不指某个人的熟人，不能加“我的”。"}, {"text": "这条路修好了，他要和群众结婚。", "explanation": "这里应该用〈对象〉。“群众”指广大普通人，是集合名词，不能指某个具体的人作结婚对象。"}, {"text": "这条路修好了，路边开满了群众。", "explanation": "这里应该用〈鲜花〉。“群众”指人，不能“开满”路边。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86338, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个人民群众的力量很大。", "corrected_sentence": "人民群众的力量很大。", "error_description": "错误在于多出的“一个”。“群众”是集合名词，指一大群人，不能用个体量词“个”来计数，应去掉“一个”，说“人民群众的力量很大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86338, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市长向群众的意见很重视。", "corrected_sentence": "市长对群众的意见很重视。", "error_description": "“对”不能换成“向”。“向”表示动作的方向，不能用来修饰“很重视”这样的态度，应说“对群众的意见很重视”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
