INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86339, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "在某个范围的外面。", "primary_collocate": null, "pronunciation": "zhī wài", "ipa": "ʈʂɻ̩˥ waɪ˥˩", "syllable_count": 2, "sentences": [{"text": "城墙之外是一片大草地。", "target_word": "之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长城之外有很多山。", "target_word": "之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区之外有一家超市。", "target_word": "之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校大门之外是一条河。", "target_word": "之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村子之外是一片田。", "target_word": "之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家在三环之外，离市中心很远。", "target_word": "之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园之外没有地铁站。", "target_word": "之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山之外还是山。", "target_word": "之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的小路之外是一片树林。", "target_word": "之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场之外有很多出租车在等客人。", "target_word": "之外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "放在地点词后面，表示在某个空间范围的外面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cbda021-f83f-46c6-a624-91478e347744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86339, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "之外", "is_correct": true, "explanation": "「之外」表示城墙的外侧，与“城墙之外是一片大草地”的语境相符。"}, {"text": "之余", "is_correct": false, "explanation": "语义：「之余」表示事情之后的空闲，不指空间方位，「城墙之余」句意不通。"}, {"text": "之一", "is_correct": false, "explanation": "语义：「之一」表示多者中的一个，城墙只指一处，句意不通。"}, {"text": "之间", "is_correct": false, "explanation": "配价：「之间」需要两个以上的所指，句中只有「城墙」一处。"}], "explanations": {"之外": "「之外」表示城墙的外侧，与“城墙之外是一片大草地”的语境相符。", "之余": "语义：「之余」表示事情之后的空闲，不指空间方位，「城墙之余」句意不通。", "之一": "语义：「之一」表示多者中的一个，城墙只指一处，句意不通。", "之间": "配价：「之间」需要两个以上的所指，句中只有「城墙」一处。"}, "sentence_index": 0, "correct_answer": "之外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他走进校门之外。", "explanation": "「之外」指范围的外面，与「走进」（向里）的方向相反，两者矛盾。这里应该用〈之内〉，说「走进校门之内」。"}, {"text": "我们在三点之外开会。", "explanation": "「之外」指空间范围的外面，不能用来表示时间点。说时间先后应用〈之后〉，如「三点之后我们开会」。"}, {"text": "他站在老师之外。", "explanation": "这里应该用〈旁边〉。「之外」要以地点或能划定范围的事物为参照，「老师」是人，不能这样定位；表示站在老师身边应说「站在老师旁边」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86339, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "之外", "is_correct": true, "explanation": "「之外」表示公园范围的外面，与“没有地铁站”的语境相符。"}, {"text": "之首", "is_correct": false, "explanation": "语义：「之首」指最前或第一位，用于公园的位置，句意不通。"}, {"text": "之一", "is_correct": false, "explanation": "语义：「之一」表示多者中的一个，公园只指一处，句意不通。"}, {"text": "之后", "is_correct": false, "explanation": "语义：「之后」表示时间先后，「公园」是地方，不是时间点，「公园之后没有地铁站」句意不通。"}], "explanations": {"之外": "「之外」表示公园范围的外面，与“没有地铁站”的语境相符。", "之首": "语义：「之首」指最前或第一位，用于公园的位置，句意不通。", "之一": "语义：「之一」表示多者中的一个，公园只指一处，句意不通。", "之后": "语义：「之后」表示时间先后，「公园」是地方，不是时间点，「公园之后没有地铁站」句意不通。"}, "sentence_index": 6, "correct_answer": "之外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们走进公园之外，看到很多花。", "explanation": "「之外」指范围的外面，与「走进」（向里）的方向矛盾。这里应该用〈里〉，说「走进公园里」。"}, {"text": "他的心情在快乐之外。", "explanation": "「之外」表示空间范围的外面，与表示状态的〈在……中〉混淆。「快乐」是抽象情绪，不能作为空间参照，应说「他的心情很快乐」。"}, {"text": "我把书放在书包之外了，所以书包里有书。", "explanation": "「之外」表示在书包外面，后半句却说书在书包里，前后矛盾。这里应该用〈里〉，说「放在书包里」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86339, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校园之外外面有一条河。", "corrected_sentence": "校园之外有一条河。", "error_description": "「之外」本身已经表示「外面」，后面不能再加「外面」，属于重复。应去掉多余的「外面」，说「校园之外有一条河」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86339, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "图书馆之外的有一个花园。", "corrected_sentence": "图书馆之外有一个花园。", "error_description": "「之外的」要修饰后面的中心词，而这里后面是「有」，句子缺少中心语，应去掉多余的「的」，说「图书馆之外有一个花园」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
