INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86340, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86340, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "在一定范围以外。", "primary_collocate": null, "pronunciation": "zhī wài", "ipa": "ʈʂɻ̩˥ waɪ˥˩", "syllable_count": 2, "sentences": [{"text": "除了工作之外，我还喜欢画画。", "target_word": "之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习之外，他每天也锻炼身体。", "target_word": "之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事之外，我没有别的问题。", "target_word": "之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了你之外，没有人知道这个地方。", "target_word": "之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试之外，老师还让我们写日记。", "target_word": "之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课时间之外，你可以来办公室找我。", "target_word": "之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了面包之外，我还买了牛奶。", "target_word": "之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题之外，大家还有别的想法吗？", "target_word": "之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了英语之外，他还会说法语。", "target_word": "之外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作之外的时间，她都陪孩子。", "target_word": "之外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "表示在某个事物或活动的范围以外，常说“除了……之外”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cbda021-f83f-46c6-a624-91478e347744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86340, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "之外", "is_correct": true, "explanation": "「除了……之外」表示排除，与“我还喜欢画画”的语境相符。"}, {"text": "之中", "is_correct": false, "explanation": "搭配：「除了」不与「之中」搭配，此处应说「除了……之外」。"}, {"text": "之内", "is_correct": false, "explanation": "搭配：「除了」之后接「之内」不成立，表示排除要用「之外」或「以外」。"}, {"text": "之上", "is_correct": false, "explanation": "语义：「之上」表示位置在上，与「除了」的排除义无关，句意不通。"}], "explanations": {"之外": "「除了……之外」表示排除，与“我还喜欢画画”的语境相符。", "之中": "搭配：「除了」不与「之中」搭配，此处应说「除了……之外」。", "之内": "搭配：「除了」之后接「之内」不成立，表示排除要用「之外」或「以外」。", "之上": "语义：「之上」表示位置在上，与「除了」的排除义无关，句意不通。"}, "sentence_index": 0, "correct_answer": "之外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "除了学校之外，我们都在学校里上课。", "explanation": "这里误用了排除义。「除了……之外」排除了「学校」，却又说在学校里上课，前后矛盾。表示地点应说〈在……里〉，去掉「除了……之外」。"}, {"text": "除了小王之外，小王也来了。", "explanation": "「除了……之外」已经把小王排除在外，后面又说小王也来了，前后矛盾。应说「除了小王之外，小李也来了」。"}, {"text": "除了咖啡之外，我只喝咖啡。", "explanation": "排除了「咖啡」，后面却说只喝咖啡，前后矛盾。应把排除的对象换成别的东西，如「除了咖啡之外，我还喝茶」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86340, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "之外", "is_correct": true, "explanation": "「除了……之外」表示排除，与「我还买了牛奶」的语境相符。"}, {"text": "之后", "is_correct": false, "explanation": "语义：「之后」表示时间的先后，「面包」不是时间，句意不通。"}, {"text": "之前", "is_correct": false, "explanation": "语义：「之前」表示时间的先后，与「除了面包」的排除关系不合。"}, {"text": "之下", "is_correct": false, "explanation": "搭配：「除了」不与「之下」搭配，此处应说「除了……之外」。"}], "explanations": {"之外": "「除了……之外」表示排除，与「我还买了牛奶」的语境相符。", "之后": "语义：「之后」表示时间的先后，「面包」不是时间，句意不通。", "之前": "语义：「之前」表示时间的先后，与「除了面包」的排除关系不合。", "之下": "搭配：「除了」不与「之下」搭配，此处应说「除了……之外」。"}, "sentence_index": 6, "correct_answer": "之外"}, "level_6": {"correct_sentence_index": 8, "wrong_sentences": [{"text": "除了书包之外，我的书都在书包里。", "explanation": "这里误用了排除义。「除了……之外」排除了「书包」，却又说书在书包里，前后矛盾。应去掉「除了……之外」，说「我的书都在书包里」。"}, {"text": "除了妈妈之外，妈妈也喜欢唱歌。", "explanation": "「除了……之外」排除了「妈妈」，后面主语又是「妈妈」，前后矛盾。应说「除了妈妈之外，爸爸也喜欢唱歌」。"}, {"text": "除了周末之外，我周末还去公园。", "explanation": "排除了「周末」，后面又说周末去公园，前后矛盾。应说「除了周末之外，我平时也去公园」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86340, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "除了天气之外了，一切都很好。", "corrected_sentence": "除了天气之外，一切都很好。", "error_description": "「之外」后面不能加「了」，「了」不能附着在方位词「之外」上。应去掉「了」，说「除了天气之外，一切都很好」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86340, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "除了朋友之外的，我没有别的爱好。", "corrected_sentence": "除了朋友之外，我没有别的爱好。", "error_description": "「之外」后多加了「的」。「的」需要名词来修饰，这里后面是完整句子，没有可修饰的名词。「除了……之外」后直接接句子，应去掉「的」，说「除了朋友之外，我没有别的爱好」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
