INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86341, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "“选举”是大家投票，选出一个人。", "primary_collocate": null, "pronunciation": "xuǎn jǔ", "ipa": "ɕɥɛn²¹⁴ tɕy²¹⁴", "syllable_count": 2, "sentences": [{"text": "我们班明天要选举新班长。", "target_word": "选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家投票选举他当队长。", "target_word": "选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校每年选举一次学生会主席。", "target_word": "选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的人选举了一位新村长。", "target_word": "选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们今天选举，谁得票多谁当组长。", "target_word": "选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区业主选举出了三位代表。", "target_word": "选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家选举小王做组长。", "target_word": "选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司员工要选举自己的代表。", "target_word": "选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们打算怎么选举班干部？", "target_word": "选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都选举她，因为她很热心。", "target_word": "选举", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "选举了", "label": "体标"}, {"form": "选举过", "label": "体标"}, {"form": "選舉", "label": "繁体"}, {"form": "选举权", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：大家投票选出某个人担任职务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bcfb73b-b30f-4f91-b98a-882ac61a0cd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86341, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "搬运", "is_correct": false, "explanation": "搭配：「搬运」的对象是货物，不能用于人，“新班长”不能作其宾语。"}, {"text": "选举", "is_correct": true, "explanation": "「选举」指通过投票选出班长，与“明天要……新班长”的语境相符。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：「打扫」的对象是地方或物品，不能用于人，句中的“新班长”无法作宾语。"}, {"text": "欢送", "is_correct": false, "explanation": "语义：「欢送」是送别离开的人，与“新班长”即将就任的语境相矛盾。"}], "explanations": {"搬运": "搭配：「搬运」的对象是货物，不能用于人，“新班长”不能作其宾语。", "选举": "「选举」指通过投票选出班长，与“明天要……新班长”的语境相符。", "打扫": "搭配：「打扫」的对象是地方或物品，不能用于人，句中的“新班长”无法作宾语。", "欢送": "语义：「欢送」是送别离开的人，与“新班长”即将就任的语境相矛盾。"}, "sentence_index": 0, "correct_answer": "选举"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "校长选举了一位新班长。", "explanation": "这里应该用〈任命〉。选举需要全体投票，由校长直接指定职务应说任命。"}, {"text": "我选举了这条回家的路。", "explanation": "这里应该用〈选择〉。选举的对象是人或职务，挑选路线要用选择。"}, {"text": "妈妈选举了一本新书给我。", "explanation": "这里应该用〈挑选〉。选举只用于投票选出人或职务，不能用于选购书籍，挑书要用挑选。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86341, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参观", "is_correct": false, "explanation": "搭配：「参观」的对象是场所，不能指人担任组长。"}, {"text": "选举", "is_correct": true, "explanation": "「选举」指通过投票选出组长，与“大家……小王做组长”的语境相符。"}, {"text": "观看", "is_correct": false, "explanation": "搭配：「观看」的对象是节目、比赛等，不说观看某人做组长。"}, {"text": "送别", "is_correct": false, "explanation": "语义：「送别」是送人离开，与“做组长”的任职语境相矛盾。"}], "explanations": {"参观": "搭配：「参观」的对象是场所，不能指人担任组长。", "选举": "「选举」指通过投票选出组长，与“大家……小王做组长”的语境相符。", "观看": "搭配：「观看」的对象是节目、比赛等，不说观看某人做组长。", "送别": "语义：「送别」是送人离开，与“做组长”的任职语境相矛盾。"}, "sentence_index": 6, "correct_answer": "选举"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他向我选举了这个城市。", "explanation": "这里应该用〈介绍〉。选举的对象是人或职务，介绍地方要用介绍。"}, {"text": "老师选举了她参加比赛。", "explanation": "这里应该用〈推荐〉。选举需要群众投票，老师单独选定人选要用推荐，选举不能这样用。"}, {"text": "市政府选举了一张证书。", "explanation": "这里应该用〈颁发〉。选举的对象是人或职务，证书要用颁发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86341, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班以前选举着班长。", "corrected_sentence": "我们班以前选举过班长。", "error_description": "“着”用错：表示曾经有过的经历应用“过”，“着”表示动作进行或状态持续，“选举着班长”不通。错误形式“选举着班长”，正确形式“选举过班长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86341, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班下周选举了新的班干部。", "corrected_sentence": "我们班下周选举新的班干部。", "error_description": "“了”用错：“下周”是将来时间，动作尚未完成，不能用“了”。应去掉“了”，正确形式为“下周选举新的班干部”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
