INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86342, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "动词，指众人通过投票等方式挑选出代表或负责人。", "primary_collocate": null, "pronunciation": "xuǎn jǔ", "ipa": "ɕɥɛn²¹⁴ tɕy²¹⁴", "syllable_count": 2, "sentences": [{"text": "全体同学选举李明为学习委员。", "target_word": "选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家用举手的方式选举小组长。", "target_word": "选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民每五年选举一次市长。", "target_word": "选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会员们通过投票选举新的负责人。", "target_word": "选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们选举出了自己的代表。", "target_word": "选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们准备选举一位新的校长。", "target_word": "选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们先讨论，再选举。", "target_word": "选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民选举过两次村长。", "target_word": "选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家长们选举了三位家长代表。", "target_word": "选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家选举她担任社团的负责人。", "target_word": "选举", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "选举了", "label": "体标"}, {"form": "选举过", "label": "体标"}, {"form": "選舉", "label": "繁体"}, {"form": "选举人", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：众人通过投票或举手挑选代表或负责人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bcfb73b-b30f-4f91-b98a-882ac61a0cd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86342, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "担任", "is_correct": false, "explanation": "配价：「担任」后面要直接带职务，不能接“李明为……”这样的结构。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：「参观」的对象是场所，不用于给人任命职务。"}, {"text": "选举", "is_correct": true, "explanation": "「选举」指全体通过投票选出人担任职务，与“为学习委员”相符。"}, {"text": "欢送", "is_correct": false, "explanation": "语义：「欢送」是送别离开的人，与“为学习委员”的任职语境相矛盾。"}], "explanations": {"担任": "配价：「担任」后面要直接带职务，不能接“李明为……”这样的结构。", "参观": "搭配：「参观」的对象是场所，不用于给人任命职务。", "选举": "「选举」指全体通过投票选出人担任职务，与“为学习委员”相符。", "欢送": "语义：「欢送」是送别离开的人，与“为学习委员”的任职语境相矛盾。"}, "sentence_index": 0, "correct_answer": "选举"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老板选举了新的负责人。", "explanation": "这里应该用〈任命〉。选举需要众人投票，老板直接指定负责人要用任命。"}, {"text": "妈妈选举了一本新书给我。", "explanation": "这里应该用〈挑选〉。选举的对象是人或职务，不能用于选购书籍。"}, {"text": "我选举了这个方案。", "explanation": "这里应该用〈选择〉。选举是投票选出人或职务，决定采用方案要用选择。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86342, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教室", "is_correct": false, "explanation": "词性：「教室」是名词，不能放在“再”后面作谓语，“再教室”不成句。"}, {"text": "选举", "is_correct": true, "explanation": "「选举」指通过投票选出负责人，与“先讨论，再……”的决定性步骤相符。"}, {"text": "书包", "is_correct": false, "explanation": "词性：「书包」是名词，不能放在“再”后面表示动作，“再书包”不成句。"}, {"text": "失业", "is_correct": false, "explanation": "语义：「失业」指失去工作，不是讨论之后的行动，与语境不符。"}], "explanations": {"教室": "词性：「教室」是名词，不能放在“再”后面作谓语，“再教室”不成句。", "选举": "「选举」指通过投票选出负责人，与“先讨论，再……”的决定性步骤相符。", "书包": "词性：「书包」是名词，不能放在“再”后面表示动作，“再书包”不成句。", "失业": "语义：「失业」指失去工作，不是讨论之后的行动，与语境不符。"}, "sentence_index": 6, "correct_answer": "选举"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "导游向游客选举了景点。", "explanation": "这里应该用〈介绍〉。选举的对象是人或职务，介绍景点要用介绍。"}, {"text": "学校选举了三名新生。", "explanation": "这里应该用〈录取〉。选举需要群众投票，学校招收新生要用录取。"}, {"text": "市政府选举了一张奖状。", "explanation": "这里应该用〈颁发〉。选举的对象是人或职务，奖状要用颁发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86342, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "俱乐部下个月选举了一位新主席。", "corrected_sentence": "俱乐部下个月选举一位新主席。", "error_description": "“了”用错：“下个月”是将来时间，不能与“了”搭配。应去掉“了”，正确形式为“下个月选举一位新主席”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86342, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "俱乐部以前选举着新主席。", "corrected_sentence": "俱乐部以前选举过新主席。", "error_description": "“着”用错：表示曾经有过的经历应用“过”，“着”表示动作进行或状态持续，“选举着新主席”不通。错误形式“选举着新主席”，正确形式“选举过新主席”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
