INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86343, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "交是把东西给别人。", "primary_collocate": null, "pronunciation": "jiāo", "ipa": "tɕjɑʊ̯˥", "syllable_count": 1, "sentences": [{"text": "老师让我们交作业。", "target_word": "交", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把信交给了我。", "target_word": "交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把票交给门口的人。", "target_word": "交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经交了这个月的房租。", "target_word": "交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事你交给我吧。", "target_word": "交", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她把手机交给了爸爸。", "target_word": "交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试结束了，请马上交卷子。", "target_word": "交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们都在交试卷。", "target_word": "交", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每月交一次电费。", "target_word": "交", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "经理把工作交给了小王。", "target_word": "交", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "交了", "label": "完成体"}, {"form": "交过", "label": "经历体"}, {"form": "交给", "label": "复合"}], "register": "中性", "sense_fingerprint": "交：把东西交给别人（上交、转交）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da3fe4f3-6505-4386-9195-0de57bfd5131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86343, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "敲", "is_correct": false, "explanation": "qiāo 与 jiāo 声母不同（q / j），意思是敲打。"}, {"text": "交", "is_correct": true, "explanation": "正确答案：交（jiāo），意思是把东西交给别人。"}, {"text": "脚", "is_correct": false, "explanation": "jiǎo 与 jiāo 声调不同（第三声 / 第一声），意思是脚。"}, {"text": "消", "is_correct": false, "explanation": "xiāo 与 jiāo 声母不同（x / j），意思是消失、消除。"}], "explanations": {"敲": "qiāo 与 jiāo 声母不同（q / j），意思是敲打。", "交": "正确答案：交（jiāo），意思是把东西交给别人。", "脚": "jiǎo 与 jiāo 声调不同（第三声 / 第一声），意思是脚。", "消": "xiāo 与 jiāo 声母不同（x / j），意思是消失、消除。"}, "sentence_index": null, "correct_answer": "交"}, "level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“作业”不能被吃，“吃”与“作业”的意思不合。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”一般接桌子、黑板等，不能接“作业”。"}, {"text": "交", "is_correct": true, "explanation": "正确答案：“老师让我们交作业”指要求学生把作业交上去。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“作业”不能被煮，“煮”与“作业”的意思不合。"}], "explanations": {"吃": "语义：“作业”不能被吃，“吃”与“作业”的意思不合。", "擦": "搭配：“擦”一般接桌子、黑板等，不能接“作业”。", "交": "正确答案：“老师让我们交作业”指要求学生把作业交上去。", "煮": "语义：“作业”不能被煮，“煮”与“作业”的意思不合。"}, "sentence_index": 0, "correct_answer": "交"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在大学交了一座教学楼。", "explanation": "这里的“交”是结识的意思，但结识的对象只能是人，不能指教学楼；本题“把东西交给别人”不是这样用。"}, {"text": "我在山上交了一片森林。", "explanation": "这里的“交”是结识的意思，但结识的对象只能是人，不能指森林；本题“把东西交给别人”不是这样用。"}, {"text": "我在操场上交了一棵大树。", "explanation": "这里的“交”是结识的意思，但结识的对象只能是人，不能指大树；本题“把东西交给别人”不是这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86343, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "叫", "is_correct": false, "explanation": "jiào 与 jiāo 声调不同（第四声 / 第一声），意思是叫喊。"}, {"text": "交", "is_correct": true, "explanation": "正确答案：交（jiāo），意思是把东西交给别人。"}, {"text": "角", "is_correct": false, "explanation": "jiǎo 与 jiāo 声调不同（第三声 / 第一声），意思是动物的角或角落。"}, {"text": "较", "is_correct": false, "explanation": "jiào 与 jiāo 声调不同（第四声 / 第一声），意思是比较。"}], "explanations": {"叫": "jiào 与 jiāo 声调不同（第四声 / 第一声），意思是叫喊。", "交": "正确答案：交（jiāo），意思是把东西交给别人。", "角": "jiǎo 与 jiāo 声调不同（第三声 / 第一声），意思是动物的角或角落。", "较": "jiào 与 jiāo 声调不同（第四声 / 第一声），意思是比较。"}, "sentence_index": null, "correct_answer": "交"}, "level_3": {"options": [{"text": "洗", "is_correct": false, "explanation": "语义：“卷子”不是可以清洗的东西，“洗”与“卷子”不合。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“卷子”不能被煮，“煮”与“卷子”不合。"}, {"text": "交", "is_correct": true, "explanation": "正确答案：“马上交卷子”指考试结束后把试卷交上去。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”一般接水果、花，不能接“卷子”。"}], "explanations": {"洗": "语义：“卷子”不是可以清洗的东西，“洗”与“卷子”不合。", "煮": "语义：“卷子”不能被煮，“煮”与“卷子”不合。", "交": "正确答案：“马上交卷子”指考试结束后把试卷交上去。", "摘": "搭配：“摘”一般接水果、花，不能接“卷子”。"}, "sentence_index": 6, "correct_answer": "交"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "李老师交我们数学。", "explanation": "这里应该用〈教〉。“教”是传授知识；“交”是把东西给别人，不能表示上课教学。"}, {"text": "你能交我怎么包饺子吗？", "explanation": "这里应该用〈教〉。告诉别人怎么做要用“教”；“交”是把东西给别人。"}, {"text": "他在路口交了一辆出租车。", "explanation": "这里应该用〈叫〉。“叫出租车”指招呼车辆；“交”是把东西给别人，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86343, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把卷子交了给老师。", "corrected_sentence": "她把卷子交给了老师。", "error_description": "“了”的位置错误：“交给”是动词加补语，“了”应放在“给”之后，应为“交给了老师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86343, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "经理把计划交了小王。", "corrected_sentence": "经理把计划交给了小王。", "error_description": "漏掉补语：把东西交给别人要用“交给”，这里漏掉了“给”，应为“交给了小王”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86345, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以上", "is_correct": true, "explanation": "以上与“以下”构成反义，指在某个数目或位置的上面。"}, {"text": "中间", "is_correct": false, "explanation": "中间指两端之间的位置，与“以下”不是近义或反义关系。"}, {"text": "左边", "is_correct": false, "explanation": "左边指方位，与“以下”的意思没有反义关系。"}, {"text": "时间", "is_correct": false, "explanation": "时间指一段时段，与“以下”没有近义或反义关系。"}], "correct_answer": "以上", "explanations": {"以上": "以上与“以下”构成反义，指在某个数目或位置的上面。", "中间": "中间指两端之间的位置，与“以下”不是近义或反义关系。", "左边": "左边指方位，与“以下”的意思没有反义关系。", "时间": "时间指一段时段，与“以下”没有近义或反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86345, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以上", "is_correct": true, "explanation": "以上与“以下”构成反义，指在某个数目或位置的上面。"}, {"text": "天空", "is_correct": false, "explanation": "天空指天上的空间，与“以下”没有近义或反义关系。"}, {"text": "书包", "is_correct": false, "explanation": "书包是装书本的袋子，与“以下”没有近义或反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户是房屋上透光通风的开口，与“以下”没有近义或反义关系。"}], "correct_answer": "以上", "explanations": {"以上": "以上与“以下”构成反义，指在某个数目或位置的上面。", "天空": "天空指天上的空间，与“以下”没有近义或反义关系。", "书包": "书包是装书本的袋子，与“以下”没有近义或反义关系。", "窗户": "窗户是房屋上透光通风的开口，与“以下”没有近义或反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86345, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“以下”是说在这个位置或数目的下面。", "primary_collocate": null, "pronunciation": "yǐ xià", "ipa": "i²¹⁴ ɕja⁵¹", "syllable_count": 2, "sentences": [{"text": "十岁以下的孩子不用买票。", "target_word": "以下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的温度在零度以下。", "target_word": "以下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在这条线以下写名字。", "target_word": "以下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "九十分以下就不合格。", "target_word": "以下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身高一米二以下的孩子可以免费。", "target_word": "以下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水面以下有很多小鱼。", "target_word": "以下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩在平均分以下。", "target_word": "以下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "膝盖以下都湿了。", "target_word": "以下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的东西都在五十元以下。", "target_word": "以下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山腰以下都是树林。", "target_word": "以下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "位置或数目在某个点的下面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fd271da-7053-4e94-b9bc-a929e14d7b33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86345, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "以下", "is_correct": true, "explanation": "以下表示位置或数目在某个基准之下，“十岁以下”即十岁及十岁以下。"}, {"text": "上方", "is_correct": false, "explanation": "语义：“上方”指位置在上面，不能用来限定年龄。"}, {"text": "下方", "is_correct": false, "explanation": "语义：“下方”指位置在下面，与“十岁”这样的年龄不能组合。"}, {"text": "地上", "is_correct": false, "explanation": "搭配：“地上”指地面的位置，不能用来修饰年龄。"}], "explanations": {"以下": "以下表示位置或数目在某个基准之下，“十岁以下”即十岁及十岁以下。", "上方": "语义：“上方”指位置在上面，不能用来限定年龄。", "下方": "语义：“下方”指位置在下面，与“十岁”这样的年龄不能组合。", "地上": "搭配：“地上”指地面的位置，不能用来修饰年龄。"}, "sentence_index": 0, "correct_answer": "以下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "六十分以下才能及格。", "explanation": "这里应该用〈以上〉。及格要求分数达到某个数以上，“以下”表示在某数之下，意思正好相反。"}, {"text": "吃完饭以下我们去散步。", "explanation": "这里应该用〈以后〉。表示事情在某件事之后发生要用“以后”；“以下”指位置或数目在某点之下，不能用来表示先后。"}, {"text": "除了他以下，大家都同意了。", "explanation": "这里应该用〈以外〉。表示除去某人要用“除了……以外”；“以下”表示位置或数目在某点之下，不能用来排除某人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86345, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "以下", "is_correct": true, "explanation": "以下表示低于某个基准，“平均分以下”即低于平均分。"}, {"text": "桌上", "is_correct": false, "explanation": "语义：“桌上”指桌面，与成绩的高低无关。"}, {"text": "门口", "is_correct": false, "explanation": "语义：“门口”指位置，不能用来表示成绩的范围。"}, {"text": "墙外", "is_correct": false, "explanation": "搭配：“墙外”是方位，不能与“平均分”搭配。"}], "explanations": {"以下": "以下表示低于某个基准，“平均分以下”即低于平均分。", "桌上": "语义：“桌上”指桌面，与成绩的高低无关。", "门口": "语义：“门口”指位置，不能用来表示成绩的范围。", "墙外": "搭配：“墙外”是方位，不能与“平均分”搭配。"}, "sentence_index": 6, "correct_answer": "以下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "除了老师以下，大家都去了郊游。", "explanation": "这里应该用〈以外〉。表示除去某人要用“除了……以外”；“以下”不能用来排除某人。"}, {"text": "他下课以下就回家了。", "explanation": "这里应该用〈以后〉。表示下课之后才回家要用“以后”；“以下”不能表示动作的先后。"}, {"text": "他的体重高于五十公斤以下。", "explanation": "这里不该用〈以下〉。〈高于〉表示比某数大，〈以下〉表示比某数小，二者语义相反，不能同用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86345, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "十二岁的以下的孩子可以免费参观。", "corrected_sentence": "十二岁以下的孩子可以免费参观。", "error_description": "结构错误：“十二岁”与“以下”之间不能加“的”，应说“十二岁以下”，不说“十二岁的以下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86345, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "成绩在六十分的以下的同学需要补考。", "corrected_sentence": "成绩在六十分以下的同学需要补考。", "error_description": "结构错误：“六十分”与“以下”之间不能加“的”，应说“六十分以下”，不说“六十分的以下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86346, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以上", "is_correct": true, "explanation": "以上指次序在前的内容，与表示次序在后的“以下”构成反义。"}, {"text": "标题", "is_correct": false, "explanation": "标题指文章或作品的题目，与“以下”的次序义没有近义或反义关系。"}, {"text": "图片", "is_correct": false, "explanation": "图片指画面或照片，与“以下”没有近义或反义关系。"}, {"text": "课桌", "is_correct": false, "explanation": "课桌指学生用的桌子，与“以下”没有近义或反义关系。"}], "correct_answer": "以上", "explanations": {"以上": "以上指次序在前的内容，与表示次序在后的“以下”构成反义。", "标题": "标题指文章或作品的题目，与“以下”的次序义没有近义或反义关系。", "图片": "图片指画面或照片，与“以下”没有近义或反义关系。", "课桌": "课桌指学生用的桌子，与“以下”没有近义或反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86346, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以上", "is_correct": true, "explanation": "以上指次序在前的内容，与表示次序在后的“以下”构成反义。"}, {"text": "河流", "is_correct": false, "explanation": "河流指江河等水体，与“以下”没有近义或反义关系。"}, {"text": "电视", "is_correct": false, "explanation": "电视是一种电器，与“以下”没有近义或反义关系。"}, {"text": "树叶", "is_correct": false, "explanation": "树叶是植物的部分，与“以下”没有近义或反义关系。"}], "correct_answer": "以上", "explanations": {"以上": "以上指次序在前的内容，与表示次序在后的“以下”构成反义。", "河流": "河流指江河等水体，与“以下”没有近义或反义关系。", "电视": "电视是一种电器，与“以下”没有近义或反义关系。", "树叶": "树叶是植物的部分，与“以下”没有近义或反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86346, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "名词，指次序上排在后面的内容，即接下来要说或列出的部分。", "primary_collocate": null, "pronunciation": "yǐ xià", "ipa": "i²¹⁴ ɕja⁵¹", "syllable_count": 2, "sentences": [{"text": "以下是今天的作业。", "target_word": "以下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以下是我的回答。", "target_word": "以下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看以下几个句子。", "target_word": "以下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以下的话请大家记住。", "target_word": "以下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以下内容很重要，请认真听。", "target_word": "以下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，以下的题不用做。", "target_word": "以下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以下是我们的活动安排。", "target_word": "以下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以下哪个句子是对的？", "target_word": "以下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以下几个人请留下来。", "target_word": "以下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以下的问题请大家回答。", "target_word": "以下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "次序上在后面的内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fd271da-7053-4e94-b9bc-a929e14d7b33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86346, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "以下", "is_correct": true, "explanation": "以下表示次序在后的内容，作主语时指后面的内容，“以下是今天的作业”正确。"}, {"text": "上午", "is_correct": false, "explanation": "语义：“上午”是时间段，不能指今天的作业。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”与“今天的作业”时间矛盾，不能作主语指作业。"}, {"text": "早晨", "is_correct": false, "explanation": "搭配：“早晨”是时间词，不能与“是……作业”构成对应关系。"}], "explanations": {"以下": "以下表示次序在后的内容，作主语时指后面的内容，“以下是今天的作业”正确。", "上午": "语义：“上午”是时间段，不能指今天的作业。", "明天": "语义：“明天”与“今天的作业”时间矛盾，不能作主语指作业。", "早晨": "搭配：“早晨”是时间词，不能与“是……作业”构成对应关系。"}, "sentence_index": 0, "correct_answer": "以下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们先吃饭，以下再开会。", "explanation": "这里应该用〈以后〉。表示先后顺序用“以后”；“以下”是名词，不能当“然后”用。"}, {"text": "他说完话，以下就走了。", "explanation": "这里应该用〈接着〉。表示紧接着某个动作用“接着”；“以下”不能用于动作的先后。"}, {"text": "他买了票，以下进了场。", "explanation": "这里应该用〈随后〉。表示紧接着某个动作用“随后”；“以下”不能用于动作的先后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86346, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "以下", "is_correct": true, "explanation": "以下表示次序在后的内容，“以下是我们的活动安排”正确。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，不能作为“活动安排”的内容。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”是自然景观，不能指活动安排。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“安排”不与“天气”搭配，“天气”不能作活动安排的主语。"}], "explanations": {"以下": "以下表示次序在后的内容，“以下是我们的活动安排”正确。", "桌子": "语义：“桌子”是家具，不能作为“活动安排”的内容。", "河流": "语义：“河流”是自然景观，不能指活动安排。", "天气": "搭配：“安排”不与“天气”搭配，“天气”不能作活动安排的主语。"}, "sentence_index": 6, "correct_answer": "以下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们先整理资料，以下再讨论。", "explanation": "这里应该用〈然后〉。表示先后动作用“然后”；“以下”是名词，不能当“然后”用。"}, {"text": "放学以下我们一起吃饭。", "explanation": "这里应该用〈放学后〉。表示放学之后再做事要用“放学后”；“以下”不能表示动作的先后。"}, {"text": "他看完书，以下写了读后感。", "explanation": "这里应该用〈接着〉。表示紧接着某个动作用“接着”；“以下”不能用于动作的先后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86346, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "以下本周的计划。", "corrected_sentence": "以下是本周的计划。", "error_description": "成分缺失：“以下”引出后文时，后面要用“是”，应说“以下是本周的计划”，不能省略“是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86346, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "以下了有三个问题需要解决。", "corrected_sentence": "以下有三个问题需要解决。", "error_description": "体貌错误：“以下”后面不能直接加“了”，它不表示动作的完成，去掉“了”才是正确说法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86347, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "后年", "is_correct": true, "explanation": "正确：“前年”指两年前，“后年”指两年后，时间方向相反，二者互为反义词。"}, {"text": "春天", "is_correct": false, "explanation": "无关：“春天”是季节，与“前年”没有反义关系。"}, {"text": "下午", "is_correct": false, "explanation": "无关：“下午”指一天中的时段，与“前年”没有反义关系。"}, {"text": "桌子", "is_correct": false, "explanation": "无关：“桌子”是家具，与时间词“前年”没有关系。"}], "correct_answer": "后年", "explanations": {"后年": "正确：“前年”指两年前，“后年”指两年后，时间方向相反，二者互为反义词。", "春天": "无关：“春天”是季节，与“前年”没有反义关系。", "下午": "无关：“下午”指一天中的时段，与“前年”没有反义关系。", "桌子": "无关：“桌子”是家具，与时间词“前年”没有关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
