INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86347, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "前年是去年的前一年。", "primary_collocate": null, "pronunciation": "qián nián", "ipa": "tɕʰjɛn˧˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "前年我家换了新房子。", "target_word": "前年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他前年大学毕业，去年才找到工作。", "target_word": "前年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前年春天，我和朋友去了海边。", "target_word": "前年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们是前年认识的，到现在已经两年了。", "target_word": "前年", "complexity_tier": "T3", "furigana": "wǒ men shì qián nián rèn shi de, dào xiàn zài yǐ jīng liǎng nián le.", "sentence_source": "generated"}, {"text": "前年的考试很难，今年容易一些。", "target_word": "前年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妹妹前年才学会游泳，现在游得很好。", "target_word": "前年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前年这里还是一片田地，现在盖起了楼。", "target_word": "前年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我前年养了一只猫，它已经三岁了。", "target_word": "前年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥前年去了国外工作。", "target_word": "前年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前年秋天，爸爸送给我一本词典。", "target_word": "前年", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "前年：去年之前的那一年，说明年份的时间词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd9494de-5348-4735-8c04-847b659ff0a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86347, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前年", "is_correct": true, "explanation": "正确：“前年我家换了新房子”说的是过去的事，“前年”与“换了”的已完成意思相符。"}, {"text": "明年", "is_correct": false, "explanation": "语义：“明年”指将来，与“换了”表示的已完成动作矛盾。"}, {"text": "下个月", "is_correct": false, "explanation": "语义：“下个月”指将来，与“换了”表示的已完成动作矛盾。"}, {"text": "将来", "is_correct": false, "explanation": "搭配：“将来”通常与“会”“要”搭配，不与表示已完成的“了”搭配。"}], "explanations": {"前年": "正确：“前年我家换了新房子”说的是过去的事，“前年”与“换了”的已完成意思相符。", "明年": "语义：“明年”指将来，与“换了”表示的已完成动作矛盾。", "下个月": "语义：“下个月”指将来，与“换了”表示的已完成动作矛盾。", "将来": "搭配：“将来”通常与“会”“要”搭配，不与表示已完成的“了”搭配。"}, "sentence_index": 0, "correct_answer": "前年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们前年刚认识，今天就约好一起去看电影了。", "explanation": "这里应该用〈前天〉。“前年”是两年前，与“刚认识”和“今天就约好”的近期情况矛盾。"}, {"text": "我们前年就要出发去北京了，行李都收拾好了。", "explanation": "这里应该用〈明天〉。“前年”指过去，不能与“就要出发”的将来计划搭配。"}, {"text": "前年春天我们才搬进新家，到现在还不到半年。", "explanation": "这里应该用〈今年〉。“前年”是两年前，与“到现在还不到半年”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86347, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前年", "is_correct": true, "explanation": "正确：“前年这里还是一片田地，现在盖起了楼”说的是过去的变化，“前年”最合适。"}, {"text": "现在", "is_correct": false, "explanation": "语义：“现在”与后文“现在盖起了楼”重复，无法形成“以前是田地、现在有楼”的对比。"}, {"text": "刚才", "is_correct": false, "explanation": "语义：“刚才”指很短的时间，无法说明这里从田地变成楼房的长期变化。"}, {"text": "一年", "is_correct": false, "explanation": "搭配：“一年”是时段，不能直接作时间状语，需要说“一年前”。"}], "explanations": {"前年": "正确：“前年这里还是一片田地，现在盖起了楼”说的是过去的变化，“前年”最合适。", "现在": "语义：“现在”与后文“现在盖起了楼”重复，无法形成“以前是田地、现在有楼”的对比。", "刚才": "语义：“刚才”指很短的时间，无法说明这里从田地变成楼房的长期变化。", "一年": "搭配：“一年”是时段，不能直接作时间状语，需要说“一年前”。"}, "sentence_index": 6, "correct_answer": "前年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店是前年开的，到现在才开了三天。", "explanation": "这里应该用〈前天〉。“前年”是两年前，与“到现在才开了三天”矛盾。"}, {"text": "气象台说，前年一定会下大雨。", "explanation": "这里应该用〈这个星期天〉。“前年”指过去，不能用来预测将要发生的天气。"}, {"text": "前年刚下过雪，今天路上还有冰。", "explanation": "这里应该用〈昨天〉。“前年”是两年前，与“今天路上还有冰”的近期情况矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86347, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一前年大学毕业了。", "corrected_sentence": "他前年大学毕业了。", "error_description": "错误形式：「一前年」；正确形式：「前年」。数量词「一」不能直接加在时间词「前年」前面，应说「他前年大学毕业了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86347, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事是前年了才发生的。", "corrected_sentence": "这件事是前年才发生的。", "error_description": "“了”位置错误：“了”不能加在时间词“前年”后面，应说“这件事是前年才发生的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
