INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86348, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "去年的前一年。", "primary_collocate": null, "pronunciation": "qián nián", "ipa": "tɕʰjɛn˧˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我前年去过北京。", "target_word": "前年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前年夏天，我们搬到了上海。", "target_word": "前年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他前年结婚，去年有了孩子。", "target_word": "前年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前年我还在上大学，现在已经工作了。", "target_word": "前年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前年冬天特别冷，下了很多雪。", "target_word": "前年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店是前年开的，到今年已经两年了。", "target_word": "前年", "complexity_tier": "T3", "furigana": "zhè jiā diàn shì qián nián kāi de, dào jīn nián yǐ jīng liǎng nián le.", "sentence_source": "generated"}, {"text": "我前年买的手机，现在还能用。", "target_word": "前年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前年的今天，我第一次见到她。", "target_word": "前年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年没有回家，前年也没有回。", "target_word": "前年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶前年生了一场病，现在好多了。", "target_word": "前年", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "前年：去年的前一年，表示时间的名词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd9494de-5348-4735-8c04-847b659ff0a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86348, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前年", "is_correct": true, "explanation": "正确：“我前年去过北京”说的是两年前的经历，与“去过”的已完成意思相符。"}, {"text": "明年", "is_correct": false, "explanation": "语义：“明年”指将来，与“去过”表示的已发生经历矛盾。"}, {"text": "将来", "is_correct": false, "explanation": "搭配：“将来”通常与“要”“会”搭配，不与“去过”这种已完成的经历搭配。"}, {"text": "后年", "is_correct": false, "explanation": "语义：“后年”指两年后，是将来的时间，与“去过”的已发生经历矛盾。"}], "explanations": {"前年": "正确：“我前年去过北京”说的是两年前的经历，与“去过”的已完成意思相符。", "明年": "语义：“明年”指将来，与“去过”表示的已发生经历矛盾。", "将来": "搭配：“将来”通常与“要”“会”搭配，不与“去过”这种已完成的经历搭配。", "后年": "语义：“后年”指两年后，是将来的时间，与“去过”的已发生经历矛盾。"}, "sentence_index": 0, "correct_answer": "前年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们前年夏天一定会在北京见面。", "explanation": "这里应该用〈明年〉。“前年”指过去，不能与表示将来的“一定会”搭配。"}, {"text": "我前年刚见到他，他还在办公室里。", "explanation": "这里应该用〈刚才〉。“前年”指两年前，不能与“刚”搭配表示刚发生的事。"}, {"text": "我弟弟前年一定会考上大学。", "explanation": "这里应该用〈后年〉。“前年”指过去，不能与表示将来的“一定会”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86348, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前年", "is_correct": true, "explanation": "正确：“我前年买的手机，现在还能用”说的是过去买的东西，“前年”最合适。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来，与“现在还能用”说明手机早已买好的情况矛盾。"}, {"text": "下个月", "is_correct": false, "explanation": "语义：“下个月”指将来，与“买的”已发生以及“现在还能用”矛盾。"}, {"text": "一年", "is_correct": false, "explanation": "搭配：“一年”是时段，修饰“买的”时要说“一年前”，不能直接用。"}], "explanations": {"前年": "正确：“我前年买的手机，现在还能用”说的是过去买的东西，“前年”最合适。", "明天": "语义：“明天”指将来，与“现在还能用”说明手机早已买好的情况矛盾。", "下个月": "语义：“下个月”指将来，与“买的”已发生以及“现在还能用”矛盾。", "一年": "搭配：“一年”是时段，修饰“买的”时要说“一年前”，不能直接用。"}, "sentence_index": 6, "correct_answer": "前年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们是前年认识的，到现在才三天。", "explanation": "这里应该用〈前天〉。“前年”是两年前，与“到现在才三天”矛盾。"}, {"text": "天气预报说，前年会下雨。", "explanation": "这里应该用〈明天〉。“前年”指过去，不能用来预报将要发生的天气。"}, {"text": "前年的比赛一定会很精彩。", "explanation": "这里应该用〈下周〉。“前年”指过去，不能与表示预测的“一定会”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86348, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我前年的去过上海。", "corrected_sentence": "我前年去过上海。", "error_description": "“的”多余：时间词“前年”后面直接接动词，不能加“的”，应说“我前年去过上海”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
