INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86349, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "“我国”是说我们自己的国家。", "primary_collocate": null, "pronunciation": "wǒ guó", "ipa": "wɔ˨˩ kwɔ˧˥", "syllable_count": 2, "sentences": [{"text": "我国的人口很多。", "target_word": "我国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我国的北方冬天很冷。", "target_word": "我国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我国有很多好吃的菜。", "target_word": "我国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我国的高铁又快又方便。", "target_word": "我国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我国的首都是北京。", "target_word": "我国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，我国有五千年的历史。", "target_word": "我国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我国的茶叶卖到很多国家。", "target_word": "我国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我国南方的夏天又热又湿。", "target_word": "我国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我国的大城市都有地铁。", "target_word": "我国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我国的孩子从小学习汉字。", "target_word": "我国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "我们自己的国家，书面语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f13c54b2-bfd1-40d4-9d74-4f23a080aae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86349, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "我国", "is_correct": true, "explanation": "正确：“我国”指说话人自己的国家，填入后句意通顺。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是供人观赏的场所，没有人口，不能说“花园的人口”。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，不能说“汽车的人口”。"}, {"text": "公司", "is_correct": false, "explanation": "搭配：“人口”指地区的居民数量，一般不说公司的人口。"}], "explanations": {"我国": "正确：“我国”指说话人自己的国家，填入后句意通顺。", "花园": "语义：花园是供人观赏的场所，没有人口，不能说“花园的人口”。", "汽车": "语义：汽车是交通工具，不能说“汽车的人口”。", "公司": "搭配：“人口”指地区的居民数量，一般不说公司的人口。"}, "sentence_index": 0, "correct_answer": "我国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我国和你一起去吧。", "explanation": "这里应该用〈我们〉。“我国”指国家，不能代替“我们”来指一起行动的人。"}, {"text": "我国的妈妈做饭很好吃。", "explanation": "这里应该用〈我的〉。“我国”只指国家，不能用来修饰自己的家人。"}, {"text": "我国一起去吧。", "explanation": "这里应该用〈大家〉。“我国”指国家，不能作为一起去的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86349, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "我国", "is_correct": true, "explanation": "正确：“我国”指说话人自己的国家，与“卖到很多国家”的语境相符。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不是出产茶叶的地方，不能说“小猫的茶叶”。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是学习用品，不是茶叶的产地，句意不通。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“卖到”需要产地或商家作主语，电脑不能作茶叶的产地。"}], "explanations": {"我国": "正确：“我国”指说话人自己的国家，与“卖到很多国家”的语境相符。", "小猫": "语义：小猫不是出产茶叶的地方，不能说“小猫的茶叶”。", "书包": "语义：书包是学习用品，不是茶叶的产地，句意不通。", "电脑": "搭配：“卖到”需要产地或商家作主语，电脑不能作茶叶的产地。"}, "sentence_index": 6, "correct_answer": "我国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我国是学生。", "explanation": "这里应该用〈我们〉。“我国”指国家，不能用来指人。"}, {"text": "我国自己做饭吃。", "explanation": "这里应该用〈我自己〉。“我国”指国家，不能作做饭的人。"}, {"text": "我国的爸爸很忙。", "explanation": "这里应该用〈我的〉。“我国”只指国家，不能用来修饰自己的家人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86349, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我国们要保护环境。", "corrected_sentence": "我国人民要保护环境。", "error_description": "错误：“们”只能加在指人的名词或代词后，不能加在指国家的“我国”后面。应说“我国人民”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86349, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我国得茶叶出口到很多国家。", "corrected_sentence": "我国的茶叶出口到很多国家。", "error_description": "错误：修饰名词“茶叶”时应用结构助词“的”，这里误写成“得”。“得”用在动词或形容词后作补语，不能放在“我国”和“茶叶”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
