INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86350, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "名词，指说话人所在的国家。", "primary_collocate": null, "pronunciation": "wǒ guó", "ipa": "wɔ˨˩ kwɔ˧˥", "syllable_count": 2, "sentences": [{"text": "他是中国人，他说：“我国很大。”", "target_word": "我国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统说，我国欢迎各国朋友。", "target_word": "我国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上说，我国今年的天气很好。", "target_word": "我国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我国的节日很多，春节最热闹。", "target_word": "我国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻里说，我国的经济发展得很快。", "target_word": "我国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你介绍一下我国的文化。", "target_word": "我国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我国，人们见面常常握手。", "target_word": "我国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人一直很关心我国的发展。", "target_word": "我国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我国的足球队明天有比赛。", "target_word": "我国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在国外工作，常常想起我国的春节。", "target_word": "我国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "说话人所在的国家，书面语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f13c54b2-bfd1-40d4-9d74-4f23a080aae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86350, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "我国", "is_correct": true, "explanation": "正确：“我国”指说话人所在的国家，与“他是中国人”相符。"}, {"text": "今天", "is_correct": false, "explanation": "语义：今天是时间词，不能说“很大”。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天是季节，不能说“很大”。"}, {"text": "年份", "is_correct": false, "explanation": "搭配：“大”不修饰年份，一般不说“年份很大”。"}], "explanations": {"我国": "正确：“我国”指说话人所在的国家，与“他是中国人”相符。", "今天": "语义：今天是时间词，不能说“很大”。", "春天": "语义：春天是季节，不能说“很大”。", "年份": "搭配：“大”不修饰年份，一般不说“年份很大”。"}, "sentence_index": 0, "correct_answer": "我国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我国和你们一起去吧。", "explanation": "这里应该用〈我们〉。“我国”指国家，不能代替“我们”来指一起行动的人。"}, {"text": "我国的爸爸最喜欢钓鱼。", "explanation": "这里应该用〈我的〉。“我国”只指国家，不能用来修饰自己的家人。"}, {"text": "我国有三口人。", "explanation": "这里应该用〈我家〉。“我国”指国家，不能用来说家里有几口人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86350, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "我国", "is_correct": true, "explanation": "正确：“我国”指说话人所在的国家，作“在……”的处所，符合句意。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是人们见面的场所，句意不通。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不能作人们见面的处所。"}, {"text": "小猫", "is_correct": false, "explanation": "搭配：“在”后接处所名词，小猫不是处所，不能作见面的地点。"}], "explanations": {"我国": "正确：“我国”指说话人所在的国家，作“在……”的处所，符合句意。", "书包": "语义：书包不是人们见面的场所，句意不通。", "电脑": "语义：电脑不能作人们见面的处所。", "小猫": "搭配：“在”后接处所名词，小猫不是处所，不能作见面的地点。"}, "sentence_index": 6, "correct_answer": "我国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我国早上就去上班。", "explanation": "这里应该用〈他〉。“我国”指国家，不能去上班，指人要用“他”。"}, {"text": "我国自己去超市买菜。", "explanation": "这里应该用〈我自己〉。“我国”指国家，不能自己去买菜。"}, {"text": "我国在图书馆学习。", "explanation": "这里应该用〈你们〉。“我国”指国家，不能去图书馆学习，指人要用“你们”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86350, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我国们很爱吃米饭。", "corrected_sentence": "我国人民很爱吃米饭。", "error_description": "错误：“们”只能加在指人的名词或代词后，不能加在指国家的“我国”后面。应说“我国人民”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86350, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天都很关心我国地发展。", "corrected_sentence": "他每天都很关心我国的发展。", "error_description": "错误：“地”用在形容词或副词后作状语，这里修饰名词“发展”，应用结构助词“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
