INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86351, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "刚才是一小会儿以前。", "primary_collocate": null, "pronunciation": "gāng cái", "ipa": "kɑŋ˥ tsʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "刚才有人给你打电话。", "target_word": "刚才", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我刚才在厨房做饭，没听见。", "target_word": "刚才", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚才还下着雨，现在出太阳了。", "target_word": "刚才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你刚才说什么？我没听清。", "target_word": "刚才", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚才的话，请你再说一遍。", "target_word": "刚才", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师刚才进来了，大家快坐好。", "target_word": "刚才", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚才我看见小王往学校走了。", "target_word": "刚才", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对不起，刚才我说错话了。", "target_word": "刚才", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚才吃的蛋糕很好吃。", "target_word": "刚才", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他刚才还在这儿，现在不知道去哪儿了。", "target_word": "刚才", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "刚才：说话之前的一小会儿，指刚刚过去的时刻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd9494de-5348-4735-8c04-847b659ff0a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86351, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刚才", "is_correct": true, "explanation": "正确：「刚才」指刚过去不久的时间，与“有人给你打电话”的语境相符。"}, {"text": "以后", "is_correct": false, "explanation": "语义：「以后」指将来，与这里已经发生的来电不符。"}, {"text": "明年", "is_correct": false, "explanation": "语义：「明年」指将来的一年，与这里已经发生的来电不符。"}, {"text": "从前", "is_correct": false, "explanation": "语义：「从前」指很久以前，不能用来说刚发生的一个电话。"}], "explanations": {"刚才": "正确：「刚才」指刚过去不久的时间，与“有人给你打电话”的语境相符。", "以后": "语义：「以后」指将来，与这里已经发生的来电不符。", "明年": "语义：「明年」指将来的一年，与这里已经发生的来电不符。", "从前": "语义：「从前」指很久以前，不能用来说刚发生的一个电话。"}, "sentence_index": 0, "correct_answer": "刚才"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我刚才在北京工作了十年。", "explanation": "这里应该用〈以前〉。「刚才」指刚过去不久的时间，不能用来说十年的工作经历。"}, {"text": "我们明天刚才出发。", "explanation": "这里应该用〈马上〉。「刚才」指刚过去不久的时间，不能用于明天这样的将来；说将来很快要发生的事，要用「马上」。"}, {"text": "他刚才十八岁。", "explanation": "这里应该用〈刚满〉。「刚满」表示年龄刚到某一岁，「刚才」只指时间，不能用来说明岁数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86351, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刚才", "is_correct": true, "explanation": "正确：「刚才」指刚过去不久，与“看见小王往学校走了”的已完成动作相符。"}, {"text": "将来", "is_correct": false, "explanation": "体貌：「将来」指以后的时间，与句中已完成的“看见”和“走了”不符。"}, {"text": "每天", "is_correct": false, "explanation": "语义：「每天」表示经常重复，与这一次看见的具体经过不符。"}, {"text": "明早", "is_correct": false, "explanation": "体貌：「明早」指明天早上，与句中已完成的“走了”不符。"}], "explanations": {"刚才": "正确：「刚才」指刚过去不久，与“看见小王往学校走了”的已完成动作相符。", "将来": "体貌：「将来」指以后的时间，与句中已完成的“看见”和“走了”不符。", "每天": "语义：「每天」表示经常重复，与这一次看见的具体经过不符。", "明早": "体貌：「明早」指明天早上，与句中已完成的“走了”不符。"}, "sentence_index": 6, "correct_answer": "刚才"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我刚才每天都喝茶。", "explanation": "这里应该用〈平时〉。「刚才」只指刚过去的一小段时间，不能表示经常性的习惯。"}, {"text": "我昨天刚才知道这件事。", "explanation": "这里应该用〈才〉。「才」表示事情发生得比预期晚，「刚才」只指刚过去不久，不能用来说较早的某一天。"}, {"text": "刚才这里是一片海。", "explanation": "这里应该用〈从前〉。「刚才」指刚过去不久，不能用来说很久以前的地理面貌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86351, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他刚才的走了。", "corrected_sentence": "他刚才走了。", "error_description": "「的」多余：「刚才的」只能修饰后面的名词（如「刚才的话」），这里「的」后面接的是动词「走」，结构不通；应说「他刚才走了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86351, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我刚才还刚才在厨房。", "corrected_sentence": "我刚才还在厨房。", "error_description": "重复错误：「刚才」只需说一次，应说「我刚才还在厨房」，不能重复「刚才」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
