INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86352, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "刚过去不久的时间。", "primary_collocate": null, "pronunciation": "gāng cái", "ipa": "kɑŋ˥ tsʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "刚才的电影真好看。", "target_word": "刚才", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "刚才妈妈来过电话。", "target_word": "刚才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把刚才的作业写完了。", "target_word": "刚才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚才路上很堵，所以我来晚了。", "target_word": "刚才", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚才那个人是谁？", "target_word": "刚才", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "刚才天还很蓝，现在全是云。", "target_word": "刚才", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理刚才开完会，正在休息。", "target_word": "刚才", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚才你不在，有一位客人找你。", "target_word": "刚才", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚才发生的事，我都记得。", "target_word": "刚才", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他刚才跑得太快，现在很累。", "target_word": "刚才", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "刚才：刚过去不久的时间，可作定语或主语前的时间词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd9494de-5348-4735-8c04-847b659ff0a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86352, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刚才", "is_correct": true, "explanation": "正确：「刚才」指刚过去不久的时间，可以作定语修饰「电影」。"}, {"text": "明年", "is_correct": false, "explanation": "语义：「明年」指将来的时间，电影还没看，不能评价“真好看”。"}, {"text": "将来", "is_correct": false, "explanation": "语义：「将来」指还没发生的时间，不能评价已经看过的电影“真好看”。"}, {"text": "未来", "is_correct": false, "explanation": "语义：「未来」指以后的时间，与对已有作品“真好看”的评价不符。"}], "explanations": {"刚才": "正确：「刚才」指刚过去不久的时间，可以作定语修饰「电影」。", "明年": "语义：「明年」指将来的时间，电影还没看，不能评价“真好看”。", "将来": "语义：「将来」指还没发生的时间，不能评价已经看过的电影“真好看”。", "未来": "语义：「未来」指以后的时间，与对已有作品“真好看”的评价不符。"}, "sentence_index": 0, "correct_answer": "刚才"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我刚才在这个城市住了三十年。", "explanation": "这里应该用〈以前〉。「刚才」指刚过去不久，不能用来说三十年的经历。"}, {"text": "我明天刚才去医院。", "explanation": "这里应删去「刚才」，直接说「明天去医院」。「刚才」只指刚过去不久的时间，不能用于明天这样的将来时间。"}, {"text": "刚才他每天早上跑步。", "explanation": "这里应该用〈平时〉。「刚才」只指刚过去的一小段时间，不能表示每天重复的习惯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86352, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刚才", "is_correct": true, "explanation": "正确：「刚才」指刚过去不久，与句中“开完会”的完成和“正在休息”的状态相符。"}, {"text": "明天", "is_correct": false, "explanation": "体貌：「明天」指将来，与“正在休息”表示的现在状态不符。"}, {"text": "马上", "is_correct": false, "explanation": "体貌：「马上」指即将发生，与已经完成的“开完会”和现在的“正在休息”相冲突。"}, {"text": "当年", "is_correct": false, "explanation": "体貌：「当年」指过去的某一年，不能和表示现在进行的「正在」搭配。"}], "explanations": {"刚才": "正确：「刚才」指刚过去不久，与句中“开完会”的完成和“正在休息”的状态相符。", "明天": "体貌：「明天」指将来，与“正在休息”表示的现在状态不符。", "马上": "体貌：「马上」指即将发生，与已经完成的“开完会”和现在的“正在休息”相冲突。", "当年": "体貌：「当年」指过去的某一年，不能和表示现在进行的「正在」搭配。"}, "sentence_index": 6, "correct_answer": "刚才"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天刚才去了医院。", "explanation": "这里应删去「刚才」，直接说「我昨天去了医院」。「刚才」只指刚过去不久的时间，不能和「昨天」这样较早的时间连用。"}, {"text": "他刚才十八岁。", "explanation": "这里应该用〈刚满〉。「刚满」表示年龄刚到某一岁，「刚才」只指时间，不能用来说明岁数。"}, {"text": "从前这座城市还是个小渔村，刚才也是。", "explanation": "这里的「刚才」指很久以前的情况，应该用表示久远时间的说法（如“很久以前”）。「刚才」只指刚过去不久，不能用来描述很久之前的面貌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86352, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我刚才的到家了。", "corrected_sentence": "我刚才到家了。", "error_description": "错误形式：「我刚才的到家了」；正确形式：「我刚才到家了」。「刚才的」只能修饰后面的名词（如「刚才的电影」），「的」后面不能直接接动词「到家」，应去掉「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86352, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚才跑很快，我没追上。", "corrected_sentence": "他刚才跑得很快，我没追上。", "error_description": "错误形式：「他刚才跑很快」；正确形式：「他刚才跑得很快」。「跑很快」表示程度的补语前必须加补语标记「得」，漏掉「得」不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
