INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86353, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“每个”是说一个一个都有，没有哪个少了。", "primary_collocate": null, "pronunciation": "měi gè", "ipa": "meɪ˨˩ kɤ˥˩", "syllable_count": 2, "sentences": [{"text": "每个人都有自己的爱好。", "target_word": "每个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里每个同学都有一本书。", "target_word": "每个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个孩子都收到了一份礼物。", "target_word": "每个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给每个学生发了一张卡片。", "target_word": "每个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店每个房间都很干净。", "target_word": "每个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们每个人都要带水。", "target_word": "每个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里每个菜都很好吃。", "target_word": "每个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个国家都有自己的节日。", "target_word": "每个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给每个朋友写了一封信。", "target_word": "每个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家每个人都会做饭。", "target_word": "每个", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "每一个", "label": "复合"}], "register": "中性", "sense_fingerprint": "每个：逐个都有，一个不少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b16ac64-fa49-4be4-b4f1-b3825b46d122') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86353, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "每个", "is_correct": true, "explanation": "正确：“每个”指全体中逐一都有，与句中的“都”呼应，句意通顺。"}, {"text": "某个", "is_correct": false, "explanation": "语义：“某个”指特定的某一个，与“都”表示全体的意思相矛盾。"}, {"text": "有些", "is_correct": false, "explanation": "语义：“有些”表示部分，与“都有自己的爱好”的全体意义相矛盾。"}, {"text": "这个", "is_correct": false, "explanation": "搭配：“这个”指定某一个人，不能与“人都有自己的爱好”搭配，句意不通。"}], "explanations": {"每个": "正确：“每个”指全体中逐一都有，与句中的“都”呼应，句意通顺。", "某个": "语义：“某个”指特定的某一个，与“都”表示全体的意思相矛盾。", "有些": "语义：“有些”表示部分，与“都有自己的爱好”的全体意义相矛盾。", "这个": "搭配：“这个”指定某一个人，不能与“人都有自己的爱好”搭配，句意不通。"}, "sentence_index": 0, "correct_answer": "每个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了每个苹果。", "explanation": "这里应该用〈一个〉。“每个”表示全体中逐一都有，不用来说买了一个苹果这样的具体数量。"}, {"text": "我是每个学生。", "explanation": "这里应该用〈一名〉。“每个”指全体中的逐一，不能用来说明某人的身份。"}, {"text": "有每个同学没来。", "explanation": "这里应该用〈一些〉。“有……没来”说的是部分人没来；“每个”指全体，与之冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86353, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每个", "is_correct": true, "explanation": "正确：“每个”指全体中的每一个，与“都”呼应，符合“这里……菜都很好吃”的句意。"}, {"text": "某些", "is_correct": false, "explanation": "语义：“某些”表示部分，与“都很好吃”所表示的全体意义相矛盾。"}, {"text": "有的", "is_correct": false, "explanation": "语义：“有的”表示部分，与“菜都很好吃”的全体意义相矛盾。"}, {"text": "一个", "is_correct": false, "explanation": "搭配：“一个”与“都”在肯定句中不能连用，“这里一个菜都很好吃”不成立，句意不通。"}], "explanations": {"每个": "正确：“每个”指全体中的每一个，与“都”呼应，符合“这里……菜都很好吃”的句意。", "某些": "语义：“某些”表示部分，与“都很好吃”所表示的全体意义相矛盾。", "有的": "语义：“有的”表示部分，与“菜都很好吃”的全体意义相矛盾。", "一个": "搭配：“一个”与“都”在肯定句中不能连用，“这里一个菜都很好吃”不成立，句意不通。"}, "sentence_index": 6, "correct_answer": "每个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们家来了每个客人。", "explanation": "这里应该用〈一位〉。“每个”表示全体中的逐一，不能用来说来了一位客人这样的具体数量。"}, {"text": "有每个人不吃辣。", "explanation": "这里应该用〈有的〉。“有的人”表示部分，“每个人”表示全体，与“不吃辣”的部分意义冲突。"}, {"text": "只有每个同学没交作业。", "explanation": "这里应该用〈少数〉。“少数”指数量不多的一部分；“每个”指全体，与“只有……没交作业”的限定意思冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86353, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每个个学生都要交作业。", "corrected_sentence": "每个学生都要交作业。", "error_description": "错误：“每个”的量词“个”被重复，写成“每个个学生”。“个”只能用一次，应说“每个学生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86353, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每个人们都要遵守规则。", "corrected_sentence": "每个人都要遵守规则。", "error_description": "错误：“每个”后面的名词“人”加了复数词尾“们”。“每个”与“们”不能同用，应说“每个人”，不能说“每个人们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
