INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86355, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "名单是写着很多人名字的纸。", "primary_collocate": null, "pronunciation": "míng dān", "ipa": "mɪŋ˧˥ tan˥", "syllable_count": 2, "sentences": [{"text": "老师把名单贴在门口了。", "target_word": "名单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的名字在名单上。", "target_word": "名单", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你看一下这张名单。", "target_word": "名单", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他手里拿着一份名单。", "target_word": "名单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "名单上有二十个学生的名字。", "target_word": "名单", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理让我打印比赛名单。", "target_word": "名单", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "名单上没有我的名字。", "target_word": "名单", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她把参加的人写成名单交给了老师。", "target_word": "名单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛名单明天早上公布。", "target_word": "名单", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请按名单上的顺序进去。", "target_word": "名单", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "份", "label": "量词"}, {"form": "黑名单", "label": "复合"}, {"form": "名單", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名单：写着很多人名字的纸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da3fe4f3-6505-4386-9195-0de57bfd5131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86355, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "名单", "is_correct": true, "explanation": "名单是写着人名的纸，可以贴在门口，符合句意。"}, {"text": "花瓶", "is_correct": false, "explanation": "搭配：“贴”用于纸张、海报这类薄的平面物，花瓶是立体的器皿，不能贴在门口。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“贴”要求能粘附的薄物，石头不能这样贴在门口。"}, {"text": "月光", "is_correct": false, "explanation": "语义：月光是光线，看不见也摸不着，不能贴在门口。"}], "explanations": {"名单": "名单是写着人名的纸，可以贴在门口，符合句意。", "花瓶": "搭配：“贴”用于纸张、海报这类薄的平面物，花瓶是立体的器皿，不能贴在门口。", "石头": "搭配：“贴”要求能粘附的薄物，石头不能这样贴在门口。", "月光": "语义：月光是光线，看不见也摸不着，不能贴在门口。"}, "sentence_index": 0, "correct_answer": "名单"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服是名单，很贵。", "explanation": "这里应该用〈名牌〉。名牌指有名的牌子，名单是写着人名的纸，不能用来说衣服是名牌。"}, {"text": "这位明星很有名单。", "explanation": "这里应该用〈名气〉。“很有名气”指知名度，名单是写着人名的纸，不能表示知名度。"}, {"text": "老师在桌上放了一只名单。", "explanation": "这里应该用〈张〉。名单是纸，用“张”计量；“只”多用于动物或成对物品中的一个，不用于纸张。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86355, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名单", "is_correct": true, "explanation": "名单是写着人名的纸，“名单上”指名字所在的纸，符合句意。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音看不见、摸不着，不能承载名字，“声音上没有我的名字”说不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“上”前面的处所要能承载文字，空气不能作为写字的平面。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨是降水，不能承载名字，“雨上没有我的名字”说不通。"}], "explanations": {"名单": "名单是写着人名的纸，“名单上”指名字所在的纸，符合句意。", "声音": "语义：声音看不见、摸不着，不能承载名字，“声音上没有我的名字”说不通。", "空气": "搭配：“上”前面的处所要能承载文字，空气不能作为写字的平面。", "雨": "语义：雨是降水，不能承载名字，“雨上没有我的名字”说不通。"}, "sentence_index": 6, "correct_answer": "名单"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在学校的名单很好。", "explanation": "这里应该用〈名声〉。名声指别人对一个人的评价；名单是写着人名的纸，不能用来评价一个人的好坏。"}, {"text": "他打着老师的名单去骗钱。", "explanation": "这里应该用〈名义〉。“打着……的名义”表示借某人的身份作幌子，名单不能充当身份。"}, {"text": "这首歌的名单很好听。", "explanation": "这里应该用〈名字〉。歌的名字指歌名，名单是列着很多人名字的纸，不能指歌曲的名称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86355, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "张老师的名字名单上，我很高兴。", "corrected_sentence": "张老师的名字在名单上，我很高兴。", "error_description": "“名单上”前面缺了介词“在”。正确的是“名字在名单上”，表示名字位于名单之中；去掉“在”后，“名字名单上”不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86355, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班长手里拿着一只名单，走进了教室。", "corrected_sentence": "班长手里拿着一张名单，走进了教室。", "error_description": "量词错误：名单是纸，应该用“张”计量，不能用“只”。“只”多用于动物或成对物品中的一个。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
