INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86356, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "写有人名的单子。", "primary_collocate": null, "pronunciation": "míng dān", "ipa": "mɪŋ˧˥ tan˥", "syllable_count": 2, "sentences": [{"text": "这份名单是谁写的？", "target_word": "名单", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "名单已经发给大家了。", "target_word": "名单", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师照着名单叫同学的名字。", "target_word": "名单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把名单放在桌子上了。", "target_word": "名单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张名单有两页。", "target_word": "名单", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请先看看名单，再选人。", "target_word": "名单", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她在名单上画了一个圈。", "target_word": "名单", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司给了我一份客人名单。", "target_word": "名单", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "名单丢了，我们要重新写。", "target_word": "名单", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他念着名单，一个一个点名。", "target_word": "名单", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "份", "label": "量词"}, {"form": "黑名单", "label": "复合"}, {"form": "名單", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名单：写有人名的单子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da3fe4f3-6505-4386-9195-0de57bfd5131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86356, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "名单", "is_correct": true, "explanation": "名单是写有人名的单子，可以由人写，符合句意。"}, {"text": "午餐", "is_correct": false, "explanation": "语义：午餐是食物，不能被人写，“是谁写的”说不通。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光是光线，看不见也摸不着，不能被写，“是谁写的”说不通。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶是饮料，不是能被书写的东西。"}], "explanations": {"名单": "名单是写有人名的单子，可以由人写，符合句意。", "午餐": "语义：午餐是食物，不能被人写，“是谁写的”说不通。", "阳光": "语义：阳光是光线，看不见也摸不着，不能被写，“是谁写的”说不通。", "牛奶": "语义：牛奶是饮料，不是能被书写的东西。"}, "sentence_index": 0, "correct_answer": "名单"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在班里的名单很好。", "explanation": "这里应该用〈名声〉。名声指别人对一个人的评价；名单是写有人名的单子，不能用来评价人的好坏。"}, {"text": "这双鞋是名单的，很贵。", "explanation": "这里应该用〈名牌〉。名牌指有名的品牌，名单是写着人名的纸，不能用来说鞋子是名牌。"}, {"text": "服务员，请给我看看名单，我要点菜。", "explanation": "这里应该用〈菜单〉。点菜要看写着菜名和价钱的菜单；名单是写有人名的单子，不能用来点菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86356, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名单", "is_correct": true, "explanation": "名单是写有人名的单子，可以在上面画圈，符合句意。"}, {"text": "香味", "is_correct": false, "explanation": "语义：香味看不见、摸不着，不能被画上圈，“在香味上画圈”说不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音看不见、摸不着，不能被画上圈。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：心情不是可以画圈的平面，“画”与“心情”搭配不当。"}], "explanations": {"名单": "名单是写有人名的单子，可以在上面画圈，符合句意。", "香味": "语义：香味看不见、摸不着，不能被画上圈，“在香味上画圈”说不通。", "声音": "语义：声音看不见、摸不着，不能被画上圈。", "心情": "搭配：心情不是可以画圈的平面，“画”与“心情”搭配不当。"}, "sentence_index": 6, "correct_answer": "名单"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位歌手很有名单。", "explanation": "这里应该用〈名气〉。“有名气”指知名度，名单不能表示知名度。"}, {"text": "他打着班长的名单去借钱。", "explanation": "这里应该用〈名义〉。“打着……的名义”表示借某人的身份作幌子，名单不能充当身份。"}, {"text": "他的名单叫李明。", "explanation": "这里应该用〈名字〉。名字指人的称呼，名单是写着很多人名字的纸，不能用来指一个人的称呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86356, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学生的名字都写这张名单上。", "corrected_sentence": "学生的名字都写在这张名单上。", "error_description": "“写……上”结构缺了介词“在”。应为“写在这张名单上”，表示把名字写到名单上；“写这张名单上”不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86356, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师翻开一只名单，开始点名。", "corrected_sentence": "老师翻开一张名单，开始点名。", "error_description": "量词错误：名单是纸，应该用“张”计量，“只”不能用于纸张。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
