INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86359, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地震是大地突然摇晃起来。", "primary_collocate": null, "pronunciation": "dì zhèn", "ipa": "ti˥˩ ʈʂən˥˩", "syllable_count": 2, "sentences": [{"text": "昨天夜里地震了，我们都跑到楼下。", "target_word": "地震", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震的时候，不要坐电梯。", "target_word": "地震", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "房子突然摇起来，我知道是地震了。", "target_word": "地震", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震时，桌子和椅子都在动。", "target_word": "地震", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，发生地震时要先躲到桌子下面。", "target_word": "地震", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在十楼，觉得地震的时候楼晃得很厉害。", "target_word": "地震", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震来了！大家快跑出教室！", "target_word": "地震", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "半夜里，大地突然晃了一下，是不是地震？", "target_word": "地震", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天的地震很小，我只觉得椅子轻轻晃了一下。", "target_word": "地震", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里常常地震，晚上床会摇起来。", "target_word": "地震", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场地震", "label": "量词"}, {"form": "一次地震", "label": "量词"}, {"form": "地震带", "label": "复合"}], "register": "中性", "sense_fingerprint": "地震：人亲身感到大地突然摇晃", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eb6a069-3cc9-4bff-bb63-1f24166f25c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86359, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地震", "is_correct": true, "explanation": "正确：「地震」表示大地突然摇晃，与“跑到楼下”的反应相符。"}, {"text": "睡着", "is_correct": false, "explanation": "语义：睡着的人不会跑到楼下，与“我们都跑到楼下”矛盾。"}, {"text": "写字", "is_correct": false, "explanation": "语义：写字不会让大家都跑到楼下，与语境不符。"}, {"text": "做梦", "is_correct": false, "explanation": "语义：做梦不会让人跑到楼下，与“我们都跑到楼下”矛盾。"}], "explanations": {"地震": "正确：「地震」表示大地突然摇晃，与“跑到楼下”的反应相符。", "睡着": "语义：睡着的人不会跑到楼下，与“我们都跑到楼下”矛盾。", "写字": "语义：写字不会让大家都跑到楼下，与语境不符。", "做梦": "语义：做梦不会让人跑到楼下，与“我们都跑到楼下”矛盾。"}, "sentence_index": 0, "correct_answer": "地震"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的手机在口袋里地震了一下。", "explanation": "这里应该用〈震动〉。地震指大地突然摇晃，手机的振动要用〈震动〉，不能用地震。"}, {"text": "地震内部的岩石很坚硬，不容易断裂。", "explanation": "这里应该用〈地壳〉。地震指大地突然摇晃，不能指岩石所在的地层；地层要用〈地壳〉。"}, {"text": "地震刮得窗户咯咯响，我吓得不敢动。", "explanation": "这里应该用〈大风〉。地震是大地摇晃，不会刮风；刮得窗户咯咯响的是大风，应该用〈大风〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f0c2dc0-701e-4d12-98e2-361ee568df0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86359, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地震", "is_correct": true, "explanation": "正确：「地震」表示大地突然摇晃，与“快跑出教室”的反应相符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试来了”不会让人马上跑出教室，与语境矛盾。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：“饭菜来了”不需要大家快跑出教室，与语境矛盾。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业来了”不会促使大家快跑出教室，与语境矛盾。"}], "explanations": {"地震": "正确：「地震」表示大地突然摇晃，与“快跑出教室”的反应相符。", "考试": "语义：“考试来了”不会让人马上跑出教室，与语境矛盾。", "饭菜": "语义：“饭菜来了”不需要大家快跑出教室，与语境矛盾。", "作业": "语义：“作业来了”不会促使大家快跑出教室，与语境矛盾。"}, "sentence_index": 6, "correct_answer": "地震"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地震拍打着礁石，发出巨大的声音。", "explanation": "这里应该用〈海浪〉。地震是大地的摇晃，不会拍打礁石；拍打礁石的是海浪，应该用〈海浪〉。"}, {"text": "地震击中了一棵大树。", "explanation": "这里应该用〈雷电〉。地震是大地摇晃，不能击中树木；击中大树的是雷电，应该用〈雷电〉。"}, {"text": "今天的地震突然下降了十度。", "explanation": "这里应该用〈气温〉。地震指大地突然摇晃，不能用来描述温度的变化；温度下降要用〈气温〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f0c2dc0-701e-4d12-98e2-361ee568df0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86359, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天夜里发生了一只地震，我们都跑到楼下。", "corrected_sentence": "昨天夜里发生了一场地震，我们都跑到楼下。", "error_description": "量词错误：地震前应用“场”，不能用“只”。“只”用于动物等，正确说法是“发生了一场地震”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f0c2dc0-701e-4d12-98e2-361ee568df0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86359, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里以前地震了过很多次。", "corrected_sentence": "这里以前地震过很多次。", "error_description": "错误：“了”和“过”不能同时用。表示曾经发生时只用“过”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f0c2dc0-701e-4d12-98e2-361ee568df0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
