INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86360, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地壳快速震动的自然现象。", "primary_collocate": null, "pronunciation": "dì zhèn", "ipa": "ti˥˩ ʈʂən˥˩", "syllable_count": 2, "sentences": [{"text": "地震是地壳快速震动造成的自然现象。", "target_word": "地震", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次地震的震级是六点五级。", "target_word": "地震", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震发生时，地壳里的岩石会突然断裂。", "target_word": "地震", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "日本在两个板块之间，经常发生地震。", "target_word": "地震", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震之前，有些动物的行为会变得奇怪。", "target_word": "地震", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震是一种自然现象，人们还不能准确预报它。", "target_word": "地震", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里每年都有几百次地震，但是大多数人感觉不到。", "target_word": "地震", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震和火山一样，都和地壳的运动有关。", "target_word": "地震", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他研究地震二十年，知道地壳是怎么动的。", "target_word": "地震", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "历史上最大的一次地震发生在智利。", "target_word": "地震", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场地震", "label": "量词"}, {"form": "一次地震", "label": "量词"}, {"form": "地震带", "label": "复合"}], "register": "中性", "sense_fingerprint": "地震：地壳快速震动的自然现象（科学说明）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eb6a069-3cc9-4bff-bb63-1f24166f25c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
